    /// java: `EntityLiving.playLivingSound` → `Entity.playSound` → `World.playSoundAtEntity` →
    /// the empty `RenderGlobal.playSound`. The live tick must drain the tracker's ambient queue
    /// (so it stays bounded) without handing any of it to the audio engine: the audible idle
    /// sound is the server's S29. This test used to require the opposite.
    #[test]
    fn ambient_entity_sound_events_are_drained_but_not_played() {
        let source = include_str!("driver.rs");
        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("the live 20 Hz client tick remains present");
        let (tick, _) = tick
            .split_once("fn upload_terrain(")
            .expect("the live client tick has a frame-only tail");
        let drain = tick
            .find("drop(session.state_mut().entities.take_ambient_sound_events());")
            .expect("the entity ambient queue is drained by the live tick");
        let wither = tick
            .find("self.tick_wither_heads()")
            .expect("the post-entity wither phase remains present");
        assert!(drain < wither);
        let between = &tick[drain..wither];
        assert!(
            !between.contains("self.play_sound"),
            "ambient mob sounds must not reach the audio funnel: {between}"
        );
    }

