    #[test]
    fn live_horse_upload_maps_watched_tack_and_springs_to_stateful_geometry() {
        let watched = crate::sync::watched::HorseState {
            saddled: true,
            chested: true,
            eating_haystack: true,
            mouth_open: true,
            horse_type: 2,
            variant: 2 | (3 << 8),
            armour: 3,
            ..crate::sync::watched::HorseState::default()
        };
        let mut animation = mc_render::entity::models::passive::HorseAnim::default();
        animation.tick(watched.eating_haystack, watched.rearing, watched.mouth_open);
        let state = animation.render_state(
            0.5,
            watched.horse_type,
            true,
            watched.saddled,
            watched.chested,
            true,
        );
        assert!(state.adult);
        assert!(state.saddled);
        assert!(state.chested);
        assert!(state.ridden);
        assert_eq!(state.horse_type, 2);
        assert!((state.grass_eating_amount - 0.225).abs() < 1.0e-6);
        assert!((state.mouth_openness - 0.375).abs() < 1.0e-6);

        let mut models = RenderManager::new();
        let params = mc_render::entity::AnimParams::still();
        let mut equipped = Vec::new();
        models
            .emit_horse_with_state(
                &EntityTransform::default(),
                &params,
                &state,
                watched.variant,
                watched.armour,
                &mut equipped,
            )
            .expect("a watched mule selects a horse renderer");
        assert_eq!(
            equipped.len(),
            37 * 36,
            "23 base parts + 10 tack + 2 reins + 2 mule chests"
        );

        let plain_watched = crate::sync::watched::HorseState::default();
        let plain_state = mc_render::entity::models::passive::HorseAnim::default().render_state(
            0.5,
            plain_watched.horse_type,
            true,
            plain_watched.saddled,
            plain_watched.chested,
            false,
        );
        let mut plain = Vec::new();
        models
            .emit_horse_with_state(
                &EntityTransform::default(),
                &params,
                &plain_state,
                plain_watched.variant,
                plain_watched.armour,
                &mut plain,
            )
            .expect("an ordinary horse selects a renderer");
        assert_eq!(plain.len(), 23 * 36);

        let source = include_str!("driver.rs");
        assert!(source.contains(".horse_render_state("));
        assert!(source.contains("self.models.emit_horse_with_state("));
        assert!(source.contains("tracked.has_rider(),"));
    }

