    /// java: `RenderPlayer.doRender` hands `y - 0.125` to `RendererLivingEntity.doRender` for a
    /// sneaking remote player, and its `super.doRender` reaches `renderName` with that `y`. With
    /// the sneaking branch's `+ height + 0.5` and its quarter-block post-scale drop, the label's
    /// anchor sits at `feet + 1.8 + 0.5 - 0.125 - 0.25`.
    #[test]
    fn a_sneaking_remote_players_label_drops_with_render_players_body_offset() {
        use crate::sync::entities::TrackedKind;
        let feet = DVec3::new(10.0, 64.0, -3.0);
        let dropped = nameplate_feet(feet, TrackedKind::Player, true);
        assert_eq!(dropped, DVec3::new(10.0, 63.875, -3.0));
        assert_eq!(nameplate_feet(feet, TrackedKind::Player, false), feet);
        // Only RenderPlayer has the offset: a sneaking-flagged mob or armour stand keeps it.
        let mob = TrackedKind::Type(mc_data::EntityType::Zombie);
        assert_eq!(nameplate_feet(feet, mob, true), feet);

        let plate = mc_render::entity::Nameplate {
            text: "Sneaker".to_owned(),
            rel: (dropped - feet).as_vec3(),
            height: 1.8,
            child: false,
            sneaking: true,
        };
        let anchor = plate.local_to_world(0.0, 0.0, 0.0, 0.0);
        assert!(
            (anchor[1] - (1.8 + 0.5 - 0.125 - 0.25)).abs() < 1e-5,
            "{anchor:?}"
        );
    }

