    #[test]
    fn boss_hud_observation_matches_dragon_wither_and_live_last_writer_bridge() {
        let language = mc_assets::Language::new("test");
        assert_eq!(
            boss_hud_observation(
                Some(mc_data::EntityType::EnderDragon),
                Some(150.0),
                None,
                None,
                &language,
            ),
            Some(BossHudObservation {
                health: 150.0,
                max_health: 200.0,
                name: "entity.EnderDragon.name".to_owned(),
                has_color_modifier: false,
            })
        );
        // java: `getMaxHealth()` is the attribute, which S20 updates for the dragon too.
        assert_eq!(
            boss_hud_observation(
                Some(mc_data::EntityType::EnderDragon),
                Some(150.0),
                Some(999.0),
                None,
                &language,
            )
            .map(|observation| observation.max_health),
            Some(999.0)
        );
        assert_eq!(
            boss_hud_observation(
                Some(mc_data::EntityType::WitherBoss),
                Some(240.0),
                Some(600.0),
                Some("\u{a7}cNamed Wither".to_owned()),
                &language,
            ),
            Some(BossHudObservation {
                health: 240.0,
                max_health: 600.0,
                name: "\u{a7}cNamed Wither".to_owned(),
                has_color_modifier: true,
            })
        );
        assert!(boss_hud_observation(
            Some(mc_data::EntityType::Zombie),
            Some(20.0),
            None,
            None,
            &language,
        )
        .is_none());
        assert!(boss_hud_observation(
            Some(mc_data::EntityType::WitherBoss),
            None,
            None,
            None,
            &language,
        )
        .is_none());

        let source = include_str!("driver.rs");
        let (_, upload) = source
            .split_once(
                "fn upload_entities(&mut self, gpu: &Gpu, camera: &Camera, partial_ticks: f32)",
            )
            .expect("live entity upload remains present");
        let (upload, _) = upload
            .split_once("fn drive_atmosphere(")
            .expect("boss bridge is confined to entity upload");
        assert!(upload.contains("boss_hud_observation("));
        assert!(upload.contains("self.hud.set_boss_status("));
        assert!(
            upload.contains("self.boss_color_modifier_requested = observation.has_color_modifier;")
        );

        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("live tick remains present");
        let (tick, _) = tick
            .split_once("fn tick_fog_light_smoothing(")
            .expect("tick ends before its helper methods");
        assert!(tick.contains(".tick(&mut self.boss_color_modifier_requested);"));

        let (_, atmosphere) = source
            .split_once("fn drive_atmosphere(")
            .expect("live atmosphere driver remains present");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("atmosphere driver ends before later render helpers");
        assert!(atmosphere
            .contains("boss_darkening: self.boss_color_modifier.interpolated(partial_ticks)"));
    }

