    #[test]
    fn live_boss_modifier_reaches_fog_color_and_clears_when_inactive() {
        let environment = SkyEnvironment::default();
        let mut modifier = BossColorModifier::default();
        let mut requested = true;
        modifier.tick(&mut requested);
        assert!(!requested, "the draw request is consumed by the tick");

        let mut inputs = mc_render::sky::FogInputs {
            boss_color_modifier: boss_fog_modifier(&modifier, 1.0),
            ..mc_render::sky::FogInputs::default()
        };
        assert_eq!(inputs.boss_color_modifier, Some(0.05));
        let tinted = FogState::compute(&environment, inputs, 1.0);

        inputs.boss_color_modifier = boss_fog_modifier(&BossColorModifier::default(), 1.0);
        assert_eq!(inputs.boss_color_modifier, None);
        let inactive = FogState::compute(&environment, inputs, 1.0);
        assert!(tinted.color.x < inactive.color.x);
        assert!(tinted.color.y < inactive.color.y);
        assert!(tinted.color.z < inactive.color.z);

        let source = include_str!("driver.rs");
        let (_, atmosphere) = source
            .split_once("fn drive_atmosphere(")
            .expect("live atmosphere driver");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("bounded atmosphere driver");
        assert!(
            atmosphere.contains("boss_fog_modifier(&self.boss_color_modifier, partial_ticks)"),
            "the interpolated boss modifier must reach FogInputs every live frame"
        );
    }

    #[test]
    fn live_lightmap_refresh_fans_one_java_table_to_terrain_particles_tiles_and_entities_in_order()
    {
        let source = include_str!("driver.rs");
        let (_, atmosphere) = source
            .split_once(
                "fn drive_atmosphere(&mut self, gpu: &Gpu, camera: &Camera, partial_ticks: f32) {",
            )
            .expect("live atmosphere driver remains present");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("atmosphere driver remains bounded before particle upload");
        let terrain = atmosphere
            .find("render.terrain.borrow_mut().set_lightmap_params(gpu, params);")
            .expect("terrain consumes the live lightmap table");
        let particles = atmosphere
            .find("phase.set_lightmap_params(gpu, params)")
            .expect("particles consume the live lightmap table");
        let tiles = atmosphere
            .find("if let Some(tiles) = &self.tiles")
            .expect("the optional tile phase consumes the live lightmap table");
        let tile_upload = atmosphere[tiles..]
            .find("phase.set_lightmap_params(gpu, params)")
            .map(|offset| tiles + offset)
            .expect("tiles use the same frame parameters as terrain and particles");
        let entities = atmosphere
            .find("render\n                .entities\n                .with(|phase| phase.set_lightmap_params(gpu, params));")
            .expect("entities consume the live lightmap table");
        assert!(
            terrain < particles && particles < tile_upload && tile_upload < entities,
            "terrain, particles, optional tiles, then entities must consume one ordered lightmap refresh"
        );
        assert_eq!(
            atmosphere
                .matches("set_lightmap_params(gpu, params)")
                .count(),
            4,
            "the one Java-shaped frame table must reach all four live lightmap owners"
        );

        let (_, frame) = source
            .split_once(
                "pub fn frame(&mut self, gpu: &Gpu, camera: &mut Camera, partial_ticks: f32) {",
            )
            .expect("Client::frame remains present");
        let (frame, _) = frame
            .split_once("fn shader_action_after_reload(")
            .expect("Client::frame remains bounded before shader helpers");
        let atmosphere_call = frame
            .find("self.drive_atmosphere(gpu, camera, partial_ticks);")
            .expect("frame drives atmosphere");
        let particle_upload = frame
            .find("self.upload_particles(gpu, camera, partial_ticks);")
            .expect("frame uploads particles");
        assert!(
            atmosphere_call < particle_upload,
            "the shared lightmap must be refreshed before particle vertices are uploaded"
        );
        let tile_upload = frame
            .find("self.upload_tile_entities(gpu, camera, partial_ticks);")
            .expect("frame uploads tile entities");
        assert!(
            tile_upload < atmosphere_call,
            "tile geometry must be queued before the frame refreshes its shared lightmap"
        );
    }

    #[test]
    fn dynamic_lightmap_state_changes_with_java_time_gamma_and_night_vision_inputs() {
        let base = LightmapParams {
            sun_brightness: 1.0,
            dimension: Dimension::Overworld,
            gamma: 0.0,
            night_vision: 0.0,
            torch_flicker: 1.5,
            lightning_flash: false,
            boss_darkening: 0.0,
            fullbright: false,
        };
        let daylight = mc_render::sky::lightmap::Lightmap::generate(base);

        let night = mc_render::sky::lightmap::Lightmap::generate(LightmapParams {
            sun_brightness: 0.15,
            ..base
        });
        assert_ne!(
            daylight.sample(15, 0),
            night.sample(15, 0),
            "time-of-day sun brightness must alter the table consumed by particles"
        );

        let gamma =
            mc_render::sky::lightmap::Lightmap::generate(LightmapParams { gamma: 1.0, ..base });
        assert_ne!(
            daylight.sample(0, 0),
            gamma.sample(0, 0),
            "the gamma option must alter the dynamic table rather than a screen overlay"
        );

        let night_vision = mc_render::sky::lightmap::Lightmap::generate(LightmapParams {
            night_vision: 1.0,
            ..base
        });
        assert_ne!(
            daylight.sample(0, 0),
            night_vision.sample(0, 0),
            "the active night-vision potion must alter the particle lightmap"
        );

        let dim_light = LightmapParams {
            sun_brightness: 0.3,
            ..base
        };
        let dim_daylight = mc_render::sky::lightmap::Lightmap::generate(dim_light);
        let lightning = mc_render::sky::lightmap::Lightmap::generate(LightmapParams {
            lightning_flash: true,
            ..dim_light
        });
        assert_ne!(
            dim_daylight.sample(15, 0),
            lightning.sample(15, 0),
            "a live lightning flash must alter the shared tile lightmap"
        );

        let boss_darkening = mc_render::sky::lightmap::Lightmap::generate(LightmapParams {
            boss_darkening: 1.0,
            ..base
        });
        assert_ne!(
            daylight.sample(0, 0),
            boss_darkening.sample(0, 0),
            "active boss darkening must alter the shared tile lightmap"
        );

        // The non-vanilla fullbright option rides the same shared value, so every consumer of
        // the table (terrain, particles, tile entities, entities) turns white together.
        let fullbright = mc_render::sky::lightmap::Lightmap::generate(LightmapParams {
            fullbright: true,
            ..base
        });
        assert_eq!(fullbright.rgba, vec![255u8; 256 * 4]);
        assert_ne!(daylight.rgba, fullbright.rgba);
        assert!(include_str!("driver.rs").contains("fullbright: self.settings.fullbright,"));
        // TESR models take a CPU brightness instead of a lightmap coordinate; fullbright gives
        // them the white-texel value, which is the full-light brightness.
        assert!(include_str!("tiles.rs").contains("light: if fullbright {"));
        assert_eq!(mc_render::entity::tilepass::light_brightness(15), 1.0);

        // The same `Copy` value is passed to both phase owners in the live driver. Keep a
        // generated-table equality control here so a future phase-specific parameter fork cannot
        // silently make terrain and particles disagree on one frame.
        let terrain_table = mc_render::sky::lightmap::Lightmap::generate(base);
        let particle_table = mc_render::sky::lightmap::Lightmap::generate(base);
        assert_eq!(terrain_table.rgba, particle_table.rgba);
    }

    #[test]
    fn torch_flicker_advances_only_at_the_client_tick_boundary() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let before = client.torch_flicker.block_light_multiplier();
        for _ in 0..8 {
            assert_eq!(
                client.torch_flicker.block_light_multiplier(),
                before,
                "render-rate reads without a tick must not advance the random walk"
            );
        }

        client.tick(&MoveInput::default());
        assert_ne!(
            client.torch_flicker.block_light_multiplier(),
            before,
            "one 20 Hz client tick must consume the three flicker draws"
        );

        // Pin the live cadence boundary: the numeric check above bites an omitted tick step,
        // while this source edge prevents a later frame path from adding a second step back.
        let source = include_str!("driver.rs");
        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("live client tick");
        let (tick, _) = tick
            .split_once("fn tick_fog_light_smoothing(")
            .expect("end of client tick region");
        assert!(tick.contains("self.torch_flicker.step("));

        let (_, atmosphere) = source
            .split_once("fn drive_atmosphere(")
            .expect("live atmosphere frame driver");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("end of atmosphere region");
        assert!(
            !atmosphere.contains("self.torch_flicker.step("),
            "render frames may consume the multiplier but cannot advance its RNG/state"
        );
    }

    #[test]
    fn barrier_reveal_gate_is_strict_and_sampling_keeps_six_draw_order() {
        let barrier = stack_named("barrier", 1);
        let stone = stack_named("stone", 1);
        let unknown = mc_protocol::ItemStack {
            item_id: 32_767,
            count: 1,
            damage: 0,
            nbt: None,
        };
        assert!(barrier_reveal_enabled(true, Some(&barrier)));
        assert!(!barrier_reveal_enabled(false, Some(&barrier)));
        assert!(!barrier_reveal_enabled(true, Some(&stone)));
        assert!(!barrier_reveal_enabled(true, Some(&unknown)));
        assert!(!barrier_reveal_enabled(true, None));

        let origin = BlockPos::new(0, 64, 0);
        let candidate = BlockPos::new(-2, 58, 6);
        let mut world = mc_world::World::new();
        world.load_empty_chunk(mc_math::ChunkPos::new(-1, 0));
        world.set_block(
            candidate,
            mc_data::BlockState::new(mc_data::BlockId(166), 0),
        );

        let mut actual_rng = mc_math::JavaRandom::new(0);
        assert_eq!(
            collect_barrier_reveal_positions(&world, &mut actual_rng, origin, true, 1),
            vec![DVec3::new(-1.5, 58.5, 6.5)]
        );
        let mut expected_rng = mc_math::JavaRandom::new(0);
        let draws: Vec<_> = (0..6).map(|_| expected_rng.next_i32_bound(16)).collect();
        assert_eq!(draws, vec![11, 13, 3, 9, 10, 4]);
        assert_eq!(actual_rng.raw_seed(), expected_rng.raw_seed());

        let mut hidden_rng = mc_math::JavaRandom::new(0);
        assert!(
            collect_barrier_reveal_positions(&world, &mut hidden_rng, origin, false, 1).is_empty()
        );
        assert_eq!(
            hidden_rng.raw_seed(),
            expected_rng.raw_seed(),
            "the held-item gate suppresses only emission, not the six world samples"
        );

        world.set_block(candidate, mc_data::BlockState::new(mc_data::BlockId(1), 0));
        let mut stone_rng = mc_math::JavaRandom::new(0);
        assert!(
            collect_barrier_reveal_positions(&world, &mut stone_rng, origin, true, 1).is_empty()
        );

        let mut unloaded = mc_world::World::new();
        unloaded.set_block(
            candidate,
            mc_data::BlockState::new(mc_data::BlockId(166), 0),
        );
        assert!(!unloaded.is_chunk_loaded(candidate.chunk_pos()));
        // The write lands in the shared blank chunk, which inherits
        // `Chunk.setBlockState`/`getBlockState`, so `World.getBlockState` reads the barrier.
        assert_eq!(
            unloaded.block_at(candidate).props().block,
            mc_data::BlockId(166),
            "EmptyChunk keeps the barrier state for every absent column"
        );
        // The ambient pass (like `World::do_void_fog_particles`) still reads absent columns as
        // air. Vanilla's `doVoidFogParticles` reads `getBlockState` and would reveal this one: a
        // known, purely cosmetic difference that is left alone.
        let mut unloaded_rng = mc_math::JavaRandom::new(0);
        assert!(
            collect_barrier_reveal_positions(&unloaded, &mut unloaded_rng, origin, true, 1)
                .is_empty(),
            "the ambient pass skips absent columns"
        );
        assert_eq!(unloaded_rng.raw_seed(), expected_rng.raw_seed());
    }

    #[test]
    fn live_barrier_reveal_runs_after_world_tick_and_before_particle_drain() {
        let source = include_str!("driver.rs");
        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("the concrete client tick remains present");
        let (tick, _) = tick
            .split_once("fn upload_terrain(")
            .expect("the tick implementation ends before frame-only terrain work");
        let world_tick = tick
            .find("session.tick_with_held(input, held.as_ref());")
            .expect("world tick");
        let reveal = tick
            .find("self.tick_barrier_reveal_particles(held.as_ref());")
            .expect("live barrier reveal producer");
        let particle_drain = tick
            .find("take_particle_events()")
            .expect("entity particle drain");
        assert!(world_tick < reveal && reveal < particle_drain);
        assert_eq!(BARRIER_REVEAL_SAMPLES, 1_000);
    }

