    /// F-P2-client.particle-02-3: the firework rocket's ordinary per-tick trail is produced by
    /// the remote entity tracker, but it is only visible if the application drains that queue
    /// through the packet particle factory. Keep a second entity-owned particle family beside
    /// it so a test-only direct spark insertion, or a drain that drops one ID, cannot pass.
    #[test]
    fn firework_rocket_trail_reaches_the_live_particle_system_alongside_smoke() {
        use mc_data::EntityType;
        use mc_render::particle::ParticleKind;
        use mc_world::entity::Metadata;

        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.particles.clear();
        spawn_pick_target(
            &mut client,
            901,
            EntityType::FireworksRocketEntity,
            [0, 0, 0],
            Metadata::new(),
        );
        spawn_pick_target(
            &mut client,
            902,
            EntityType::PrimedTnt,
            [32, 0, 0],
            Metadata::new(),
        );

        client.tick(&MoveInput::default());

        let particles = client.particles.particles();
        assert!(
            particles
                .iter()
                .any(|particle| matches!(particle.kind, ParticleKind::Smoke { .. })),
            "negative control: the same drain must still forward an unrelated smoke event"
        );
        assert!(
            particles
                .iter()
                .any(|particle| matches!(particle.kind, ParticleKind::FireworkSpark { .. })),
            "the live entity-event drain must retain the rocket's ordinary spark trail"
        );
    }

    /// F-P0-network.play.server-07-6 / F-P1-potion-01-6: S1D's 32767 cap is a display flag, not
