    /// java: `handleTitle` (`:1571`) maps a null message to `""`. A
    /// Gson-null TITLE therefore shows, and re-times, an empty title; a null SUBTITLE clears the
    /// subtitle text. The former consumer fell back to the raw JSON and displayed "null".
    #[test]
    fn a_gson_null_title_is_an_empty_title_not_the_text_null() {
        use mc_protocol::play::s2c::Title;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        // Control: the former fallback (`from_json` or the raw text) rendered the word "null".
        let former = mc_ui::font::component::ChatComponent::from_json("null")
            .unwrap_or_else(|_| mc_ui::font::component::ChatComponent::text("null".to_owned()))
            .formatted_text(&client.assets.language);
        assert!(former.contains("null"), "{former:?}");
        client.react(&ClientEvent::Title(Box::new(Title::SetSubtitle {
            text: r#"{"text":"sub"}"#.into(),
        })));
        assert!(client.hud.subtitle.contains("sub"));
        client.react(&ClientEvent::Title(Box::new(Title::SetTitle {
            text: "null".into(),
        })));
        assert_eq!(client.hud.title, "");
        assert_eq!(
            client.hud.title_timer, 100,
            "TITLE (re)starts the default 10 + 70 + 20 tick timer"
        );
        client.react(&ClientEvent::Title(Box::new(Title::SetSubtitle {
            text: String::new(),
        })));
        assert_eq!(client.hud.subtitle, "");
    }

    /// Wire-reachable random packets through the live client path:
    /// `Session::poll_next` -> `sync::apply` -> `Session::react_to` -> `Client::react`, with
    /// client ticks in between. vanilla logs a main-thread handler exception and carries on; a
    /// Rust panic anywhere on this path is a crash a server can trigger.
    #[test]
    fn random_wire_reachable_packets_never_panic_the_live_client() {
        use mc_protocol::play::{s2c, S2CPlay};
        const LOCAL: i32 = 1_000;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut failures = Vec::new();
        // Exploratory runs: `H4_FUZZ_STEPS` per seed and `H4_FUZZ_SEEDS` extra seeds.
        let env_number = |name: &str| std::env::var(name).ok().and_then(|v| v.parse::<u64>().ok());
        let steps = env_number("H4_FUZZ_STEPS").unwrap_or(400);
        let extra_seeds = env_number("H4_FUZZ_SEEDS").unwrap_or(0);
        let seeds = [0x5EED_u64, 0xC0FF_EE11, 0xBADC_0DE5]
            .into_iter()
            .chain((1..=extra_seeds).map(|n| n.wrapping_mul(0x9E37_79B9_7F4A_7C15)));
        for seed in seeds {
            let (session, to_game, mut to_net) = offline_session(mc_world::World::new());
            client.session = Some(session);
            client.ui = Ui::InGame;
            let join = S2CPlay::JoinGame(s2c::JoinGame {
                entity_id: LOCAL,
                hardcore_mode: false,
                game_mode: 0,
                dimension: 0,
                difficulty: 2,
                max_players: 20,
                level_type: "default".into(),
                reduced_debug_info: false,
            });
            to_game
                .try_send(crate::net::ToGame::Packet(join))
                .expect("join channel");
            client.poll();
            let mut fuzzer = crate::sync::fuzz::PacketFuzzer::new(seed, LOCAL);
            // The client ticks here, so motion-feeding values stay finite and small: a huge one
            // only reproduces vanilla's own `getCollidingBoundingBoxes` freeze.
            fuzzer.physical = true;
            // `H4_FUZZ_TRACE=1` prints each packet before it is applied, so a stall names the
            // packet that caused it.
            let trace = std::env::var_os("H4_FUZZ_TRACE").is_some();
            for step in 0..steps {
                let packet = fuzzer.packet();
                let shown = format!("{packet:?}");
                if trace {
                    eprintln!("H4-FUZZ seed {seed:#x} step {step}: {shown:.300}");
                }
                let _ = to_game.try_send(crate::net::ToGame::Packet(packet));
                let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                    client.poll();
                    if trace {
                        eprintln!("H4-FUZZ   polled");
                    }
                    if step % 4 == 0 {
                        client.tick(&MoveInput::default());
                        if trace {
                            eprintln!("H4-FUZZ   ticked");
                        }
                    }
                }));
                while to_net.try_recv().is_ok() {}
                if let Err(panic) = result {
                    let message = panic
                        .downcast_ref::<String>()
                        .cloned()
                        .or_else(|| panic.downcast_ref::<&str>().map(|s| (*s).to_owned()))
                        .unwrap_or_default();
                    failures.push(format!(
                        "seed {seed:#x} step {step}: {message}\n  {shown:.800}"
                    ));
                    // The client may be half-updated after a panic; move on to the next seed.
                    break;
                }
            }
        }
        assert!(
            failures.is_empty(),
            "{} live-client panics:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }

    /// F-P0-network.play.server-11-1 / F-P0-network.play.client-05-6: reason 4 must open the
    /// full-screen End poem, and Escape must reach the existing single C16(PERFORM_RESPAWN)
    /// producer. The ordinary death screen remains a separate `GameOverScreen` mode.
    #[test]
    fn enter_credits_opens_win_game_and_escape_respawns_once() {
        use mc_protocol::play::{c2s, C2SPlay};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);

        client.react(&ClientEvent::GameState {
            reason: mc_protocol::play::s2c::GameStateReason::EnterCredits,
            value: 0.0,
        });
        let Ui::GameOver(screen) = &client.ui else {
            panic!("reason 4 must display GuiWinGame through the existing GameOver slot");
        };
        assert!(screen.is_win_game());
        assert!(!client.ui.shows_world());
        assert!(!client.ui.allows_user_input());

        let action = client.screen_key_typed(
            None,
            mc_ui::widget::keys::ESCAPE,
            mc_ui::widget::keys::Modifiers::NONE,
        );
        assert_eq!(action, Action::Respawn);
        client.handle_action(action);
        assert!(matches!(client.ui, Ui::InGame));
        let sent = drained(&mut to_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, C2SPlay::ClientStatus(_)))
                .count(),
            1,
            "Escape must emit exactly one terminal status packet"
        );
        assert!(matches!(
            sent.as_slice(),
            [C2SPlay::ClientStatus(c2s::ClientStatus {
                action: c2s::ClientStatusAction::PerformRespawn
            })]
        ));
    }

    /// F-P0-client.network-02-13 / F-P0-network.play-01-15: reason 5's screen and
    /// tutorial-chat values must both terminate in live presentation consumers. In particular,
    /// the chat text is built from current bindings, not hard-coded WASD/E labels.
    #[test]
    fn demo_game_state_opens_the_screen_and_formats_live_rebound_help() {
        use mc_protocol::play::s2c::GameStateReason;
        use mc_render::input::{keys as bind, Input};
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.assets.language.merge_lang_str(
            "demo.help.movement=Move with %s, %s, %s, %s\n\
             demo.help.jump=Jump with %s\n\
             demo.help.inventory=Inventory with %s\n",
        );
        client
            .settings
            .keys
            .set_binding(bind::FORWARD, Input::Key(KeyCode::ArrowUp));
        client
            .settings
            .keys
            .set_binding(bind::LEFT, Input::Key(KeyCode::ArrowLeft));
        client
            .settings
            .keys
            .set_binding(bind::BACK, Input::Key(KeyCode::ArrowDown));
        client
            .settings
            .keys
            .set_binding(bind::RIGHT, Input::Key(KeyCode::ArrowRight));
        client
            .settings
            .keys
            .set_binding(bind::JUMP, Input::Key(KeyCode::KeyJ));
        client
            .settings
            .keys
            .set_binding(bind::INVENTORY, Input::Key(KeyCode::KeyI));

        client.react(&ClientEvent::GameState {
            reason: GameStateReason::DemoMessage,
            value: 0.0,
        });
        assert!(matches!(client.ui, Ui::Demo(_)));
        assert_eq!(client.ui.name(), "demo");
        assert!(client.ui.shows_world());

        for value in [101.0, 102.0, 103.0] {
            client.react(&ClientEvent::GameState {
                reason: GameStateReason::DemoMessage,
                value,
            });
        }
        assert_eq!(client.chat.received_count(), 3);
        let text: Vec<&str> = client
            .chat
            .lines()
            .iter()
            .map(|line| line.text.as_str())
            .collect();
        assert!(text
            .iter()
            .any(|line| line.contains("Move with UP, LEFT, DOWN, RIGHT")));
        assert!(text.iter().any(|line| line.contains("Jump with J")));
        assert!(text.iter().any(|line| line.contains("Inventory with I")));

        client.react(&ClientEvent::GameState {
            reason: GameStateReason::DemoMessage,
            value: 104.0,
        });
        assert_eq!(
            client.chat.received_count(),
            3,
            "other reason-5 values are inert"
        );
    }

    /// F-P0-network.play.server-11-5: reasons 6 and 10 must terminate in their positional
    /// presentation consumers, while the unused reason 9 remains inert.
    #[test]
    fn game_state_hit_marker_and_guardian_effect_reach_live_consumers() {
        use mc_protocol::play::s2c::GameStateReason;
        use mc_render::particle::ParticleKind;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 7,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("channel");
        client.poll();
        let pose = &mut client
            .session
            .as_mut()
            .and_then(Session::predictor_mut)
            .expect("join built predictor")
            .state;
        pose.set_position(DVec3::new(4.25, 65.0, -2.75));
        let feet = pose.pos;
        let eye = pose.eye_pos();

        client.audio.clear_recent();
        client.react(&ClientEvent::GameState {
            reason: GameStateReason::ArrowHittingPlayer,
            value: 123.0,
        });
        let hit = client.audio.last_play().expect("reason 6 reached audio");
        assert_eq!(hit.request.event.path, "random.successful_hit");
        assert_eq!(hit.request.position, Some(eye));
        assert_eq!(hit.request.volume, 0.18);
        assert_eq!(hit.request.pitch, 0.45);

        client.audio.clear_recent();
        let before = client.particles.len();
        client.react(&ClientEvent::GameState {
            reason: GameStateReason::PlayMobAppearance,
            value: -9.0,
        });
        let curse = client.audio.last_play().expect("reason 10 reached audio");
        assert_eq!(curse.request.event.path, "mob.guardian.curse");
        assert_eq!(curse.request.position, Some(feet));
        assert_eq!(curse.request.volume, 1.0);
        assert_eq!(curse.request.pitch, 1.0);
        assert_eq!(client.particles.len(), before + 1);
        let appearance = client.particles.particles().last().expect("appearance");
        assert!(matches!(appearance.kind, ParticleKind::MobAppearance));
        assert_eq!(appearance.pos, feet);

        // The controller is intentionally absent from ParticlePhase's billboard batches. Pin
        // its separate live entity-phase handoff so dropping the final visible submission bites
        // even in this CPU-only test.
        let source = include_str!("driver.rs");
        let (_, upload) = source
            .split_once(
                "fn upload_entities(&mut self, gpu: &Gpu, camera: &Camera, partial_ticks: f32)",
            )
            .expect("live entity upload");
        let (upload, _) = upload
            .split_once("fn drive_atmosphere(")
            .expect("entity upload boundary");
        let begin = upload
            .find("render.entities.with(|phase| phase.begin());")
            .expect("entity phase begin");
        let descriptor = upload
            .find("mc_render::particle::mob_appearance_draw(particle, camera, partial_ticks)")
            .expect("appearance draw descriptor");
        let texture = upload
            .find("mc_render::particle::MOB_APPEARANCE_TEXTURE")
            .expect("elder texture load");
        let submit = upload
            .find("draw.submit(&mut self.models, phase);")
            .expect("appearance entity submission");
        let finish = upload
            .find("render.nameplates.with(|phase| phase.finish(gpu));")
            .expect("nameplate phase finish");
        assert!(!upload.contains("render.entities.with(|phase| phase.finish(gpu));"));
        assert!(begin < descriptor && descriptor < texture && texture < submit && submit < finish);

        client.audio.clear_recent();
        let before = client.particles.len();
        client.react(&ClientEvent::GameState {
            reason: GameStateReason::Other(9),
            value: 1.0,
        });
        assert!(client.audio.last_play().is_none());
        assert_eq!(client.particles.len(), before);
    }

