    /// The descriptor, rather than the locale code, is the source of bidi state. Replacing the
    /// same-code descriptor must therefore flip the live renderer, while an unknown/synthetic
    /// locale remains the safe LTR fallback. This catches the old `unicode_flag`-only bridge.
    #[test]
    fn live_language_direction_reloads_when_same_locale_descriptor_changes() {
        struct DescriptorPack {
            descriptor: mc_assets::LanguageInfo,
        }

        impl mc_assets::ResourcePack for DescriptorPack {
            fn open(
                &self,
                _location: &mc_assets::ResourceLocation,
            ) -> Option<Box<dyn std::io::Read>> {
                None
            }

            fn contains(&self, _location: &mc_assets::ResourceLocation) -> bool {
                false
            }

            fn language_descriptors(&self) -> &[mc_assets::LanguageInfo] {
                std::slice::from_ref(&self.descriptor)
            }
        }

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let code = client.assets.language.code().to_owned();
        let descriptor = |bidirectional| mc_assets::LanguageInfo {
            code: code.clone(),
            region: "ZZ".to_owned(),
            name: "Test".to_owned(),
            bidirectional,
        };
        let mut resources = mc_assets::ResourceManager::new();
        resources.push_pack(Box::new(DescriptorPack {
            descriptor: descriptor(false),
        }));
        apply_language_direction(&mut client.font, &resources, &code);
        assert!(!client.font.bidi_flag());

        resources.reload(vec![Box::new(DescriptorPack {
            descriptor: descriptor(true),
        })]);
        apply_language_direction(&mut client.font, &resources, &code);
        assert!(
            client.font.bidi_flag(),
            "same-code descriptor replacement must be observable"
        );

        apply_language_direction(&mut client.font, &resources, "synthetic_missing");
        assert!(
            !client.font.bidi_flag(),
            "missing descriptors use the LTR fallback"
        );
    }

