    #[test]
    fn anaglyph_driver_seeds_startup_and_loading_owners() {
        let source = include_str!("driver.rs");
        let (_, stack) = source
            .split_once("impl RenderStack {")
            .expect("the concrete render stack remains present");
        let (stack, _) = stack
            .split_once("/// Which screen is in front.")
            .expect("the render stack implementation keeps its boundary");
        for constructor in [
            "SkyPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "CloudsPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "TerrainPhase::install_with_anaglyph(",
            "EntityPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "NameplatePhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "BlockOverlayPhase::new_with_anaglyph(",
            "ParticlePhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "WeatherPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "FirstPersonPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "FogPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "OverlayPhase::new_with_anaglyph(gpu, settings.anaglyph)",
            "phase.set_anaglyph_with_gpu(gpu, settings.anaglyph)",
            "UiPhase::new_with_anaglyph(",
        ] {
            assert!(
                stack.contains(constructor),
                "startup render owner omitted anaglyph seed: {constructor}"
            );
        }
        let cloud_seed = stack
            .find("CloudsPhase::new_with_anaglyph(gpu, settings.anaglyph)")
            .expect("clouds keep their startup anaglyph seed");
        let cloud_load = stack
            .find("clouds.load_texture(gpu, &assets.resources);")
            .expect("clouds retain their startup texture upload");
        assert!(
            cloud_seed < cloud_load,
            "cloud anaglyph state must be seeded before clouds.png is uploaded"
        );
        let block_overlay_seed = stack
            .find("BlockOverlayPhase::new_with_anaglyph(")
            .expect("block overlay keeps its startup anaglyph seed");
        let block_overlay_atlas = stack[block_overlay_seed..]
            .find("Some(&assets.atlas)")
            .map(|offset| block_overlay_seed + offset)
            .expect("block overlay keeps its atlas source");
        let block_overlay_setting = stack[block_overlay_atlas..]
            .find("settings.anaglyph")
            .map(|offset| block_overlay_atlas + offset)
            .expect("block overlay receives the persisted anaglyph setting");
        assert!(
            block_overlay_atlas < block_overlay_setting,
            "block overlay anaglyph state must be seeded alongside its atlas upload"
        );
        let tile_seed = source
            .find(
                "TilePhase::new_with_anaglyph(\n            gpu,\n            self.settings.anaglyph,\n        )",
            )
            .expect("tile phase keeps its startup anaglyph seed");
        let tile_register = source[tile_seed..]
            .find("phases.insert(PhaseOrder::ENTITIES, Box::new(tiles.clone()));")
            .map(|offset| tile_seed + offset)
            .expect("tile phase remains registered after construction");
        assert!(
            tile_seed < tile_register,
            "tile phase anaglyph state must be seeded before registration and visible uploads"
        );

        let (_, loading) = source
            .split_once("pub fn install_loading_ui(")
            .expect("loading UI installation remains present");
        let (loading, _) = loading
            .split_once("/// Whether a deferred asset load")
            .expect("loading UI installation keeps its boundary");
        assert!(
            loading.contains("UiPhase::new_with_anaglyph(")
                && loading.contains("self.settings.anaglyph"),
            "the loading screen UI must upload with the persisted anaglyph mode"
        );
    }

    #[test]
    fn anaglyph_driver_fanout_is_one_preupload_false_true_false_boundary() {
        let source = include_str!("driver.rs");
        let production = source
            .split_once("impl Client {")
            .expect("Client implementation remains live")
            .1
            .split_once("#[cfg(test)]\nmod tests {")
            .expect("Client implementation keeps its test boundary")
            .0;
        let (_, fanout) = production
            .split_once("fn sync_anaglyph_with_gpu(&mut self, gpu: &Gpu) {")
            .expect("the consolidated GPU-aware fanout remains present");
        let (fanout, _) = fanout
            .split_once("fn flush_atlas_animation_uploads(&mut self, gpu: &Gpu) {")
            .expect("the fanout ends before atlas upload flushing");
        assert_eq!(
            fanout.matches("set_anaglyph_with_gpu").count(),
            13,
            "one GPU-aware call must reach sky, clouds, terrain, block overlay, entities, tiles, nameplates, particles, weather, first-person, overlay, post, and UI"
        );
        assert!(
            fanout.contains("self.font.set_anaglyph(enabled);")
                && fanout.contains("self.standard_galactic_font.set_anaglyph(enabled);"),
            "both live font palettes must follow the setting without reconstructing either renderer"
        );
        assert!(
            fanout.contains("render.fog.with(|phase| phase.set_anaglyph(enabled));"),
            "fog's CPU-only final-colour setter must be in the same fanout"
        );
        for owner in [
            ".sky",
            ".clouds",
            ".terrain",
            ".block_overlay",
            ".entities",
            ".tiles",
            ".nameplates",
            ".particles",
            ".weather",
            ".first_person",
            ".fog",
            ".overlay",
            ".post",
            ".ui",
        ] {
            assert!(
                fanout.contains(owner),
                "consolidated fanout omitted {owner}"
            );
        }

        let fonts = fanout
            .find("self.font.set_anaglyph(enabled);")
            .expect("font palettes are synced at the pre-upload seam");
        let render_guard = fanout
            .find("let Some(render) = self.render.as_ref() else {")
            .expect("the GPU owner fanout keeps its no-render guard");
        assert!(
            fonts < render_guard,
            "CPU font palettes must update even when the loading UI has no world render stack"
        );

        let clouds = fanout
            .find(
                "render\n            .clouds\n            .with(|phase| phase.set_anaglyph_with_gpu(gpu, enabled));",
            )
            .expect("clouds must be in the consolidated GPU fanout");
        let terrain = fanout
            .find(
                "render\n            .terrain\n            .borrow_mut()\n            .set_anaglyph_with_gpu(gpu, enabled);",
            )
            .expect("terrain must remain in the consolidated GPU fanout");
        let block_overlay = fanout
            .find(
                "render\n            .block_overlay\n            .with(|phase| phase.set_anaglyph_with_gpu(gpu, enabled));",
            )
            .expect("block overlay must be in the consolidated GPU fanout");
        assert!(
            clouds < terrain,
            "cloud sync must retain sky-phase ordering"
        );
        assert!(
            terrain < block_overlay,
            "block overlay sync must follow terrain in the consolidated GPU fanout"
        );
        let entities = fanout
            .find(
                "render\n            .entities\n            .with(|phase| phase.set_anaglyph_with_gpu(gpu, enabled));",
            )
            .expect("entities must be in the consolidated GPU fanout");
        let tiles = fanout
            .find("if let Some(tiles) = &self.tiles {")
            .expect("tiles must be in the consolidated GPU fanout");
        let nameplates = fanout
            .find(
                "render\n            .nameplates\n            .with(|phase| phase.set_anaglyph_with_gpu(gpu, enabled));",
            )
            .expect("nameplates must be in the consolidated GPU fanout");
        assert!(
            entities < tiles && tiles < nameplates,
            "tile sync must follow entities and precede nameplates"
        );

        let (_, frame) = production
            .split_once(
                "pub fn frame(&mut self, gpu: &Gpu, camera: &mut Camera, partial_ticks: f32) {",
            )
            .expect("Client::frame remains present");
        let sync = frame
            .find("self.sync_anaglyph_with_gpu(gpu);")
            .expect("frame must sync before any GPU upload");
        let flush = frame
            .find("self.flush_atlas_animation_uploads(gpu);")
            .expect("frame must retain the atlas upload boundary");
        assert!(sync < flush, "anaglyph sync must precede atlas uploads");
        let terrain_upload = frame
            .find("self.upload_terrain(gpu, camera);")
            .expect("frame must retain the terrain upload caller");
        assert!(
            flush < terrain_upload,
            "atlas animation uploads must precede terrain uploads after anaglyph sync"
        );
        assert_eq!(
            frame[..flush]
                .matches("sync_anaglyph_with_gpu(gpu);")
                .count(),
            1,
            "one frame must have exactly one pre-upload anaglyph sync"
        );

        let (_, entities) = production
            .split_once("fn upload_entities(&mut self, gpu: &Gpu")
            .expect("the live entity upload caller remains present");
        let (entities, _) = entities
            .split_once("fn drive_atmosphere(")
            .expect("the entity upload caller ends before atmosphere");
        assert!(
            !entities.contains("set_anaglyph_with_gpu"),
            "entity upload must not retain a redundant nameplate-only sync"
        );
    }

