    #[test]
    fn live_anaglyph_false_true_false_updates_clouds_tile_and_both_font_palettes() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let normal_texture = client.font.default_texture();
        let standard_texture = client.standard_galactic_font.default_texture();
        client.font.set_unicode_flag(true);
        client.font.set_bidi_flag(true);
        client.standard_galactic_font.set_unicode_flag(true);
        client.standard_galactic_font.set_bidi_flag(true);
        let normal_data = client.font.data() as *const _;
        let standard_data = client.standard_galactic_font.data() as *const _;

        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 64, 64);
        {
            let render = client
                .render
                .as_ref()
                .expect("install creates render stack");
            assert!(!render.block_overlay.with(|phase| phase.anaglyph_enabled()));
            assert!(!client
                .tiles
                .as_ref()
                .expect("install creates tile phase")
                .with(|phase| phase.anaglyph_enabled()));
        }

        for enabled in [false, true, false] {
            client.settings.anaglyph = enabled;
            client.sync_anaglyph_with_gpu(&gpu);

            assert_eq!(client.font.anaglyph_enabled(), enabled);
            assert_eq!(client.standard_galactic_font.anaglyph_enabled(), enabled);
            assert_eq!(client.font.colors(), &mc_ui::font::color_table(enabled));
            assert_eq!(
                client.standard_galactic_font.colors(),
                &mc_ui::font::color_table(enabled)
            );
            assert_eq!(client.font.default_texture(), normal_texture);
            assert_eq!(
                client.standard_galactic_font.default_texture(),
                standard_texture
            );
            assert!(client.font.unicode_flag());
            assert!(client.font.bidi_flag());
            assert!(client.standard_galactic_font.unicode_flag());
            assert!(client.standard_galactic_font.bidi_flag());
            assert_eq!(client.font.data() as *const _, normal_data);
            assert_eq!(
                client.standard_galactic_font.data() as *const _,
                standard_data
            );

            let render = client
                .render
                .as_ref()
                .expect("install creates render stack");
            assert_eq!(
                render.clouds.with(|phase| phase.anaglyph_enabled()),
                enabled
            );
            assert_eq!(
                render.block_overlay.with(|phase| phase.anaglyph_enabled()),
                enabled
            );
            assert_eq!(
                client
                    .tiles
                    .as_ref()
                    .expect("install creates tile phase")
                    .with(|phase| phase.anaglyph_enabled()),
                enabled
            );
        }
    }

