    /// F-P1-block-41-1's driver boundary: the predicted trapdoor virtual body sits before C08,
    /// has Java's sneaking/empty-hand guard, and consumes the controller click while forwarding
    /// the returned local level event to the common auxiliary-effect fan-out.
    #[test]
    fn live_trapdoor_activation_predicts_before_c08_and_fans_its_effect() {
        let source = include_str!("driver.rs");
        let (_, after_right_click) = source
            .split_once("fn on_player_right_click(")
            .expect("the concrete player right-click controller remains present");
        let (right_click, _) = after_right_click
            .split_once("/// The boxes `World.checkNoEntityCollision")
            .expect("right-click controller ends before placement blockers");
        let activation = right_click
            .find(".activate_trapdoor(hit.pos)")
            .expect("live controller dispatches the trapdoor virtual body");
        let c08 = right_click
            .find("out.place_block(hit.pos, hit.face, cursor, stack, slot, packets);")
            .expect("the normal C08 remains after client prediction");
        assert!(activation < c08, "activation must precede C08 emission");
        assert!(
            right_click.contains("if !spectator && (!sneaking || held.is_none())")
                && right_click.contains("consumed = activation.consumed")
                && right_click.contains("if !spectator && !consumed")
                && right_click.contains("self.play_aux_sfx(effect.id, effect.pos, effect.data);"),
            "the Java guard, consumed result, and returned local effect must all stay live"
        );
    }

