    /// F-P1-entity.passive-05-5: the live descriptor path must not select the neutral Squid
    /// placement retained for state-free callers. The two angles originate in SquidAnim, reach
    /// AnimParams after partial interpolation, and are consumed by RenderSquid's unique corpse
    /// rotation (which also suppresses the superclass death spin).
    #[test]
    fn live_entity_upload_forwards_squid_pitch_and_yaw_to_placement() {
        let transform = EntityTransform {
            rel: mc_math::Vec3::new(1.0, 2.0, 3.0),
            body_yaw: 35.0,
            death_rotation: 90.0,
            ..EntityTransform::default()
        };
        let mut params = mc_render::entity::AnimParams::still();
        params.entity.squid_pitch = -40.0;
        params.entity.squid_yaw = 20.0;

        let live =
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Squid), &transform, &params);
        let expected = mc_render::entity::manager::squid_placement_matrix(
            &transform,
            params.entity.squid_pitch,
            params.entity.squid_yaw,
        );
        let neutral = mc_render::entity::manager::squid_placement_matrix(&transform, 0.0, 0.0);
        assert_eq!(live, expected);
        assert_ne!(live, neutral);

        assert_eq!(
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Cow), &transform, &params,),
            mc_render::entity::manager::placement_matrix_for(
                mc_data::EntityType::Cow,
                &transform,
                &params,
            ),
            "squid-only angles must not perturb another living renderer"
        );
    }

    #[test]
    fn live_entity_upload_applies_only_the_baby_villager_pre_scale() {
        let transform = EntityTransform {
            scale: 0.9375,
            ..EntityTransform::default()
        };
        let adult = mc_render::entity::AnimParams::still();
        let mut child = adult.clone();
        child.entity.child = true;

        assert_eq!(
            uploaded_entity_placement_matrix(
                Some(mc_data::EntityType::Villager),
                &transform,
                &child,
            ),
            mc_render::entity::render::entity_matrix_scaled(&transform, mc_math::Vec3::splat(0.5),)
        );
        assert_ne!(
            uploaded_entity_placement_matrix(
                Some(mc_data::EntityType::Villager),
                &transform,
                &child,
            ),
            uploaded_entity_placement_matrix(
                Some(mc_data::EntityType::Villager),
                &transform,
                &adult,
            ),
            "omitting RenderVillager's child callback must change the live matrix"
        );
        for kind in [mc_data::EntityType::Zombie, mc_data::EntityType::Cow] {
            assert_eq!(
                uploaded_entity_placement_matrix(Some(kind), &transform, &child),
                uploaded_entity_placement_matrix(Some(kind), &transform, &adult),
                "the half-size pre-render callback is Villager-only: {kind:?}"
            );
        }
    }

    #[test]
    fn live_entity_upload_consumes_creeper_fuse_scale_without_moving_other_mobs() {
        let transform = EntityTransform {
            scale: 0.9375,
            ..EntityTransform::default()
        };
        let neutral = mc_render::entity::AnimParams::still();
        let mut flashing = neutral.clone();
        flashing.entity.creeper_flash = 0.75;

        let actual = uploaded_entity_placement_matrix(
            Some(mc_data::EntityType::Creeper),
            &transform,
            &flashing,
        );
        let expected = mc_render::entity::render::entity_matrix_scaled(
            &transform,
            mc_render::entity::manager::creeper_pre_render_scale(0.75),
        );
        assert_eq!(actual, expected);
        assert_ne!(
            actual,
            uploaded_entity_placement_matrix(
                Some(mc_data::EntityType::Creeper),
                &transform,
                &neutral,
            ),
            "dropping the live Creeper callback must change its body matrix"
        );
        assert_eq!(
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Cow), &transform, &flashing,),
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Cow), &transform, &neutral,),
            "Creeper-only fuse progress cannot scale another mob"
        );

        let source = include_str!("driver.rs");
        let body = source
            .split_once("if draw != crate::app::appearance::BodyDraw::Skip")
            .expect("live body submission")
            .1
            .split_once("RendererLivingEntity.renderLayers")
            .expect("flash replay remains between body and ordinary layers")
            .0;
        assert!(body.contains("LayerBlend::WhiteFlash"));
        assert!(body.contains("vertex.color = flash"));
    }

