    #[test]
    fn live_entity_upload_forwards_bat_hanging_state_to_placement() {
        let transform = EntityTransform {
            rel: mc_math::Vec3::new(2.0, 4.0, 6.0),
            ..EntityTransform::default()
        };
        let mut flying = mc_render::entity::AnimParams::still();
        flying.age_in_ticks = 3.0;
        let mut hanging = flying.clone();
        hanging.entity.bat_hanging = true;

        let flying_live =
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Bat), &transform, &flying);
        let hanging_live =
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Bat), &transform, &hanging);
        assert_eq!(
            flying_live,
            mc_render::entity::manager::placement_matrix_for(
                mc_data::EntityType::Bat,
                &transform,
                &flying,
            )
        );
        assert_eq!(
            hanging_live,
            mc_render::entity::manager::placement_matrix_for(
                mc_data::EntityType::Bat,
                &transform,
                &hanging,
            )
        );
        assert_ne!(flying_live, hanging_live);
        assert_ne!(
            flying_live,
            mc_render::entity::manager::placement_matrix(mc_data::EntityType::Bat, &transform),
            "the live upload must not discard the bat's flying bob"
        );
        assert_ne!(
            hanging_live,
            mc_render::entity::manager::placement_matrix(mc_data::EntityType::Bat, &transform),
            "the live upload must not discard the bat's hanging offset"
        );

        let cow_live =
            uploaded_entity_placement_matrix(Some(mc_data::EntityType::Cow), &transform, &hanging);
        assert_eq!(
            cow_live,
            mc_render::entity::manager::placement_matrix(mc_data::EntityType::Cow, &transform),
            "bat-only state must not move an ordinary entity"
        );
    }

    #[test]
    fn screaming_enderman_shimmer_uses_two_gaussians_without_moving_y() {
        let position = DVec3::new(3.0, 5.0, 7.0);
        let mut calm_rng = mc_math::JavaRandom::new(0x5EED);
        assert_eq!(
            enderman_shimmer_position(
                position,
                Some(mc_data::EntityType::Enderman),
                false,
                &mut calm_rng,
            ),
            position
        );

        let mut expected_rng = mc_math::JavaRandom::new(0x5EED);
        let expected = DVec3::new(
            position.x + expected_rng.next_gaussian() * 0.02,
            position.y,
            position.z + expected_rng.next_gaussian() * 0.02,
        );
        let mut live_rng = mc_math::JavaRandom::new(0x5EED);
        let shimmered = enderman_shimmer_position(
            position,
            Some(mc_data::EntityType::Enderman),
            true,
            &mut live_rng,
        );
        assert_eq!(shimmered, expected);
        assert_ne!(shimmered.x, position.x);
        assert_ne!(shimmered.z, position.z);
        assert_eq!(shimmered.y, position.y);

        let after_first = live_rng.raw_seed();
        let second = enderman_shimmer_position(
            position,
            Some(mc_data::EntityType::Enderman),
            true,
            &mut live_rng,
        );
        assert_ne!(second, shimmered, "the renderer RNG persists across draws");
        assert_ne!(live_rng.raw_seed(), after_first);

        let mut wrong_kind_rng = mc_math::JavaRandom::new(0x5EED);
        let before = wrong_kind_rng.raw_seed();
        assert_eq!(
            enderman_shimmer_position(
                position,
                Some(mc_data::EntityType::Zombie),
                true,
                &mut wrong_kind_rng,
            ),
            position,
        );
        assert_eq!(wrong_kind_rng.raw_seed(), before);
    }

