    #[test]
    fn max_health_operation_two_ignores_s20_wire_order() {
        use mc_protocol::play::s2c::{
            AttributeModifierOperation as Op, AttributeModifierSnapshot as Modifier,
        };

        let wire = [
            Modifier {
                uuid: uuid::Uuid::from_u128(18),
                amount: 4.004_807_362_210_215,
                operation: Op::Multiply,
            },
            Modifier {
                uuid: uuid::Uuid::from_u128(1),
                amount: 1.625_183_354_820_274_8,
                operation: Op::Multiply,
            },
            Modifier {
                uuid: uuid::Uuid::from_u128(2),
                amount: 3.549_961_541_408_507,
                operation: Op::Multiply,
            },
        ];
        let java =
            ((0.1_f64 * 2.625_183_354_820_274_8) * 5.004_807_362_210_215) * 4.549_961_541_408_507;
        let reordered = [wire[1], wire[0], wire[2]];

        assert_eq!(
            resolve_attribute_value(0.1, &wire).to_bits(),
            java.to_bits()
        );
        assert_eq!(
            resolve_attribute_value(0.1, &wire).to_bits(),
            resolve_attribute_value(0.1, &reordered).to_bits()
        );
    }

    #[test]
    fn live_max_health_snapshots_replace_uuid_state_reject_duplicates_and_clamp_consumers() {
        use mc_protocol::play::s2c::{
            AttributeModifierOperation as Op, AttributeModifierSnapshot as Modifier,
            AttributePropertySnapshot, EntityProperties,
        };

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, _to_game, _to_net) = offline_session(mc_world::World::new());
        session.state_mut().local.entity_id = 7;
        client.session = Some(session);
        client.player_hud.health = 35.0;

        let modifier = |amount| Modifier {
            uuid: uuid::Uuid::from_u128(9),
            amount,
            operation: Op::Multiply,
        };
        let event = |base_value, modifiers| {
            ClientEvent::EntityProperties(Box::new(EntityProperties {
                entity_id: 7,
                properties: vec![AttributePropertySnapshot {
                    key: "generic.maxHealth".into(),
                    base_value,
                    modifiers,
                }],
            }))
        };

        client.react(&event(20.0, vec![modifier(1.0)]));
        assert_eq!(client.wither_max_health.get(&7), Some(&40.0));
        assert_eq!(client.player_hud.max_health, 40.0);
        assert_eq!(client.player_hud.health, 35.0);
        let first = client.max_health_attributes[&7].clone();

        // A whole S20 snapshot replaces removeAllModifiers + applyModifier: omitting UUID 9
        // removes its multiplier rather than merging it into the prior map.
        client.react(&event(30.0, Vec::new()));
        assert_eq!(client.wither_max_health.get(&7), Some(&30.0));
        assert_eq!(client.player_hud.max_health, 30.0);
        assert_eq!(client.player_hud.health, 30.0);
        assert_ne!(client.max_health_attributes[&7], first);
        let before_bad = client.max_health_attributes[&7].clone();

        // Java rejects the second UUID before the attribute instance is replaced. A vector fold
        // mutant would accept both and change the scalar to 45.
        client.react(&event(20.0, vec![modifier(0.5), modifier(0.5)]));
        assert_eq!(client.max_health_attributes[&7], before_bad);
        assert_eq!(client.wither_max_health.get(&7), Some(&30.0));

        client.react(&event(2_048.0, Vec::new()));
        assert_eq!(client.wither_max_health.get(&7), Some(&1_024.0));
        client.react(&event(-1.0, Vec::new()));
        assert_eq!(client.wither_max_health.get(&7), Some(&0.0));
        assert_eq!(client.player_hud.health, 0.0);
    }

