    #[test]
    fn custom_head_block_model_applies_stack_tint_only_to_tagged_quads() {
        use mc_assets::{BakedModel, BakedQuad, Vertex};

        let quad = |tint_index| BakedQuad {
            verts: [
                Vertex {
                    pos: [0.0, 0.0, 0.5],
                    uv: [0.0, 1.0],
                },
                Vertex {
                    pos: [0.0, 1.0, 0.5],
                    uv: [0.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 1.0, 0.5],
                    uv: [1.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 0.0, 0.5],
                    uv: [1.0, 1.0],
                },
            ],
            face: None,
            shade_face: None,
            tint_index,
            shade: false,
        };
        let mut model = BakedModel::default();
        model.general_quads.extend([quad(Some(0)), quad(None)]);
        let vine = mc_protocol::ItemStack {
            item_id: mc_data::item_by_name("vine").expect("known block item").0 as i16,
            count: 1,
            damage: 0,
            nbt: None,
        };

        let mut out = Vec::new();
        emit_custom_head_item_model(&vine, &model, mc_render::entity::Mat4::IDENTITY, &mut out);
        assert_eq!(out.len(), 12);
        assert!(out[..6]
            .iter()
            .all(|vertex| { vertex.color == [72.0 / 255.0, 181.0 / 255.0, 24.0 / 255.0, 1.0] }));
        assert!(out[6..]
            .iter()
            .all(|vertex| vertex.color == mc_render::entity::EntityVertex::WHITE));

        let mut shifted_model = model.clone();
        shifted_model.transforms.head.translation = [1.0, 0.0, 0.0];
        let mut shifted = Vec::new();
        emit_custom_head_item_model(
            &vine,
            &shifted_model,
            mc_render::entity::Mat4::IDENTITY,
            &mut shifted,
        );
        assert_eq!(shifted.len(), out.len());
        assert!(
            shifted
                .iter()
                .zip(&out)
                .any(|(transformed, identity)| transformed.pos != identity.pos),
            "the live worn-block adapter must consume baked display.head transforms"
        );
    }

    #[test]
    fn remote_equipped_baked_items_replay_two_glint_passes_in_every_live_layer_arm() {
        use mc_assets::{BakedModel, BakedQuad, Vertex};

        let mut model = BakedModel::default();
        model.general_quads.push(BakedQuad {
            verts: [
                Vertex {
                    pos: [0.0, 0.0, 0.5],
                    uv: [0.0, 1.0],
                },
                Vertex {
                    pos: [0.0, 1.0, 0.5],
                    uv: [0.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 1.0, 0.5],
                    uv: [1.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 0.0, 0.5],
                    uv: [1.0, 1.0],
                },
            ],
            face: None,
            shade_face: None,
            tint_index: None,
            shade: false,
        });
        let mut enchantments = mc_nbt::NbtCompound::new();
        enchantments.insert("ench", mc_nbt::Nbt::list(vec![]));
        let enchanted = mc_protocol::ItemStack {
            item_id: 1,
            count: 1,
            damage: 0,
            nbt: Some(enchantments),
        };
        let plain = mc_protocol::ItemStack {
            nbt: None,
            ..enchanted.clone()
        };

        let mut base = Vec::new();
        mc_render::entity::item::emit_baked_model(
            &model,
            mc_render::entity::Mat4::IDENTITY,
            &mut base,
        );
        let mut glint = base.clone();
        emit_equipped_item_glint(&enchanted, base.len(), || 1_500, &mut glint);
        let glint = &glint[base.len()..];
        assert_eq!(glint.len(), 12, "one quad is replayed in two foil passes");
        let mut rewalk = Vec::new();
        mc_render::entity::item::emit_baked_model_glint(
            &model,
            mc_render::entity::Mat4::IDENTITY,
            1_500,
            &mut rewalk,
        );
        assert_eq!(
            glint,
            &rewalk[..],
            "the reused base equals the full foil re-walk"
        );
        for pass in glint.chunks_exact(base.len()) {
            assert!(pass
                .iter()
                .zip(&base)
                .all(|(foil, item)| foil.pos == item.pos));
        }
        let mut none = base.clone();
        emit_equipped_item_glint(
            &plain,
            base.len(),
            || panic!("an ordinary stack must not read the glint clock"),
            &mut none,
        );
        assert_eq!(none, base, "an ordinary stack has no foil replay");

        let source = include_str!("driver.rs");
        for (start, end) in [
            ("LayerKind::HeldItem =>", "LayerKind::HeldBlock =>"),
            ("LayerKind::WitchHeldItem =>", "LayerKind::CustomHead =>"),
            ("LayerKind::CustomHead =>", "LayerKind::SnowmanHead =>"),
        ] {
            let (_, arm) = source.split_once(start).expect("live layer arm");
            let (arm, _) = arm.split_once(end).expect("bounded live layer arm");
            assert!(
                arm.contains("emit_equipped_item_glint("),
                "{start} must replay enchanted baked geometry"
            );
            assert!(arm.contains("LayerBlend::Glint"));
        }
    }

