    /// C1-10: the shell's present request follows the client's live settings, so the in-game
    /// VSync toggle no longer waits for a restart.
    #[test]
    fn shell_present_request_follows_the_live_vsync_toggle() {
        let Some((mut client, _temp)) = offline_client() else {
            return;
        };
        client.settings.enable_vsync = true;
        let before = <Client as mc_render::ShellApp>::wants_present(&client)
            .expect("the client always states its present request");
        assert!(before.vsync);
        client.settings.enable_vsync = false;
        client.settings.frame_latency = 1;
        let after = <Client as mc_render::ShellApp>::wants_present(&client)
            .expect("the client always states its present request");
        assert!(!after.vsync, "the toggle must reach the request");
        assert_eq!(after.frame_latency, 1);
        assert_eq!(after.preference, client.settings.present_mode);
    }

    // ---- the F3 overlay's FPS line ---------------------------------------------------------

    /// Transcribed from `Minecraft.java:1197`'s format string, not from this port's output.
    #[test]
    fn the_fps_line_matches_vanillas_format_string() {
        let mut settings = GameSettings::default();
        settings.limit_framerate = mc_render::settings::FRAMERATE_UNLIMITED;
        settings.enable_vsync = true;
        settings.fancy_graphics = true;
        settings.clouds = 2;
        settings.use_vbo = false;
        let counter = FpsCounter {
            fps: 120,
            chunk_updates: 0,
            ..FpsCounter::default()
        };
        assert_eq!(
            counter.line(&settings),
            "120 fps (0 chunk updates) T: inf vsync fancy-clouds"
        );

        // Vanilla's pluraliser drops the `s` at exactly one and nowhere else.
        let one = FpsCounter {
            chunk_updates: 1,
            ..counter
        };
        assert!(one.line(&settings).contains("(1 chunk update)"));
        let two = FpsCounter {
            chunk_updates: 2,
            ..counter
        };
        assert!(two.line(&settings).contains("(2 chunk updates)"));

        // `T:` is the cap when there is one, and every trailing flag responds to its setting.
        settings.limit_framerate = 60;
        settings.enable_vsync = false;
        settings.fancy_graphics = false;
        settings.clouds = 1;
        settings.use_vbo = true;
        assert_eq!(
            counter.line(&settings),
            "120 fps (0 chunk updates) T: 60 fast fast-clouds vbo"
        );

        // Clouds off is vanilla's one silent case — no flag at all, not " no-clouds".
        settings.clouds = 0;
        assert_eq!(
            counter.line(&settings),
            "120 fps (0 chunk updates) T: 60 fast vbo"
        );
    }

    /// F-P2-client.gui-11-13: the live driver must preserve F3's modifier snapshot when it
    /// selects the auxiliary debug modes. A plain F3 clears a prior Alt/Shift selection.
    #[test]
    fn f3_driver_edge_selects_lagometer_and_profiler_modes() {
        use crate::app::input::KeyPress;
        use mc_ui::widget::keys::Modifiers;
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let f3 = |mods| KeyPress {
            sequence: 0,
            code: KeyCode::F3,
            lwjgl: 61,
            typed: None,
            mods,
            repeat: false,
        };

        // `Client::new` intentionally starts on the main menu. Vanilla's runTick only
        // dispatches this branch while `currentScreen == null`; prove the menu is a negative
        // control, then put the fixture in the corresponding no-screen state before driving the
        // auxiliary-mode edges. Leaving it on the menu would test the wrong path and make the
        // failure look like a production regression.
        client.key_pressed(f3(Modifiers::SHIFT));
        assert!(
            !client.debug.visible,
            "F3 must not dispatch through an open screen"
        );
        assert!(!client.debug.profiler_chart_visible());
        assert!(!client.debug.lagometer_visible());
        client.ui = Ui::InGame;

        client.key_pressed(f3(Modifiers::SHIFT));
        assert!(client.debug.visible);
        assert!(client.debug.profiler_chart_visible());
        assert!(!client.debug.lagometer_visible());

        client.key_pressed(f3(Modifiers {
            ctrl: false,
            shift: false,
            alt: true,
        }));
        assert!(!client.debug.visible);
        assert!(!client.debug.profiler_chart_visible());
        assert!(client.debug.lagometer_visible());

        client.key_pressed(f3(Modifiers::NONE));
        assert!(client.debug.visible);
        assert!(!client.debug.profiler_chart_visible());
        assert!(!client.debug.lagometer_visible());
    }

    /// java: `Minecraft.runTick:1952-2007`'s in-game chords. F3+D clears
    /// chat (lines and sent history), F3+P flips `pauseOnLostFocus` and saves, F3+A re-meshes
    /// every live section, F3+S/F3+T refresh resources, and F3+F is 1.8.9's broken
    /// `setOptionValue(RENDER_DISTANCE, 1)`: only `saveOptions()`, the distance unchanged. The
    /// old client handled none of these; the same keys without F3 are the negative control.
    #[test]
    fn f3_chords_match_the_in_game_branch_of_run_tick() {
        use crate::app::input::KeyPress;
        use mc_ui::widget::keys::Modifiers;
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let edge = |code, lwjgl| KeyPress {
            sequence: 0,
            code,
            lwjgl,
            typed: None,
            mods: Modifiers::NONE,
            repeat: false,
        };
        let chords = [
            (KeyCode::KeyD, 32),
            (KeyCode::KeyP, 25),
            (KeyCode::KeyA, 30),
            (KeyCode::KeyT, 20),
            (KeyCode::KeyS, 31),
            (KeyCode::KeyF, 33),
        ];
        client.ui = Ui::InGame;
        client.chat.add_sent("/l");
        for z in 0..3 {
            client
                .uploaded_sections
                .insert(ChunkSectionPos::new(0, 4, z));
        }
        let pause = client.settings.pause_on_lost_focus;
        let distance = client.settings.render_distance_chunks;
        let options = client.config.options_path();

        for (code, lwjgl) in chords {
            client.key_pressed(edge(code, lwjgl));
        }
        assert_eq!(client.chat.sent_messages(), ["/l".to_owned()]);
        assert_eq!(client.settings.pause_on_lost_focus, pause);
        assert_eq!(client.mesh_queue.len(), 0);
        assert!(!client.pending_pack_reload);

        client.handle_raw_key(KeyCode::F3, true, false, None);
        client.key_pressed(edge(KeyCode::KeyD, 32));
        assert!(client.chat.sent_messages().is_empty(), "F3+D clears chat");
        client.key_pressed(edge(KeyCode::KeyP, 25));
        assert_eq!(client.settings.pause_on_lost_focus, !pause);
        let expected = format!("pauseOnLostFocus:{}", !pause);
        assert!(std::fs::read_to_string(&options)
            .expect("F3+P saves options")
            .lines()
            .any(|line| line == expected));
        client.key_pressed(edge(KeyCode::KeyA, 30));
        assert_eq!(
            client.mesh_queue.len(),
            3,
            "F3+A re-meshes every live section"
        );
        client.key_pressed(edge(KeyCode::KeyT, 20));
        assert!(client.pending_pack_reload, "F3+T refreshes resources");
        client.pending_pack_reload = false;
        client.key_pressed(edge(KeyCode::KeyS, 31));
        assert!(client.pending_pack_reload, "F3+S refreshes resources");
        std::fs::remove_file(&options).expect("options were saved above");
        client.key_pressed(edge(KeyCode::KeyF, 33));
        assert_eq!(client.settings.render_distance_chunks, distance);
        assert!(options.is_file(), "F3+F still runs saveOptions");
        client.handle_raw_key(KeyCode::F3, false, false, None);
    }

    #[test]
    fn f3_h_toggles_advanced_tooltips_once_and_propagates_to_live_inventory() {
        use crate::app::input::KeyPress;
        use mc_ui::widget::keys::Modifiers;
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let edge = |code, lwjgl, repeat| KeyPress {
            sequence: 0,
            code,
            lwjgl,
            typed: None,
            mods: Modifiers::NONE,
            repeat,
        };
        let f3 = || edge(KeyCode::F3, 61, false);
        let h = || edge(KeyCode::KeyH, 35, false);

        // Java's dispatch chord is suppressed by any current screen, even though the physical
        // F3 latch is down. This is the negative control for the no-screen branch below.
        client.handle_raw_key(KeyCode::F3, true, false, None);
        client.key_pressed(h());
        assert!(!client.settings.advanced_item_tooltips);
        client.handle_raw_key(KeyCode::F3, false, false, None);

        client.ui = Ui::InGame;
        client.handle_raw_key(KeyCode::F3, true, false, None);
        client.key_pressed(f3());
        client.key_pressed(h());
        assert!(client.settings.advanced_item_tooltips);
        assert!(std::fs::read_to_string(client.config.options_path())
            .expect("F3+H saves options immediately")
            .lines()
            .any(|line| line == "advancedItemTooltips:true"));

        // The repeat edge is discarded before dispatch, so holding H cannot flip the setting
        // back while F3 remains physically down.
        client.key_pressed(edge(KeyCode::KeyH, 35, true));
        assert!(client.settings.advanced_item_tooltips);

        // Releasing F3 closes the raw physical latch; a later H is an ordinary screen key.
        client.handle_raw_key(KeyCode::F3, false, false, None);
        client.key_pressed(h());
        assert!(client.settings.advanced_item_tooltips);

        let screen = client.new_player_inventory_screen();
        assert!(screen.advanced_tooltips);
        let creative = client.new_creative_inventory_screen();
        assert!(creative.advanced_tooltips);

        // An already-open screen receives the same live snapshot at the frame seam.
        client.settings.advanced_item_tooltips = false;
        client.ui = Ui::Container(Box::new(screen));
        client.sync_advanced_tooltips();
        let Ui::Container(screen) = &client.ui else {
            panic!("the inventory fixture must remain installed");
        };
        assert!(!screen.advanced_tooltips);
    }

