    /// The chunk total must be the one from the window the FPS figure came from — accumulated
    /// across the whole second, then zeroed, exactly as `RenderChunk.renderChunksUpdated` is.
    /// F-P2-client.gui-11-9/11-10: the caller must fill every right-column machine slot and pass
    /// distinct OS memory roles. The old caller copied the launcher version into the Java slot,
    /// left CPU/renderer/API empty, copied the renderer into the vendor slot, and repeated RSS
    /// three times; each of those regressions is a direct failure here.
    /// The live driver owns the Java `ShaderGroup` name separately from F4 visibility: a reload
    /// tears down the old group before scheduling its replacement, while world stop clears both
    /// the active debug name and the deferred GPU action immediately.
    #[test]
    fn shader_debug_name_tracks_reload_and_world_stop_controls() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        assert_eq!(
            client.shader_cycle.activate_next(true, true),
            mc_render::post::SuperSecretShaderAction::Load("notch")
        );
        client.active_shader = Some("minecraft:shaders/post/old.json".to_owned());
        client.shader_visible = false;
        assert_eq!(
            client.shader_action_after_reload(),
            mc_render::post::SuperSecretShaderAction::Load("notch")
        );
        assert!(
            client.active_shader.is_none(),
            "reload deletes the old group first"
        );
        assert!(
            client.shader_visible,
            "loadShader re-arms useShader on reload"
        );

        client.active_shader = Some("minecraft:shaders/post/notch.json".to_owned());
        client.unload_world();
        assert!(
            client.active_shader.is_none(),
            "world stop clears the debug name"
        );
        assert_eq!(
            client.pending_shader_action,
            Some(mc_render::post::SuperSecretShaderAction::Clear)
        );
    }

    #[test]
    fn debug_info_populates_runtime_graphics_and_memory_values() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let info = client.debug_info(&gpu);
        assert_eq!(info.java_bits, usize::BITS as u8);
        assert_ne!(info.java_version, info.version);
        assert!(
            info.cpu.contains("x "),
            "CPU line is not populated: {}",
            info.cpu
        );
        assert!(!info.renderer.is_empty(), "renderer line is empty");
        assert!(!info.api_version.is_empty(), "API version line is empty");
        assert_ne!(
            info.display.2, info.renderer,
            "Display must carry the vendor, not the renderer name"
        );
        assert!(info.memory.0 > 0, "resident memory sample is empty");
        assert!(
            info.memory.0 <= info.memory.1 && info.memory.1 <= info.memory.2,
            "memory roles must be used <= allocated <= max: {:?}",
            info.memory
        );
        assert_ne!(
            info.memory.0, info.memory.2,
            "memory must not repeat one RSS value in every Java heap slot"
        );

        // GuiOverlayDebug asks EntityRenderer.isShaderActive(), which is the resident
        // ShaderGroup and deliberately ignores F4's independent useShader visibility bit. The
        // no-shader control proves the line is absent when no group is resident at all.
        client.active_shader = Some("minecraft:shaders/post/notch.json".to_owned());
        client.shader_visible = false;
        assert_eq!(
            client.debug_info(&gpu).shader.as_deref(),
            Some("minecraft:shaders/post/notch.json"),
            "F4 must hide post pixels without removing the active F3 shader line"
        );
        client.active_shader = None;
        assert_eq!(
            client.debug_info(&gpu).shader,
            None,
            "a client with no resident ShaderGroup must emit no shader line"
        );
    }

