    #[test]
    fn chunk_updates_roll_on_the_same_window_the_fps_does() {
        let mut counter = FpsCounter::default();

        // Three frames inside the first window, uploading as they go. Nothing is reported yet:
        // the window has not closed, so vanilla would still be showing the previous second's.
        counter.pending_chunk_updates += 2;
        counter.roll_to(0, 0);
        counter.pending_chunk_updates += 3;
        counter.roll_to(0, 0);
        assert_eq!(counter.chunk_updates, 0);

        // The window closes: the five uploads become the reported figure and the accumulator
        // restarts, so they are never counted twice.
        counter.roll_to(1, 250);
        assert_eq!(counter.fps, 250);
        assert_eq!(counter.chunk_updates, 5);
        assert_eq!(counter.pending_chunk_updates, 0);

        // A second with no uploads at all reports zero rather than repeating the last figure.
        counter.roll_to(2, 240);
        assert_eq!(counter.chunk_updates, 0);
        assert_eq!(counter.fps, 240);

        // Frames within a window keep refreshing the fps but must not re-roll the chunk total.
        counter.pending_chunk_updates += 7;
        counter.roll_to(2, 238);
        assert_eq!(counter.fps, 238);
        assert_eq!(
            counter.chunk_updates, 0,
            "a repeated window number is not a new window"
        );
    }

