    #[test]
    fn achievement_toast_reaches_the_build_ui_frame_list_only_for_a_new_unlock() {
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.ui = Ui::InGame;
        client.settings.show_inventory_achievement_hint = false;
        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 64, 64);

        let has_achievement_background = |client: &Client| {
            client
                .render
                .as_ref()
                .expect("install populated the UI phase")
                .ui
                .with(|phase| {
                    phase.list().batches().iter().any(|batch| {
                        matches!(
                            &batch.texture,
                            UiTexture::Resource(location)
                                if location.path
                                    == mc_ui::screens::common::ACHIEVEMENT_BACKGROUND_TEXTURE
                        )
                    })
                })
        };
        let stat = |stat_id: &str, value| mc_protocol::play::s2c::StatisticEntry {
            stat_id: stat_id.to_owned(),
            value,
        };

        // The first S37 is a silent baseline even when it contains a positive achievement.
        client.react(&ClientEvent::Statistics(vec![
            stat("achievement.mineWood", 2),
            stat("achievement.buildWorkBench", 0),
        ]));
        client.build_ui(&gpu, 0.0);
        assert!(!has_achievement_background(&client));

        // Ordinary statistics, zero values, decrements and repeated positives all remain silent.
        client.react(&ClientEvent::Statistics(vec![stat("stat.walkOneCm", 10)]));
        client.react(&ClientEvent::Statistics(vec![stat(
            "achievement.buildWorkBench",
            0,
        )]));
        client.react(&ClientEvent::Statistics(vec![stat(
            "achievement.mineWood",
            1,
        )]));
        client.react(&ClientEvent::Statistics(vec![stat(
            "achievement.mineWood",
            1,
        )]));
        client.build_ui(&gpu, 0.0);
        assert!(!has_achievement_background(&client));

        // Only a later zero-to-positive achievement reaches the final submitted frame list.
        client.react(&ClientEvent::Statistics(vec![stat(
            "achievement.buildWorkBench",
            1,
        )]));
        client.build_ui(&gpu, 0.0);
        assert!(has_achievement_background(&client));

        // GuiAchievement expires strictly after its three-second presentation window.
        client.started -= std::time::Duration::from_millis(3_100);
        client.build_ui(&gpu, 0.0);
        assert!(!has_achievement_background(&client));
    }

