    // ---- The camera interpolates by `partial_ticks` --------------------

    /// In the living-entity pass, an unreached player's spectator outline is pushed before the
    /// outline-only entity leaves the loop, and the section gate comes before the range and
    /// frustum check, as in `RenderGlobal.renderEntities`.
    #[test]
    fn an_unreached_player_leaves_the_living_pass_only_after_its_outline() {
        let source = include_str!("driver.rs");
        let pass = source
            .split_once("fn upload_entities(&mut self, gpu: &Gpu")
            .expect("living-entity pass")
            .1;
        let gate = pass
            .find("let section_gate = crate::app::entrender::entity_pass_gate(")
            .expect("section gate");
        // Not the full path: another test counts its call sites in this file.
        let range = pass
            .find("entrender::should_render_tracked_with_leash(")
            .expect("range and frustum check");
        let outline = pass
            .find("phase.push_outline(color, &verts)")
            .expect("outline push");
        let leave = pass
            .find("if section_gate == crate::app::entrender::EntityPassGate::OutlineOnly {")
            .expect("outline-only exit");
        assert!(gate < range && range < outline && outline < leave);
    }

