    #[test]
    fn the_eye_lerps_between_the_two_ticks_it_sits_between() {
        // java: `EntityRenderer.orientCamera:637` — `prevPosX + (posX - prevPosX) * partialTicks`
        // on all three axes. Before this, `place_camera` ignored `partial_ticks` entirely and the
        // whole world translated once per 20 Hz tick.
        let mut state = mc_physics::state::PhysicsState::new_player(DVec3::new(10.0, 64.0, -4.0));
        let prev = DVec3::new(0.0, 64.0, 0.0);
        state.set_position(DVec3::new(1.0, 68.0, -2.0));
        let eye_height = state.eye_pos().y - state.pos.y;

        let at = |pt: f32| interpolated_eye(Some(prev), &state, pt);
        // The two endpoints are exact: no interpolation error may creep into either tick.
        assert_eq!(at(0.0), prev + DVec3::new(0.0, eye_height, 0.0));
        assert_eq!(at(1.0), state.pos + DVec3::new(0.0, eye_height, 0.0));
        // ...and the midpoint is halfway along every axis, not just the horizontal ones.
        let mid = at(0.5);
        assert_eq!(
            interpolated_feet(Some(prev), &state, 0.5),
            DVec3::new(0.5, 66.0, -1.0),
            "getPositionEyes starts from the interpolated feet"
        );
        assert_eq!(
            interpolated_player_eye(Some(prev), &state, false, 0.5),
            mid,
            "sky horizon input uses the local player's current eye height"
        );
        assert!(
            (mid.x - 0.5).abs() < 1e-12,
            "x did not interpolate: {mid:?}"
        );
        assert!(
            (mid.y - (66.0 + eye_height)).abs() < 1e-12,
            "y did not interpolate: {mid:?}"
        );
        assert!(
            (mid.z + 1.0).abs() < 1e-12,
            "z did not interpolate: {mid:?}"
        );

        // Distinct fractions must give distinct eyes — the whole point of the finding is that
        // every frame inside one tick used to render from a bit-identical camera.
        let samples: Vec<DVec3> = (0..5).map(|i| at(i as f32 / 5.0)).collect();
        for pair in samples.windows(2) {
            assert_ne!(pair[0], pair[1]);
        }

        // Sleeping is a separate Java eye-height branch, and must not inherit the standing 1.62F
        // value merely because the camera can still be interpolated from the same two positions.
        // java: `getPositionEyes` adds `(double) getEyeHeight()`, and the sleeping eye height is
        // the float `0.2F`, so the promoted value is 0.20000000298023224, not the double 0.2.
        assert_eq!(
            interpolated_player_eye(Some(prev), &state, true, 0.5),
            DVec3::new(0.5, 66.0 + f64::from(0.2f32), -1.0)
        );
    }

    /// F-P1-util-14-2: Java samples the interaction ray once in `runTick` and again from
    /// `renderWorldPass` with the frame's partial position/current look.  Keeping two deliberately
    /// different blocks on those rays is a biting negative control for accidentally driving the
    /// outline from the packet-facing tick result (or overwriting the packet result in a frame).
    #[test]
    fn the_render_pick_is_a_separate_snapshot_from_the_tick_pick() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let tick_target = BlockPos::new(3, 65, 4);
        let render_target = BlockPos::new(6, 65, 3);
        mc_render::terrain::fixture::place(
            &mut client
                .session
                .as_mut()
                .expect("live test session")
                .state_mut()
                .world,
            render_target,
            "minecraft:stone",
        );

        // At the tick pose, yaw 0 faces +Z and reaches only the first block. The player has
        // faced it for the last ticks, so the click's head yaw and the outline's lerp agree.
        {
            let session = client.session.as_mut().expect("live test session");
            session.face_local_player(0.0, 0.0);
            session
                .predictor_mut()
                .expect("join built predictor")
                .state
                .pos = DVec3::new(3.5, 64.0, 3.0);
        }
        client.update_hit_result();
        assert_eq!(
            client.hit.block().map(|hit| hit.pos),
            Some(tick_target),
            "the 1.0F interaction sample must see the +Z block"
        );

        // Between ticks the mouse turns the player toward +X and 45 degrees up. The render sample
        // is `getLook(partialTicks)`: the live pitch (`setAngles` moves `prevRotationPitch` with
        // the mouse) and the head-yaw lerp, which only a tick moves (L7). So the outline rises to the block above the tick target instead of
        // swinging to the +X block, while the tick result stays for the next C02/C07 producer.
        let up_target = BlockPos::new(3, 66, 4);
        mc_render::terrain::fixture::place(
            &mut client
                .session
                .as_mut()
                .expect("live test session")
                .state_mut()
                .world,
            up_target,
            "minecraft:stone",
        );
        client.camera_prev_pos = Some(DVec3::new(3.0, 64.0, 3.0));
        client.camera_prev_corrections = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("join built predictor")
            .corrections;
        {
            let state = &mut client
                .session
                .as_mut()
                .expect("live test session")
                .predictor_mut()
                .expect("join built predictor")
                .state;
            state.yaw = -90.0;
            state.pitch = -45.0;
        }
        client.update_render_hit_result(0.5);

        assert_eq!(
            client.render_hit.block().map(|hit| hit.pos),
            Some(up_target),
            "the partial render ray follows the live pitch and the head yaw, not the +X turn"
        );
        assert_ne!(
            client.render_hit.block().map(|hit| hit.pos),
            Some(render_target)
        );
        assert_eq!(
            client.hit.block().map(|hit| hit.pos),
            Some(tick_target),
            "negative control: a frame sample must not overwrite the packet-facing tick hit"
        );
        assert_ne!(
            client.hit, client.render_hit,
            "the two rays are intentionally different in this between-ticks sample"
        );
    }

    /// `runTick`'s `getMouseOver(1.0F)` aims with
    /// `EntityLivingBase.getLook(1.0F)`: `rotationYawHead`, which `updateEntityActionState`
    /// copied from `rotationYaw` during the previous tick, and the *current* `rotationPitch`. The
    /// frames of mouse motion between two ticks therefore move the pitch a click aims with but
    /// not its yaw; the click faces where the last C03 told the server the player was looking.
    /// Drives the real `Client::tick` (which copies the head yaw) and the real frame mouse path.
    /// Negative control: the old pick aimed with the frame-fresh yaw and saw the +X block.
    #[test]
    fn the_click_pick_aims_with_last_ticks_head_yaw_and_the_current_pitch() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let plus_z = BlockPos::new(3, 65, 4);
        let plus_x = BlockPos::new(6, 65, 3);
        let up_z = BlockPos::new(3, 66, 4);
        {
            let session = client.session.as_mut().expect("live test session");
            let world = &mut session.state_mut().world;
            // A floor, so the ticks below leave the eye where it is.
            for pos in [BlockPos::new(3, 63, 3), plus_x, up_z] {
                mc_render::terrain::fixture::place(world, pos, "minecraft:stone");
            }
            let predictor = session.predictor_mut().expect("join built predictor");
            predictor.state.set_position(DVec3::new(3.5, 64.0, 3.5));
            predictor.state.yaw = 0.0;
            predictor.state.pitch = 0.0;
        }
        let input = |yaw: f32| MoveInput {
            yaw,
            pitch: 0.0,
            ..MoveInput::default()
        };
        let block = |client: &Client| client.hit.block().map(|hit| hit.pos);

        // Tick facing +Z: `updateEntityActionState` copies yaw 0 into the head.
        client.tick(&input(0.0));
        // Between ticks the mouse turns the player to face +X.
        client.turn_local_player(&mut Camera::default(), -600.0, 0.0);
        let turned = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("join built predictor")
            .state;
        assert!((turned.yaw + 90.0).abs() < 1.0e-3, "the mouse turned to +X");

        client.update_hit_result();
        assert_eq!(
            block(&client),
            Some(plus_z),
            "the click aims with last tick's yaw"
        );
        let (eye, _, _) = client
            .session
            .as_ref()
            .and_then(Session::tick_pick_ray)
            .expect("local pick ray");
        assert_eq!(
            client
                .pick_result_at(eye, turned.yaw, turned.pitch)
                .block()
                .map(|hit| hit.pos),
            Some(plus_x),
            "negative control: the frame-fresh yaw the old pick used sees the +X block"
        );

        // The pitch, unlike the yaw, is read live: looking up between ticks raises the click.
        client
            .session
            .as_mut()
            .and_then(Session::predictor_mut)
            .expect("join built predictor")
            .state
            .pitch = -45.0;
        client.update_hit_result();
        assert_eq!(
            block(&client),
            Some(up_z),
            "getLook(1.0F) reads the current pitch"
        );

        // The next tick reports the turned yaw; from then on the click aims along it too.
        client.tick(&input(-90.0));
        client
            .session
            .as_mut()
            .and_then(Session::predictor_mut)
            .expect("join built predictor")
            .state
            .pitch = 0.0;
        client.update_hit_result();
        assert_eq!(
            block(&client),
            Some(plus_x),
            "the head yaw follows one tick behind"
        );
    }

    /// The pick's reach is `PlayerControllerMP`'s, which reads
    /// `currentGameType.isCreative()` (`getBlockReachDistance:344`, `extendedReach:607`), the
    /// game mode S01/S07/S2B install. `thePlayer.capabilities.isCreativeMode` (S39) is a separate
    /// field a server may set on its own; with it the old pick gave a survival player creative's
    /// 6.0 entity ray and no 3.0 rejection, a hit a vanilla client cannot make.
    #[test]
    fn the_pick_reach_follows_the_controller_game_mode_not_the_s39_creative_bit() {
        use mc_protocol::play::s2c::GameMode;
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        {
            let session = client.session.as_mut().expect("session");
            session.state_mut().local.head_yaw = 0.0;
            let predictor = session
                .predictor_mut()
                .expect("JoinGame built the predictor");
            predictor.state.pos = DVec3::new(0.5, 64.0, 0.5);
            predictor.state.yaw = 0.0;
            predictor.state.pitch = 0.0;
        }
        // A zombie whose 0.1-bordered box starts 4.00625 down the +Z ray: inside survival's 4.5
        // block reach (the MISS hit vector the block ray returns sits at 4.5) but past its 3.0
        // entity limit.
        spawn_pick_target(
            &mut client,
            31,
            mc_data::EntityType::Zombie,
            [16, 2048, 157],
            mc_world::entity::Metadata::new(),
        );
        let pick = |client: &mut Client, mode: GameMode, s39_creative: bool| {
            let local = &mut client.session.as_mut().expect("session").state_mut().local;
            local.game_mode = mode;
            local.abilities.creative_mode = s39_creative;
            client.update_hit_result();
            client.hit.entity().map(|hit| hit.network_id)
        };

        assert_eq!(
            pick(&mut client, GameMode::Survival, true),
            None,
            "survival keeps getMouseOver's 3.0 rejection whatever S39 says"
        );
        assert_eq!(
            client.hit,
            HitResult::Miss,
            "the rejection replaces the hit with a MISS"
        );
        assert_eq!(
            pick(&mut client, GameMode::Creative, false),
            Some(31),
            "creative keeps extendedReach whatever S39 says"
        );
        // Controls: the two fields agreeing.
        assert_eq!(pick(&mut client, GameMode::Survival, false), None);
        assert_eq!(pick(&mut client, GameMode::Creative, true), Some(31));
    }

    /// L7: `EntityLivingBase.getLook(partialTicks)`'s head-yaw lerp after `onUpdate`'s tail has
    /// moved `prevRotationYawHead` by whole turns to within 180 degrees of `rotationYawHead`.
    #[test]
    fn the_outline_yaw_is_the_wrapped_head_yaw_lerp() {
        assert_eq!(interpolated_head_yaw(10.0, 30.0, 0.5), 20.0);
        // 170 -> -170 crosses the seam: prev becomes -190, so the lerp goes the short way.
        assert_eq!(interpolated_head_yaw(170.0, -170.0, 0.5), -180.0);
        // -170 -> 170: prev becomes 190, and the lerp runs 190 -> 170.
        assert_eq!(interpolated_head_yaw(-170.0, 170.0, 0.25), 185.0);
        // An unwrapped local yaw two turns away still takes the short arc.
        assert_eq!(interpolated_head_yaw(0.0, 725.0, 0.0), 720.0);
        // The edges are asymmetric, as in Java: a delta of exactly -180 fails `< -180.0F` and
        // stays, exactly +180 passes `>= 180.0F` and wraps.
        assert_eq!(interpolated_head_yaw(180.0, 0.0, 0.0), 180.0);
        assert_eq!(interpolated_head_yaw(0.0, 180.0, 0.0), 360.0);
        // No hang on a non-finite sample (Java's uncapped loop would spin on the second).
        assert!(interpolated_head_yaw(f32::NAN, 0.0, 0.5).is_nan());
        assert!(interpolated_head_yaw(0.0, f32::INFINITY, 0.5).is_infinite());
    }

    /// F-P1-entity.hitbox-SWEEP-3 / F-P1-entity-03-6: the production entity pick must consume
    /// the tracker's live Java `width`/`height`, not the static `EntityInfo` constructor row.
    /// Each target is placed just outside the old box and just inside (or outside) the resized
    /// one, so a helper-only dimensions assertion cannot make this pass.
    #[test]
    fn live_dynamic_dimensions_reach_the_driver_entity_pick_box() {
        use mc_data::EntityType as E;
        use mc_world::entity::{Metadata, MetadataValue};

        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        {
            let predictor = client
                .session
                .as_mut()
                .expect("session")
                .predictor_mut()
                .expect("JoinGame built the predictor");
            // The fixture's ray at yaw 0 is +Z.  Keep its x coordinate at 0.5 and place the
            // dynamic targets at x=0.9375, where the 0.1 collision border is included below.
            predictor.state.pos = DVec3::new(0.5, 64.0, 0.5);
        }
        // Facing +Z since the last ticks: the click aims with that head yaw (L7).
        client
            .session
            .as_mut()
            .expect("session")
            .face_local_player(0.0, 0.0);

        // A size-4 slime is 2.0400002 wide.  The old 0.6-wide table box misses this ray, while
        // the live box (including Java's 0.1 collision border) intersects it.
        let mut slime = Metadata::new();
        slime.set(16, MetadataValue::Byte(4));
        spawn_pick_target(&mut client, 10, E::Slime, [30, 2048, 96], slime);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(10),
            "size-4 slime must be picked through its live 2.0400002-wide box"
        );
        despawn_pick_target(&mut client, 10);

        // A child cow is half-width (0.45), while its adult constructor row is 0.9.  At this
        // x-coordinate the stale adult box would be selected, but Java's live child box must miss.
        let mut child_cow = Metadata::new();
        child_cow.set(12, MetadataValue::Byte(-1));
        spawn_pick_target(&mut client, 11, E::Cow, [30, 2080, 96], child_cow);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity(),
            None,
            "a child cow must not be picked through its adult-width constructor box"
        );
        let child_blockers = client.placement_blockers();
        assert!(
            child_blockers.iter().any(|bounds| {
                let size = bounds.max - bounds.min;
                (size.x - 0.45).abs() < 1.0e-6
                    && (size.y - 0.65).abs() < 1.0e-6
                    && (size.z - 0.45).abs() < 1.0e-6
            }),
            "placement collision must use the child cow's live half dimensions"
        );
        despawn_pick_target(&mut client, 11);

        // Horse foals use EntityHorse's age callback rather than a renderer-only scale.  Put the
        // ray between the adult and foal widths so the final pick consumer bites an adult-box
        // mutant, then verify the independently assembled placement collision box as well.
        let horse = E::EntityHorse.info();
        spawn_pick_target(
            &mut client,
            14,
            E::EntityHorse,
            [31, 2080, 96],
            Metadata::new(),
        );
        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(14),
            "the edge ray must hit an adult horse's live-width box"
        );
        assert!(client.placement_blockers().iter().any(|bounds| {
            let size = bounds.max - bounds.min;
            (size.x - f64::from(horse.width)).abs() < 1.0e-6
                && (size.y - f64::from(horse.height)).abs() < 1.0e-6
                && (size.z - f64::from(horse.width)).abs() < 1.0e-6
        }));

        set_pick_age(&mut client, 14, -1);
        tick_pick_dimensions(&mut client);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity(),
            None,
            "the same edge ray must miss the horse after its foal transition"
        );
        assert!(client.placement_blockers().iter().any(|bounds| {
            let size = bounds.max - bounds.min;
            (size.x - f64::from(horse.width * 0.5)).abs() < 1.0e-6
                && (size.y - f64::from(horse.height * 0.5)).abs() < 1.0e-6
                && (size.z - f64::from(horse.width * 0.5)).abs() < 1.0e-6
        }));

        set_pick_age(&mut client, 14, 0);
        tick_pick_dimensions(&mut client);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(14),
            "restoring adult age must restore the horse pick box"
        );
        despawn_pick_target(&mut client, 14);

        // A wither skeleton receives its 0.72 x 2.535 client box from onLivingUpdate, so drive
        // one tracker tick before the caller snapshot.  The static 0.6-wide row misses here.
        let mut wither = Metadata::new();
        wither.set(13, MetadataValue::Byte(1));
        spawn_pick_target(&mut client, 12, E::Skeleton, [30, 2048, 96], wither);
        tick_pick_dimensions(&mut client);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(12),
            "wither skeleton must be picked through its live 0.72-wide box"
        );
        despawn_pick_target(&mut client, 12);

        // Marker stands are resized to a zero box on the client tick and are also rejected by
        // canBeCollidedWith.  Assert both the exact box handed to the driver helper and the live
        // pick result, so a static full-size box cannot hide behind the predicate control.
        let mut marker = Metadata::new();
        marker.set(10, MetadataValue::Byte(0x10));
        spawn_pick_target(&mut client, 13, E::ArmorStand, [16, 2048, 96], marker);
        tick_pick_dimensions(&mut client);
        let (marker_dimensions, marker_bounds) = {
            let session = client.session.as_ref().expect("session");
            let state = session.state();
            let tracked = state.entities.get(13).expect("marker target");
            let dimensions = tracked.dimensions();
            let pos = tracked.render_position(&state.world, 1.0);
            let bounds = client.pick_bounds(
                &state.world,
                tracked,
                Some(E::ArmorStand),
                pos,
                dimensions.0,
                dimensions.1,
            );
            (dimensions, bounds)
        };
        assert_eq!(marker_dimensions, (0.0, 0.0));
        assert_eq!(marker_bounds.min, marker_bounds.max);
        client.update_hit_result();
        assert_eq!(
            client.hit.entity(),
            None,
            "marker stands remain absent from the entity pick result"
        );

        // The seam assertion is deliberately kept with the live controls: it catches a future
        // refactor that makes the numeric fixture pass through a copied helper while the actual
        // production caller regresses to the static table.
        let source = include_str!("driver.rs");
        let (_, pick) = source
            .split_once("fn pick_result_at(&self, eye: DVec3, yaw: f32, pitch: f32) -> HitResult {")
            .expect("the concrete driver pick remains present");
        let (pick, _) = pick
            .split_once("    /// The box `getMouseOver` intersects for one tracked entity.")
            .expect("the pick loop ends before its box helper");
        assert!(
            pick.contains("let (width, height) = tracked.dimensions();"),
            "the production pick loop must read live tracker dimensions"
        );
    }

    /// F-P1-entity.hitbox-SWEEP-4: packet targets are the end of a three-tick ease, not the
    /// current pick position. The ray intersects the zombie after one interpolation step but
    /// misses its packet target, so a target-position mutant drops both the hit and C02 attack.
    #[test]
    fn entity_pick_and_attack_use_the_current_mid_lerp_position_not_the_packet_target() {
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        {
            let predictor = client
                .session
                .as_mut()
                .expect("session")
                .predictor_mut()
                .expect("JoinGame built the predictor");
            predictor.state.pos = DVec3::new(0.5, 64.0, 0.5);
        }
        // Facing +Z since the last ticks: the click aims with that head yaw (L7).
        client
            .session
            .as_mut()
            .expect("session")
            .face_local_player(0.0, 0.0);

        const ENTITY_ID: i32 = 214;
        spawn_pick_target(
            &mut client,
            ENTITY_ID,
            mc_data::EntityType::Zombie,
            [16, 2048, 96],
            mc_world::entity::Metadata::new(),
        );
        {
            let state = client.session.as_mut().expect("session").state_mut();
            assert!(state.entities.apply_relative_move_grounded(
                &mut state.world,
                ENTITY_ID,
                [32, 0, 0],
                None,
                Some(true),
            ));
            state.entities.tick_interpolation(&mut state.world);
            let tracked = state
                .entities
                .get(ENTITY_ID)
                .expect("zombie remains tracked");
            let current = tracked.render_position(&state.world, 1.0);
            assert!((current.x - 0.833_333_333_333_333_3).abs() < 1.0e-12);
            assert!((tracked.target_pos.x - 1.5).abs() < 1.0e-12);
        }

        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(ENTITY_ID),
            "the current one-third-step box crosses the +Z ray; the target box does not"
        );
        client.click_mouse();
        let sent = drained(&mut to_net);
        assert!(
            sent.iter().any(|packet| matches!(
                packet,
                mc_protocol::play::C2SPlay::UseEntity(use_entity)
                    if use_entity.entity_id == ENTITY_ID
                        && use_entity.action == mc_protocol::play::c2s::UseEntityAction::Attack
            )),
            "the mid-lerp hit must survive through click_mouse into C02: {sent:?}"
        );
    }

    /// F-P1-util-08-1: `World.getEntitiesInAABBexcluding` walks chunk X, then Z, then ascending
    /// Y slices.  Two equal-distance zombie boxes are spawned in reverse world-list order; the
    /// Java bucket order must still choose the negative-X chunk first.  A direct unkeyed pick is
    /// also the negative control: geometry and strict `<` are intentionally identical, so the
    /// insertion-order result is known to be the opposite id.
    #[test]
    fn entity_pick_uses_java_chunk_order_before_tracker_insertion_order() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        {
            let predictor = client
                .session
                .as_mut()
                .expect("live test session")
                .predictor_mut()
                .expect("join built predictor");
            predictor.state.pos = DVec3::new(0.0, 64.0, 0.0);
        }
        // Facing +Z since the last ticks: the click aims with that head yaw (L7).
        client
            .session
            .as_mut()
            .expect("live test session")
            .face_local_player(0.0, 0.0);
        // Spawn +X first, then -X.  Both boxes are equally close to the +Z ray, but they occupy
        // chunk 0 and chunk -1 respectively.  Java's x-outer traversal therefore picks id 200.
        let insertion_order = {
            let state = client
                .session
                .as_mut()
                .expect("live test session")
                .state_mut();
            state.entities.spawn(
                &mut state.world,
                100,
                crate::sync::entities::TrackedKind::Type(mc_data::EntityType::Zombie),
                None,
                [10, 2048, 64],
                0.0,
                0.0,
                DVec3::ZERO,
                mc_world::entity::Metadata::new(),
            );
            state.entities.spawn(
                &mut state.world,
                200,
                crate::sync::entities::TrackedKind::Type(mc_data::EntityType::Zombie),
                None,
                [-10, 2048, 64],
                0.0,
                0.0,
                DVec3::ZERO,
                mc_world::entity::Metadata::new(),
            );
            state.entities.iter().map(|(id, _)| id).collect::<Vec<_>>()
        };
        assert_eq!(
            insertion_order,
            [100, 200],
            "the control must retain the deliberate reverse insertion order"
        );

        client.update_hit_result();
        assert_eq!(
            client.hit.entity().map(|hit| hit.network_id),
            Some(200),
            "the negative-X chunk wins before the reverse insertion-order id 100"
        );

        // Same eye/ray and same geometry, but deliberately bypass the production chunk key.
        // This proves the expected mutation: without the sort, strict `<` keeps id 100.
        let eye = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("join built predictor")
            .state
            .eye_pos();
        let look = interact::look_vector(0.0, 0.0);
        let world = &client
            .session
            .as_ref()
            .expect("live test session")
            .state()
            .world;
        let unkeyed = interact::pick_with_riding(
            world,
            eye,
            look,
            4.5,
            false,
            None,
            [
                interact::Pickable {
                    network_id: 100,
                    bounds: interact::size_bounding_box(DVec3::new(0.3125, 64.0, 2.0), 0.6, 1.95),
                    border_size: 0.1,
                    collidable: true,
                },
                interact::Pickable {
                    network_id: 200,
                    bounds: interact::size_bounding_box(DVec3::new(-0.3125, 64.0, 2.0), 0.6, 1.95),
                    border_size: 0.1,
                    collidable: true,
                },
            ],
        );
        assert_eq!(
            unkeyed.entity().map(|hit| hit.network_id),
            Some(100),
            "negative control: equal intercepts preserve the input order"
        );
    }

