    #[test]
    fn first_person_item_has_effect_uses_raw_potion_data_and_item_overrides() {
        let mut potion = stack_named("potion", 1);
        assert!(
            !first_person_item_has_effect(&potion),
            "plain metadata-zero potion has no ItemPotion effect"
        );
        potion.damage = 8_194;
        assert!(
            first_person_item_has_effect(&potion),
            "raw metadata 8194 must survive model canonicalization and foil"
        );

        // ItemPotion.getEffects reads the raw CustomPotionEffects list, even when metadata is the
        // otherwise-empty water potion. This is a biting control against looking only at the
        // already-selected baked model key or at the metadata colour path.
        potion.damage = 0;
        let mut effect = mc_nbt::NbtCompound::new();
        effect.insert("Id", mc_nbt::Nbt::Byte(1));
        effect.insert("Amplifier", mc_nbt::Nbt::Byte(0));
        effect.insert("Duration", mc_nbt::Nbt::Int(1_200));
        let mut root = mc_nbt::NbtCompound::new();
        root.insert(
            "CustomPotionEffects",
            mc_nbt::Nbt::list(vec![mc_nbt::Nbt::Compound(effect)]),
        );
        potion.nbt = Some(root);
        assert!(
            first_person_item_has_effect(&potion),
            "custom effects must foil an otherwise-empty raw potion"
        );

        for name in [
            "enchanted_book",
            "experience_bottle",
            "written_book",
            "nether_star",
        ] {
            assert!(
                first_person_item_has_effect(&stack_named(name, 1)),
                "{name} has an unconditional Item.hasEffect override"
            );
        }
        let mut apple = stack_named("golden_apple", 1);
        assert!(!first_person_item_has_effect(&apple));
        apple.damage = 1;
        assert!(first_person_item_has_effect(&apple));

        let source = include_str!("driver.rs");
        let (_, helper) = source
            .split_once("// <<FIRSTPERSONGLINT-HELPERS>>")
            .expect("the first-person predicate seam remains marker-bounded");
        let production = source
            .split_once("#[cfg(test)]\nmod tests {")
            .expect("driver keeps its inline test module")
            .0;
        assert!(helper.contains("mc_ui::screens::container::tooltip::has_effect(stack)"));
        assert!(helper.contains("minecraft:written_book"));
        assert!(helper.contains("minecraft:nether_star"));
        assert!(production.contains("phase.set_item_glint_enabled(item_has_effect);"));
        assert!(production.contains("load_glint_texture(gpu, &assets.resources);"));
    }

    #[test]
    fn first_person_builtin_item_route_keeps_descriptor_texture_and_glint_boundaries() {
        let source = include_str!("driver.rs");
        let production = source
            .split_once("#[cfg(test)]\nmod tests {")
            .expect("driver keeps its inline test module")
            .0;
        assert!(production.contains("builtin_tile_item_from_stack"));
        assert!(production.contains("builtin_tile_item_from_stack_with_players"));
        assert!(production.contains("phase.set_builtin_item_model(model, item);"));
        assert!(production.contains("phase.update_builtin_item(item);"));
        assert!(production.contains("Some((model.clone(), model.gui_3d))"));
        assert!(!production
            .contains("mc_data::item_props(id).block.is_some() && id != mc_data::ItemId(111)"));
        // "the hand still shows this stack" is now Java's object comparison.
        assert!(production.contains("} else if latch_matches {"));
        assert!(
            production.contains("phase.ensure_builtin_item_texture(gpu, &self.assets.resources);")
        );

        let swap = production
            .split_once("// <<FIRSTPERSONTILEITEM-SWAP>>")
            .expect("builtin swap marker remains in the production seam")
            .1;
        let swap = swap
            .split_once("// <<FIRSTPERSONTILEITEM-UPLOAD>>")
            .map_or(swap, |(body, _)| body);
        assert!(
            swap.contains("phase.set_builtin_item_model(model, item);")
                && swap.contains("RenderItem's builtin/entity branch")
        );
        assert!(
            !swap.contains("phase.set_item_glint_enabled(item_has_effect);")
                || swap.contains("(Some((model, gui_3d)), None)")
        );

        let mut skull = stack_named("skull", 1);
        skull.damage = 2;
        assert_eq!(
            crate::app::tiles::builtin_tile_item_from_stack(&skull),
            Some(mc_render::entity::tilepass::BuiltinTileItem::Skull { skull_type: 2 })
        );
        assert!(
            crate::app::tiles::builtin_tile_item_from_stack(&stack_named("stone", 1)).is_none(),
            "ordinary baked items stay on the atlas route"
        );
    }

    // ---- EntityRenderer.hurtCameraEffect -----------------------------

    fn matrix_close(actual: mc_render::entity::Mat4, expected: mc_render::entity::Mat4) {
        for (index, (actual, expected)) in actual
            .to_cols_array()
            .into_iter()
            .zip(expected.to_cols_array())
            .enumerate()
        {
            assert!(
                (actual - expected).abs() < 1.0e-6,
                "matrix entry {index}: {actual} != {expected}"
            );
        }
    }

    // The F5 rays' asymmetric end point (Java adds the corner's Z offset to the end's X too)
    // moved with the rest of the ray into `mods::w5_grass::third_person_camera_distance`, whose
    // tests compare it bit for bit with the real 1.8.9 classes (`javaref/CameraRayRef.java`).

    #[test]
    fn particle_upload_handoff_tracks_local_angles_and_every_f5_mode() {
        let camera = Camera {
            yaw: 217.0,
            pitch: 31.0,
            ..Camera::default()
        };
        let raw = Some((37.0, -23.0));

        let first = particle_upload_camera(&camera, raw, 0);
        let rear = particle_upload_camera(&camera, raw, 1);
        let front = particle_upload_camera(&camera, raw, 2);

        assert_eq!((first.yaw, first.pitch), (37.0, -23.0));
        assert_eq!((rear.yaw, rear.pitch), (37.0, -23.0));
        assert_eq!((front.yaw, front.pitch), (37.0, -23.0));
        assert_eq!(
            first.view.x_axis.w, 0.0,
            "first-person handoff must not carry a front-view sign"
        );
        assert_eq!(
            rear.view.x_axis.w, 1.0,
            "rear F5 needs its own explicit mode even though its basis is unchanged"
        );
        assert_eq!(
            front.view.x_axis.w, -1.0,
            "front F5 is the only Java ActiveRenderInfo sign-flipped mode"
        );

        // A mode switch must not mutate the live frame camera. This is the narrow handoff edge:
        // the phase receives a copy with raw local angles while GPU recording still receives the
        // already-positioned camera passed to `frame`.
        assert_eq!((camera.yaw, camera.pitch), (217.0, 31.0));

        let fallback = particle_upload_camera(
            &Camera {
                yaw: 217.0,
                pitch: 31.0,
                ..Camera::default()
            },
            None,
            2,
        );
        assert_eq!((fallback.yaw, fallback.pitch), (37.0, -31.0));
    }

