    #[test]
    fn death_camera_uses_the_java_roll_formula_and_partial_ticks() {
        let death_time = 7;
        let partial_ticks = 0.375_f32;
        let f1 = death_time as f32 + partial_ticks;
        let roll = 40.0_f32 - 8000.0_f32 / (f1 + 200.0_f32);
        let expected = mc_render::entity::Mat4::from_rotation_z(roll.to_radians());
        matrix_close(death_camera_transform(death_time, partial_ticks), expected);

        // Before the first death update there is no roll at the exact tick boundary, while a
        // fractional frame already does. This catches both a missing partial-tick term and an
        // off-by-one death counter in the renderer consumer.
        matrix_close(
            death_camera_transform(0, 0.0),
            mc_render::entity::Mat4::IDENTITY,
        );
        assert!(
            death_camera_transform(0, 0.5)
                .to_cols_array()
                .into_iter()
                .zip(mc_render::entity::Mat4::IDENTITY.to_cols_array())
                .any(|(actual, identity)| (actual - identity).abs() > 1.0e-6),
            "partial death frames must consume the fractional deathTime"
        );
    }

    #[test]
    fn death_fov_zoom_matches_vanilla_and_is_neutral_before_death() {
        let base = 1.15_f32;
        let death_time = 17;
        let partial_ticks = 0.25_f32;
        let f1 = death_time as f32 + partial_ticks;
        let denominator = (1.0_f32 - 500.0_f32 / (f1 + 500.0_f32)) * 2.0_f32 + 1.0_f32;
        let expected = base / denominator;
        let actual = death_fov_modifier(base, death_time, partial_ticks);
        assert!((actual - expected).abs() < 1.0e-7, "{actual} != {expected}");
        assert!(actual < base, "the death zoom narrows the field of view");

        assert_eq!(
            death_fov_modifier(base, 0, 0.0),
            base,
            "zero deathTime at the tick boundary has no zoom yet"
        );
        assert_ne!(
            death_fov_modifier(base, death_time, partial_ticks),
            base,
            "negative control: omitting the death divide must not satisfy this sample"
        );
    }

    #[test]
    fn hurt_camera_uses_partial_ticks_and_the_java_sine_table() {
        // `f = (float)hurtTime - partialTicks`, then the left-associated f32 fourth power and
        // `MathHelper.sin`. This deliberately picks a non-boundary fraction: using libm sine,
        // forgetting partial ticks, or doing the power in f64 all choose a different roll.
        let partial_ticks = 0.25;
        let raw = 5.0_f32 - partial_ticks;
        let normalized = raw / 10.0;
        let wave = sin(normalized * normalized * normalized * normalized * std::f32::consts::PI);
        let expected = mc_render::entity::Mat4::from_rotation_z((-wave * 14.0).to_radians());
        let actual = hurt_camera_transform(5, 10, 0.0, partial_ticks);
        matrix_close(actual, expected);

        let no_partial = hurt_camera_transform(5, 10, 0.0, 0.0);
        assert!(
            actual
                .to_cols_array()
                .into_iter()
                .zip(no_partial.to_cols_array())
                .any(|(left, right)| (left - right).abs() > 1.0e-5),
            "negative control: a partial-tick-free kick must not satisfy this sample"
        );
    }

    #[test]
    fn hurt_camera_conjugates_the_roll_by_attacked_yaw() {
        let hurt = 6.0_f32 / 10.0;
        let wave = sin(hurt * hurt * hurt * hurt * std::f32::consts::PI);
        let expected = mc_render::entity::Mat4::from_rotation_y((-90.0_f32).to_radians())
            * mc_render::entity::Mat4::from_rotation_z((-wave * 14.0).to_radians())
            * mc_render::entity::Mat4::from_rotation_y(90.0_f32.to_radians());
        let actual = hurt_camera_transform(6, 10, 90.0, 0.0);
        matrix_close(actual, expected);

        let screen_roll = hurt_camera_transform(6, 10, 0.0, 0.0);
        assert!(
            actual
                .to_cols_array()
                .into_iter()
                .zip(screen_roll.to_cols_array())
                .any(|(left, right)| (left - right).abs() > 1.0e-4),
            "negative control: omitting attackedAtYaw must visibly change an off-axis hit"
        );
    }

    #[test]
    fn hurt_camera_expires_after_the_partial_tick_but_keeps_zero_tick_java_order() {
        assert_eq!(
            hurt_camera_transform(0, 10, 37.0, 0.25).to_cols_array(),
            mc_render::entity::Mat4::IDENTITY.to_cols_array(),
            "Java returns when hurtTime - partialTicks is negative"
        );

        // At exactly zero Java does not return; its yaw / zero-roll / inverse-yaw sequence is
        // still submitted. This pins the branch to `< 0`, rather than the tempting `<= 0`.
        let at_zero = hurt_camera_transform(0, 10, 37.0, 0.0);
        let java_zero = mc_render::entity::Mat4::from_rotation_y((-37.0_f32).to_radians())
            * mc_render::entity::Mat4::from_rotation_z(0.0)
            * mc_render::entity::Mat4::from_rotation_y(37.0_f32.to_radians());
        matrix_close(at_zero, java_zero);
    }

    #[test]
    fn view_bobbing_interpolates_walk_and_camera_springs_in_java_order() {
        let mut state = mc_physics::PhysicsState::new_player(DVec3::ZERO);
        state.prev_distance_walked_modified = 0.5;
        state.distance_walked_modified = 1.0;
        state.prev_camera_yaw = 0.1;
        state.camera_yaw = 0.2;
        state.prev_camera_pitch = 0.05;
        state.camera_pitch = 0.15;
        let partial_ticks = 0.5;

        let walked = -(1.0_f32 + (1.0_f32 - 0.5_f32) * partial_ticks);
        let yaw = 0.1_f32 + (0.2_f32 - 0.1_f32) * partial_ticks;
        let pitch = 0.05_f32 + (0.15_f32 - 0.05_f32) * partial_ticks;
        let phase = walked * std::f32::consts::PI;
        let expected = mc_render::entity::Mat4::from_translation(Vec3::new(
            mc_math::sin(phase) * yaw * 0.5,
            -(mc_math::cos(phase) * yaw).abs(),
            0.0,
        )) * mc_render::entity::Mat4::from_rotation_z(
            (mc_math::sin(phase) * yaw * 3.0).to_radians(),
        ) * mc_render::entity::Mat4::from_rotation_x(
            ((mc_math::cos(phase - 0.2) * yaw).abs() * 5.0).to_radians(),
        ) * mc_render::entity::Mat4::from_rotation_x(pitch.to_radians());
        matrix_close(view_bobbing_transform(&state, partial_ticks), expected);

        let still = mc_physics::PhysicsState::new_player(DVec3::ZERO);
        matrix_close(
            view_bobbing_transform(&still, partial_ticks),
            mc_render::entity::Mat4::IDENTITY,
        );
    }

