    #[test]
    fn portal_camera_matrix_uses_partial_tick_and_nausea_spin() {
        let previous = 0.25_f32;
        let current = 0.75_f32;
        let partial_ticks = 0.5_f32;
        let tick = 42_u64;
        let portal = previous + (current - previous) * partial_ticks;
        let mut squash = 5.0_f32 / (portal * portal + 5.0_f32) - portal * 0.04_f32;
        squash *= squash;
        let angle = (tick as f32 + partial_ticks) * 7.0_f32;
        let axis = Vec3::new(0.0, 1.0, 1.0).normalize();
        let expected = mc_render::entity::Mat4::from_axis_angle(axis, angle.to_radians())
            * mc_render::entity::Mat4::from_scale(Vec3::new(1.0 / squash, 1.0, 1.0))
            * mc_render::entity::Mat4::from_axis_angle(axis, (-angle).to_radians());
        let actual = portal_camera_transform(previous, current, partial_ticks, tick, true);
        matrix_close(actual, expected);

        matrix_close(
            portal_camera_transform(0.0, 0.0, partial_ticks, tick, true),
            mc_render::entity::Mat4::IDENTITY,
        );
        let ordinary = portal_camera_transform(previous, current, partial_ticks, tick, false);
        assert!(
            actual
                .to_cols_array()
                .into_iter()
                .zip(ordinary.to_cols_array())
                .any(|(nausea, portal)| (nausea - portal).abs() > 1.0e-5),
            "confusion must select the seven-degree spin rather than portal contact's twenty"
        );
    }

    #[test]
    fn place_camera_reads_live_hurt_timers_after_building_the_base_orientation() {
        // The pure helper tests above would still pass if a refactor silently stopped applying
        // it to the camera. Keep this guard deliberately narrow: it pins the production seam,
        // including the non-commutative order relative to `Camera::update`, without pretending
        // a GPU frame is a useful oracle for a four-matrix CPU operation.
        // `rustfmt` keeps the live tuple one field per line in this driver shape. Check the
        // field reads independently so formatting cannot turn a truthful seam into a false
        // failure, while a stale constant/remote-render tuple still fails the guard.
        let source = include_str!("driver.rs");
        let (_, place_camera) = source
            .split_once("fn place_camera(&self, camera: &mut Camera, partial_ticks: f32) {")
            .expect("the concrete camera producer remains present");
        let (place_camera, _) = place_camera
            .split_once("fn upload_terrain(")
            .expect("the camera producer ends before terrain upload");
        let update = place_camera
            .find("camera.update();")
            .expect("orientCamera-equivalent matrix must be built");
        let hurt = place_camera
            .find("hurt_camera_transform(hurt_time, max_hurt_time, 0.0, partial_ticks)")
            .expect("hurtCameraEffect must feed the live camera");
        assert!(
            update < hurt,
            "hurt camera matrix must pre-multiply the completed orientCamera view"
        );
        assert!(
            place_camera.contains("local.hurt_time")
                && place_camera.contains("local.max_hurt_time"),
            "the producer must read the live LocalPlayer hurt timers, not HUD mirror state"
        );
    }

