    /// java: `EntityRenderer.updateFovModifierHand` calls
    /// `getFovModifier()` on the render view entity (`instanceof AbstractClientPlayer`). While
    /// spectating a remote player (S43), that player's own bow draw (`EntityOtherPlayerMP`'s
    /// watched use flag and `getItemInUseDuration()`) zooms the view; the local player's item
    /// state is not consulted. The old client always read the local controller, so a spectated
    /// bow draw never zoomed. A non-player view entity keeps `f = 1.0F`.
    #[test]
    fn spectating_a_player_uses_their_bow_draw_for_the_fov_zoom() {
        use crate::sync::entities::TrackedKind;
        use mc_protocol::{MetadataEntry, MetadataValue as Wire};

        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let bow = mc_protocol::ItemStack {
            item_id: 261,
            count: 1,
            damage: 0,
            nbt: None,
        };
        {
            let session = client.session.as_mut().expect("session");
            let state = session.state_mut();
            state.entities.spawn(
                &mut state.world,
                2,
                TrackedKind::Player,
                Some(uuid::Uuid::nil()),
                [0, 2048, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                mc_world::entity::Metadata::new(),
            );
            assert!(state.entities.apply_equipment(2, 0, Some(bow)));
            assert!(state.entities.apply_metadata(
                &mut state.world,
                2,
                &vec![MetadataEntry {
                    index: 0,
                    value: Wire::Byte(0x10),
                }],
            ));
            // The edge tick installs the 72000-tick use; twenty more draw it for 20 ticks.
            for _ in 0..21 {
                state.entities.tick_interpolation(&mut state.world);
            }
            session.set_render_view_entity(2);
        }
        let session = client.session.as_ref().expect("session");
        assert!(matches!(
            session.render_view_target(),
            crate::session::RenderViewTarget::Entity { network_id: 2, .. }
        ));
        let duration = session
            .state()
            .entities
            .get(2)
            .and_then(crate::sync::entities::TrackedEntity::remote_bow_use_duration);
        assert_eq!(duration, Some(20));

        client.fov_modifier_hand = 1.0;
        client.update_fov_modifier_hand();
        let walk = mc_physics::state::WALK_SPEED as f32;
        let expected =
            step_fov_modifier_hand(1.0, fov_modifier_target(false, walk, walk, Some(20)));
        assert_eq!(client.fov_modifier_hand, expected);
        assert!(expected < 1.0, "a full draw narrows the spectated view");

        // A non-player camera is not an AbstractClientPlayer: `f` stays 1.0.
        {
            let session = client.session.as_mut().expect("session");
            let state = session.state_mut();
            state.entities.spawn(
                &mut state.world,
                3,
                TrackedKind::Type(mc_data::EntityType::Zombie),
                None,
                [0, 2048, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                mc_world::entity::Metadata::new(),
            );
            session.set_render_view_entity(3);
        }
        client.fov_modifier_hand = 0.5;
        client.update_fov_modifier_hand();
        assert_eq!(client.fov_modifier_hand, step_fov_modifier_hand(0.5, 1.0));
    }

