    #[test]
    fn client_tick_produces_local_death_time_at_the_world_tick_boundary() {
        let source = include_str!("driver.rs");
        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("the concrete client tick remains present");
        let (tick, _) = tick
            .split_once("fn upload_terrain(")
            .expect("the tick implementation ends before frame-only terrain work");
        let session_tick = tick
            .find("session.tick_with_held(input, held.as_ref());")
            .expect("the session world tick remains the local entity boundary");
        let death_tick = tick
            .find("session.state_mut().local.tick_living_state();")
            .expect("local death_time must be produced by the client tick");
        let phase_gate = tick
            .find("if matches!(session.phase(), crate::session::Phase::Playing)")
            .expect("local entity lifecycle must remain inside the playing-world gate");
        assert!(
            session_tick < death_tick,
            "the local EntityLivingBase tail follows Session::tick: session={session_tick}, death={death_tick}"
        );
        assert!(
            phase_gate < death_tick,
            "the lifecycle call belongs inside the world-tick phase gate"
        );
    }

    #[test]
    fn live_rain_scheduler_is_not_helper_only() {
        // The renderer helper can be perfectly unit-tested while the game remains dry if its
        // caller is accidentally removed. Keep the omitted-caller mutant visible at the actual
        // client tick boundary, and require its particle/audio fan-out to stay wired.
        let source = include_str!("driver.rs");
        let (_, tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("the concrete client tick remains present");
        let (tick, _) = tick
            .split_once("fn upload_terrain(")
            .expect("the tick implementation ends before frame-only terrain work");
        let rain_call = tick
            .find("self.tick_rain_particles();")
            .expect("live tick must call the rain scheduler");
        let world_tick = tick
            .find("session.tick_with_held(")
            .expect("the live world tick remains present");
        assert!(
            rain_call < world_tick,
            "addRainParticles runs before WorldClient.updateEntities"
        );

        let (_, rain) = source
            .split_once("fn tick_rain_particles(&mut self) {")
            .expect("the concrete rain scheduler remains present");
        let (rain, _) = rain
            .split_once("fn tick_barrier_reveal_particles(")
            .expect("the rain scheduler ends before the ambient world scheduler");
        assert!(rain.contains("mc_render::sky::add_rain_particles("));
        assert!(rain.contains("self.spawn_effect_particle("));
        assert!(rain.contains("self.play_sound("));
    }

    #[test]
    fn precipitation_builds_from_raw_view_entity_feet_not_the_frame_camera() {
        // java: `EntityRenderer.renderRainSnow:1603-1616,1684-1717` uses the current raw
        // `entity.posX/Y/Z` for both the search centre and fade, even though it later translates
        // the submitted geometry by a separately interpolated position. This must remain true
        // at every partial-tick boundary and while F5 has displaced the actual frame camera.
        let mut state = mc_physics::PhysicsState::new_player(DVec3::new(104.875, 70.125, -29.25));
        let prev = DVec3::new(96.25, 64.0, -40.75);
        state.prev_pos = prev;
        let raw = precipitation_view_entity_pos(&state);
        assert_eq!(
            raw, state.pos,
            "weather uses Entity.pos, not an eye position"
        );

        for partial_ticks in [0.0, 0.5, 1.0] {
            assert_ne!(
                raw,
                interpolated_eye(Some(prev), &state, partial_ticks),
                "partial_ticks={partial_ticks}: the raw weather position must not lerp"
            );
        }
        let third_person_camera = DVec3::new(111.0, 73.0, -34.0);
        assert_ne!(raw, third_person_camera, "the F5 orbit is translation-only");

        // Guard the driver edge too: a helper-only test would pass if a later edit wired
        // `build_columns` back to `camera.pos`.
        let source = include_str!("driver.rs");
        let (_, atmosphere) = source
            .split_once(
                "fn drive_atmosphere(&mut self, gpu: &Gpu, camera: &Camera, partial_ticks: f32) {",
            )
            .expect("the concrete atmosphere producer remains present");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("the weather producer ends before particle upload");
        assert!(
            atmosphere.contains("session.render_view_position(1.0)"),
            "build inputs must originate at the raw render-view entity"
        );
        assert!(
            atmosphere.contains("view_pos.x.to_bits()")
                && atmosphere.contains("view_pos.y.to_bits()")
                && atmosphere.contains("view_pos.z.to_bits()"),
            "the cache key must track every raw build-position axis"
        );
        let (_, build_call) = atmosphere
            .split_once("mc_render::sky::build_columns(")
            .expect("the concrete precipitation build call remains present");
        let (build_call, _) = build_call
            .split_once("render.weather.with(|phase| phase.upload(columns));")
            .expect("the precipitation build call retains its upload edge");
        assert!(build_call.contains("view_pos"));
        assert!(
            !build_call.contains("camera.pos"),
            "the transformed frame camera may translate quads but cannot choose their columns"
        );
    }

