    #[test]
    fn eye_height_is_added_after_the_lerp_and_is_not_itself_interpolated() {
        // java: `float f = entity.getEyeHeight();` is read once, before the three lerps, and
        // added to `d1` afterwards — so crouching still steps at 20 Hz in vanilla too. This
        // pins the ordering: interpolating the *eye* instead of the *feet* would make a player
        // who started sneaking this tick drift downward across the frames of that tick.
        let mut standing = mc_physics::state::PhysicsState::new_player(DVec3::new(0.0, 64.0, 0.0));
        standing.sneaking = false;
        let mut sneaking = standing;
        sneaking.sneaking = true;

        let prev = Some(DVec3::new(0.0, 64.0, 0.0));
        // Same feet, same `partial_ticks`: the only difference is the eye height, and it must
        // appear in full immediately rather than being blended in.
        let drop =
            interpolated_eye(prev, &standing, 0.5).y - interpolated_eye(prev, &sneaking, 0.5).y;
        assert!(
            (drop - 0.08).abs() < 1e-6,
            "the sneak crouch must be applied whole, got {drop}"
        );
    }

    #[test]
    fn firstperson_eye_brightness_uses_the_current_eye_block_not_a_lerped_or_body_sample() {
        // java: `Entity.getBrightness(partialTicks)` adds the current `getEyeHeight()` to the
        // current feet position. The old generic body-light helper could sample a different block
        // and the pre-feed overlay always stayed at 1.0, so keep those controls visibly distinct.
        let mut world = mc_world::World::new();
        world.set_has_sky_light(false);
        world.load_empty_chunk(mc_math::ChunkPos::new(0, 0));
        let previous_body_block = BlockPos::new(0, 65, 0);
        let current_eye_block = BlockPos::new(0, 66, 0);
        world.set_light_for(mc_world::SkyBlock::Block, previous_body_block, 2);
        world.set_light_for(mc_world::SkyBlock::Block, current_eye_block, 6);

        let mut state = mc_physics::state::PhysicsState::new_player(DVec3::new(0.25, 64.5, 0.25));
        state.prev_pos = DVec3::new(0.25, 63.5, 0.25);
        let table =
            mc_render::sky::lightmap::light_brightness_table(Dimension::Overworld.ambient_light());
        let brightness = eye_block_brightness_for_state(&world, &state, Dimension::Overworld);
        assert_eq!(
            brightness, table[6],
            "the sample must be the current eye block"
        );
        assert_ne!(brightness, table[2], "a previous/body sample must not win");
        assert_ne!(
            brightness, 1.0,
            "a live eye light must replace the old bright fallback"
        );

        world.set_has_sky_light(true);
        world.set_light_for(mc_world::SkyBlock::Sky, previous_body_block, 3);
        world.set_light_for(mc_world::SkyBlock::Sky, current_eye_block, 13);
        assert_eq!(
            eye_combined_light_for_state(&world, &state),
            (6 << 4) | (13 << 20),
            "the F5 lightmap coordinate must pack the current eye cell, not the body cell"
        );

        let unloaded = mc_world::World::new();
        assert_eq!(
            eye_block_brightness_for_state(&unloaded, &state, Dimension::Overworld),
            0.0,
            "vanilla's unloaded eye-block guard returns zero"
        );
        assert_eq!(
            eye_combined_light_for_state(&unloaded, &state),
            0,
            "getBrightnessForRender also returns zero for an unloaded eye cell"
        );
        assert_eq!(
            combined_light_at_loaded_sample(&unloaded, current_eye_block),
            0,
            "tracked entities must not receive blank-column skylight either"
        );

        let source = include_str!("driver.rs");
        let (_, frame) = source
            .split_once("// <<FIRSTPERSONFEEDS-FRAME>>")
            .expect("the live overlay feed marker remains present");
        assert!(
            frame.contains("eye_block_brightness_for_state(")
                && frame.contains("phase.set_water_brightness(eye_block_brightness);"),
            "the frame must feed the exact eye-block brightness into OverlayPhase"
        );
        let (_, f5) = source
            .split_once("// <<LOCAL-F5-LIGHT>>")
            .expect("the local third-person light marker remains present");
        assert!(
            f5.contains("eye_combined_light_for_state(")
                && f5.contains("push_entity_geometry_lit("),
            "the local F5 body must use its packed eye light instead of full bright"
        );
        let (_, remote_tail) = source
            .split_once("// <<REMOTE-ENTITY-EYE-LIGHT>>")
            .expect("the tracked-entity light marker remains present");
        let (remote, _) = remote_tail
            .split_once("let combined_light =")
            .expect("the packed sample remains immediately before the entity override");
        assert!(
            remote.contains("combined_light_at_loaded_sample(world, light_pos)"),
            "tracked bodies and their layers must share the loaded eye-cell guard"
        );
    }

    #[test]
    fn render_manager_burning_override_is_terminal_and_narrow() {
        let dark_world = 0;
        let ordinary = 7 << 20 | 5 << 4;
        assert_eq!(
            entity_combined_light_with_burning_override(dark_world, false),
            dark_world,
            "ordinary unlit entities retain their sampled world light"
        );
        assert_eq!(
            entity_combined_light_with_burning_override(ordinary, false),
            ordinary,
            "the clear-fire path must not make ordinary entities full-bright"
        );
        assert_eq!(
            entity_combined_light_with_burning_override(dark_world, true),
            mc_render::entity::render::FULL_BRIGHT_COMBINED_LIGHT,
            "RenderManager replaces the packed light for burning entities"
        );
        assert_eq!(
            entity_combined_light_with_burning_override(
                mc_render::entity::render::FULL_BRIGHT_COMBINED_LIGHT,
                true,
            ),
            mc_render::entity::render::FULL_BRIGHT_COMBINED_LIGHT,
            "the terminal override preserves an entity-specific full-bright value"
        );

        let source = include_str!("driver.rs");
        let (_, remote) = source
            .split_once("// <<REMOTE-ENTITY-EYE-LIGHT>>")
            .expect("tracked entity light marker remains present");
        assert!(
            remote.contains("let entity_combined_light =")
                && remote.contains("entity_combined_light_with_burning_override(")
                && remote.contains("appearance::is_burning(world, tracked)"),
            "tracked uploads must apply burning after the concrete entity light selection"
        );
        let (_, local) = source
            .split_once("// <<LOCAL-F5-LIGHT>>")
            .expect("local F5 light marker remains present");
        assert!(
            local.contains("entity_combined_light_with_burning_override(")
                && local.contains("session.local_fire_timer() > 0"),
            "the local third-person upload must include its private fire timer"
        );
    }

