    // ---- `Camera::fov_modifier` is actually driven --------------------

    #[test]
    fn sprinting_widens_the_field_of_view_and_standing_still_does_not() {
        // java: `AbstractClientPlayer.getFovModifier:119` —
        // `f * ((attributeValue / walkSpeed + 1.0) / 2.0)`. The `movementSpeed` attribute is
        // `0.1` walking and `0.1 * 1.3` sprinting (`setSprinting`'s operation-2 modifier), and
        // `capabilities.walkSpeed` is `0.1`, so the two targets are exactly 1.0 and 1.15.
        let mut walking = mc_physics::PhysicsState::new_player(DVec3::ZERO);
        walking.set_sprinting(false);
        let mut sprinting = walking;
        // `setSprinting(true)` installs the attribute entry the FOV reads, not just the flag.
        sprinting.set_sprinting(true);

        let neutral = fov_modifier_target(false, walking.ai_move_speed(), 0.1, None);
        assert!(
            (neutral - 1.0).abs() < 1e-6,
            "walking must be neutral, got {neutral}"
        );
        let sprint = fov_modifier_target(false, sprinting.ai_move_speed(), 0.1, None);
        assert!(
            (sprint - 1.15).abs() < 1e-5,
            "sprinting must widen to 1.15, got {sprint}"
        );

        // java: `if (this.capabilities.isFlying) { f *= 1.1F; }`, applied before the ratio.
        let flying = fov_modifier_target(true, walking.ai_move_speed(), 0.1, None);
        assert!(
            (flying - 1.1).abs() < 1e-5,
            "flying must widen to 1.1, got {flying}"
        );

        // java: the `walkSpeed == 0.0F || isNaN || isInfinite` guard. A server that sets the
        // walk speed to zero must not produce an infinite FOV.
        assert_eq!(fov_modifier_target(false, 0.1, 0.0, None), 1.0);

        let half_draw = fov_modifier_target(false, walking.ai_move_speed(), 0.1, Some(10));
        assert!(
            (half_draw - 0.9625).abs() < 1e-6,
            "ten bow-use ticks must apply the squared half-draw multiplier"
        );
        let full_draw = fov_modifier_target(false, walking.ai_move_speed(), 0.1, Some(20));
        assert!(
            (full_draw - 0.85).abs() < 1e-6,
            "twenty bow-use ticks must clamp at vanilla's 0.85 multiplier"
        );
    }

    #[test]
    fn live_bow_fov_samples_before_the_item_use_count_is_decremented() {
        let source = include_str!("driver.rs");
        let sample = source
            .find("self.update_fov_modifier_hand();")
            .expect("live FOV sample");
        let decrement = source
            .find(".tick_item_in_use_at_slot(held.as_ref(), held_slot, held_identity);")
            .expect("live item-use decrement");
        assert!(
            sample < decrement,
            "FOV must sample the bow-use count before the same tick decrements it"
        );

        let elapsed_ten = fov_modifier_target(false, 0.1, 0.1, Some(10));
        let pre_decrement = step_fov_modifier_hand(1.0, elapsed_ten);
        assert!(
            (pre_decrement - 0.98125).abs() < 1.0e-6,
            "elapsed tick 10 must be sampled before decrement: {pre_decrement}"
        );

        let elapsed_eleven = fov_modifier_target(false, 0.1, 0.1, Some(11));
        let delayed_mutant = step_fov_modifier_hand(1.0, elapsed_eleven);
        assert!(
            (delayed_mutant - 0.9773125).abs() < 1.0e-6,
            "post-decrement control changed unexpectedly: {delayed_mutant}"
        );
        assert_ne!(pre_decrement.to_bits(), delayed_mutant.to_bits());

        assert_eq!(fov_modifier_target(false, 0.1, 0.1, None), 1.0);
        assert!((fov_modifier_target(false, 0.13, 0.1, None) - 1.15).abs() < 1.0e-6);
    }

    #[test]
    fn live_first_person_bow_model_uses_all_three_pull_variants_and_restores_base() {
        let state = |action, elapsed_duration| interact::ItemUseRenderState {
            action,
            remaining_count: 72_000 - elapsed_duration,
            max_duration: 72_000,
            elapsed_duration,
        };
        assert_eq!(bow_model_variant(None), 0);
        assert_eq!(
            bow_model_variant(Some(state(interact::ItemUseAction::Eat, 40))),
            0,
            "a non-bow use cannot select a pulling model"
        );
        for (elapsed, variant) in [(0, 0), (1, 1), (13, 1), (14, 2), (17, 2), (18, 3)] {
            assert_eq!(
                bow_model_variant(Some(state(interact::ItemUseAction::Bow, elapsed))),
                variant,
                "wrong raw bow model at elapsed tick {elapsed}"
            );
        }

        let source = include_str!("driver.rs");
        assert!(
            source.contains(
                "mc_assets::item_model_override_for_variant(id, bow_model_variant(use_state))"
            ) && source.contains("first_person_equip::refreshes_held_model(")
                && source.contains("dynamic_bow,"),
            "the live first-person caller must refresh pulling stages without an equip swap"
        );
    }

    #[test]
    fn the_fov_modifier_eases_halfway_each_tick_and_clamps_to_vanillas_range() {
        // java: `updateFovModifierHand:532` — `fovModifierHand += (f - fovModifierHand) * 0.5F`,
        // then `> 1.5 -> 1.5` and `< 0.1 -> 0.1`. Halving is what makes sprint FOV ease in over
        // a few ticks rather than snapping.
        let mut hand = 1.0_f32;
        hand = step_fov_modifier_hand(hand, 1.15);
        assert!((hand - 1.075).abs() < 1e-6, "first tick: {hand}");
        hand = step_fov_modifier_hand(hand, 1.15);
        assert!((hand - 1.1125).abs() < 1e-6, "second tick: {hand}");

        // It converges rather than overshooting, and never reaches the target exactly.
        for _ in 0..40 {
            hand = step_fov_modifier_hand(hand, 1.15);
        }
        assert!((hand - 1.15).abs() < 1e-4 && hand <= 1.15);

        // The clamp is on the *stored* value, so an absurd target is capped and stays capped.
        assert_eq!(step_fov_modifier_hand(1.4, 10.0), 1.5);
        assert_eq!(step_fov_modifier_hand(0.2, -10.0), 0.1);
    }

    #[test]
    fn camera_medium_follows_the_render_camera_not_the_player_eye() {
        // java: `ActiveRenderInfo.getBlockAtEntityViewpoint` samples the camera point produced by
        // `orientCamera`, while `Entity.isInsideOfMaterial` (HUD air and water overlay) samples
        // the local player's eye. These two deliberately crossed controls must remain distinct:
        // a submerged player can have a dry F5 orbit, and a dry player can orbit into water.
        let mut world = mc_world::World::new();
        world.load_empty_chunk(BlockPos::new(0, 64, 0).chunk_pos());
        let water = mc_data::BlockState::new(
            mc_data::block_by_name("water").expect("vanilla water registry row"),
            0,
        );
        // A full source column under the player's eye; the orbit sample is placed above it.
        for y in 64..=65 {
            world.set_block(BlockPos::new(0, y, 0), water);
        }

        let submerged_player =
            mc_physics::state::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5));
        assert!(mc_physics::player::is_inside_of_material(
            &world,
            &submerged_player,
            Material::Water
        ));
        let dry_orbit = DVec3::new(0.5, 66.5, 0.5);
        assert_eq!(
            camera_medium_at(&world, dry_orbit),
            CameraMedium::Air,
            "a dry camera must not inherit the player's submerged eye medium"
        );

        let dry_player = mc_physics::state::PhysicsState::new_player(DVec3::new(2.5, 64.0, 0.5));
        assert!(!mc_physics::player::is_inside_of_material(
            &world,
            &dry_player,
            Material::Water
        ));
        let wet_orbit = DVec3::new(0.5, 65.5, 0.5);
        assert_eq!(
            camera_medium_at(&world, wet_orbit),
            CameraMedium::Water,
            "a submerged camera must fog a dry player"
        );

        // The production guards make the helper-only controls bite the actual driver edges.
        let source = include_str!("driver.rs");
        let (_, atmosphere) = source
            .split_once(
                "fn drive_atmosphere(&mut self, gpu: &Gpu, camera: &Camera, partial_ticks: f32) {",
            )
            .expect("the concrete atmosphere producer remains present");
        let (atmosphere, _) = atmosphere
            .split_once("fn upload_particles(")
            .expect("the atmosphere producer ends before particle upload");
        assert!(
            atmosphere.contains("medium = camera_medium_at(&session.state().world, camera.pos);"),
            "fog medium must come from the frame camera after place_camera"
        );
        let (_, fov) = source
            .split_once("fn fov_modifier(&self, camera_pos: DVec3, partial_ticks: f32) -> f32 {")
            .expect("the concrete FOV producer remains present");
        let (fov, _) = fov
            .split_once("fn snapshot_prev_pos(")
            .expect("the FOV producer ends before camera snapshots");
        assert!(
            fov.contains("camera_medium_at(&session.state().world, camera_pos)"),
            "the underwater FOV squeeze must use the actual camera point"
        );
        assert!(
            !fov.contains("self.eye_medium()"),
            "FOV must not fall back to the player-eye medium"
        );
        let (_, place_camera) = source
            .split_once("fn place_camera(&self, camera: &mut Camera, partial_ticks: f32) {")
            .expect("the camera producer remains present");
        assert!(
            place_camera.contains("self.fov_modifier(camera.pos, partial_ticks)"),
            "FOV must consume the already-interpolated/orbited camera position"
        );
    }

    /// Bug report: F5's front view "keeps switching between looking forwards and backwards".
    ///
    /// `place_camera` leaves the front view's `(yaw + 180, -pitch)` in the shell camera. The
    /// next frame's mouse look and the next tick's movement input used to read that back as the
    /// player's own look, flipping the player (and the C05/C06 it reports) and so the orbit,
    /// every frame. java: `orientCamera` (`:663-716`) only reads the entity's rotation, and
    /// `setAngles` turns `thePlayer` from its own rotation.
    #[test]
    fn front_view_never_feeds_the_orbit_back_into_the_players_look() {
        use mc_render::ShellApp;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 27,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("join channel");
        client.poll();
        let (yaw, pitch) = (347.80002_f32, -19.817451_f32);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::PlayerPositionLook(
                    mc_protocol::play::s2c::PlayerPositionLook {
                        x: 7.5,
                        y: 64.0,
                        z: 2.5,
                        yaw,
                        pitch,
                        flags: 0,
                    },
                ),
            ))
            .expect("S08 channel");
        let mut camera = menu_camera();
        client.before_ticks(&mut camera);
        while to_net.try_recv().is_ok() {}

        client.third_person_view = 2;
        let mut input = mc_render::InputState::default();
        let mut settings = mc_render::GameSettings::default();
        let look = interact::look_vector(yaw, pitch);
        for frame in 0..6_u64 {
            // One shell iteration: a game tick, then this frame's mouse look and camera pose.
            ShellApp::tick(
                &mut client,
                &mut mc_render::TickCtx {
                    input: &mut input,
                    settings: &mut settings,
                    camera: &mut camera,
                    tick: frame,
                },
            );
            client.turn_local_player(&mut camera, 0.0, 0.0);
            client.place_camera(&mut camera, 0.5);
            while to_net.try_recv().is_ok() {}

            let state = client
                .session
                .as_ref()
                .and_then(Session::predictor)
                .expect("joined predictor")
                .state;
            assert_eq!(
                (state.yaw, state.pitch),
                (yaw, pitch),
                "frame {frame}: the front view must not rewrite the player's look"
            );
            assert_eq!(
                (camera.yaw, camera.pitch),
                (yaw + 180.0, -pitch),
                "frame {frame}: the front view looks back along the player's look"
            );
            let eye = client.interpolated_eye(&state, 0.5);
            assert!(
                (camera.pos - eye).dot(look) > 3.9,
                "frame {frame}: the orbit must stay 4 blocks in front of the player"
            );
        }

        // A real mouse turn still turns the player by exactly the first-person amount, and the
        // orbit follows it.
        let mut reference = Camera {
            yaw,
            pitch,
            ..Camera::default()
        };
        reference.turn_mouse(40.0, -12.0);
        client.turn_local_player(&mut camera, 40.0, -12.0);
        client.place_camera(&mut camera, 0.5);
        let state = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("joined predictor")
            .state;
        assert_eq!((state.yaw, state.pitch), (reference.yaw, reference.pitch));
        assert_eq!(
            (camera.yaw, camera.pitch),
            (reference.yaw + 180.0, -reference.pitch)
        );

        // `place_camera` also hands the hand its own FOV: a 110 setting and the sprint modifier
        // widen the world but never the hand (java: `getFOVModifier(partialTicks, false)`).
        client.settings.fov = 110.0;
        client.fov_modifier_hand_prev = 1.15;
        client.fov_modifier_hand = 1.15;
        client.place_camera(&mut camera, 0.5);
        assert!(camera.effective_fov() > 120.0, "{}", camera.effective_fov());
        assert_eq!(camera.hand_fov, 70.0);
    }

    /// L12 (b): nameplates billboard with `RenderManager.playerViewY/X`.
    ///
    /// java: `cacheActiveRenderInfo` (`RenderManager.java:258-267`) sets `playerViewX` to the
    /// view entity's own pitch and adds 180 to `playerViewY` only, in the F5 front view;
    /// `renderLivingLabel` (`Render.java:344-345`) rotates by `-playerViewY` then `playerViewX`.
    /// The front-view camera's pitch is the player's pitch negated, so a label fed the camera's
    /// angles faced the camera instead of tilting the way vanilla's does.
    #[test]
    fn f5_front_view_nameplates_take_render_manager_player_view() {
        use mc_render::ShellApp;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 27,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("join channel");
        client.poll();
        let (yaw, pitch) = (30.0_f32, 25.0_f32);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::PlayerPositionLook(
                    mc_protocol::play::s2c::PlayerPositionLook {
                        x: 7.5,
                        y: 64.0,
                        z: 2.5,
                        yaw,
                        pitch,
                        flags: 0,
                    },
                ),
            ))
            .expect("S08 channel");
        let mut camera = menu_camera();
        client.before_ticks(&mut camera);
        while to_net.try_recv().is_ok() {}
        let mut input = mc_render::InputState::default();
        let mut settings = mc_render::GameSettings::default();
        ShellApp::tick(
            &mut client,
            &mut mc_render::TickCtx {
                input: &mut input,
                settings: &mut settings,
                camera: &mut camera,
                tick: 0,
            },
        );
        while to_net.try_recv().is_ok() {}

        for view in 0..=2_u8 {
            client.third_person_view = view;
            client.place_camera(&mut camera, 0.5);
            let label = crate::app::entrender::render_manager_view(&camera, view);
            // java: playerViewY = yaw (+180 in view 2), playerViewX = pitch, never negated.
            let vanilla = if view == 2 {
                (yaw + 180.0, pitch)
            } else {
                (yaw, pitch)
            };
            assert_eq!(label, vanilla, "view {view}");
            if view == 2 {
                assert_eq!(
                    (camera.yaw, camera.pitch),
                    (yaw + 180.0, -pitch),
                    "the front-view camera itself keeps its negated pitch"
                );
                let plate = mc_render::entity::Nameplate {
                    text: "bob".to_owned(),
                    rel: Vec3::new(0.0, 0.0, 3.0),
                    height: 1.8,
                    child: false,
                    sneaking: false,
                };
                assert_ne!(
                    plate.matrix(label.0, label.1),
                    plate.matrix(camera.yaw, camera.pitch),
                    "the vanilla label tilts against the front-view camera"
                );
            }
        }

        // The live label submission uses that pair (computed once per frame).
        let source = include_str!("driver.rs");
        let upload = source
            .split_once("    fn upload_entities(&mut self, gpu: &Gpu, camera: &Camera")
            .expect("upload_entities")
            .1;
        let labels = upload
            .split_once("self.nameplate_cache.begin_frame();")
            .expect("the nameplate loop")
            .1
            .split_once("mc_ui::nameplate::submit_cached(")
            .expect("the nameplate submission")
            .0;
        assert!(labels.contains(
            "crate::app::entrender::render_manager_view(camera, self.third_person_view)"
        ));
        assert!(labels.contains("view_yaw: label_view_yaw,"));
        assert!(labels.contains("view_pitch: label_view_pitch,"));
        assert!(!labels.contains("view_pitch: camera.pitch"));
    }

    /// Bug report: the held item "looks too far on screen ... even worse while sprinting".
    ///
    /// java: `renderHand` projects with `getFOVModifier(partialTicks, false)` (`:551-583`): a
    /// fixed 70 with only the death zoom and the underwater squeeze, never `fovSetting` or
    /// `fovModifierHand`.
    #[test]
    fn the_hand_fov_ignores_the_fov_setting_and_the_sprint_modifier() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut world = mc_world::World::new();
        world.load_empty_chunk(BlockPos::new(0, 64, 0).chunk_pos());
        let water = mc_data::BlockState::new(
            mc_data::block_by_name("water").expect("vanilla water registry row"),
            0,
        );
        for y in 64..=65 {
            world.set_block(BlockPos::new(0, y, 0), water);
        }
        let (session, _to_game, _to_net) = offline_session(world);
        client.session = Some(session);
        client.settings.fov = 110.0;
        client.fov_modifier_hand_prev = 1.15;
        client.fov_modifier_hand = 1.15;

        let dry = DVec3::new(4.5, 64.5, 0.5);
        let wet = DVec3::new(0.5, 64.5, 0.5);
        assert!(
            (client.fov_modifier(dry, 0.5) - 1.15).abs() < 1e-6,
            "the world FOV does widen while sprinting"
        );
        assert_eq!(client.hand_fov(dry, 0.5), 70.0);
        assert_eq!(
            client.hand_fov(wet, 0.5),
            60.0,
            "java: f * 60 / 70 underwater"
        );

        let local = &mut client.session.as_mut().expect("session").state_mut().local;
        local.health = 0.0;
        local.death_time = 7;
        assert_eq!(
            client.hand_fov(dry, 0.25),
            death_fov_modifier(70.0, 7, 0.25),
            "the death zoom still applies"
        );
    }

    /// `EntityRenderer.updateRenderer` samples `new BlockPos(renderViewEntity)`, which floors
    /// the player's feet. The nearby eye cell is a biting control: reusing the fog-medium
    /// lookup would choose light 15 and make this first easing step much brighter.
    #[test]
    fn live_fog_light_smoothing_ticks_from_the_feet_block_once() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, to_game, _to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 3,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("channel");
        session.poll(16);
        let feet = BlockPos::new(0, 64, 0);
        let eye = BlockPos::new(0, 65, 0);
        session.state_mut().world.load_empty_chunk(feet.chunk_pos());
        session
            .state_mut()
            .world
            .set_light_for(mc_world::SkyBlock::Sky, feet, 3);
        session
            .state_mut()
            .world
            .set_light_for(mc_world::SkyBlock::Sky, eye, 15);
        session
            .predictor_mut()
            .expect("join creates the player predictor")
            .state
            .pos = DVec3::new(0.5, 64.0, 0.5);
        client.session = Some(session);
        client.settings.render_distance_chunks = 8;

        client.tick_fog_light_smoothing();

        let brightness = mc_render::sky::lightmap::light_brightness_table(0.0)[3];
        let target = FogLightSmoothing::target(brightness, 8);
        assert_eq!(client.fog_light_smoothing.current(), target * 0.1);
        let eye_target = FogLightSmoothing::target(1.0, 8) * 0.1;
        assert_ne!(client.fog_light_smoothing.current(), eye_target);
    }

