    /// F-P1-entity-07-1 / F-P1-entity.item-07-5 / -08-1 / -09-4: subtype defaults and a watched
    /// override feed the one display descriptor consumed immediately before the cart shell.
    #[test]
    fn minecart_display_resolves_defaults_custom_air_and_the_live_pre_shell_call() {
        use crate::sync::entities::TrackedKind;
        use crate::sync::watched::Watched;
        use mc_world::entity::{Metadata, MetadataValue};

        let empty = Metadata::new();
        let watched = |kind| Watched::new(TrackedKind::Type(kind), &empty);
        let state = |name: &str| mc_data::block_by_name(name).unwrap().default_state();

        assert_eq!(
            minecart_display_state(
                mc_data::EntityType::MinecartRideable,
                watched(mc_data::EntityType::MinecartRideable),
            ),
            Some((mc_data::BlockState::AIR, 6))
        );
        for (kind, name, offset) in [
            (mc_data::EntityType::MinecartChest, "minecraft:chest", 8),
            (mc_data::EntityType::MinecartTNT, "minecraft:tnt", 6),
            (mc_data::EntityType::MinecartHopper, "minecraft:hopper", 1),
            (
                mc_data::EntityType::MinecartSpawner,
                "minecraft:mob_spawner",
                6,
            ),
            (
                mc_data::EntityType::MinecartCommandBlock,
                "minecraft:command_block",
                6,
            ),
        ] {
            assert_eq!(
                minecart_display_state(kind, watched(kind)),
                Some((state(name), offset)),
                "{}",
                kind.name()
            );
        }
        assert_eq!(
            minecart_display_state(
                mc_data::EntityType::MinecartFurnace,
                watched(mc_data::EntityType::MinecartFurnace),
            ),
            Some((state("minecraft:furnace"), 6))
        );
        let mut powered = Metadata::new();
        powered.set(16, MetadataValue::Byte(1));
        assert_eq!(
            minecart_display_state(
                mc_data::EntityType::MinecartFurnace,
                Watched::new(
                    TrackedKind::Type(mc_data::EntityType::MinecartFurnace),
                    &powered,
                ),
            ),
            Some((state("minecraft:lit_furnace"), 6))
        );

        let mut custom = Metadata::new();
        custom.set(
            20,
            MetadataValue::Int(state("minecraft:stone").to_java_state_id()),
        );
        custom.set(21, MetadataValue::Int(11));
        custom.set(22, MetadataValue::Byte(1));
        assert_eq!(
            minecart_display_state(
                mc_data::EntityType::MinecartTNT,
                Watched::new(TrackedKind::Type(mc_data::EntityType::MinecartTNT), &custom,),
            ),
            Some((state("minecraft:stone"), 11)),
            "custom state/offset replace the TNT subtype default"
        );

        let mut custom_air = Metadata::new();
        custom_air.set(22, MetadataValue::Byte(1));
        assert_eq!(
            minecart_display_state(
                mc_data::EntityType::MinecartTNT,
                Watched::new(
                    TrackedKind::Type(mc_data::EntityType::MinecartTNT),
                    &custom_air,
                ),
            ),
            Some((mc_data::BlockState::AIR, 6)),
            "index 20's registered zero is custom air, not fallback TNT"
        );

        let source = include_str!("driver.rs");
        let (_, live) = source
            .split_once("// <<MINECART-DISPLAY-LIVE>>")
            .expect("the live display bridge remains present");
        let shell_at = live
            .find("self.models.emit_with(desc.model, base, &params, &mut verts);")
            .expect("minecart shell submission remains after display");
        let display = &live[..shell_at];
        let shell = &live[shell_at..];
        assert!(display.contains("minecart_display_state(kind, watched)"));
        assert!(display.contains("emit_minecart_display("));
        assert!(shell.contains("desc.model"));
    }

    /// F-P2-client.renderer.entity-07-10: the retained TNT-cart fuse must affect the already-live
    /// cargo draw, not the cart shell, and the flash must replay that exact transformed geometry.
    #[test]
    fn tnt_minecart_fuse_reaches_live_cargo_swell_and_white_flash() {
        assert_eq!(tnt_minecart_display_scale(None, 0.5), 1.0);
        assert_eq!(tnt_minecart_display_scale(Some(-1), 0.5), 1.0);
        assert_eq!(tnt_minecart_display_scale(Some(10), 0.0), 1.0);
        assert!(tnt_minecart_display_scale(Some(4), 0.5) > 1.0);

        let body = [mc_render::entity::EntityVertex {
            pos: [1.0, 2.0, 3.0],
            uv: [0.25, 0.75],
            normal: [0.0, 1.0, 0.0],
            color: [0.2, 0.3, 0.4, 1.0],
        }];
        let mut flash = Vec::new();
        prepare_tnt_minecart_flash_vertices(Some(-1), 0.5, &body, &mut flash);
        assert!(flash.is_empty(), "an unlit TNT cart has no white pass");
        prepare_tnt_minecart_flash_vertices(Some(5), 0.5, &body, &mut flash);
        assert!(
            flash.is_empty(),
            "the odd five-tick phase has no white pass"
        );
        prepare_tnt_minecart_flash_vertices(Some(4), 0.5, &body, &mut flash);
        assert_eq!(flash.len(), body.len());
        assert_eq!(flash[0].pos, body[0].pos);
        assert_eq!(flash[0].uv, body[0].uv);
        assert_eq!(flash[0].normal, body[0].normal);
        assert_eq!(flash[0].color, mc_render::entity::objects::TNT_FLASH_COLOR);

        let source = include_str!("driver.rs");
        let (_, live) = source
            .split_once("// <<MINECART-DISPLAY-LIVE>>")
            .expect("the live display bridge remains present");
        let shell_at = live
            .find("self.models.emit_with(desc.model, base, &params, &mut verts);")
            .expect("minecart shell submission remains after TNT cargo");
        let display = &live[..shell_at];
        assert!(display.contains("tracked.tnt_minecart_fuse()"));
        assert!(display.contains("tnt_minecart_display_scale(tnt_minecart_fuse"));
        assert!(display.contains("prepare_tnt_minecart_flash_vertices("));
        assert!(display.contains("LayerBlend::TntFlash"));
    }

    #[test]
    fn minecart_display_dispatches_model_chest_and_invisible_states() {
        use mc_assets::{BakedModel, BakedQuad, Vertex};
        use mc_math::Facing;

        let state = |name: &str| mc_data::block_by_name(name).unwrap().default_state();
        let mut tile_models = mc_render::entity::tilepass::TileModels::new(false);
        let mut out = Vec::new();

        let mut model = BakedModel::default();
        model.general_quads.push(BakedQuad {
            verts: [
                Vertex {
                    pos: [0.0, 1.0, 0.0],
                    uv: [0.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 1.0, 0.0],
                    uv: [1.0, 0.0],
                },
                Vertex {
                    pos: [1.0, 1.0, 1.0],
                    uv: [1.0, 1.0],
                },
                Vertex {
                    pos: [0.0, 1.0, 1.0],
                    uv: [0.0, 1.0],
                },
            ],
            face: Some(Facing::Up),
            shade_face: Some(Facing::Up),
            tint_index: None,
            shade: false,
        });

        emit_minecart_display_model(
            state("minecraft:tnt"),
            &model,
            mc_render::entity::Mat4::IDENTITY,
            0.4,
            &mut out,
        );
        assert!(!out.is_empty(), "the baked TNT display produces geometry");

        out.clear();
        let texture = emit_minecart_display(
            &mut tile_models,
            state("minecraft:chest"),
            mc_render::entity::Mat4::IDENTITY,
            0.4,
            &mut out,
        )
        .expect("the chest display has its own entity texture");
        assert!(
            texture.contains("textures/entity/chest/normal"),
            "{texture}"
        );
        assert!(!out.is_empty());
        assert!(out.iter().all(|vertex| {
            (vertex.color[0] - 0.4).abs() < 1e-6
                && (vertex.color[1] - 0.4).abs() < 1e-6
                && (vertex.color[2] - 0.4).abs() < 1e-6
        }));

        out.clear();
        assert_eq!(
            emit_minecart_display(
                &mut tile_models,
                mc_data::BlockState::AIR,
                mc_render::entity::Mat4::IDENTITY,
                1.0,
                &mut out,
            ),
            None
        );
        assert!(out.is_empty());
    }

    #[test]
    fn third_person_obstruction_excludes_transparent_and_non_rendered_blocks() {
        let eye_cell = BlockPos::new(0, 65, 0);
        let camera = DVec3::new(0.5, 65.5, 0.5);
        for name in [
            "stone",
            "dirt",
            "glass",
            "flowing_water",
            "stone_slab",
            "tallgrass",
            "barrier",
            "air",
        ] {
            let mut world = mc_world::World::new();
            let block = mc_data::BlockState::new(mc_data::block_by_name(name).expect(name), 0);
            mc_physics::scene::set_block(&mut world, eye_cell, block);
            let mut player = mc_physics::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5));
            let expected = matches!(name, "stone" | "dirt");
            assert_eq!(
                third_person_obstruction(&world, &player, camera, true, false),
                expected,
                "{name}"
            );
            assert!(
                !third_person_obstruction(&world, &player, camera, false, false),
                "first person keeps its textured overlay"
            );
            assert!(
                !third_person_obstruction(&world, &player, camera, true, true),
                "sleeping {name}"
            );
            player.no_clip = true;
            assert!(
                !third_person_obstruction(&world, &player, camera, true, false),
                "no-clip {name}"
            );
        }
        let mut world = mc_world::World::new();
        mc_physics::scene::set_block(
            &mut world,
            eye_cell,
            mc_data::BlockState::new(mc_data::block_by_name("stone").unwrap(), 0),
        );
        let player = mc_physics::PhysicsState::new_player(DVec3::new(10.5, 64.0, 10.5));
        assert!(
            third_person_obstruction(&world, &player, camera, true, false),
            "camera alone enters stone"
        );
        assert!(
            !third_person_obstruction(&world, &player, DVec3::new(10.5, 65.5, 6.5), true, false),
            "ordinary open F5 view"
        );
    }

    /// Drive the real F5 camera/obstruction/UI path over a bright completed-world image. The
    /// final UI phase must overwrite every pixel even with F1, and leave normal F5 untouched.
    #[test]
    fn third_person_obstruction_renders_black_after_world_effects_and_keeps_the_hud() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        // Complete the real join/position handshake: JoinGame alone leaves the terrain
        // download screen active, which correctly suppresses the HUD even with F1 off.
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("join channel");
        client.poll();
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::PlayerPositionLook(
                    mc_protocol::play::s2c::PlayerPositionLook {
                        x: 0.5,
                        y: 64.0,
                        z: 0.5,
                        yaw: 0.0,
                        pitch: 0.0,
                        flags: 0,
                    },
                ),
            ))
            .expect("position channel");
        client.poll();
        assert!(matches!(client.ui, Ui::InGame));
        assert!(!client.session.as_ref().unwrap().terrain_download_active());
        let Ok(mut gpu) = mc_render::Gpu::headless(
            320,
            240,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };
        let mut unused_world_phases = PhaseList::new();
        client.install(&gpu, &mut unused_world_phases, 320, 240);
        client.hide_gui = true;
        client.settings.gui_scale = 1;
        let mut phases = PhaseList::new();
        // Represents the already-completed world/post chain. Rendering only the final UI
        // isolates the protection from terrain backface/visibility decisions.
        phases.clear_color = wgpu::Color {
            r: 1.0,
            g: 0.0,
            b: 1.0,
            a: 1.0,
        };
        phases.insert(
            PhaseOrder::UI,
            Box::new(client.render.as_ref().unwrap().ui.clone()),
        );
        let mut camera = Camera::default();
        camera.set_viewport(320, 240);
        for (name, perspective, block_name, camera_only, spectator, expected) in [
            ("stone-back", 1, "stone", false, false, true),
            ("stone-front", 2, "stone", false, false, true),
            ("glass-back", 1, "glass", false, false, false),
            ("glass-front", 2, "glass", false, false, false),
            ("water", 1, "flowing_water", false, false, false),
            ("open-f5", 1, "air", false, false, false),
            ("camera-in-stone", 1, "stone", true, false, true),
            ("spectator", 1, "stone", false, true, false),
            ("first-person", 0, "stone", false, false, false),
        ] {
            let session = client.session.as_mut().unwrap();
            session.state_mut().world = mc_world::World::new();
            session.state_mut().local.game_mode = if spectator {
                mc_protocol::play::s2c::GameMode::Spectator
            } else {
                mc_protocol::play::s2c::GameMode::Survival
            };
            session.predictor_mut().unwrap().state =
                mc_physics::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5));
            let cell = if camera_only {
                BlockPos::new(2, 65, 2)
            } else {
                BlockPos::new(0, 65, 0)
            };
            mc_physics::scene::set_block(
                &mut session.state_mut().world,
                cell,
                mc_data::BlockState::new(mc_data::block_by_name(block_name).unwrap(), 0),
            );
            client.third_person_view = perspective;
            client.place_camera(&mut camera, 0.5);
            if camera_only {
                camera.pos = DVec3::new(2.5, 65.5, 2.5);
                camera.update();
            }
            client.update_third_person_obstruction(&camera);
            assert_eq!(client.third_person_obstructed, expected, "{name}");
            client.build_ui(&gpu, 0.5);
            let frame = gpu.acquire().expect("headless frame");
            phases.render(&gpu, frame.view(), &camera, 0.5);
            frame.present(&gpu.queue);
            let pixels = gpu.read_pixels().expect("frame readback");
            if expected {
                assert!(
                    pixels.chunks_exact(4).all(|pixel| pixel[..3] == [0, 0, 0]),
                    "{name}: no world or prior-frame pixels may leak"
                );
            } else {
                assert!(
                    pixels
                        .chunks_exact(4)
                        .all(|pixel| pixel[..3] == [255, 0, 255]),
                    "{name}: normal view stays unchanged"
                );
            }
            if let Some(out) = std::env::var_os("MC_CAMERA_OBSTRUCTION_OUT") {
                std::fs::create_dir_all(&out).unwrap();
                image::save_buffer(
                    std::path::Path::new(&out).join(format!("{name}.png")),
                    &pixels,
                    320,
                    240,
                    image::ColorType::Rgba8,
                )
                .unwrap();
            }
        }
        client.third_person_view = 1;
        client.hide_gui = false;
        client.place_camera(&mut camera, 0.5);
        client.update_third_person_obstruction(&camera);
        assert!(client.third_person_obstructed);
        client.build_ui(&gpu, 0.5);
        let frame = gpu.acquire().expect("HUD frame");
        phases.render(&gpu, frame.view(), &camera, 0.5);
        frame.present(&gpu.queue);
        let pixels = gpu.read_pixels().unwrap();
        if let Some(out) = std::env::var_os("MC_CAMERA_OBSTRUCTION_OUT") {
            std::fs::create_dir_all(&out).unwrap();
            image::save_buffer(
                std::path::Path::new(&out).join("stone-back-hud.png"),
                &pixels,
                320,
                240,
                image::ColorType::Rgba8,
            )
            .unwrap();
        }
        assert!(
            pixels.chunks_exact(4).any(|pixel| pixel[..3] != [0, 0, 0]),
            "HUD remains visible over the obstruction"
        );
        assert!(
            pixels[..320 * 4]
                .chunks_exact(4)
                .all(|pixel| pixel[..3] == [0, 0, 0]),
            "world stays black above the HUD"
        );
        client.disconnect();
        assert!(
            !client.third_person_obstructed,
            "disconnect clears obstruction state"
        );
    }

    /// F-P1-block-01-8 / F-P1-entity-02-9 / F-P2-client.renderer-08-6: the already-faithful
    /// eye-corner producer reaches the first-person overlay gate, with Java's F5/sleep/noClip
    /// negatives. The actual atlas UV is resolved immediately after this production helper.
    #[test]
    fn opaque_eye_block_reaches_only_the_awake_first_person_overlay_path() {
        let mut world = mc_world::World::new();
        let stone = mc_data::BlockState::new(mc_data::block_by_name("stone").unwrap(), 0);
        mc_physics::scene::set_block(&mut world, BlockPos::new(0, 65, 0), stone);
        let mut state = mc_physics::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5));

        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, false),
            Some(stone)
        );
        assert_eq!(
            local_opaque_overlay_block(&world, &state, true, false),
            None
        );
        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, true),
            None
        );
        state.no_clip = true;
        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, false),
            None
        );
        assert_eq!(
            local_opaque_overlay_block(
                &mc_world::World::new(),
                &mc_physics::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5)),
                false,
                false,
            ),
            None,
            "air never selects an atlas sprite"
        );
    }

    /// `ItemRenderer.renderOverlays` gates the draw on the *selected* state's
    /// `getRenderType() != -1`. A barrier is visually opaque (it is picked) but invisible, so
    /// being inside one draws no overlay, even when an ordinary corner was seen earlier: the last
    /// opaque corner wins the selection and then fails the gate.
    #[test]
    fn a_barrier_at_the_eye_draws_no_suffocation_overlay() {
        let barrier = mc_data::BlockState::new(mc_data::block_by_name("barrier").unwrap(), 0);
        let stone = mc_data::BlockState::new(mc_data::block_by_name("stone").unwrap(), 0);
        assert!(mc_data::block_props(barrier).visually_opaque);
        assert_eq!(
            mc_data::block_props(barrier).render_type,
            mc_data::RenderType::Invisible
        );
        let state = mc_physics::PhysicsState::new_player(DVec3::new(0.5, 64.0, 0.5));

        let mut world = mc_world::World::new();
        mc_physics::scene::set_block(&mut world, BlockPos::new(0, 65, 0), barrier);
        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, false),
            None
        );

        // Width 0.6: the corners span x/z 0.26..0.74, all in column (0, 0); the eye's Y probes
        // reach 65 only. Stone below the barrier is never sampled, stone in the same cell is the
        // only alternative, so a mixed case needs a cell boundary: move the player to x = 0.9 so
        // the +X corners sample x = 1.
        let state = mc_physics::PhysicsState::new_player(DVec3::new(0.9, 64.0, 0.5));
        let mut world = mc_world::World::new();
        mc_physics::scene::set_block(&mut world, BlockPos::new(0, 65, 0), stone);
        mc_physics::scene::set_block(&mut world, BlockPos::new(1, 65, 0), barrier);
        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, false),
            None,
            "the +X barrier corner is enumerated after the -X stone one, so it wins and is hidden"
        );
        let mut world = mc_world::World::new();
        mc_physics::scene::set_block(&mut world, BlockPos::new(0, 65, 0), barrier);
        mc_physics::scene::set_block(&mut world, BlockPos::new(1, 65, 0), stone);
        assert_eq!(
            local_opaque_overlay_block(&world, &state, false, false),
            Some(stone),
            "stone enumerated last still draws"
        );
    }

    /// FW2-FURNACE-MINECART-PREDICTION: the Java tick decrements fuel before the powered watcher
    /// and consumes one per-cart RNG draw only while powered.  The terminal tick clears pushX/Z;
    /// an unpowered cart must not perturb its Entity.rand stream, and unrelated watcher bits stay
    /// intact when bit 0 is mirrored.
    #[test]
    fn furnace_minecart_tick_has_powered_rng_gate_and_terminal_push_reset() {
        let mut world = mc_world::World::new();
        let generation = world.ecs.spawn(());
        let mut state = FurnaceMinecartClientState {
            generation,
            fuel: 2,
            push_x: 4.0,
            push_z: -3.0,
        };
        let seed = (0_i64..10_000)
            .find(|seed| {
                let mut random = mc_math::JavaRandom::new(*seed);
                random.next_i32_bound(4) == 0
            })
            .expect("a bounded JavaRandom seed must hit the smoke branch");
        let mut random = mc_math::JavaRandom::new(seed);
        let before_powered = random.raw_seed();
        assert!(tick_furnace_minecart_state(&mut state, &mut random));
        assert_eq!(state.fuel, 1);
        assert_eq!((state.push_x, state.push_z), (4.0, -3.0));
        assert_ne!(random.raw_seed(), before_powered);

        let after_powered = random.raw_seed();
        assert!(!tick_furnace_minecart_state(&mut state, &mut random));
        assert_eq!(state.fuel, 0);
        assert_eq!((state.push_x, state.push_z), (0.0, 0.0));
        assert_eq!(random.raw_seed(), after_powered);

        let mut metadata = mc_world::Metadata::default();
        metadata.set(16, mc_world::MetadataValue::Byte(0b1000));
        set_furnace_minecart_powered(&mut metadata, true);
        assert_eq!(
            metadata.get(16),
            Some(&mc_world::MetadataValue::Byte(0b1001))
        );
        set_furnace_minecart_powered(&mut metadata, false);
        assert_eq!(
            metadata.get(16),
            Some(&mc_world::MetadataValue::Byte(0b1000))
        );
    }

    // ---- The block overlay is actually driven -----------------

    /// A session with no socket behind it, holding `world`. The two channel ends come back so
    /// the caller can keep them alive — dropping them makes every `send` report `NotConnected`.
    #[allow(clippy::type_complexity)]
    fn offline_session(
        world: mc_world::World,
    ) -> (
        Session,
        tokio::sync::mpsc::Sender<crate::net::ToGame>,
        tokio::sync::mpsc::UnboundedReceiver<crate::net::ToNet>,
    ) {
        let (handle, to_game, to_net) = crate::net::channel::NetHandle::new_pair();
        let mut session = Session::new(handle, JoinSettings::default());
        session.state_mut().world = world;
        (session, to_game, to_net)
    }

    /// F-P0-network.play.server-14-12: S39 capability flags remain authoritative when they
    /// deliberately disagree with the mode-owned controller state. `allow_edit` is the opposite
    /// control: Join/Respawn/GameMode configure it from game type because S39 does not carry it.
    #[test]
    fn packet_ability_flags_own_creative_and_damage_guards_when_mode_disagrees() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, _to_game, _to_net) = offline_session(mc_world::World::new());

        session.state_mut().local.game_mode = mc_protocol::play::s2c::GameMode::Survival;
        session.state_mut().local.abilities.creative_mode = true;
        session.state_mut().local.abilities.invulnerable = true;
        session.state_mut().local.abilities.allow_edit = false;
        client.session = Some(session);

        assert!(client.is_creative());
        let guards = client.use_guards();
        assert!(guards.creative);
        assert!(guards.disable_damage);
        assert!(
            !client
                .session
                .as_ref()
                .unwrap()
                .state()
                .local
                .abilities
                .allow_edit
        );

        let local = &mut client.session.as_mut().unwrap().state_mut().local;
        local.game_mode = mc_protocol::play::s2c::GameMode::Creative;
        local.abilities.creative_mode = false;
        local.abilities.invulnerable = false;
        local.abilities.allow_edit = true;

        assert!(!client.is_creative());
        let guards = client.use_guards();
        assert!(!guards.creative);
        assert!(!guards.disable_damage);
        assert!(
            client
                .session
                .as_ref()
                .unwrap()
                .state()
                .local
                .abilities
                .allow_edit
        );
    }

    /// F-P0-network.play.server-01-2: the live `GuiDownloadTerrain` seam starts at JoinGame,
    /// ignores unrelated play traffic, and closes only on the first S08 after Session has queued
    /// the C06 confirmation. The same test drives both reset controls: a same-dimension respawn
    /// leaves the closed latch alone, while a new dimension and a subsequent JoinGame reopen it.
    #[test]
    fn terrain_download_screen_follows_join_poslook_and_dimension_lifecycle() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);

        let join = || {
            crate::net::ToGame::Packet(mc_protocol::play::S2CPlay::JoinGame(
                mc_protocol::play::s2c::JoinGame {
                    entity_id: 3,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                },
            ))
        };
        let poslook = || {
            crate::net::ToGame::Packet(mc_protocol::play::S2CPlay::PlayerPositionLook(
                mc_protocol::play::s2c::PlayerPositionLook {
                    x: 8.5,
                    y: 70.0,
                    z: 8.5,
                    yaw: 0.0,
                    pitch: 0.0,
                    flags: 0,
                },
            ))
        };
        let respawn = |dimension| {
            crate::net::ToGame::Packet(mc_protocol::play::S2CPlay::Respawn(
                mc_protocol::play::s2c::Respawn {
                    dimension,
                    difficulty: 2,
                    game_mode: 0,
                    level_type: "default".into(),
                },
            ))
        };
        let discard_outbound = |to_net: &mut tokio::sync::mpsc::UnboundedReceiver<
            crate::net::ToNet,
        >| { while to_net.try_recv().is_ok() {} };

        // A correction received before JoinGame has no active GuiDownloadTerrain. The dispatch
        // event is intentionally harmless here: this is the negative control for a global
        // TerrainDownloaded -> InGame transition.
        to_game
            .try_send(poslook())
            .expect("pre-join position channel");
        let events = client.poll();
        assert!(events
            .iter()
            .any(|event| matches!(event, ClientEvent::TerrainDownloaded)));
        assert!(
            !matches!(client.ui, Ui::InGame),
            "a pre-JoinGame completion event cannot open the in-game screen"
        );

        to_game.try_send(join()).expect("join channel");
        let events = client.poll();
        assert!(matches!(events.first(), Some(ClientEvent::JoinedGame(_))));
        assert!(
            matches!(client.ui, Ui::Loading),
            "JoinGame opens the screen"
        );
        assert!(!client.ui.allows_user_input());
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(0)
        );

        // PositionCorrection is not itself the close edge. This direct screen dispatch control
        // catches a premature-close mutant without allowing the real S08 packet's subsequent
        // TerrainDownloaded event to mask it.
        client.react(&ClientEvent::PositionCorrection(
            mc_physics::prediction::PositionCorrection::from_packet(8.5, 70.0, 8.5, 0.0, 0.0, 0),
        ));
        assert!(
            matches!(client.ui, Ui::Loading),
            "PositionCorrection alone cannot dismiss GuiDownloadTerrain"
        );
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(0)
        );
        let ctx = ScreenCtx::new(client.resolution(320, 240), 0.0);
        let mut download_draw = DrawList::new();
        client.draw_terrain_download_screen(&mut download_draw, &ctx);
        assert_eq!(
            download_draw.batches().first().map(|batch| &batch.texture),
            Some(&UiTexture::gui("textures/gui/options_background.png")),
            "GuiDownloadTerrain fills the frame with the dirt background"
        );
        let font_batch = download_draw
            .batches()
            .iter()
            .find(|batch| matches!(batch.texture, UiTexture::Font(_)))
            .expect("GuiDownloadTerrain draws its translated message");
        assert!(
            download_draw.vertices()[font_batch.range.clone()]
                .iter()
                .any(|vertex| vertex.pos[1] == (ctx.height / 2 - 50) as f32),
            "the message uses GuiDownloadTerrain's height/2 - 50 baseline"
        );
        discard_outbound(&mut to_net);

        // A non-S08 play packet must not close the screen or advance its progress counter.
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::KeepAlive(mc_protocol::play::s2c::KeepAlive { id: 41 }),
            ))
            .expect("keep-alive channel");
        assert!(client.poll().is_empty());
        assert!(matches!(client.ui, Ui::Loading));
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(0)
        );

        client.tick(&MoveInput::default());
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(1),
            "GuiDownloadTerrain.progress advances on the game tick"
        );
        discard_outbound(&mut to_net);

        to_game.try_send(poslook()).expect("position channel");
        let events = client.poll();
        assert!(matches!(
            events.as_slice(),
            [
                ClientEvent::PositionCorrection(_),
                ClientEvent::TerrainDownloaded
            ]
        ));
        assert!(
            matches!(client.ui, Ui::InGame),
            "the first S08 closes the screen"
        );
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            None
        );
        let confirmation = to_net
            .try_recv()
            .expect("the S08 must queue C06 before close");
        assert!(matches!(
            confirmation,
            crate::net::ToNet::Send(mc_protocol::play::C2SPlay::PlayerPositionAndLook(
                mc_protocol::play::c2s::PlayerPositionAndLook {
                    on_ground: false,
                    ..
                }
            ))
        ));
        assert!(
            to_net.try_recv().is_err(),
            "no packet follows the C06 close edge"
        );

        // Same-dimension S07 replaces the local player but does not install a new download
        // screen or reset doneLoadingTerrain.
        to_game
            .try_send(respawn(0))
            .expect("same-dimension respawn");
        client.poll();
        assert!(matches!(client.ui, Ui::InGame));
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            None
        );

        // A dimension change builds a new WorldClient and immediately installs a fresh screen.
        to_game.try_send(respawn(-1)).expect("dimension respawn");
        client.poll();
        assert!(matches!(client.ui, Ui::Loading));
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(0)
        );

        // A second JoinGame on the same connection is the proxy/server-switch reset path.
        to_game
            .try_send(poslook())
            .expect("dimension position channel");
        client.poll();
        discard_outbound(&mut to_net);
        to_game.try_send(join()).expect("second join channel");
        client.poll();
        assert!(matches!(client.ui, Ui::Loading));
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live session")
                .terrain_download_progress(),
            Some(0)
        );
    }

    /// W-POSLOOK: the shell camera is a second rotation owner and must converge to S08 before
    /// its same-frame mouse delta is copied back into the predictor. Relative rotation flags are
    /// included so this cannot pass by copying the packet's raw fields instead of the resolved
    /// player pose.
    #[test]
    fn a_position_correction_updates_the_stale_shell_camera_before_mouse_look() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let world = mc_render::terrain::fixture::blank_world(1);
        let (session, to_game, _to_net) = offline_session(world);
        client.session = Some(session);
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 3,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("channel");
        client.poll();
        {
            let predictor = client
                .session
                .as_mut()
                .and_then(Session::predictor_mut)
                .expect("join built predictor");
            predictor.state.yaw = 40.0;
            predictor.state.pitch = -10.0;
        }

        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::PlayerPositionLook(
                    mc_protocol::play::s2c::PlayerPositionLook {
                        x: 0.0,
                        y: 64.0,
                        z: 0.0,
                        yaw: 30.0,
                        pitch: 5.0,
                        // X_ROT | Y_ROT: add both packet angles to the current player pose.
                        flags: 0x08 | 0x10,
                    },
                ),
            ))
            .expect("channel");
        let events = client.poll();
        let mut camera = Camera {
            yaw: 5.0,
            pitch: 6.0,
            ..Camera::default()
        };
        assert_ne!((camera.yaw, camera.pitch), (70.0, -5.0));

        client.sync_camera_to_position_correction(&events, &mut camera);
        assert_eq!((camera.yaw, camera.pitch), (70.0, -5.0));
    }

    #[test]
    fn the_rendered_camera_moves_between_ticks_and_not_only_on_them() {
        // End to end. The unit tests above pin `interpolated_eye`'s
        // arithmetic; this one drives the whole chain the finding is actually about —
        // `Client::tick`'s snapshot, `Client::frame`, `place_camera` — and asserts that two
        // frames rendered inside one tick no longer produce the identical camera. (`terrain/
        // cull.rs` keys its walk cache on `camera.pos.to_bits()`, which is why "bit-identical
        // within a tick" was measurable at all.)
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let world = mc_render::terrain::fixture::blank_world(1);
        let (mut session, to_game, _to_net) = offline_session(world);
        // `JoinGame` is what builds the predictor — nothing else does.
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 3,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("channel");
        session.poll(16);
        assert!(session.predictor().is_some(), "JoinGame must build one");

        let from = DVec3::new(10.0, 64.0, 10.0);
        let to = DVec3::new(14.0, 64.0, 10.0);
        session
            .predictor_mut()
            .expect("just checked")
            .state
            .set_position(from);
        client.session = Some(session);

        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 64, 64);
        let mut camera = menu_camera();

        // Take the tick's snapshot at `from`, then move the player as a tick would.
        client.snapshot_prev_pos();
        client
            .session
            .as_mut()
            .expect("set above")
            .predictor_mut()
            .expect("set above")
            .state
            .set_position(to);

        let eye_height = client
            .session
            .as_ref()
            .expect("set above")
            .predictor()
            .expect("set above")
            .state
            .eye_pos()
            .y
            - to.y;

        let mut seen = Vec::new();
        for step in 0..=4 {
            client.frame(&gpu, &mut camera, step as f32 / 4.0);
            seen.push(camera.pos);
        }
        assert_eq!(seen[0], from + DVec3::new(0.0, eye_height, 0.0));
        assert_eq!(seen[4], to + DVec3::new(0.0, eye_height, 0.0));
        for pair in seen.windows(2) {
            assert!(
                pair[1].x > pair[0].x,
                "the camera did not advance between frames of one tick: {seen:?}"
            );
        }

        // And the guard: with the snapshot cleared, every fraction renders the destination.
        client.camera_prev_pos = None;
        for step in 0..=4 {
            client.frame(&gpu, &mut camera, step as f32 / 4.0);
            assert_eq!(camera.pos, to + DVec3::new(0.0, eye_height, 0.0));
        }
    }

    #[test]
    fn the_selection_outline_is_driven_from_the_hit_result_and_reaches_the_phase() {
        // `BlockOverlayPhase::selection` had exactly one assignment in the
        // whole workspace and it was in `mc-render/tests/s11_render.rs`
        // claimed the outline as `[x]`. This drives the real client path — `Client::frame`, not
        // `drive_block_overlay` directly — and then reads the value back out of the *installed*
        // phase, so it fails if any link in the chain is missing.
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let pos = BlockPos::new(3, 65, 4);
        let mut world = mc_render::terrain::fixture::blank_world(1);
        mc_render::terrain::fixture::place(&mut world, pos, "minecraft:stone");
        // A render-time pick needs the same local player that vanilla's
        // `EntityRenderer.getMouseOver(partialTicks)` reads.  Keep the world
        // assignment after `JoinGame`: that packet resets the session world.
        let (mut session, to_game, _to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(
                mc_protocol::play::S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
            ))
            .expect("channel");
        session.poll(16);
        session.state_mut().world = world;
        client.session = Some(session);

        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 64, 64);
        let mut camera = menu_camera();

        // Looking at nothing: no outline. This is the state the client was permanently stuck in.
        client.hit = HitResult::Miss;
        client.frame(&gpu, &mut camera, 0.0);
        let render = client.render.as_ref().expect("install populated it");
        assert!(render.block_overlay.with(|phase| phase.selection).is_none());

        // Move the render sample onto the stone.  The tick sample remains the packet-facing
        // `client.hit` below; `frame` must derive the outline from the current interpolated eye
        // instead of blindly reusing that stale tick value.
        client
            .session
            .as_mut()
            .expect("join built predictor")
            .predictor_mut()
            .expect("join built predictor")
            .state
            .pos = DVec3::new(3.5, 64.0, 3.0);
        // Facing +Z for the last ticks: the outline aims with the head-yaw lerp (L7).
        client
            .session
            .as_mut()
            .expect("join built predictor")
            .face_local_player(0.0, 0.0);

        // Looking at the stone block: the outline is its render bounds expanded by vanilla's
        // 0.002, in world space.
        client.hit = HitResult::Block(interact::BlockHit {
            pos,
            face: mc_math::Facing::Up,
            hit_vec: DVec3::new(3.5, 66.0, 4.5),
        });
        client.frame(&gpu, &mut camera, 0.0);
        let render = client.render.as_ref().expect("install populated it");
        let selection = render
            .block_overlay
            .with(|phase| phase.selection)
            .expect("the outline must be driven from the hit result");
        let expected = mc_render::terrain::SelectionBox::for_block(
            pos,
            client
                .session
                .as_ref()
                .expect("set above")
                .state()
                .world
                .block_at(pos),
        );
        assert_eq!(selection, expected);

        // java: `drawSelectionBox:1889` — `block.getMaterial() != Material.air`. A stale
        // `HitResult` naming a block that has since been mined must not keep an outline alive.
        client
            .session
            .as_mut()
            .expect("set above")
            .state_mut()
            .world
            .set_block(pos, mc_data::BlockState::AIR);
        client.frame(&gpu, &mut camera, 0.0);
        let render = client.render.as_ref().expect("install populated it");
        assert!(render.block_overlay.with(|phase| phase.selection).is_none());
    }

    #[test]
    fn damaged_block_forget_keeps_the_java_boundary_and_tile_entity_order() {
        let stone = mc_data::block_by_name("stone")
            .expect("stone")
            .default_state();
        let chest = mc_data::block_by_name("chest")
            .expect("chest")
            .default_state();
        let feet = DVec3::new(0.0, 64.0, 0.0);

        assert!(damaged_block_remains(stone, BlockPos::new(32, 64, 0), feet));
        assert!(!damaged_block_remains(
            stone,
            BlockPos::new(33, 64, 0),
            feet
        ));
        assert!(damaged_block_remains(chest, BlockPos::new(33, 64, 0), feet));
    }

    #[test]
    fn a_remote_breakers_packet_reaches_the_crack_overlay() {
        // `sync::dispatch` built `ClientEvent::BlockBreakProgress` and
        // `Client::react` had no arm for it, so the event was constructed and dropped; the
        // `breaking` field's only assignment in the workspace was a test in `mc-render`. This
        // starts from the event and ends at the installed phase.
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let pos = BlockPos::new(1, 65, 2);
        let mut world = mc_render::terrain::fixture::blank_world(1);
        mc_render::terrain::fixture::place(&mut world, pos, "minecraft:stone");
        let (session, _to_game, _to_net) = offline_session(world);
        client.session = Some(session);

        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 64, 64);
        // This fixture has no predictor, so the cull's defensive fallback is the camera.
        let mut camera = menu_camera();
        camera.pos = DVec3::new(1.5, 66.0, 0.0);

        client.react_to_break_progress(&[ClientEvent::BlockBreakProgress {
            breaker_id: 42,
            position: pos,
            progress: 6,
        }]);
        client.frame(&gpu, &mut camera, 0.0);
        let render = client.render.as_ref().expect("install populated it");
        let breaking = render.block_overlay.with(|phase| phase.breaking.clone());
        assert_eq!(breaking.len(), 1, "the packet must reach the phase");
        assert_eq!(breaking[0].0.pos, pos);
        assert_eq!(breaking[0].0.stage, 6);

        // java: `sendBlockBreakProgress:2380` — a progress outside `0..10` is the "done" signal.
        client.react_to_break_progress(&[ClientEvent::BlockBreakProgress {
            breaker_id: 42,
            position: pos,
            progress: 10,
        }]);
        client.frame(&gpu, &mut camera, 0.0);
        let render = client.render.as_ref().expect("install populated it");
        assert!(render.block_overlay.with(|phase| phase.breaking.is_empty()));

        // java: `drawBlockDamageTexture:1837` — beyond 32 blocks the entry is dropped outright.
        client.react_to_break_progress(&[ClientEvent::BlockBreakProgress {
            breaker_id: 42,
            position: pos,
            progress: 3,
        }]);
        camera.pos = DVec3::new(1.5, 66.0, 400.0);
        client.frame(&gpu, &mut camera, 0.0);
        assert!(
            client.damaged_blocks.is_empty(),
            "a far-away break must be forgotten, not just skipped"
        );
    }

    #[test]
    fn break_progress_is_keyed_by_breaker_and_out_of_range_progress_clears_it() {
        // java: `RenderGlobal.sendBlockBreakProgress:2362` — `damagedBlocks` is a
        // `Map<Integer, DestroyBlockProgress>` keyed by breaker id, and the `progress >= 0 &&
        // progress < 10` test is what turns a packet into either an update or a removal.
        let mut damaged = HashMap::new();
        let a = BlockPos::new(4, 64, 4);
        let b = BlockPos::new(5, 64, 4);

        send_block_break_progress(&mut damaged, 10, 7, a, 3);
        assert_eq!(damaged.len(), 1);
        assert_eq!(damaged[&7].pos, a);
        assert_eq!(damaged[&7].stage, 3);

        // A second breaker is a second entry, not a replacement.
        send_block_break_progress(&mut damaged, 10, 8, a, 9);
        assert_eq!(damaged.len(), 2);

        // The *same* breaker moving to a new block replaces their entry and restarts the crack.
        send_block_break_progress(&mut damaged, 11, 7, b, 0);
        assert_eq!(damaged.len(), 2);
        assert_eq!(damaged[&7].pos, b);
        assert_eq!(damaged[&7].stage, 0);

        // `-1` is `resetBlockRemoving`; `10` is what a server sends when the block is gone.
        send_block_break_progress(&mut damaged, 12, 7, b, -1);
        assert!(!damaged.contains_key(&7));
        send_block_break_progress(&mut damaged, 12, 8, a, 10);
        assert!(damaged.is_empty());
    }

    #[test]
    fn damaged_blocks_expire_four_hundred_ticks_after_the_last_update() {
        // java: `RenderGlobal.updateClouds:1142` gates cleanup to every twentieth cloud tick,
        // then `cleanupDamagedBlocks:1131` removes only when `cloudTickCounter - i > 400`.
        // Crossing 400 on an ordinary tick is therefore not enough; the next cleanup tick bites.
        let mut damaged = HashMap::new();
        let pos = BlockPos::new(0, 64, 0);
        send_block_break_progress(&mut damaged, 100, 1, pos, 5);

        cleanup_damaged_blocks(&mut damaged, 500);
        assert_eq!(damaged.len(), 1, "exactly 400 ticks old must survive");
        cleanup_damaged_blocks(&mut damaged, 501);
        assert_eq!(
            damaged.len(),
            1,
            "cleanup must not run between twentieth ticks"
        );
        cleanup_damaged_blocks(&mut damaged, 519);
        assert_eq!(damaged.len(), 1);
        cleanup_damaged_blocks(&mut damaged, 520);
        assert!(
            damaged.is_empty(),
            "the next twentieth tick must drop the stale entry"
        );

        // Progress at tick 400 pushes the deadline out to 800, rather than the entry dying at
        // 400 ticks after it was first created.
        send_block_break_progress(&mut damaged, 100, 1, pos, 5);
        send_block_break_progress(&mut damaged, 400, 1, pos, 6);
        cleanup_damaged_blocks(&mut damaged, 801);
        assert_eq!(damaged.len(), 1);
        cleanup_damaged_blocks(&mut damaged, 820);
        assert!(damaged.is_empty());
    }

    // ---- direct connect / add / edit server wiring -----------------------------------------
    //
    // Before this wiring, `Ui` had no variant that could hold `DirectConnectScreen` or
    // `AddServerScreen`, so `Action::OpenDirectConnect`/`OpenAddServer`/`OpenEditServer` all fell
    // through `handle_action`'s `other => tracing::debug!(...)` catch-all — the buttons were
    // real, tested, and produced the right `Action` at the `mc-ui` layer, but nothing in
    // `mc-client` ever acted on it, so clicking them did nothing.

    // Returns the `TempDir` guard alongside the client — `config.game_dir` points inside it, so
    // it must outlive `Client`, not just this function.
    fn offline_client() -> Option<(Client, tempfile::TempDir)> {
        let dir = tempfile::tempdir().expect("tempdir");
        let config = ClientConfig {
            game_dir: dir.path().to_path_buf(),
            login: LoginMode::Offline("Dev".to_owned()),
            ..ClientConfig::default()
        }
        .with_discovered_assets();
        if !config.version_jar.as_ref().is_some_and(|p| p.is_file()) {
            eprintln!("skip: no vanilla jar in this checkout");
            return None;
        }
        let client = Client::new(config, &mut |_, _| {}).expect("the real assets must load");
        Some((client, dir))
    }

    /// With a report coming (a failed load here), the shell's exit hook
    /// leaves the shutdown to `main`, so the report can still describe the live world.
    /// The shell's hook and `main` both call the shutdown; the second
    /// call returns the first report and saves nothing again.
    #[test]
    fn the_exit_hook_waits_for_the_report_and_shutdown_runs_once() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.fatal = Some(ClientError::Io(std::io::Error::other(
            "test: a failed load",
        )));
        <Client as mc_render::ShellApp>::shutdown(&mut client, &GameSettings::default());
        assert!(client.shutdown_report().is_none(), "left to main");
        client.fatal = None;

        let options = client.config.options_path();
        let first = client.shutdown().steps.clone();
        assert_eq!(first, crate::app::shutdown::ORDER.to_vec());
        std::fs::remove_file(&options).expect("the first shutdown saved options.txt");
        let second = client.shutdown().steps.clone();
        assert_eq!(second, first, "the first report again");
        assert!(!options.exists(), "the second shutdown saved nothing");
    }

    /// A window dragged to its smallest leaves a client area a pixel or
    /// two high, and a thin one is possible too; half- and quarter-size targets of such a window
    /// round to nothing. The title screen and the options over it must build and draw without a
    /// panic at those sizes.
    #[test]
    fn the_title_screen_and_options_draw_in_tiny_and_thin_windows() {
        for (width, height) in [(1, 1), (2, 2), (1, 480), (854, 1), (5, 3)] {
            let mut gpu = match Gpu::headless(width, height, mc_render::GpuOptions::default()) {
                Ok(gpu) => gpu,
                Err(mc_render::RenderError::NoAdapter) => {
                    eprintln!("skip: no wgpu adapter available on this machine");
                    return;
                }
                Err(error) => panic!("headless GPU at {width}x{height}: {error}"),
            };
            let Some((mut client, _dir)) = offline_client() else {
                return;
            };
            let mut phases = PhaseList::new();
            client.install(&gpu, &mut phases, width, height);
            let camera = Camera::default();
            for screen in ["title", "options"] {
                if screen == "options" {
                    client.handle_action(Action::OpenOptions);
                }
                for frame_index in 0..3 {
                    client.build_ui(&gpu, 0.5);
                    let frame = gpu.acquire().unwrap_or_else(|error| {
                        panic!("{screen} frame {frame_index} at {width}x{height}: {error}")
                    });
                    phases.render(&gpu, frame.view(), &camera, 0.5);
                    frame.present(&gpu.queue);
                }
            }
        }
    }

    /// The same sizes in game: the world, its post effects and the HUD.
    #[test]
    fn the_game_draws_in_tiny_and_thin_windows() {
        for (width, height) in [(1, 1), (2, 2), (1, 480), (854, 1), (5, 3)] {
            let Ok(mut gpu) = Gpu::headless(width, height, mc_render::GpuOptions::default()) else {
                eprintln!("skip: no wgpu adapter available on this machine");
                return;
            };
            let Some((mut client, _dir)) = offline_client() else {
                return;
            };
            let (session, to_game, _to_net) = offline_session(mc_world::World::new());
            client.session = Some(session);
            use mc_protocol::play::S2CPlay;
            for packet in [
                S2CPlay::JoinGame(mc_protocol::play::s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                }),
                S2CPlay::PlayerPositionLook(mc_protocol::play::s2c::PlayerPositionLook {
                    x: 0.5,
                    y: 64.0,
                    z: 0.5,
                    yaw: 0.0,
                    pitch: 0.0,
                    flags: 0,
                }),
            ] {
                to_game
                    .try_send(crate::net::ToGame::Packet(packet))
                    .expect("packet channel");
                client.poll();
            }
            assert!(matches!(client.ui, Ui::InGame));
            // Every effect whose targets are a fraction of the window, on.
            for effect in [
                "ambient_occlusion",
                "anti_aliasing",
                "motion_blur",
                "color_grading",
                "volumetric_clouds",
                "custom_sky",
                "menu_blur",
                "blur_hud",
                "shaders_classic",
                "shader",
                "underwater_clarity",
            ] {
                let _ = client.mods.settings.set_enabled(effect, true);
            }
            for known in [
                "ambient_occlusion",
                "anti_aliasing",
                "motion_blur",
                "color_grading",
                "menu_blur",
            ] {
                assert!(client.mods.settings.enabled(known), "{known} is on");
            }
            let mut phases = PhaseList::new();
            client.install(&gpu, &mut phases, width, height);
            let mut camera = Camera::default();
            camera.set_viewport(width, height);
            let mut input = InputState::default();
            let settings = GameSettings::default();
            let stats = mc_render::FrameStats::new();
            for frame_index in 0..6 {
                if frame_index == 4 {
                    // A menu over the game: the blurred-backdrop path.
                    client.handle_action(Action::OpenOptions);
                }
                <Client as mc_render::ShellApp>::before_ticks(&mut client, &mut camera);
                <Client as mc_render::ShellApp>::frame(
                    &mut client,
                    &mut mc_render::FrameCtx {
                        gpu: &gpu,
                        phases: &mut phases,
                        camera: &mut camera,
                        input: &mut input,
                        settings: &settings,
                        partial_ticks: 0.5,
                        stats: &stats,
                    },
                );
                camera.update();
                let frame = gpu.acquire().unwrap_or_else(|error| {
                    panic!("game frame {frame_index} at {width}x{height}: {error}")
                });
                phases.render(&gpu, frame.view(), &camera, 0.5);
                frame.present(&gpu.queue);
            }
        }
    }

