    #[test]
    fn multiplayer_wheel_dispatch_uses_the_live_cursor_viewport() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut servers = ServerList::new();
        for index in 0..40 {
            servers.add(ServerEntry::new(
                format!("server-{index}"),
                format!("host{index}"),
            ));
        }
        client.ui = Ui::Multiplayer(Box::new(MultiplayerScreen::new(servers)));
        client.settings.gui_scale = 1;
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let language = client.assets.language.clone();
        if let Ui::Multiplayer(screen) = &mut client.ui {
            screen.init(&ctx, &language);
            // The init pass stages the five visible pings; drain them so the input assertion
            // cannot be obscured by the normal at-most-five ping handoff.
            let _ = screen.take_ping_queue();
        } else {
            panic!("the fixture must install Ui::Multiplayer");
        }

        client.cursor = (427, 31);
        client.mouse_wheel(-1.0);
        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("the fixture must retain Ui::Multiplayer");
        };
        assert_eq!(
            screen.slot_index_at(427, 100),
            Some(1),
            "a wheel event over the title/fade must not reach ServerSelectionList"
        );

        client.cursor = (427, 32);
        client.mouse_wheel(-1.0);
        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("the fixture must retain Ui::Multiplayer");
        };
        assert_eq!(
            screen.slot_index_at(427, 100),
            Some(2),
            "the inclusive top viewport boundary must scroll by half a server row"
        );
    }

    /// The full S36 seam: a live sign is locked while editing, a key replaces only its selected
    /// component, and each of vanilla's two close paths emits one unwrapped C12 before restoring
    /// editability.  Running both paths prevents a Done-only test from hiding Escape's
    /// `actionPerformed(doneBtn)` route (or vice versa).
    #[test]
    fn sign_editor_s36_edit_then_escape_or_done_sends_one_c12_and_restores_tile() {
        use crate::app::input::KeyPress;
        use mc_ui::widget::keys::{self, Modifiers};
        use winit::keyboard::KeyCode;

        for close_with_done in [false, true] {
            let Some((mut client, _dir)) = offline_client() else {
                return;
            };
            let position = BlockPos::new(3, 65, 4);
            let mut world = mc_render::terrain::fixture::blank_world(1);
            mc_render::terrain::fixture::place(&mut world, position, "minecraft:standing_sign");
            let (session, _to_game, mut to_net) = offline_session(world);
            client.session = Some(session);
            let initial_components = [
                r#"{"color":"red","text":"old"}"#.to_owned(),
                r#"{"bold":true,"text":"keep"}"#.to_owned(),
                "\"\"".to_owned(),
                "\"\"".to_owned(),
            ];
            client
                .session_mut()
                .expect("live test session")
                .state_mut()
                .world
                .apply_sign_components(
                    position,
                    [
                        "old".to_owned(),
                        "keep".to_owned(),
                        String::new(),
                        String::new(),
                    ],
                    initial_components.clone(),
                );

            client.react(&ClientEvent::OpenSignEditor(position));
            let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
            let language = client.assets.language.clone();
            let done_rect = match &mut client.ui {
                Ui::EditSign(screen) => {
                    screen.init(&ctx, &language);
                    screen.done_button().rect
                }
                other => panic!("S36 must open Ui::EditSign, got {}", other.name()),
            };
            client.sync_sign_editor_render_state();
            client.drain_sign_actions();
            assert!(
                !client
                    .session()
                    .unwrap()
                    .world()
                    .tile_entity(position)
                    .and_then(mc_world::TileEntity::sign)
                    .unwrap()
                    .editable,
                "initGui must lock the real tile before S33 can overwrite it"
            );

            client.key_pressed(KeyPress {
                sequence: 0,
                code: KeyCode::KeyX,
                lwjgl: 45,
                typed: Some('x'),
                mods: Modifiers::default(),
                repeat: false,
            });
            if close_with_done {
                client.cursor = (done_rect.x + 1, done_rect.y + 1);
                client.mouse_clicked(0, ctx);
            } else {
                client.key_pressed(KeyPress {
                    sequence: 0,
                    code: KeyCode::Escape,
                    lwjgl: keys::ESCAPE,
                    typed: None,
                    mods: Modifiers::default(),
                    repeat: false,
                });
            }

            let sent = drained(&mut to_net);
            let updates: Vec<_> = sent
                .iter()
                .filter_map(|packet| match packet {
                    mc_protocol::play::C2SPlay::UpdateSign(update) => Some(update),
                    _ => None,
                })
                .collect();
            assert_eq!(
                updates.len(),
                1,
                "Done/Escape must each emit exactly one C12"
            );
            assert_eq!(updates[0].position, position);
            assert_eq!(
                updates[0].lines,
                [
                    "\"oldx\"".to_owned(),
                    initial_components[1].clone(),
                    "\"\"".to_owned(),
                    "\"\"".to_owned(),
                ],
                "C12 receives the model's JSON strings directly, preserving untouched rows"
            );
            let sign = client
                .session()
                .unwrap()
                .world()
                .tile_entity(position)
                .and_then(mc_world::TileEntity::sign)
                .unwrap();
            assert!(sign.editable, "onGuiClosed must restore the tile after C12");
            assert_eq!(sign.components, updates[0].lines);
            assert!(matches!(client.ui, Ui::InGame));
        }
    }

