    #[test]
    fn screen_input_merges_keyboard_and_mouse_by_shell_receipt_order() {
        use winit::event::MouseButton;
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.settings.gui_scale = 1;
        client.handle_action(Action::OpenMultiplayer);
        client.handle_action(Action::OpenAddServer);
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let Ui::AddServer(screen) = &mut client.ui else {
            panic!("add-server screen");
        };
        screen.init(&ctx, &client.assets.language);
        let original_name = screen.name.text().to_owned();

        // The address click arrived first, then X. Draining the keyboard queue first would type
        // into the initially focused name field before applying the older mouse event.
        let mut input = InputState::new();
        input.on_cursor_moved(330.0, 110.0);
        input.on_mouse_button_at_ms_with_sequence(MouseButton::Left, true, 0, 0);
        client.handle_raw_key_with_sequence(KeyCode::KeyX, true, false, Some('x'), 1);
        client.handle_screen_input(&mut input, 854, 480);

        let Ui::AddServer(screen) = &client.ui else {
            panic!("input changed the screen");
        };
        assert_eq!(screen.name.text(), original_name);
        assert_eq!(screen.address.text(), "x");
    }

