        screen
            .address
            .set_text("typed.example.com:25566", &client.font);
        client.handle_action(Action::Connect(Box::new(ServerEntry::new(
            "",
            "typed.example.com:25566",
        ))));
        assert_eq!(client.settings.last_server, "typed.example.com:25566");
        let saved = std::fs::read_to_string(client.config.options_path()).expect("options.txt");
        assert!(saved
            .lines()
            .any(|line| line == "lastServer:typed.example.com:25566"));

        client.settings.last_server = "direct-only.example:25565".to_owned();
