    /// F-P2-client.gui-03-10: the real input route must reach GuiTextField's Java boundary walk,
    /// including a click that arrives before the first draw has laid out the newly opened chat.
    #[test]
    fn clicking_a_live_chat_input_places_the_caret_at_scaled_java_boundaries() {
        use mc_ui::widget::Rect;
        use winit::event::MouseButton;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.settings.gui_scale = 2;
        client.open_chat("abcdef");

        let (width, height) = (1280, 601);
        let resolution = client.resolution(width, height);
        assert_eq!(
            (
                resolution.scale_factor(),
                resolution.scaled_width(),
                resolution.scaled_height()
            ),
            (2, 640, 301),
            "the physical fixture must exercise scaled GUI coordinates"
        );
        let mut input = mc_render::InputState::new();
        let glyph_width = client.font.string_width("a");
        assert!(
            glyph_width > 0,
            "the live font must measure the ASCII fixture"
        );
        let boundary_gui_x = 4 + glyph_width;
        let physical_x = |gui_x: i32| gui_x * width as i32 / resolution.scaled_width();

        // One physical pixel before the first glyph boundary must stay at position zero. This is
        // intentionally the first event after open_chat, before any draw/init pass.
        input.on_cursor_moved(f64::from(physical_x(boundary_gui_x - 1)), 580.0);
        input.on_mouse_button(MouseButton::Left, true);
        client.handle_screen_input(&mut input, width, height);
        let Ui::Chat(screen) = &client.ui else {
            panic!("the click must leave the chat screen open");
        };
        assert_eq!(screen.input.rect, Rect::new(4, 289, 636, 12));
        assert_eq!(screen.input.cursor_position(), 0);
        assert_eq!(screen.input.selection_end(), 0);

        // Release the edge, then click exactly on the first glyph boundary. Java's
        // trimStringToWidth chooses the longest prefix that fits, so this exact pixel selects
        // position one rather than zero.
        input.on_mouse_button(MouseButton::Left, false);
        client.handle_screen_input(&mut input, width, height);
        input.on_cursor_moved(f64::from(physical_x(boundary_gui_x)), 580.0);
        input.on_mouse_button(MouseButton::Left, true);
        client.handle_screen_input(&mut input, width, height);
        let Ui::Chat(screen) = &client.ui else {
            panic!("the boundary click must leave the chat screen open");
        };
        assert_eq!(screen.input.cursor_position(), 1);
        assert_eq!(screen.input.selection_end(), 1);

        // Build a real selection, then click one GUI pixel above the field (physical y=576 maps
        // to GUI y=288). GuiTextField has canLoseFocus=false, so this outside click must not move
        // either selection endpoint. This also guards the chat init/relayout marker from being
        // consumed on every frame.
        input.on_mouse_button(MouseButton::Left, false);
        client.handle_screen_input(&mut input, width, height);
        let font = &client.font;
        if let Ui::Chat(screen) = &mut client.ui {
            screen.input.set_cursor_position(6, font);
            screen.input.set_selection_pos(0, font);
            assert_eq!(screen.input.selected_text(), "abcdef");
        } else {
            panic!("the chat screen must still own its input");
        }
        input.on_cursor_moved(18.0, 576.0);
        input.on_mouse_button(MouseButton::Left, true);
        client.handle_screen_input(&mut input, width, height);
        let Ui::Chat(screen) = &client.ui else {
            panic!("the outside click must leave the chat screen open");
        };
        assert_eq!(screen.input.cursor_position(), 6);
        assert_eq!(screen.input.selection_end(), 0);
    }

    /// F-P1-util-14-3: Java treats Command as GuiScreen's control modifier on macOS. Drive the
    /// deterministic macOS branch through RawKeyboard's real queue, the live per-frame screen
    /// dispatcher and ChatScreen's actual TextField, rather than testing either endpoint alone.
    #[test]
    fn mac_command_reaches_live_text_field_editing_and_word_selection() {
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.open_chat("alpha beta gamma");

        {
            let mut key = |code, pressed, typed| {
                client
                    .keyboard
                    .push_for_platform_for_test(code, pressed, typed, true);
            };
            key(KeyCode::SuperLeft, true, None);
            key(KeyCode::KeyA, true, Some('a'));
            key(KeyCode::KeyC, true, Some('c'));
            key(KeyCode::KeyX, true, Some('x'));
            key(KeyCode::KeyV, true, Some('v'));
        }
        client.handle_screen_input(&mut InputState::new(), 854, 480);

        let Ui::Chat(screen) = &client.ui else {
            panic!("Command editing must leave chat open");
        };
        assert_eq!(screen.input.text(), "alpha beta gamma");
        assert_eq!(screen.input.cursor_position(), 16);

        {
            let mut key = |code, pressed| {
                client
                    .keyboard
                    .push_for_platform_for_test(code, pressed, None, true);
            };
            key(KeyCode::ArrowLeft, true);
            key(KeyCode::ShiftLeft, true);
            key(KeyCode::ArrowRight, true);
            key(KeyCode::ShiftLeft, false);
            key(KeyCode::SuperLeft, false);
        }
        client.handle_screen_input(&mut InputState::new(), 854, 480);

        let Ui::Chat(screen) = &client.ui else {
            panic!("Command word selection must leave chat open");
        };
        assert_eq!(screen.input.cursor_position(), 11);
        assert_eq!(screen.input.selection_end(), 16);
        assert_eq!(screen.input.selected_text(), "gamma");
    }

    /// java: `GuiChat.autocompletePlayerNames:232-247` prints the
    /// candidate line with `printChatMessageWithOptionalDeletion(..., 1)` on the cycle S3A starts
    /// **and on every later cycling Tab** while more than one name was found, so the id-1 line is
    /// deleted and re-added as the newest line each time. The old client printed it only from
    /// the S3A arm; a cycling Tab left it buried under later chat. A single candidate prints no
    /// line on either path.
    #[test]
    fn every_cycling_tab_reprints_the_candidate_line() {
        use mc_ui::widget::keys as uikeys;
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let hint_lines = |client: &Client| {
            client
                .chat
                .lines()
                .iter()
                .filter(|line| line.id == 1)
                .count()
        };
        client.open_chat("/tp No");
        let action =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        client.handle_action(action);
        let _ = drained(&mut to_net);
        client.react(&ClientEvent::TabComplete(vec![
            "Notch".into(),
            "Nobody".into(),
        ]));
        assert_eq!(
            hint_lines(&client),
            1,
            "the S3A-started cycle prints the line"
        );
        // Ordinary chat arrives on top of the hint while the player is still cycling.
        let layout = ChatLayout::from_settings(&client.settings);
        client.chat.add_message(
            mc_ui::font::component::ChatComponent::text("unrelated"),
            0,
            client.tick as i32,
            &layout,
            &client.font,
            &client.assets.language,
            true,
        );
        assert_eq!(client.chat.lines()[0].id, 0);

        let action =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        client.handle_action(action);
        let Ui::Chat(screen) = &client.ui else {
            panic!("cycling keeps chat open");
        };
        assert_eq!(screen.input.text(), "/tp Nobody");
        assert_eq!(
            client.chat.lines()[0].id,
            1,
            "the cycling Tab re-prints the candidate line as the newest line"
        );
        assert!(client.chat.lines()[0].text.contains("Notch, Nobody"));
        assert_eq!(hint_lines(&client), 1, "id 1 replaces, never stacks");
        assert!(
            drained(&mut to_net).is_empty(),
            "cycling is local: no second C14"
        );

        // A non-Tab key never prints, even right after a cycle set the flag.
        let before = client.chat.lines().len();
        let _ = client.screen_key_typed(Some('x'), 45, mc_ui::widget::keys::Modifiers::default());
        assert_eq!(client.chat.lines().len(), before);

        // One candidate equal to the typed word takes the cycling branch, but Java's
        // `size() > 1` gate prints nothing on the S3A or on the cycling Tab.
        client.open_chat("/gamemode");
        let action =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        client.handle_action(action);
        let lines_before_single = client.chat.lines().len();
        client.react(&ClientEvent::TabComplete(vec!["/gamemode".into()]));
        let _ =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        assert_eq!(client.chat.lines().len(), lines_before_single);
    }

    #[test]
    fn live_chat_completion_sends_the_looked_at_block_and_consumes_the_reply() {
        use mc_ui::widget::keys as uikeys;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let expected = client.hit.block().expect("fixture block").pos;
        client.open_chat("/he");
        let action =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        client.handle_action(action);

        let sent = drained(&mut to_net);
        let request = sent
            .iter()
            .find_map(|packet| match packet {
                mc_protocol::play::C2SPlay::TabComplete(packet) => Some(packet),
                _ => None,
            })
            .expect("Tab sends C14");
        assert_eq!(request.message, "/he");
        assert_eq!(request.target_block, Some(expected));

        client.react(&ClientEvent::TabComplete(vec![
            "/head".into(),
            "/hello".into(),
        ]));
        let Ui::Chat(screen) = &client.ui else {
            panic!("completion keeps chat open")
        };
        assert_eq!(screen.completions(), &["/head", "/hello"]);
        assert!(
            screen.completion_hint(),
            "an equal common prefix takes Java's candidate-hint branch"
        );
        let hint_count = client
            .chat
            .lines()
            .iter()
            .filter(|line| line.id == 1)
            .count();

        // A shorter input lets the same response insert `/hel`; Java leaves the id-1 line alone
        // instead of printing the candidates for this prefix-extension branch.
        client.open_chat("/h");
        let action =
            client.screen_key_typed(None, uikeys::TAB, mc_ui::widget::keys::Modifiers::default());
        client.handle_action(action);
        let _ = drained(&mut to_net);
        client.react(&ClientEvent::TabComplete(vec![
            "/help".into(),
            "/hello".into(),
        ]));
        let Ui::Chat(screen) = &client.ui else {
            panic!("prefix completion keeps chat open")
        };
        assert_eq!(screen.input.text(), "/hel");
        assert!(!screen.completion_hint());
        assert_eq!(
            client
                .chat
                .lines()
                .iter()
                .filter(|line| line.id == 1)
                .count(),
            hint_count,
            "prefix insertion does not produce another id-1 hint"
        );
    }

    /// The five chat geometry/opacity sliders call `GuiNewChat.refreshChat` immediately. The
    /// mc-ui event alone is not sufficient evidence: this drives a real slider through the
    /// client and observes refresh's externally visible scroll reset.
    #[test]
    fn chat_slider_press_refreshes_the_live_chat_log() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let layout = ChatLayout::from_settings(&client.settings);
        for tick in 0..30 {
            client.chat.add_message(
                mc_ui::font::component::ChatComponent::text(format!("line {tick}")),
                0,
                tick,
                &layout,
                &client.font,
                &client.assets.language,
                false,
            );
        }
        client.chat.scroll_by(3, &layout, true);
        assert!(
            client.chat.scroll_pos() > 0,
            "negative control: log is scrolled"
        );

        client.handle_action(Action::OpenOptions);
        client.handle_action(Action::OpenOptionsPage(OptionsPage::Chat));
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let Ui::OptionList(_, screen) = &mut client.ui else {
            panic!("expected chat options")
        };
        screen.init(&ctx, &client.settings, &client.assets.language);
        let row = screen
            .list
            .rows
            .iter()
            .find(|row| {
                matches!(
                    row,
                    mc_ui::screens::options::OptionRow::Slider(
                        mc_ui::screens::options::OptionId::ChatWidth,
                        _
                    )
                )
            })
            .expect("chat width slider");
        let mc_ui::screens::options::OptionRow::Slider(_, slider) = row else {
            unreachable!()
        };
        client.cursor = (slider.button.rect.x + 40, slider.button.rect.y + 5);
        client.mouse_clicked(0, ctx);

        assert_eq!(client.chat.scroll_pos(), 0);
        assert!(!client.chat.is_scrolled());
    }

    /// java: inherited `GuiScreen.keyTyped` sends Escape to `displayGuiScreen(null)`, not to a
    /// screen's Done button and its `parentScreen`. `GuiControls` only swallows Escape while a
    /// binding is armed.
    #[test]
    fn escape_closes_the_options_tree_instead_of_pressing_done() {
        use mc_ui::widget::keys as uikeys;
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let escape = |client: &mut Client| {
            client.key_pressed(crate::app::input::KeyPress {
                sequence: 0,
                code: winit::keyboard::KeyCode::Escape,
                lwjgl: uikeys::ESCAPE,
                typed: None,
                mods: mc_ui::widget::keys::Modifiers::default(),
                repeat: false,
            });
        };

        client.handle_action(Action::OpenOptions);
        client.handle_action(Action::OpenOptionsPage(OptionsPage::Video));
        escape(&mut client);
        assert_eq!(client.ui.name(), "main_menu");

        // GuiControls reaches the inherited close path when it is not capturing a binding.
        client.handle_action(Action::OpenOptions);
        client.handle_action(Action::OpenOptionsPage(OptionsPage::Controls));
        escape(&mut client);
        assert_eq!(client.ui.name(), "main_menu");

        // And while a binding is armed, Escape *unbinds* rather than closing. java:
        // `setOptionKeyBinding(buttonId, 0)`.
        client.handle_action(Action::OpenOptions);
        client.handle_action(Action::OpenOptionsPage(OptionsPage::Controls));
        let Ui::Controls(screen) = &mut client.ui else {
            panic!("expected the controls screen")
        };
        screen.arming = Some(mc_render::input::keys::FORWARD.to_owned());
        escape(&mut client);
        assert_eq!(client.ui.name(), "controls", "the screen must stay open");
        assert_eq!(
            client
                .settings
                .keys
                .get(mc_render::input::keys::FORWARD)
                .map(|b| b.binding()),
            Some(mc_render::input::Input::Unbound)
        );
    }

    /// The half of A06-01 that is not routing: a changed option has to reach `options.txt` and
    /// the live subsystem. This clicks a real row on the real video screen through
    /// `Client::mouse_clicked` and then reads the file back off disk.
    #[test]
    fn changing_a_video_option_reaches_both_options_txt_and_the_next_frames_layout() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.handle_action(Action::OpenOptions);
        client.handle_action(Action::OpenOptionsPage(OptionsPage::Video));

        // Lay the rows out at a known resolution, then click the Graphics button.
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let Ui::OptionList(_, screen) = &mut client.ui else {
            panic!("expected the video screen")
        };
        screen.init(&ctx, &client.settings, &client.assets.language);
        let mc_ui::screens::options::OptionRow::Button(_, button) = &screen.list.rows[0] else {
            panic!("java: GuiVideoSettings' first option is Graphics, a cycling button")
        };
        let (x, y) = (button.rect.x + 1, button.rect.y + 1);
        assert!(client.settings.fancy_graphics);
        client.cursor = (x, y);
        client.mouse_clicked(0, ctx);
        assert!(
            !client.settings.fancy_graphics,
            "the click changed the value"
        );

        // java: `GameSettings.setOptionValue` ends in `saveOptions()`.
        let saved = std::fs::read_to_string(client.config.options_path())
            .expect("options.txt must have been written");
        assert!(
            saved.lines().any(|l| l == "fancyGraphics:false"),
            "options.txt must carry the new value, got:\n{saved}"
        );

        // The "applied" half, for the one option this can prove with no world loaded: GUI scale
        // is re-derived from `self.settings` by `Client::resolution`, which `build_ui` calls on
        // **every** frame, so moving the slider changes the very next frame's layout.
        // java: `GuiVideoSettings.mouseClicked` re-running `setWorldAndResolution`.
        client.settings.gui_scale = 1;
        let at_one = client.resolution(854, 480).scaled_width();
        client.settings.gui_scale = 3;
        let at_three = client.resolution(854, 480).scaled_width();
        assert!(
            at_three < at_one,
            "a larger GUI scale must shrink the scaled surface: {at_one} -> {at_three}"
        );
    }

    /// `Action::Relayout` was declared, emitted by two screens, and handled by nobody. The half
    /// that is real work is the language switch: java: `GuiLanguage.actionPerformed` →
    /// `languageManager.setCurrentLanguage` + `refreshResources()`. Storing `lang:` in
    /// `options.txt` without reloading the table would leave the whole UI in the old language
    /// until the next restart.
    #[test]
    fn switching_the_language_reloads_the_translation_table_not_just_the_setting() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        assert_eq!(client.assets.language.code(), mc_assets::DEFAULT_LANGUAGE);

        // The language screen must be able to offer something other than en_US at all — that is
        // `available_languages`, which reads the object store's `pack.mcmeta`.
        let languages = client.available_languages();
        assert!(
            languages.len() > 1,
            "the 1.8 asset index declares ~75 locales, got {}",
            languages.len()
        );
        let Some(other) = languages.iter().find(|l| l.code == "en_GB") else {
            eprintln!("skip: this asset index does not declare en_GB");
            return;
        };

        client.settings.language = other.code.clone();
        client.handle_action(Action::Relayout);
        assert_eq!(
            client.assets.language.code(),
            "en_GB",
            "the live translation table must follow the setting"
        );
        assert_eq!(
            client.assets.language.tr("gui.done"),
            "Done",
            "and it must have really loaded, not just been renamed"
        );

        // java: `GuiOptions`' every transition calls `saveOptions()`.
        let saved = std::fs::read_to_string(client.config.options_path()).expect("options.txt");
        assert!(
            saved.lines().any(|l| l == "lang:en_GB"),
            "options.txt must carry the new locale, got:\n{saved}"
        );
    }

    /// Rebinding a key on `GuiControls` writes `client.settings.keys`, but the window loop reads
    /// the **shell's** clone (`main.rs` hands `Shell::run` a `client.settings.clone()`). Until
    /// `handle_game_input` reconciled them, every rebind was inert.
    #[test]
    fn a_rebound_key_reaches_the_bindings_the_window_loop_actually_reads() {
        use mc_render::input::{keys as bind, Input};
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut shell_keys = client.settings.keys.clone();
        client
            .settings
            .keys
            .set_binding(bind::FORWARD, Input::from_lwjgl(23));
        assert_ne!(
            shell_keys.get(bind::FORWARD).map(|b| b.binding()),
            client.settings.keys.get(bind::FORWARD).map(|b| b.binding()),
            "the two copies start out disagreeing, which is the bug"
        );

        client.handle_game_input(&InputState::new(), &mut shell_keys);
        assert_eq!(
            shell_keys.get(bind::FORWARD).map(|b| b.binding()),
            Some(Input::from_lwjgl(23)),
            "the rebind must reach the shell's copy"
        );
    }

    #[test]
    fn smooth_camera_keybinding_reaches_the_live_session_flag() {
        use mc_render::input::{keys as bind, Input};
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut shell_keys = client.settings.keys.clone();
        client
            .settings
            .keys
            .set_binding(bind::SMOOTH_CAMERA, Input::Key(KeyCode::F8));

        // First tick transfers the rebind to the shell-owned live bindings. The next key edge
        // must toggle the actual field the render frame reads, even with no world yet loaded.
        client.handle_game_input(&InputState::new(), &mut shell_keys);
        shell_keys.set_state(Input::Key(KeyCode::F8), true);
        client.handle_game_input(&InputState::new(), &mut shell_keys);
        assert!(client.settings.smooth_camera);

        // It is a key toggle, not a held switch: release then a second edge turns it back off.
        shell_keys.set_state(Input::Key(KeyCode::F8), false);
        shell_keys.set_state(Input::Key(KeyCode::F8), true);
        client.handle_game_input(&InputState::new(), &mut shell_keys);
        assert!(!client.settings.smooth_camera);

        let source = include_str!("driver.rs");
        assert!(
            source.contains("self.smooth_camera.tick("),
            "the live game-tick owner must advance the smooth filter"
        );
        assert!(
            source.contains(".look_delta_raw(self.look_sensitivity(), false)"),
            "invert-Y must stay out of the persistent MouseFilter registers"
        );
        assert!(
            source.contains("dy * if self.settings.invert_mouse"),
            "the live frame must apply invert-Y after smooth filtering"
        );
    }

    #[test]
    fn mouse_grab_boundary_is_reconciled_before_look_sampling() {
        // Java's displayGuiScreen/setIngameFocus boundary preserves an ungrabbed delta but
        // clears it when the next grab happens. Keep the live frame ordering explicit: a GUI
        // frame must not consume the pending delta, and a gameplay frame must request Grabbed
        // before look_delta_raw can read the reset.
        let source = include_str!("driver.rs");
        let request = source
            .find("let wants_cursor = self.reconcile_cursor_grab(ctx.input, width, height);")
            .expect("live frame cursor request");
        let look = source
            .find(".look_delta_raw(self.look_sensitivity(), false)")
            .expect("live frame look sample");
        let guard = source[request..look]
            .find("if !wants_cursor && self.diagnostic_progress.is_none() {")
            .expect("look sample remains gameplay-gated");

        // B2 (2026-11-07): a screen the ticks or the event pump opened must release (and
        // re-centre) the cursor before its first input pass reads the pointer.
        let early = source
            .find("self.reconcile_cursor_grab(ctx.input, width, height);")
            .expect("early cursor reconcile");
        let screen_input = source
            .find("self.handle_screen_input(ctx.input, width, height);")
            .expect("live frame screen input pass");
        assert!(
            early < screen_input && screen_input < request,
            "release before the first input pass, and again after it"
        );
        assert!(
            request < look,
            "cursor mode must be reconciled before sampling"
        );
        assert!(
            request + guard < look,
            "GUI frames must not drain raw motion"
        );

        // Negative control: the old tail placement would leave the request after the sample.
        assert!(
            !source[..look].contains("ctx.input.request_cursor(if self.ui.wants_cursor()"),
            "the stale post-sample request must not return"
        );
    }

    /// A focused, grabbed, in-game `InputState` on a 854x480 window at GUI scale 2, with the
    /// hidden pointer parked at `parked` (wherever the last grab caught it).
    fn in_game_with_parked_pointer(client: &mut Client, parked: (f64, f64)) -> InputState {
        client.settings.gui_scale = 2;
        client.ui = Ui::InGame;
        let mut input = InputState::new();
        input.on_focus(true);
        input.set_window_size(854, 480);
        assert!(!client.reconcile_cursor_grab(&mut input, 854, 480));
        assert!(input.grabbed());
        input.on_cursor_moved(parked.0, parked.1);
        input
    }

    /// Should the cursor go back to the middle of the screen when opening an inventory? Yes: `displayGuiScreen` → `setIngameNotInFocus` →
    /// `MouseHelper.ungrabMouseCursor` puts the pointer at `Mouse.setCursorPosition(w / 2,
    /// h / 2)` before the screen's first input and `drawScreen`. A screen a tick opens (the
    /// inventory key, an S2D window, the lost-focus pause) must see that point in its first
    /// input pass, before any OS echo of the shell's warp.
    #[test]
    fn a_screen_opened_by_a_tick_sees_the_centred_cursor_in_its_first_input_pass() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut input = in_game_with_parked_pointer(&mut client, (20.0, 470.0));

        // The tick opens a screen; then the frame's early reconcile and its input pass.
        client.show_screen(Some(Ui::Pause(Box::new(PauseScreen::new()))));
        assert!(client.reconcile_cursor_grab(&mut input, 854, 480));
        client.handle_screen_input(&mut input, 854, 480);

        assert!(!input.grabbed());
        assert!(
            input.take_cursor_recentre(),
            "the shell is asked to warp the OS pointer"
        );
        assert_eq!(input.cursor(), (427.0, 239.0));
        // Vanilla: Mouse.getX/getY = (427, 240) after the ungrab, and drawScreen receives
        // (427 * 427 / 854, 240 - 240 * 240 / 480 - 1) at scale 2.
        assert_eq!(client.cursor_window, (427, 240));
        assert_eq!(client.cursor, (213, 119));

        // A screen-to-screen change keeps the pointer: vanilla only ungrabs from in-game.
        input.on_cursor_moved(100.0, 100.0);
        client.show_screen(Some(Ui::Pause(Box::new(PauseScreen::new()))));
        assert!(client.reconcile_cursor_grab(&mut input, 854, 480));
        client.handle_screen_input(&mut input, 854, 480);
        assert!(!input.take_cursor_recentre());
        assert_eq!(client.cursor, (50, 50));
    }

    /// Escape opens Pause inside the input pass itself, after the pass sampled the pointer. The
    /// frame's second reconcile must release, re-centre and re-sample before Pause's first draw.
    #[test]
    fn escape_in_the_input_pass_recentres_before_the_pause_menu_is_drawn() {
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut input = in_game_with_parked_pointer(&mut client, (800.0, 10.0));

        client.handle_raw_key(KeyCode::Escape, true, false, None);
        assert!(
            !client.reconcile_cursor_grab(&mut input, 854, 480),
            "still in game"
        );
        client.handle_screen_input(&mut input, 854, 480);
        assert!(matches!(client.ui, Ui::Pause(_)));
        assert_eq!(client.cursor, (400, 5), "sampled while still in game");

        assert!(client.reconcile_cursor_grab(&mut input, 854, 480));
        assert_eq!(
            client.cursor,
            (213, 119),
            "Pause's first draw sees the centre"
        );
        assert_eq!(client.cursor_window, (427, 240));
        assert!(input.take_cursor_recentre());
    }

    /// The Alt-Tab release and the lost-focus pause leave the pointer alone: by then it belongs
    /// to another application, and the shell must not drag it back into the game window.
    #[test]
    fn an_unfocused_screen_open_does_not_recentre() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut input = in_game_with_parked_pointer(&mut client, (800.0, 10.0));
        input.on_focus(false);
        // The frame after the focus loss re-grabs (no screen yet), then the pause opens.
        assert!(!client.reconcile_cursor_grab(&mut input, 854, 480));
        client.show_screen(Some(Ui::Pause(Box::new(PauseScreen::new()))));
        assert!(client.reconcile_cursor_grab(&mut input, 854, 480));
        client.handle_screen_input(&mut input, 854, 480);
        assert!(!input.take_cursor_recentre());
        assert_eq!(input.cursor(), (800.0, 10.0));
        assert_eq!(client.cursor, (400, 5));
    }

    // ---- the tab-list overlay ----------------------------------------

    /// `key.playerlist` was one of four bindings that were bound but never read. The overlay is
    /// gated on the held state sampled in `handle_game_input`, so this checks the sampling and
    /// the "a screen being open drops it" rule that `unpress_all` gives for free.
    #[test]
    fn holding_tab_is_what_raises_the_overlay() {
        use mc_render::input::keys as bind;
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut keys = client.settings.keys.clone();
        assert!(!client.tab_list_held);

        keys.set_state(
            keys.get(bind::PLAYER_LIST).expect("Tab is bound").binding(),
            true,
        );
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(client.tab_list_held, "Tab held must raise the flag");

        // java: `displayGuiScreen` → `setIngameNotInFocus` → `unPressAllKeys`, which is what
        // makes the overlay vanish the moment a screen opens even with Tab still physically down.
        client.show_screen(Some(Ui::Pause(Box::new(PauseScreen::new()))));
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(!client.tab_list_held);
    }

    /// Every options screen must actually *render* through the real client path — not just be
    /// constructible. This drives `Client::build_ui` on a real (headless) GPU for each page and
    /// checks the submitted draw list carries the widget artwork and the glyphs a laid-out screen
    /// produces. Without it, "reachable" could still mean "opens to a blank surface".
    #[test]
    fn the_drop_binding_sends_in_survival_and_is_consumed_in_spectator_mode() {
        use mc_protocol::play::s2c::GameMode;
        use mc_render::input::keys as bind;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.ui = Ui::InGame;
        let mut keys = client.settings.keys.clone();
        let binding = keys.get(bind::DROP).expect("drop is bound").binding();

        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(
            !drained(&mut to_net).is_empty(),
            "survival control must send the drop action"
        );

        // `runTick:2107` asks `thePlayer.isSpectator()`, the player's
        // own S38 tab row (H2's `player_is_spectator`), not the controller's game type. A
        // controller in spectator whose row has not arrived still drops; this used to be refused.
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .game_mode = GameMode::Spectator;
        keys.set_state(binding, false);
        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(
            !drained(&mut to_net).is_empty(),
            "no local spectator tab row: thePlayer.isSpectator() is false, so the drop is sent"
        );

        let set_row = |client: &mut Client, game_mode: GameMode| {
            let session = client.session.as_mut().expect("session");
            let uuid = session.state().local.uuid;
            session
                .state_mut()
                .players
                .apply(&mc_protocol::play::s2c::PlayerListItem::AddPlayer(vec![
                    mc_protocol::play::s2c::AddPlayerEntry {
                        uuid,
                        username: "Dev".into(),
                        properties: Vec::new(),
                        game_mode,
                        ping: 0,
                        display_name: None,
                    },
                ]))
                .expect("the local row applies");
        };
        set_row(&mut client, GameMode::Spectator);
        keys.set_state(binding, false);
        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(
            drained(&mut to_net).is_empty(),
            "spectator presses are consumed without C07"
        );

        // A spectator row with the controller back in survival is still a spectator here.
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .game_mode = GameMode::Survival;
        keys.set_state(binding, false);
        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(
            drained(&mut to_net).is_empty(),
            "the tab row, not the controller, gates the drop key"
        );
    }

    /// **W-GAMEMODE / F-P1-world-08-1.** The live `sendClickBlockToController` seam must carry
    /// the controller's Adventure/Spectator gate all the way to the wire. Survival is the
    /// negative control: it must still produce the ordinary C07 START packet.
    #[test]
    fn live_block_digging_suppresses_c07_in_adventure_and_spectator() {
        use mc_protocol::play::s2c::GameMode;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;

        for mode in [GameMode::Adventure, GameMode::Spectator] {
            let session = client.session.as_mut().expect("live test session");
            session.state_mut().local.game_mode = mode;
            session
                .state_mut()
                .local
                .abilities
                .configure_for_game_mode(mode);

            client.send_click_block_to_controller(true);
            let sent = drained(&mut to_net);
            assert!(
                sent.iter().all(|packet| {
                    !matches!(packet, mc_protocol::play::C2SPlay::PlayerDigging(_))
                }),
                "{mode:?} must not queue any C07: {sent:?}"
            );
            assert!(
                sent.is_empty(),
                "the denied block path must not leak a swing or another action: {sent:?}"
            );
        }

        // Negative control: the same live target remains breakable in Survival and therefore
        // proves this test can reach the C07 producer rather than passing on an inert fixture.
        let session = client.session.as_mut().expect("live test session");
        session.state_mut().local.game_mode = GameMode::Survival;
        session
            .state_mut()
            .local
            .abilities
            .configure_for_game_mode(GameMode::Survival);
        client.send_click_block_to_controller(true);
        let sent = drained(&mut to_net);
        assert!(
            sent.iter().any(|packet| matches!(
                packet,
                mc_protocol::play::C2SPlay::PlayerDigging(dig)
                    if dig.status
                        == mc_protocol::play::c2s::PlayerDiggingStatus::StartDestroyBlock
            )),
            "Survival must retain its C07 START control: {sent:?}"
        );
    }

    /// **W-GAMEMODE / F-P3-client.gui.spectator-01-1.** Both spectator hotbar controls are UI
    /// actions, not inventory mutations. The next controller update is included so an eager
    /// `select_hotbar_slot` mutation demonstrably turns into the forbidden C09.
    #[test]
    fn spectator_hotbar_selection_stays_in_the_menu_without_c09() {
        use mc_protocol::play::s2c::GameMode;
        use mc_render::input::keys as bind;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        let session = client.session.as_mut().expect("live test session");
        session.state_mut().local.game_mode = GameMode::Spectator;
        session
            .state_mut()
            .local
            .abilities
            .configure_for_game_mode(GameMode::Spectator);
        // H2: `runTick:2079` routes the key on `thePlayer.isSpectator()`, the local S38 row.
        let uuid = session.state().local.uuid;
        let local_row = |game_mode| {
            mc_protocol::play::s2c::PlayerListItem::AddPlayer(vec![
                mc_protocol::play::s2c::AddPlayerEntry {
                    uuid,
                    username: "Dev".into(),
                    properties: Vec::new(),
                    game_mode,
                    ping: 0,
                    display_name: None,
                },
            ])
        };
        session
            .state_mut()
            .players
            .apply(&local_row(GameMode::Spectator))
            .expect("the local spectator row applies");

        let mut keys = client.settings.keys.clone();
        let binding = keys
            .get(&bind::hotbar(4))
            .expect("hotbar four is bound")
            .binding();
        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);

        assert!(
            client.spectator_hud.is_open(),
            "the first key opens GuiSpectator"
        );
        assert_eq!(client.player_hud.selected_slot, 0);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .held_slot,
            0,
            "spectator selection must not mutate InventoryPlayer.currentItem"
        );
        assert!(
            drained(&mut to_net).is_empty(),
            "opening the spectator bar must not emit C09"
        );

        client
            .session
            .as_mut()
            .expect("session")
            .update_controller();
        assert!(
            drained(&mut to_net)
                .iter()
                .all(|packet| !matches!(packet, mc_protocol::play::C2SPlay::HeldItemChange(_))),
            "a controller update after a spectator key must still be C09-free"
        );

        // Negative control: leaving spectator mode restores the ordinary key path, which then
        // reaches C09 at the lazy controller boundary.
        let session = client.session.as_mut().expect("live test session");
        session.state_mut().local.game_mode = GameMode::Survival;
        session
            .state_mut()
            .local
            .abilities
            .configure_for_game_mode(GameMode::Survival);
        session
            .state_mut()
            .players
            .apply(&local_row(GameMode::Survival))
            .expect("the local survival row applies");
        keys.set_state(binding, false);
        keys.set_state(binding, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert_eq!(client.player_hud.selected_slot, 3);
        client
            .session
            .as_mut()
            .expect("session")
            .update_controller();
        assert!(
            drained(&mut to_net).iter().any(|packet| matches!(
                packet,
                mc_protocol::play::C2SPlay::HeldItemChange(
                    mc_protocol::play::c2s::HeldItemChange { slot_id: 3 }
                )
            )),
            "the non-spectator control must still emit its lazy C09"
        );
    }

    /// **W-GAMEMODE / F-P1-entity.player-05-4.** Vanilla uses spectator wheel input for flight
    /// speed while the bar is closed, and switches to menu selection once it exists. Neither
    /// branch changes the inventory slot or emits C09.
    #[test]
    fn spectator_wheel_changes_fly_speed_only_with_a_closed_menu() {
        use mc_protocol::play::s2c::GameMode;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        let session = client.session.as_mut().expect("live test session");
        session.state_mut().local.game_mode = GameMode::Spectator;
        session
            .state_mut()
            .local
            .abilities
            .configure_for_game_mode(GameMode::Spectator);
        let initial_speed = session.state().local.abilities.fly_speed;

        // H2: `runTick:1863` asks `thePlayer.isSpectator()`, the local S38 row. With the
        // controller in spectator but no row yet, the wheel is an ordinary inventory scroll.
        client.mouse_wheel(1.0);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .abilities
                .fly_speed,
            initial_speed,
            "no local tab row: not a spectator for the wheel"
        );
        client.pending_hotbar_scroll = 0;
        let session = client.session.as_mut().expect("live test session");
        let uuid = session.state().local.uuid;
        session
            .state_mut()
            .players
            .apply(&mc_protocol::play::s2c::PlayerListItem::AddPlayer(vec![
                mc_protocol::play::s2c::AddPlayerEntry {
                    uuid,
                    username: "Dev".into(),
                    properties: Vec::new(),
                    game_mode: GameMode::Spectator,
                    ping: 0,
                    display_name: None,
                },
            ]))
            .expect("the local spectator row applies");

        client.mouse_wheel(1.0);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .abilities
                .fly_speed,
            initial_speed + 0.005
        );
        assert_eq!(client.player_hud.selected_slot, 0);
        assert!(
            drained(&mut to_net)
                .iter()
                .all(|packet| !matches!(packet, mc_protocol::play::C2SPlay::HeldItemChange(_))),
            "closed-menu flight-speed changes must not emit C09"
        );

        client.spectator_hud.replace_entries(
            vec![SpectatorEntry::player(
                "Target",
                [1; 16],
                mc_ui::widget::UiTexture::gui("textures/entity/steve.png"),
            )],
            Vec::new(),
        );
        client.spectator_hud.select_slot(0, 0);
        assert!(client.spectator_hud.is_open());
        let open_speed = client
            .session
            .as_ref()
            .expect("session")
            .state()
            .local
            .abilities
            .fly_speed;
        client.mouse_wheel(-1.0);
        assert_eq!(client.spectator_hud.selected_slot(), 0);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .abilities
                .fly_speed,
            open_speed,
            "an open spectator bar consumes wheel input for selection"
        );
        assert!(
            drained(&mut to_net)
                .iter()
                .all(|packet| !matches!(packet, mc_protocol::play::C2SPlay::HeldItemChange(_))),
            "open-menu wheel selection must not emit C09"
        );
    }

    #[test]
    fn same_tick_lightning_uses_distinct_replayable_local_rngs() {
        let tick = 4_242_u64;

        let mut first = mc_math::JavaRandom::new(local_lightning_seed(tick, 0));
        let first_vertex = first.next_i64();
        let first_lifetime = first.next_i32_bound(3) + 1;
        let first_thunder = 0.8 + first.next_f32() * 0.2;
        let first_explosion = 0.5 + first.next_f32() * 0.2;

        let mut second = mc_math::JavaRandom::new(local_lightning_seed(tick, 1));
        let second_vertex = second.next_i64();
        let second_lifetime = second.next_i32_bound(3) + 1;
        let second_thunder = 0.8 + second.next_f32() * 0.2;
        let second_explosion = 0.5 + second.next_f32() * 0.2;

        assert_ne!(
            first_vertex, second_vertex,
            "same-tick bolts need distinct geometry"
        );
        assert_ne!(
            first.raw_seed(),
            second.raw_seed(),
            "each strike keeps its own RNG tail"
        );
        assert!((1..=3).contains(&first_lifetime));
        assert!((1..=3).contains(&second_lifetime));
        assert!((0.8..1.0).contains(&first_thunder));
        assert!((0.5..0.7).contains(&first_explosion));
        assert!((0.8..1.0).contains(&second_thunder));
        assert!((0.5..0.7).contains(&second_explosion));

        let mut replay = mc_math::JavaRandom::new(local_lightning_seed(tick, 0));
        assert_eq!(replay.next_i64(), first_vertex);
        assert_eq!(replay.next_i32_bound(3) + 1, first_lifetime);
        assert_eq!(0.8 + replay.next_f32() * 0.2, first_thunder);
        assert_eq!(0.5 + replay.next_f32() * 0.2, first_explosion);
        assert_eq!(replay.raw_seed(), first.raw_seed());
    }

    /// java: `EntityLightningBolt.onUpdate` requests both strike sounds through
    /// `World.playSoundEffect`, which on a `WorldClient` reaches the empty
    /// `RenderGlobal.playSound`; the audible thunder is the server bolt's S29. A client strike
    /// must therefore play nothing locally, while each strike still advances the private nonce
    /// that seeds its bolt `Random`. This test used to require two local sounds per strike.
    #[test]
    fn a_lightning_event_leaves_its_sounds_to_the_server_s29() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.audio.clear_recent();
        client.react(&ClientEvent::LightningBolt {
            network_id: 9,
            position: DVec3::new(12.5, 64.0, -7.25),
        });
        client.react(&ClientEvent::LightningBolt {
            network_id: 10,
            position: DVec3::new(-3.5, 80.0, 19.25),
        });
        assert_eq!(
            client.audio.recent().count(),
            0,
            "a client-side bolt's playSoundEffect reaches an empty sink"
        );
        assert_eq!(client.lightning_spawn_nonce, 2);

        // Positive control: the server's S29 thunder still reaches the one audio funnel.
        client.react(&ClientEvent::SoundEffect(Box::new(
            mc_protocol::play::s2c::SoundEffect {
                sound_name: "ambient.weather.thunder".to_owned(),
                x_fixed: 100,
                y_fixed: 512,
                z_fixed: -58,
                volume: 10_000.0,
                pitch_quantized: 57,
            },
        )));
        assert_eq!(
            client
                .audio
                .last_play()
                .map(|record| record.request.event.path.as_str()),
            Some("ambient.weather.thunder")
        );
    }

    #[test]
    fn lightning_flash_repin_follows_the_weather_tick_end_state() {
        let source = include_str!("driver.rs");
        let (_, after_tick) = source
            .split_once("pub fn tick(&mut self, input: &MoveInput) {")
            .expect("the concrete 20 Hz Client::tick remains present");
        let (tick, _) = after_tick
            .split_once("fn upload_terrain(")
            .expect("Client::tick ends before frame-only terrain work");
        let decrement = tick
            .find("if self.last_lightning_bolt > 0 {")
            .expect("the independent flash countdown still decays each tick");
        let weather = tick
            .find("WeatherPhase::tick_lightning")
            .expect("the weather-owned bolt lifecycle still ticks each client tick");
        let rearm = tick
            .find("if lightning_flash {")
            .expect("the weather tick result still gates the flash re-pin");
        let assignment = tick
            .find("self.last_lightning_bolt = 2;")
            .expect("a visible/re-struck bolt still re-arms the world flash");
        let refresh = tick[assignment..]
            .find("self.sync_environment();")
            .map(|offset| assignment + offset)
            .expect("the re-pin refreshes sky/fog/weather's tick-end environment");

        // Negative controls: the sampled region includes both sides of the weather call, so a
        // mutant that re-arms before ticking (or refreshes before the assignment) is observable.
        assert!(
            decrement < weather,
            "decay must precede World.updateEntities"
        );
        assert!(weather < rearm && rearm <= assignment);
        assert!(assignment < refresh);
        assert!(tick[rearm..].contains("if lightning_flash {"));
    }

    #[test]
    fn an_explosion_keeps_the_server_sound_single_then_spawns_particles_before_motion() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.settings.particles = 0;
        client.audio.clear_recent();
        let particles_before = client.particles.len();
        let state_before = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("joined predictor")
            .state;
        let before = state_before.vel;
        let explosion_pos = state_before.pos;
        // WorldServer.doExplosionB emits S29 before WorldServer sends S27. The S27 client's
        // `World.playSoundEffect` reaches RenderGlobal.playSound, whose 1.8.9 body is empty, so
        // adding another request here would make an ordinary server explosion audible twice.
        client.react(&ClientEvent::SoundEffect(Box::new(
            mc_protocol::play::s2c::SoundEffect {
                sound_name: "random.explode".to_owned(),
                x_fixed: (explosion_pos.x * 8.0) as i32,
                y_fixed: (explosion_pos.y * 8.0) as i32,
                z_fixed: (explosion_pos.z * 8.0) as i32,
                volume: 4.0,
                pitch_quantized: 44,
            },
        )));
        assert_eq!(client.audio.recent().count(), 1);
        client.react(&ClientEvent::Explosion(Box::new(
            mc_protocol::play::s2c::Explosion {
                x: explosion_pos.x,
                y: explosion_pos.y,
                z: explosion_pos.z,
                strength: 4.0,
                affected_blocks: vec![mc_protocol::play::s2c::ExplosionAffectedBlock {
                    dx: 0,
                    dy: 0,
                    dz: 0,
                }],
                motion_x: 0.25,
                motion_y: 0.5,
                motion_z: -0.75,
            },
        )));
        let sounds: Vec<_> = client.audio.recent().collect();
        assert_eq!(
            sounds.len(),
            1,
            "S27 must not duplicate the explosion sound already delivered by S29"
        );
        assert_eq!(sounds[0].request.event.path, "random.explode");
        assert_eq!(sounds[0].request.volume, 4.0);
        assert_eq!(sounds[0].request.pitch, 44.0 / 63.0);
        assert_eq!(sounds[0].request.position, Some(explosion_pos));
        let after = client
            .session
            .as_ref()
            .and_then(Session::predictor)
            .expect("joined predictor")
            .state
            .vel;
        assert_eq!(
            client.particles.len(),
            particles_before + 3,
            "one affected block adds EXPLOSION_NORMAL + SMOKE_NORMAL after the origin fireball"
        );
        assert_eq!(after, before + DVec3::new(0.25, 0.5, -0.75));
    }

    #[test]
    fn every_options_screen_really_submits_geometry_through_build_ui() {
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 854, 480);

        client.handle_action(Action::OpenOptions);
        for page in [
            None,
            Some(OptionsPage::Video),
            Some(OptionsPage::Chat),
            Some(OptionsPage::Controls),
            Some(OptionsPage::Sound),
            Some(OptionsPage::Language),
            Some(OptionsPage::ResourcePacks),
            Some(OptionsPage::Snooper),
        ] {
            if let Some(page) = page {
                client.handle_action(Action::OpenOptionsPage(page));
            }
            let name = client.ui.name();
            client.build_ui(&gpu, 0.0);
            let render = client.render.as_ref().expect("install populated it");
            let (widgets, glyphs) = render.ui.with(|phase| {
                let batches = phase.list().batches();
                let widgets = batches
                    .iter()
                    .any(|b| b.texture == UiTexture::gui(mc_ui::widget::WIDGETS_TEXTURE));
                let glyphs: usize = batches
                    .iter()
                    .filter(|b| matches!(b.texture, UiTexture::Font(_)))
                    .map(|b| b.range.len())
                    .sum();
                (widgets, glyphs)
            });
            assert!(
                widgets,
                "{name}: no `widgets.png` batch — the buttons were not drawn"
            );
            assert!(glyphs > 0, "{name}: no glyphs — the labels were not drawn");
            if page.is_some() {
                client.handle_action(Action::Back);
            }
        }
    }

