    /// The equipped owner crosses the live preview snapshot and its cached pixels reach the
    /// GUI registry through the same descriptor upload used by ordinary skull item icons.
    #[test]
    fn worn_player_skull_inventory_preview_resolves_owner_and_uploads_cached_texture() {
        use base64::Engine as _;

        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };
        let uuid = uuid::Uuid::from_u128(0x7255_eb31_23a4_4579_8f42_0a1b_c39f_65a1);
        // A player head's skin is named by its texture URL's hash (`SkinManager.loadSkin`).
        let cache_key = crate::app::appearance::skin_texture_key_for_url(
            "https://textures.minecraft.net/texture/inventory-worn-skull-regression",
        )
        .expect("a safe texture hash");
        let wearer_uuid = client.session.as_ref().unwrap().state().local.uuid;
        assert_ne!(
            cache_key,
            crate::app::appearance::skin_texture_key(wearer_uuid)
        );
        let payload = r#"{"textures":{"SKIN":{"url":"https://textures.minecraft.net/texture/inventory-worn-skull-regression","metadata":{"model":"slim"}}}}"#;
        let mut property = mc_nbt::NbtCompound::new();
        property.insert(
            "Value",
            mc_nbt::Nbt::String(base64::engine::general_purpose::STANDARD.encode(payload)),
        );
        let mut properties = mc_nbt::NbtCompound::new();
        properties.insert(
            "textures",
            mc_nbt::Nbt::list(vec![mc_nbt::Nbt::Compound(property)]),
        );
        let mut owner = mc_nbt::NbtCompound::new();
        owner.insert("Id", mc_nbt::Nbt::String(uuid.to_string()));
        owner.insert("Name", mc_nbt::Nbt::String("InventorySkullOwner".into()));
        owner.insert("Properties", mc_nbt::Nbt::Compound(properties));
        let mut tag = mc_nbt::NbtCompound::new();
        tag.insert("SkullOwner", mc_nbt::Nbt::Compound(owner));
        let mut helmet = stack_named("skull", 1);
        helmet.damage = 3;
        helmet.nbt = Some(tag);
        // Seed the async worker's exact completion boundary before decoding the real embedded
        // texture property, so this regression never queues an HTTP request.
        client.appearance.skins.insert(
            &cache_key,
            mc_render::entity::SkinTexture {
                rgba: [220, 40, 160, 255].repeat(64 * 64).into(),
                layout: mc_render::entity::SkinLayout::Modern64x64,
                model: SkinModel::Slim,
            },
        );
        client.player_container.set_slot_contents(5, Some(helmet));
        client.ui = Ui::Container(Box::new(ContainerScreen::new(
            client.player_container.clone(),
            mc_ui::screens::container::ContainerArt::Player,
            "Inventory",
        )));
        let (snapshot, _) = client.refresh_inventory_preview_live(&gpu, 0.5);
        let owner = snapshot
            .helmet_skull_owner
            .expect("helmet owner crosses snapshot");
        assert_eq!(owner.cache_key, cache_key);
        assert_eq!(
            owner.model,
            SkinModel::Slim,
            "embedded texture metadata was decoded"
        );
        assert_eq!(owner.texture_key(), cache_key);

        // Drive the real inventory draw and UI texture-preparation path.
        let mut phases = PhaseList::new();
        client.install(&gpu, &mut phases, 854, 480);
        client.build_ui(&gpu, 0.5);
        let expected_texture = UiTexture::gui(&cache_key);
        client
            .render
            .as_ref()
            .expect("installed render stack")
            .ui
            .with(|phase| {
                assert!(
                    phase.renderer.has_texture(&expected_texture),
                    "cached helmet pixels uploaded to GUI registry"
                );
                assert!(
                    phase
                        .list()
                        .batches()
                        .iter()
                        .any(|batch| batch.texture == expected_texture),
                    "inventory head binds its owner texture"
                );
                assert!(phase.list().builtin_tile_items().iter().any(|item| matches!(
                item, mc_render::entity::tilepass::BuiltinTileItem::PlayerSkull { owner, .. }
                    if owner.cache_key == cache_key
            )));
            });

        client
            .player_container
            .set_slot_contents(5, Some(stack_named("diamond_helmet", 1)));
        let (armor, _) = client.refresh_inventory_preview_live(&gpu, 0.5);
        assert!(
            armor.helmet_skull_owner.is_none(),
            "armor swap clears old skull ownership"
        );
        client.player_container.set_slot_contents(5, None);
        let (empty, _) = client.refresh_inventory_preview_live(&gpu, 0.5);
        assert!(empty.helmet_skull_owner.is_none());
    }

    /// The live inventory seam must sample the current player container/predictor and only the
    /// currently tracked horse generation. Removing the horse leaves no snapshot to render even
    /// when the horse window itself is still open (the network id can be recycled later).
    #[test]
    fn live_inventory_preview_forwards_snapshots_and_rejects_stale_horse_ids() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let Ok(gpu) = mc_render::Gpu::headless(
            64,
            64,
            mc_render::GpuOptions {
                vsync: false,
                sample_count: 1,
                low_power: false,
            },
        ) else {
            eprintln!("skip: no wgpu adapter available on this machine");
            return;
        };

        let helmet = stack_named("diamond_helmet", 1);
        // java: `ContainerPlayer` (`:35-50`) — window slot 5 is `armorInventory[3]`, the helmet
        // (slot 8 is the boots), and the snapshot's index 4 is the helmet.
        client
            .player_container
            .set_slot_contents(5, Some(helmet.clone()));
        client.ui = Ui::Container(Box::new(ContainerScreen::new(
            client.player_container.clone(),
            mc_ui::screens::container::ContainerArt::Player,
            "Inventory",
        )));
        client
            .session
            .as_mut()
            .expect("joined session")
            .predictor_mut()
            .expect("join creates predictor")
            .state
            .sneaking = true;
        let (player, horse) = client.refresh_inventory_preview_live(&gpu, 0.5);
        assert_eq!(player.equipment[4], Some(helmet));
        assert!(player.params.entity.sneaking);
        assert!(horse.is_none(), "player inventory has no horse target");

        {
            let session = client.session.as_mut().expect("joined session");
            crate::sync::apply(
                session.state_mut(),
                mc_protocol::play::S2CPlay::SpawnMob(mc_protocol::play::s2c::SpawnMob {
                    entity_id: 42,
                    entity_type: 100,
                    x: 0,
                    y: 2048,
                    z: 0,
                    yaw: mc_protocol::Angle(0),
                    pitch: mc_protocol::Angle(0),
                    head_pitch: mc_protocol::Angle(0),
                    velocity_x: 0,
                    velocity_y: 0,
                    velocity_z: 0,
                    metadata: Vec::new(),
                }),
                &mut Vec::new(),
            )
            .expect("horse spawn applies");
        }
        let horse_window = mc_protocol::play::s2c::OpenWindow {
            window_id: 2,
            inventory_type: "EntityHorse".to_owned(),
            window_title: String::new(),
            slot_count: 2,
            entity_id: Some(42),
        };
        client.ui = Ui::Container(Box::new(
            ContainerScreen::for_open_window(&horse_window, "Horse").expect("horse window builds"),
        ));
        let (_, horse) = client.refresh_inventory_preview_live(&gpu, 0.5);
        let horse = horse.expect("the retained open-window id resolves the live horse");
        assert_eq!(horse.entity_id, 42);
        assert_eq!(horse.packed_variant, 0);
        assert_eq!(horse.armor, 0);
        assert!(
            !client.inventory_preview_uploads.is_empty(),
            "the layered horse texture must cross into the UI phase"
        );

        crate::sync::apply(
            client.session.as_mut().expect("joined session").state_mut(),
            mc_protocol::play::S2CPlay::DestroyEntities(mc_protocol::play::s2c::DestroyEntities {
                entity_ids: vec![42],
            }),
            &mut Vec::new(),
        )
        .expect("horse destroy applies");
        let (_, stale) = client.refresh_inventory_preview_live(&gpu, 0.5);
        assert!(
            stale.is_none(),
            "despawned horse state must not survive its id"
        );
        assert!(
            client.inventory_preview_uploads.is_empty(),
            "stale horse texture uploads must be cleared with the snapshot"
        );
    }

    #[test]
    fn spectator_player_heads_share_the_downloaded_ui_skin_upload() {
        let uuid = uuid::Uuid::from_u128(0x1234);
        let rgba: std::sync::Arc<[u8]> = vec![37; 64 * 64 * 4].into();
        let (entry, upload) = Client::spectator_entry_for_skin(
            "Target",
            uuid,
            SkinModel::Classic,
            Some(("profile-37".to_owned(), rgba.clone())),
        );
        let expected = Client::ui_skin_texture_key("profile-37");

        assert_eq!(upload, Some((expected.clone(), rgba)));
        assert!(matches!(
            entry.icon,
            mc_ui::screens::spectator::SpectatorIcon::PlayerHead { texture, .. }
                if texture == expected
        ));

        let (fallback, upload) =
            Client::spectator_entry_for_skin("Fallback", uuid, SkinModel::Slim, None);
        assert!(upload.is_none());
        assert!(matches!(
            fallback.icon,
            mc_ui::screens::spectator::SpectatorIcon::PlayerHead { texture, .. }
                if texture == UiTexture::gui("textures/entity/alex.png")
        ));
    }

