    /// The whole overlay, end to end: real `PlayerList` rows fed by real `S38PacketPlayerListItem`
    /// decoding, through `Client::draw_tab_list`, out into a `DrawList`. Before this the player
    /// data arrived and was read by nothing but the F3 line's `players.len()`.
    #[test]
    fn a_populated_player_list_draws_names_ping_bars_and_the_servers_header() {
        use mc_protocol::play::s2c::{AddPlayerEntry, GameMode, PlayerListItem};
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, _to_game, _to_net) = offline_session(mc_world::World::new());
        let add = |uuid: u128, name: &str, ping: i32, mode: GameMode| AddPlayerEntry {
            uuid: uuid::Uuid::from_u128(uuid),
            username: name.to_owned(),
            properties: Vec::new(),
            game_mode: mode,
            ping,
            display_name: None,
        };
        session
            .state_mut()
            .players
            .apply(&PlayerListItem::AddPlayer(vec![
                add(1, "zed", 40, GameMode::Survival),
                add(2, "ghost", 900, GameMode::Spectator),
                add(3, "alice", -1, GameMode::Creative),
            ]))
            .expect("the rows must decode");
        session
            .state_mut()
            .players
            .set_header_footer(
                r#"{"text":"Welcome to Example"}"#,
                r#"{"text":"play.example"}"#,
            )
            .expect("the header must decode");
        client.session = Some(session);

        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let mut list = DrawList::new();
        client.tab_list_held = true;
        client.draw_tab_list(&mut list, &ctx, 5_000);

        assert!(client.tab_list.being_rendered);
        assert_eq!(client.tab_list.last_time_opened, 5_000);

        // Three ping sprites out of `icons.png` — one per row, whatever the latency.
        let icons = UiTexture::gui(mc_ui::widget::draw::ICONS_TEXTURE);
        let ping_quads: usize = list
            .batches()
            .iter()
            .filter(|b| b.texture == icons)
            .map(|b| b.range.len() / 6)
            .sum();
        assert_eq!(ping_quads, 3, "one ping sprite per player");

        // The backdrop, the two header/footer plates and one plate per row.
        let plates: usize = list
            .batches()
            .iter()
            .filter(|b| matches!(b.texture, UiTexture::Solid))
            .map(|b| b.range.len() / 6)
            .sum();
        assert_eq!(plates, 6, "header + block + 3 rows + footer backdrops");

        // Names, header and footer are all glyphs; an empty overlay would have none.
        let glyphs: usize = list
            .batches()
            .iter()
            .filter(|b| matches!(b.texture, UiTexture::Font(_)))
            .map(|b| b.range.len())
            .sum();
        assert!(glyphs > 0, "the names and the header must be drawn");

        // Releasing Tab takes it down again, and `updatePlayerList(false)` is still called.
        client.tab_list_held = false;
        let mut empty = DrawList::new();
        client.draw_tab_list(&mut empty, &ctx, 6_000);
        assert!(empty.batches().is_empty());
        assert!(!client.tab_list.being_rendered);
        assert_eq!(
            client.tab_list.last_time_opened, 5_000,
            "java: lastTimeOpened is only stamped on the rising edge"
        );
    }

    /// java: `GuiPlayerTabOverlay`'s `flag` is the connection encryption bit, and it gates both
    /// the nine-pixel head column and the face draw. This is deliberately exercised through the
    /// client seam rather than only the UI renderer: a regression that hard-codes `false` here
    /// would still pass the renderer's own gate test.
    #[test]
    fn encrypted_login_controls_tab_head_column() {
        use mc_protocol::connection::LoginOutcome;
        use mc_protocol::play::s2c::{AddPlayerEntry, GameMode, PlayerListItem};

        for encrypted in [false, true] {
            let Some((mut client, _dir)) = offline_client() else {
                return;
            };
            let (mut session, to_game, _to_net) = offline_session(mc_world::World::new());
            to_game
                .try_send(crate::net::ToGame::Connected(LoginOutcome {
                    uuid: uuid::Uuid::from_u128(1),
                    username: "alex".to_owned(),
                    compression_threshold: None,
                    encrypted,
                }))
                .expect("login channel");
            session.poll(4);
            session
                .state_mut()
                .players
                .apply(&PlayerListItem::AddPlayer(vec![AddPlayerEntry {
                    uuid: uuid::Uuid::from_u128(1),
                    username: "alex".to_owned(),
                    properties: Vec::new(),
                    game_mode: GameMode::Survival,
                    ping: 0,
                    display_name: None,
                }]))
                .expect("the row must decode");
            client.session = Some(session);
            client.settings.model_parts.insert("hat".to_owned(), false);
            client.tab_list_held = true;
            let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
            let mut list = DrawList::new();
            client.draw_tab_list(&mut list, &ctx, 5_000);
            let alex = UiTexture::gui("textures/entity/alex.png");
            let faces = list
                .batches()
                .iter()
                .filter(|batch| batch.texture == alex)
                .map(|batch| batch.range.len() / 6)
                .sum::<usize>();
            assert_eq!(faces, usize::from(encrypted), "encrypted={encrypted}");
        }
    }

    // ---- the scoreboard ----------------------------

    /// `ClientEvent::Scoreboard` had **no consumer**: the four packets were decoded, boxed,
    /// pushed onto the event vector and dropped every tick. This drives `Client::react` — the
    /// real dispatch — and then the real sidebar draw.
    #[test]
    fn scoreboard_packets_reach_the_state_and_the_sidebar_is_drawn_from_them() {
        use mc_protocol::play::s2c::{
            DisplayScoreboard, ScoreboardObjective, ScoreboardObjectiveMode, ScoreboardRenderType,
            UpdateScore, UpdateScoreAction,
        };
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.session.as_mut().unwrap().state_mut().local.username = "Dev".to_owned();

        let react = |client: &mut Client, event: crate::sync::ScoreboardEvent| {
            client.react(&ClientEvent::Scoreboard(Box::new(event)));
        };
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Objective(ScoreboardObjective {
                objective_name: "kills".to_owned(),
                mode: ScoreboardObjectiveMode::Create {
                    display_name: "Kills".to_owned(),
                    render_type: ScoreboardRenderType::Integer,
                },
            }),
        );
        for (player, points) in [("Dev", 7), ("bob", 3), ("#hidden", 99)] {
            react(
                &mut client,
                crate::sync::ScoreboardEvent::Score(UpdateScore {
                    player_name: player.to_owned(),
                    objective_name: "kills".to_owned(),
                    action: UpdateScoreAction::Change { value: points },
                }),
            );
        }
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Display(DisplayScoreboard {
                position: 1,
                objective_name: "kills".to_owned(),
            }),
        );

        let board = &client.session.as_ref().unwrap().state().scoreboard;
        assert_eq!(board.score("Dev", "kills"), Some(7));
        assert_eq!(
            board
                .objective_in_display_slot(scoreboard::SLOT_SIDEBAR)
                .map(|o| o.display_name.as_str()),
            Some("Kills")
        );

        let sidebar = client
            .sidebar_snapshot()
            .expect("the sidebar slot is bound");
        assert_eq!(sidebar.title, "Kills");
        assert_eq!(
            sidebar.visible_rows(),
            [("bob".to_owned(), 3), ("Dev".to_owned(), 7)],
            "ascending by points, with the # row filtered out"
        );

        // And it actually draws.
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let mut list = DrawList::new();
        client
            .hud
            .draw_scoreboard(&mut list, &mut client.font, &ctx, &sidebar);
        assert!(
            !list.batches().is_empty(),
            "the sidebar must emit geometry once there is a board"
        );
    }

    /// Later GUI batches cover earlier ones, so isolated sidebar/chat pixel tests cannot catch a
    /// reordered live submission chain. This structural mutant guard pins the four production
    /// calls whose order is the behavior under test.
    #[test]
    fn in_game_overlay_submission_order_matches_vanilla() {
        let source = include_str!("driver.rs");
        let overlay = source
            .split_once("fn draw_ingame_overlay(")
            .expect("shared world-overlay helper")
            .1;
        let overlay = overlay
            .split_once("/// Build this frame's GUI")
            .expect("end of shared world-overlay helper")
            .0;
        let sidebar = overlay.find("if let Some(sidebar)").expect("sidebar draw");
        let chat = overlay.find("self.chat.draw").expect("chat draw");
        let tab = overlay.find("self.draw_tab_list").expect("tab-list draw");
        assert!(sidebar < chat && chat < tab, "sidebar/chat/tab ordering");
        // java: `renderGameOverlay:240-243` draws F3 after the held-item name and before the
        // action bar, the title, the sidebar, chat and the Tab list, which all cover it.
        let below = overlay
            .find("self.hud.draw_layers_below_debug(")
            .expect("lower HUD half");
        let debug = overlay.find("self.debug.draw(").expect("F3 draw");
        let above = overlay
            .find(".draw_layers_above_debug(")
            .expect("upper HUD half");
        assert!(
            below < debug && debug < above && above < sidebar,
            "F3 must sit between the two HUD halves, before the sidebar/chat/tab"
        );
        assert_eq!(
            overlay.matches("self.debug.draw(").count(),
            1,
            "F3 is drawn once"
        );

        let build = source
            .split_once("fn build_ui(&mut self, gpu: &Gpu, partial_ticks: f32)")
            .expect("live UI builder")
            .1;
        let world_call = build
            .find("self.draw_ingame_overlay(")
            .expect("session-backed world overlay call");
        let screens = build
            .find("match &mut self.ui")
            .expect("current GuiScreen draw chain");
        assert!(
            world_call < screens,
            "vanilla submits HUD/sidebar/chat/tab before Minecraft draws the open screen"
        );
        let world_gate = &build[..world_call];
        assert!(world_gate.contains("world_overlay_allowed("));
        for modal in [
            "Ui::Pause(screen)",
            "Ui::Options(screen)",
            "Ui::Stats(screen)",
            "Ui::Achievements(screen)",
            "Ui::EditSign(screen)",
            "Ui::CommandBlock(screen)",
            "Ui::ConfirmOpenLink(screen, _)",
        ] {
            assert!(build.contains(modal), "missing covered modal arm {modal}");
        }
    }

    /// F-P0-network.play.server-15-3: S3B/S3C/S3D's scoreboard state must reach the live
    /// nameplate builder. The two controls are deliberately on opposite sides of the display
    /// packet: an objective/score without slot 2 is silent, and removing the bound objective is
    /// silent again. The source-boundary assertion is the biting control for the old production
    /// `score: None` call: it fails if the live request drops the computed line after this test's
    /// CPU builder check has already proven what `Some("7 Deaths")` draws.
    #[test]
    fn below_name_packets_reach_live_nameplate_and_removed_slot_stops_drawing() {
        use mc_protocol::play::s2c::{
            DisplayScoreboard, ScoreboardObjective, ScoreboardObjectiveMode, ScoreboardRenderType,
            UpdateScore, UpdateScoreAction,
        };

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        let react = |client: &mut Client, event: crate::sync::ScoreboardEvent| {
            client.react(&ClientEvent::Scoreboard(Box::new(event)));
        };

        react(
            &mut client,
            crate::sync::ScoreboardEvent::Objective(ScoreboardObjective {
                objective_name: "deaths".to_owned(),
                mode: ScoreboardObjectiveMode::Create {
                    display_name: "Deaths".to_owned(),
                    render_type: ScoreboardRenderType::Integer,
                },
            }),
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Score(UpdateScore {
                player_name: "bob".to_owned(),
                objective_name: "deaths".to_owned(),
                action: UpdateScoreAction::Change { value: 7 },
            }),
        );

        // The objective and score are live, but no slot-2 display packet has arrived yet.
        assert_eq!(
            client
                .session
                .as_mut()
                .unwrap()
                .state_mut()
                .scoreboard
                .below_name_line("bob"),
            None,
            "a score without SLOT_BELOW_NAME must not become a nameplate line"
        );

        react(
            &mut client,
            crate::sync::ScoreboardEvent::Display(DisplayScoreboard {
                position: scoreboard::SLOT_BELOW_NAME as i8,
                objective_name: "deaths".to_owned(),
            }),
        );
        let score = client
            .session
            .as_mut()
            .unwrap()
            .state_mut()
            .scoreboard
            .below_name_line("bob")
            .expect("SLOT_BELOW_NAME must expose the objective")
            .to_owned();
        assert_eq!(score, "7 Deaths");

        // Build the same request shape upload_entities sends. Two backdrops mean the score line
        // and the name line both reached the renderer; the no-score control has exactly one.
        let plate = mc_render::entity::Nameplate {
            text: "bob".to_owned(),
            rel: Camera::default().relative(DVec3::new(0.0, 0.0, 5.0)),
            height: 1.8,
            child: false,
            sneaking: false,
        };
        let with_score = mc_ui::nameplate::build(
            &mut client.font,
            &mc_ui::nameplate::NameplateRequest {
                plate: &plate,
                view_yaw: 0.0,
                view_pitch: 0.0,
                distance_sq: 25.0,
                score: Some(&score),
            },
        )
        .expect("near standing player is in nameplate range");
        let without_score = mc_ui::nameplate::build(
            &mut client.font,
            &mc_ui::nameplate::NameplateRequest {
                plate: &plate,
                view_yaw: 0.0,
                view_pitch: 0.0,
                distance_sq: 25.0,
                score: None,
            },
        )
        .expect("name remains in range without a score");
        assert_eq!(with_score.solid.len(), 2, "score backdrop + name backdrop");
        assert_eq!(without_score.solid.len(), 1, "name backdrop only");
        assert!(
            with_score.glyph_vertex_count() > without_score.glyph_vertex_count(),
            "the score text must reach the font/nameplate geometry"
        );

        react(
            &mut client,
            crate::sync::ScoreboardEvent::Objective(ScoreboardObjective {
                objective_name: "deaths".to_owned(),
                mode: ScoreboardObjectiveMode::Remove,
            }),
        );
        assert_eq!(
            client
                .session
                .as_mut()
                .unwrap()
                .state_mut()
                .scoreboard
                .below_name_line("bob"),
            None,
            "removing the objective must clear the bound score line"
        );

        // This pins the exact live consumer, not merely the model or the UI helper. Replacing
        // `score.as_deref()` with `None` (the old finding) makes this assertion fail.
        let source = include_str!("driver.rs");
        let (_, below_name) = source
            .split_once("// **ENTITY-2's D1**, the `belowName` line.")
            .expect("live below-name render block remains present");
        let (below_name, _) = below_name
            .split_once("render.nameplates.with(|phase| phase.finish(gpu));")
            .expect("below-name block ends before nameplate phase finish");
        assert!(
            below_name
                .contains("Some(name) if *distance_sq < 100.0 => board.below_name_line(name)"),
            "the live caller must request the Java <100 block score line"
        );
        assert!(
            below_name.contains("score: score.as_deref(),"),
            "the live NameplateRequest must carry the computed below-name score"
        );
    }

    /// F-P1-entity.item-06-7: `RenderItemFrame.renderName` labels only the currently pointed
    /// frame, and only from the displayed stack's custom NBT name. Ordinary item names must not
    /// leak into the nameplate path.
    #[test]
    fn pointed_item_frame_custom_name_is_the_only_stack_label() {
        use mc_nbt::{Nbt, NbtCompound};
        use mc_world::entity::{Metadata, MetadataValue};

        let stack_metadata = |stack| {
            let mut metadata = Metadata::new();
            metadata.set(8, MetadataValue::ItemStack(stack));
            metadata
        };
        let mut display = NbtCompound::new();
        display.insert("Name", Nbt::String("Treasure Map".to_owned()));
        let mut root = NbtCompound::new();
        root.insert("display", Nbt::Compound(display));
        let custom = mc_protocol::ItemStack {
            item_id: 1,
            count: 1,
            damage: 0,
            nbt: Some(root),
        };
        let plain = mc_protocol::ItemStack {
            nbt: None,
            ..custom.clone()
        };

        let mut world = mc_world::World::new();
        let mut tracker = crate::sync::entities::EntityTracker::new();
        for (id, metadata) in [
            (77, stack_metadata(Some(custom.clone()))),
            (78, stack_metadata(Some(plain))),
            (79, stack_metadata(None)),
        ] {
            tracker.spawn(
                &mut world,
                id,
                crate::sync::entities::TrackedKind::Type(mc_data::EntityType::ItemFrame),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                metadata,
            );
        }
        tracker.spawn(
            &mut world,
            80,
            crate::sync::entities::TrackedKind::Type(mc_data::EntityType::Boat),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            stack_metadata(Some(custom)),
        );
        let language = mc_assets::Language::new("xx_TEST");

        assert_eq!(
            pointed_item_frame_label(77, tracker.get(77).unwrap(), &world, Some(77), &language),
            Some("Treasure Map".to_owned())
        );
        assert_eq!(
            pointed_item_frame_label(77, tracker.get(77).unwrap(), &world, Some(78), &language),
            None,
            "a custom frame outside the crosshair is silent"
        );
        assert_eq!(
            pointed_item_frame_label(77, tracker.get(77).unwrap(), &world, None, &language),
            None,
            "losing the target clears the label immediately"
        );
        assert_eq!(
            pointed_item_frame_label(78, tracker.get(78).unwrap(), &world, Some(78), &language),
            None,
            "ordinary localized item names are not frame labels"
        );
        assert_eq!(
            pointed_item_frame_label(79, tracker.get(79).unwrap(), &world, Some(79), &language),
            None,
            "an empty frame has no label"
        );
        assert_eq!(
            pointed_item_frame_label(80, tracker.get(80).unwrap(), &world, Some(80), &language),
            None,
            "the same metadata slot on another entity type is not an item-frame label"
        );
    }

    /// Phase 4b review S4: with no scoreboard traffic the revision never changes, so the
    /// per-username label cache is bounded by size instead.
    #[test]
    fn the_player_label_cache_is_bounded_without_scoreboard_traffic() {
        let inputs = || PlayerLabelInputs {
            has_team: false,
            name_tag_visible: true,
            sees_friendly_invisible: false,
            display: String::new(),
        };
        let mut cache = PlayerLabelCache::default();
        for n in 0..PlayerLabelCache::MAX_PLAYERS * 3 {
            cache.get(0, "Viewer", &format!("Bot{n}"), inputs);
            assert!(cache.players.len() <= PlayerLabelCache::MAX_PLAYERS);
        }
        let mut derived = 0;
        for _ in 0..2 {
            cache.get(0, "Viewer", "Steve", || {
                derived += 1;
                inputs()
            });
        }
        assert_eq!(
            derived, 1,
            "a name is still derived once after a start-over"
        );
    }

    #[test]
    fn pointed_living_custom_name_reaches_the_label_without_forcing_always_visible() {
        use mc_world::entity::{Metadata, MetadataValue};

        let metadata = |flags: i8, always: i8| {
            let mut metadata = Metadata::new();
            metadata.set(0, MetadataValue::Byte(flags));
            metadata.set(2, MetadataValue::Str("Dinnerbone".to_owned()));
            metadata.set(3, MetadataValue::Byte(always));
            metadata
        };
        let mut world = mc_world::World::new();
        let mut tracker = crate::sync::entities::EntityTracker::new();
        // 96: a zombie with an empty name (`hasCustomName` is `length() >
        // 0`); 97: a named, invisible armor stand without index 3.
        let mut nameless = metadata(0, 1);
        nameless.set(2, MetadataValue::Str(String::new()));
        for (id, kind, metadata) in [
            (91, mc_data::EntityType::Zombie, metadata(0, 0)),
            (92, mc_data::EntityType::Zombie, metadata(0, 1)),
            (93, mc_data::EntityType::Zombie, metadata(0x20, 1)),
            (94, mc_data::EntityType::ArmorStand, metadata(0x20, 1)),
            (96, mc_data::EntityType::Zombie, nameless),
            (97, mc_data::EntityType::ArmorStand, metadata(0x20, 0)),
        ] {
            tracker.spawn(
                &mut world,
                id,
                crate::sync::entities::TrackedKind::Type(kind),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                metadata,
            );
        }

        // An unnamed armour stand with index 3 set: `getName()` falls back to the translation.
        let mut unnamed = Metadata::new();
        unnamed.set(0, MetadataValue::Byte(0x20));
        unnamed.set(3, MetadataValue::Byte(1));
        tracker.spawn(
            &mut world,
            95,
            crate::sync::entities::TrackedKind::Type(mc_data::EntityType::ArmorStand),
            None,
            [0, 0, 0],
            0.0,
            0.0,
            DVec3::ZERO,
            unnamed,
        );
        let mut language = mc_assets::Language::new("en_US");
        language.insert("entity.ArmorStand.name", "Armor Stand");
        let label_with =
            |id: i32, pointed: Option<i32>, gui: bool, spectator: bool, ridden: bool, always| {
                living_nameplate_label(
                    id,
                    tracker.get(id).unwrap(),
                    &world,
                    pointed,
                    gui,
                    spectator,
                    ridden,
                    &language,
                    always,
                )
            };
        let label = |id: i32, pointed: Option<i32>, gui: bool, spectator: bool, ridden: bool| {
            label_with(id, pointed, gui, spectator, ridden, false)
        };
        // java: the text is `getDisplayName().getFormattedText()`, which ends in `§r`.
        let dinnerbone = Some("Dinnerbone\u{a7}r".to_owned());

        // "Always show mob names" drops only the crosshair test: named
        // mobs are labelled unpointed, index 3 or not; the rest of the gate and the armor-stand
        // rule are vanilla's.
        let always = |id: i32, gui: bool, spectator: bool, ridden: bool| {
            label_with(id, None, gui, spectator, ridden, true)
        };
        assert_eq!(
            always(91, true, false, false),
            dinnerbone,
            "named, unpointed"
        );
        assert_eq!(
            always(92, true, false, false),
            dinnerbone,
            "index 3 set too"
        );
        assert_eq!(
            always(93, true, false, false),
            None,
            "an invisible mob stays hidden"
        );
        assert_eq!(
            always(93, true, true, false),
            dinnerbone,
            "but not from a spectator"
        );
        assert_eq!(always(91, false, false, false), None, "F1 still hides it");
        assert_eq!(
            always(91, true, false, true),
            None,
            "a ridden mob still has none"
        );
        assert_eq!(
            always(95, true, false, false),
            Some("Armor Stand\u{a7}r".to_owned()),
            "an armor stand keeps its own index-3 rule"
        );
        assert_eq!(
            always(96, true, false, false),
            None,
            "no custom name, no label"
        );
        assert_eq!(
            always(97, true, false, false),
            None,
            "a named stand without index 3 stays hidden, as in vanilla"
        );
        assert_eq!(
            label(96, Some(96), true, false, false),
            None,
            "an unnamed mob has no label even pointed"
        );

        assert_eq!(
            label(91, Some(91), true, false, false),
            dinnerbone,
            "the pointed fallback does not require watched index 3"
        );
        assert_eq!(
            label(91, None, true, false, false),
            None,
            "an unpointed ordinary custom name remains hidden"
        );
        // java: `EntityLivingBase.getAlwaysRenderNameTagForRender` returns `false` and
        // `EntityLiving` does not override it, so `RenderLiving.canRenderName` ignores index 3.
        assert_eq!(
            label(92, None, true, false, false),
            None,
            "index 3 does not show an unpointed mob's name in 1.8.9"
        );
        assert_eq!(
            label(92, Some(92), true, false, false),
            dinnerbone,
            "the same mob still shows its name under the crosshair"
        );
        assert_eq!(
            label(93, Some(93), true, false, false),
            None,
            "pointing does not reveal an invisible ordinary mob"
        );
        assert_eq!(
            label(93, Some(93), true, true, false),
            dinnerbone,
            "a spectator can see the invisible entity and its pointed name"
        );
        assert_eq!(
            label(91, Some(91), false, false, false),
            None,
            "F1's GUI gate suppresses the generic living label"
        );
        assert_eq!(
            label(91, Some(91), true, false, true),
            None,
            "a ridden entity cannot submit the generic label"
        );
        assert_eq!(
            label(94, None, false, false, true),
            dinnerbone,
            "the armor-stand always-visible override remains intact"
        );
        assert_eq!(
            label(95, None, true, false, false),
            Some("Armor Stand\u{a7}r".to_owned()),
            "ArmorStandRenderer needs only index 3; an unnamed stand shows its entity name"
        );
        assert_eq!(display_name_label("deadmau5"), "deadmau5\u{a7}r");
        let plate = |text: &str| mc_render::entity::Nameplate {
            text: text.to_owned(),
            rel: Vec3::ZERO,
            height: 1.8,
            child: false,
            sneaking: false,
        };
        assert_eq!(
            plate(&display_name_label("deadmau5")).layout(40).text_y,
            0.0,
            "java: \"deadmau5§r\".equals(\"deadmau5\") is false, so a name label never lifts"
        );
    }

    /// java: every non-living renderer but the lightning bolt reaches `Render.renderName` through
    /// `super.doRender`, whose `canRenderName` is index 3 plus `hasCustomName()`. Minecarts
    /// override `hasCustomName` with an NBT-only field, and item frames override `renderName`.
    #[test]
    fn non_living_entities_take_render_can_render_name_and_item_frames_offset_their_label() {
        use mc_world::entity::{Metadata, MetadataValue};

        let named = |always: i8| {
            let mut metadata = Metadata::new();
            metadata.set(0, MetadataValue::Byte(0x20));
            metadata.set(2, MetadataValue::Str("Loot".to_owned()));
            metadata.set(3, MetadataValue::Byte(always));
            metadata
        };
        let mut world = mc_world::World::new();
        let mut tracker = crate::sync::entities::EntityTracker::new();
        for (id, kind, metadata) in [
            (101, mc_data::EntityType::Item, named(1)),
            (102, mc_data::EntityType::Item, named(0)),
            (103, mc_data::EntityType::MinecartRideable, named(1)),
            (104, mc_data::EntityType::Boat, named(1)),
            (105, mc_data::EntityType::Zombie, named(1)),
        ] {
            tracker.spawn(
                &mut world,
                id,
                crate::sync::entities::TrackedKind::Type(kind),
                None,
                [0, 0, 0],
                0.0,
                0.0,
                DVec3::ZERO,
                metadata,
            );
        }
        let label = |id: i32| non_living_nameplate_label(tracker.get(id).unwrap(), &world);
        assert_eq!(
            label(101),
            Some("Loot\u{a7}r".to_owned()),
            "an invisible-flagged named item with index 3 is labelled; no GUI/invisible gate"
        );
        assert_eq!(label(102), None, "index 3 is required");
        assert_eq!(
            label(103),
            None,
            "EntityMinecart.hasCustomName never sees index 2"
        );
        assert_eq!(label(104), Some("Loot\u{a7}r".to_owned()));
        assert_eq!(
            label(105),
            None,
            "living entities use their renderer's own rule"
        );

        // RenderItemFrame.doRender: `x + facing.x * 0.3F, y - 0.25D, z + facing.z * 0.3F`.
        let centre = DVec3::new(4.5, 70.5, -2.03125);
        let feet = item_frame_label_feet(centre, mc_math::Facing::South);
        assert_eq!(feet.x, 4.5);
        assert_eq!(feet.y, 70.25);
        assert_eq!(feet.z, -2.03125 + f64::from(0.3_f32));
        let west = item_frame_label_feet(centre, mc_math::Facing::West);
        assert_eq!(west.x, 4.5 - f64::from(0.3_f32));
        assert_eq!(west.z, -2.03125);

        assert!(generic_nameplate_eligible(true, false, false, false));
        assert!(!generic_nameplate_eligible(false, false, false, false));
        assert!(!generic_nameplate_eligible(true, true, false, false));
        assert!(generic_nameplate_eligible(true, true, true, false));
        assert!(!generic_nameplate_eligible(true, false, false, true));
        assert!(
            player_nameplate_eligible(true, true, false, true, false, true),
            "a represented team returns before the generic gates"
        );
        assert!(!player_nameplate_eligible(
            true, false, true, false, false, false
        ));
        assert!(!player_nameplate_eligible(
            false, true, false, false, false, false
        ));
        assert!(player_nameplate_eligible(
            false, true, true, true, true, false
        ));
    }

    /// java: `GuiIngame.renderGameOverlay:318` — the **local player's team colour** picks
    /// display slot `3 + colorIndex` in preference to the plain `sidebar` slot. This is how a
    /// server shows each team a different board off one packet stream, and it is unreachable
    /// without team memberships.
    /// F-P1-scoreboard-02-1 / F-P1-scoreboard-03-3: Teams packets must format the remote
    /// player's actual nameplate text before the CPU geometry builder sees it. The suffix makes
    /// the glyph-count oracle independent of the colour-code parser; the source assertion pins
    /// the production caller so a raw-`info.username` mutant cannot pass via this local fixture.
    #[test]
    fn team_packets_format_remote_nameplate_text_before_geometry_submission() {
        use mc_protocol::play::s2c::{TeamInfo, Teams, TeamsAction};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.react(&ClientEvent::Scoreboard(Box::new(
            crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "blue".to_owned(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "Blue".to_owned(),
                        prefix: "\u{a7}9<B> ".to_owned(),
                        suffix: " </B>".to_owned(),
                        friendly_flags: 0,
                        name_tag_visibility: "always".to_owned(),
                        color: 9,
                    },
                    players: vec!["bob".to_owned()],
                },
            })),
        )));

        let board = &client.session.as_ref().expect("session").state().scoreboard;
        let formatted = board.format_player_name("bob");
        assert_eq!(formatted, "\u{a7}9<B> bob </B>");
        assert_eq!(
            board.format_player_name("alice"),
            "alice",
            "teamless control"
        );

        let build = |font: &mut _, text: String| {
            let plate = mc_render::entity::Nameplate {
                text,
                rel: Camera::default().relative(DVec3::new(0.0, 0.0, 5.0)),
                height: 1.8,
                child: false,
                sneaking: false,
            };
            mc_ui::nameplate::build(
                font,
                &mc_ui::nameplate::NameplateRequest {
                    plate: &plate,
                    view_yaw: 0.0,
                    view_pitch: 0.0,
                    distance_sq: 25.0,
                    score: None,
                },
            )
            .expect("near standing player is in nameplate range")
        };
        let raw = build(&mut client.font, "bob".to_owned());
        let styled = build(&mut client.font, formatted);
        assert!(
            styled.glyph_vertex_count() > raw.glyph_vertex_count(),
            "prefix/suffix glyphs must reach final nameplate geometry"
        );
        let raw_color = raw.glyphs[1].verts[0].color;
        let styled_color = styled.glyphs[1].verts[0].color;
        assert_ne!(
            styled_color, raw_color,
            "the live team formatting code must recolour final nameplate vertices"
        );
        assert!(
            styled_color[2] > styled_color[0] && styled_color[2] > styled_color[1],
            "section-9 must select blue glyphs, got {styled_color:?}"
        );

        let source = include_str!("driver.rs");
        let (_, nameplates) = source
            .split_once("// Nameplates: S12 deliberately left")
            .expect("live nameplate collection remains present");
        let (nameplates, _) = nameplates
            .split_once("// **ENTITY-2's D1**, the `belowName` line.")
            .expect("remote-name collection ends before below-name submission");
        assert!(
            nameplates.contains("board.format_player_name(username)"),
            "the production plate text must not regress to the raw account name"
        );
    }

    #[test]
    fn the_local_players_team_colour_picks_its_own_sidebar_slot() {
        use mc_protocol::play::s2c::{
            DisplayScoreboard, ScoreboardObjective, ScoreboardObjectiveMode, ScoreboardRenderType,
            TeamInfo, Teams, TeamsAction, UpdateScore, UpdateScoreAction,
        };
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.session.as_mut().unwrap().state_mut().local.username = "Dev".to_owned();
        let react = |client: &mut Client, event: crate::sync::ScoreboardEvent| {
            client.react(&ClientEvent::Scoreboard(Box::new(event)));
        };
        let objective = |name: &str, display: &str| {
            crate::sync::ScoreboardEvent::Objective(ScoreboardObjective {
                objective_name: name.to_owned(),
                mode: ScoreboardObjectiveMode::Create {
                    display_name: display.to_owned(),
                    render_type: ScoreboardRenderType::Integer,
                },
            })
        };

        react(&mut client, objective("common", "Everyone"));
        react(&mut client, objective("redboard", "Red Team"));
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Score(UpdateScore {
                player_name: "Dev".to_owned(),
                objective_name: "redboard".to_owned(),
                action: UpdateScoreAction::Change { value: 1 },
            }),
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Display(DisplayScoreboard {
                position: 1,
                objective_name: "common".to_owned(),
            }),
        );
        // Colour index 12 is `red`, so the slot is 3 + 12 = 15.
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Display(DisplayScoreboard {
                position: 15,
                objective_name: "redboard".to_owned(),
            }),
        );

        // With no team, the plain sidebar slot wins.
        assert_eq!(client.sidebar_snapshot().unwrap().title, "Everyone");

        react(
            &mut client,
            crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "red".to_owned(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "Red".to_owned(),
                        prefix: "\u{a7}c[R] ".to_owned(),
                        suffix: String::new(),
                        friendly_flags: 0,
                        name_tag_visibility: "always".to_owned(),
                        color: 12,
                    },
                    players: vec!["Dev".to_owned()],
                },
            })),
        );
        let sidebar = client.sidebar_snapshot().expect("a board is bound");
        assert_eq!(
            sidebar.title, "Red Team",
            "joining the red team must switch the board to slot 3 + 12"
        );
        assert_eq!(
            sidebar.visible_rows(),
            [("\u{a7}c[R] Dev".to_owned(), 1)],
            "java: the row names go through ScorePlayerTeam.formatPlayerName"
        );

        // #8 / C2-1: the per-frame sidebar cache equals a fresh snapshot, survives frames with
        // no scoreboard change, and follows the very next packet.
        client.refresh_sidebar_cache();
        let cached = |client: &Client| {
            client
                .sidebar_cache
                .as_ref()
                .and_then(|cache| cache.sidebar.clone())
        };
        assert_eq!(cached(&client), Some(sidebar.clone()));
        let revision = client.sidebar_cache.as_ref().expect("cache").revision;
        client.refresh_sidebar_cache();
        assert_eq!(
            client.sidebar_cache.as_ref().expect("cache").revision,
            revision
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Score(UpdateScore {
                player_name: "Dev".to_owned(),
                objective_name: "redboard".to_owned(),
                action: UpdateScoreAction::Change { value: 5 },
            }),
        );
        client.refresh_sidebar_cache();
        assert_ne!(
            client.sidebar_cache.as_ref().expect("cache").revision,
            revision
        );
        assert_eq!(cached(&client), client.sidebar_snapshot());
        assert_eq!(
            cached(&client).expect("a board is bound").visible_rows(),
            [("\u{a7}c[R] Dev".to_owned(), 5)]
        );
    }

    /// The tab list's other half of the same state: display slot 0 puts a score column beside
    /// every name, and team prefixes reach the rows.
    #[test]
    fn the_tab_list_picks_up_the_display_slot_zero_objective_and_team_prefixes() {
        use mc_protocol::play::s2c::{
            AddPlayerEntry, DisplayScoreboard, GameMode, PlayerListItem, ScoreboardObjective,
            ScoreboardObjectiveMode, ScoreboardRenderType, TeamInfo, Teams, TeamsAction,
            UpdateScore, UpdateScoreAction,
        };
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, _to_game, _to_net) = offline_session(mc_world::World::new());
        session
            .state_mut()
            .players
            .apply(&PlayerListItem::AddPlayer(vec![
                AddPlayerEntry {
                    uuid: uuid::Uuid::from_u128(1),
                    username: "bob".to_owned(),
                    properties: Vec::new(),
                    game_mode: GameMode::Survival,
                    ping: 40,
                    display_name: None,
                },
                AddPlayerEntry {
                    uuid: uuid::Uuid::from_u128(2),
                    username: "alice".to_owned(),
                    properties: Vec::new(),
                    game_mode: GameMode::Survival,
                    ping: 50,
                    display_name: None,
                },
            ]))
            .expect("the row must decode");
        client.session = Some(session);
        let react = |client: &mut Client, event: crate::sync::ScoreboardEvent| {
            client.react(&ClientEvent::Scoreboard(Box::new(event)));
        };
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Objective(ScoreboardObjective {
                objective_name: "hp".to_owned(),
                mode: ScoreboardObjectiveMode::Create {
                    display_name: "Health".to_owned(),
                    render_type: ScoreboardRenderType::Integer,
                },
            }),
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Display(DisplayScoreboard {
                position: 0,
                objective_name: "hp".to_owned(),
            }),
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Score(UpdateScore {
                player_name: "bob".to_owned(),
                objective_name: "hp".to_owned(),
                action: UpdateScoreAction::Change { value: 17 },
            }),
        );
        react(
            &mut client,
            crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "blue".to_owned(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "Blue".to_owned(),
                        prefix: "\u{a7}9<B> ".to_owned(),
                        suffix: String::new(),
                        friendly_flags: 0,
                        name_tag_visibility: "always".to_owned(),
                        color: 9,
                    },
                    players: vec!["bob".to_owned()],
                },
            })),
        );

        let board = &client.session.as_ref().unwrap().state().scoreboard;
        assert_eq!(board.format_player_name("bob"), "\u{a7}9<B> bob");
        assert_eq!(board.score("bob", "hp"), Some(17));
        assert!(board
            .objective_in_display_slot(scoreboard::SLOT_LIST)
            .is_some());

        // The overlay draws more glyphs with the objective bound than without, because the score
        // column and the prefix are both text.
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        client.tab_list_held = true;
        let mut with_board = DrawList::new();
        client.draw_tab_list(&mut with_board, &ctx, 1);
        assert_eq!(
            client
                .session
                .as_ref()
                .unwrap()
                .state()
                .scoreboard
                .score("alice", "hp"),
            Some(0),
            "the live tab snapshot must preserve getValueFromObjective's row-creating side effect"
        );
        let glyphs = |d: &DrawList| -> usize {
            d.batches()
                .iter()
                .filter(|b| matches!(b.texture, UiTexture::Font(_)))
                .map(|b| b.range.len())
                .sum()
        };
        let before = glyphs(&with_board);
        client
            .session
            .as_mut()
            .unwrap()
            .state_mut()
            .scoreboard
            .clear();
        let mut without = DrawList::new();
        client.draw_tab_list(&mut without, &ctx, 2);
        assert!(
            before > glyphs(&without),
            "the score column and the team prefix must both reach the overlay"
        );
    }

    // ---------------------------------------------------------------------------------------
    // W-RCLICK / W-SWING — `rightClickMouse`'s `flag`, the placement gate, and the arm swing.
    // ---------------------------------------------------------------------------------------

    /// Everything the client actually put on the wire, in order.
    fn drained(
        to_net: &mut tokio::sync::mpsc::UnboundedReceiver<crate::net::ToNet>,
    ) -> Vec<mc_protocol::play::C2SPlay> {
        let mut out = Vec::new();
        while let Ok(msg) = to_net.try_recv() {
            if let crate::net::ToNet::Send(packet) = msg {
                out.push(packet);
            }
        }
        out
    }

    /// F-P2-client.gui-03-1 / F-P1-entity-07-3: a creative command-block activation must reach
    /// the flat UI, preserve typed text across a redraw, and drain Done into one live
    /// `MC|AdvCdm` packet before returning to the HUD.  The initial C09/C08 pair is retained as a
    /// control: opening the GUI does not suppress `PlayerControllerMP.onPlayerRightClick`'s
    /// placement packet.
    #[test]
    fn creative_command_block_activation_reaches_ui_and_drains_live_payload() {
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let position = BlockPos::new(3, 65, 4);
        {
            let session = client.session.as_mut().expect("live test session");
            session.state_mut().local.game_mode = mc_protocol::play::s2c::GameMode::Creative;
            session
                .state_mut()
                .world
                .set_block(position, mc_data::BlockState::new(mc_data::BlockId(137), 0));
        }
        assert!(client.on_player_right_click(
            interact::BlockHit {
                pos: position,
                face: mc_math::Facing::Up,
                hit_vec: DVec3::new(3.5, 66.0, 4.5),
            },
            None,
        ));
        assert!(matches!(client.ui, Ui::CommandBlock(_)));

        // Layout once as the frame renderer would, then type across a frame boundary.  A second
        // init at the same resolution must retain the command instead of restoring the spawn
        // snapshot from `initial_command`.
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let font = &client.font;
        let lang = &client.assets.language;
        let clipboard = &mut client.clipboard;
        if let Ui::CommandBlock(screen) = &mut client.ui {
            screen.init(&ctx, lang, font);
            screen.key_typed(
                Some('s'),
                0,
                mc_ui::widget::keys::Modifiers::NONE,
                clipboard,
                font,
            );
            screen.key_typed(
                Some('a'),
                0,
                mc_ui::widget::keys::Modifiers::NONE,
                clipboard,
                font,
            );
            screen.init(&ctx, lang, font);
            assert_eq!(screen.command(), "sa");
            screen.key_typed(
                None,
                mc_ui::widget::keys::ENTER,
                mc_ui::widget::keys::Modifiers::NONE,
                clipboard,
                font,
            );
        } else {
            panic!("creative command block must open Ui::CommandBlock");
        }
        client.drain_command_block_actions();
        assert!(matches!(client.ui, Ui::InGame));

        let packets = drained(&mut to_net);
        assert!(packets
            .iter()
            .any(|packet| matches!(packet, mc_protocol::play::C2SPlay::PlayerBlockPlacement(_))));
        let payload = packets
            .iter()
            .find_map(|packet| match packet {
                mc_protocol::play::C2SPlay::PluginMessage(payload)
                    if payload.channel == "MC|AdvCdm" =>
                {
                    Some(payload)
                }
                _ => None,
            })
            .expect("Done must drain MC|AdvCdm");
        let mut bytes = mc_protocol::PacketBuffer::from_slice(&payload.data);
        assert_eq!(bytes.read_u8().unwrap(), 0);
        assert_eq!(bytes.read_i32().unwrap(), position.x);
        assert_eq!(bytes.read_i32().unwrap(), position.y);
        assert_eq!(bytes.read_i32().unwrap(), position.z);
        assert_eq!(bytes.read_string(32767).unwrap(), "sa");
        assert!(bytes.read_bool().unwrap());
        assert!(bytes.as_slice().is_empty());
        let state = client
            .session()
            .expect("session")
            .state()
            .world
            .tile_entity(position)
            .and_then(mc_world::TileEntity::command_block)
            .expect("local command-block state");
        // Java does not mutate `commandStored` on the client when Done sends C17; the server's
        // next S35 action-2 is the authoritative command update.
        assert!(state.command.is_empty());
        assert!(state.track_output);
    }

    /// F-P1-entity-07-3: `EntityMinecartCommandBlock.interactFirst` opens the same editor only
    /// in creative mode.  Its Java return value is still false, so the two C02 packets remain on
    /// the wire and no held-item C08 is invented when the player has an empty hand.
    #[test]
    fn creative_command_minecart_right_click_opens_editor_without_item_fallback() {
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let entity_id = 44;
        {
            let session = client.session.as_mut().expect("live test session");
            session.state_mut().local.game_mode = mc_protocol::play::s2c::GameMode::Creative;
            session.state_mut().local.abilities.creative_mode = true;
            crate::sync::apply(
                session.state_mut(),
                mc_protocol::play::S2CPlay::SpawnObject(mc_protocol::play::s2c::SpawnObject {
                    entity_id,
                    object_type: 10,
                    x: 16,
                    y: 2064,
                    z: 64,
                    pitch: mc_protocol::Angle(0),
                    yaw: mc_protocol::Angle(0),
                    data: 6,
                    velocity: None,
                }),
                &mut Vec::new(),
            )
            .expect("spawn command minecart");
            crate::sync::apply(
                session.state_mut(),
                mc_protocol::play::S2CPlay::EntityMetadata(
                    mc_protocol::play::s2c::EntityMetadata {
                        entity_id,
                        metadata: vec![
                            mc_protocol::MetadataEntry {
                                index: 23,
                                value: mc_protocol::MetadataValue::String("say cart".to_owned()),
                            },
                            mc_protocol::MetadataEntry {
                                index: 24,
                                value: mc_protocol::MetadataValue::String(
                                    r#"{"text":"ran"}"#.to_owned(),
                                ),
                            },
                        ],
                    },
                ),
                &mut Vec::new(),
            )
            .expect("command minecart metadata");
        }
        client.hit = HitResult::Entity(interact::EntityHit {
            network_id: entity_id,
            hit_vec: DVec3::new(0.5, 65.0, 2.0),
        });
        let _ = drained(&mut to_net);
        client.right_click_mouse();

        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let font = &client.font;
        let lang = &client.assets.language;
        if let Ui::CommandBlock(screen) = &mut client.ui {
            screen.init(&ctx, lang, font);
            assert_eq!(screen.target(), CommandBlockTarget::Minecart { entity_id });
            assert_eq!(screen.command(), "say cart");
            assert_eq!(screen.previous_output_text_field().text(), "ran");
        } else {
            panic!("creative command minecart must open Ui::CommandBlock");
        }

        let sent = drained(&mut to_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, mc_protocol::play::C2SPlay::UseEntity(_)))
                .count(),
            2,
            "Java sends INTERACT_AT then INTERACT before interactFirst opens GUI: {sent:?}"
        );
        assert!(
            placements(&sent).is_empty(),
            "empty-hand command-minecart interaction must not produce fallback C08: {sent:?}"
        );
    }

    /// FW2-FURNACE-MINECART-PREDICTION: the live targeted path queues both C02 packets before
    /// applying the local coal mutation, decrements survival inventory once, derives pushX/Z from
    /// the click-edge positions, and lets the next client tick own the watcher/fuel transition.
    /// A server watcher correction remains visible until that tick, while an id-reused generation
    /// starts with fresh private state instead of inheriting fuel from the old cart.
    #[test]
    fn live_furnace_minecart_prediction_preserves_c02_order_and_correction_gates() {
        let Some((mut client, _dir, mut to_net)) =
            client_aimed_at_stone(Some(stack_named("coal", 2)))
        else {
            return;
        };
        let entity_id = 44;
        spawn_pick_target(
            &mut client,
            entity_id,
            mc_data::EntityType::MinecartFurnace,
            [16, 2064, 64],
            mc_world::Metadata::default(),
        );
        let (generation, cart_position, player_position) = {
            let session = client.session.as_ref().expect("live test session");
            let tracked = session
                .state()
                .entities
                .get(entity_id)
                .expect("furnace cart generation");
            let position = session
                .state()
                .world
                .ecs
                .get::<&mc_world::entity::Position>(tracked.entity)
                .expect("furnace cart position")
                .0;
            (
                tracked.entity,
                position,
                session.predictor().expect("local predictor").state.pos,
            )
        };
        client.hit = HitResult::Entity(interact::EntityHit {
            network_id: entity_id,
            hit_vec: DVec3::new(0.5, 65.0, 2.0),
        });
        let _ = drained(&mut to_net);
        client.right_click_mouse();

        let sent = drained(&mut to_net);
        let use_entity_count = sent
            .iter()
            .filter(|packet| matches!(packet, mc_protocol::play::C2SPlay::UseEntity(_)))
            .count();
        assert_eq!(
            use_entity_count, 2,
            "furnace interactFirst keeps INTERACT_AT then INTERACT on the wire: {sent:?}"
        );
        assert!(
            placements(&sent).is_empty(),
            "a consumed furnace target must not reach fallback C08: {sent:?}"
        );
        let held = client
            .held_item()
            .expect("the survival coal stack remains after one fuel click");
        assert_eq!(held.count, 1);
        let shadow = client
            .furnace_minecart_predictions
            .get(&entity_id)
            .copied()
            .expect("targeted click installs the furnace private shadow");
        assert_eq!(shadow.generation, generation);
        assert_eq!(shadow.fuel, 3600);
        assert_eq!(
            (shadow.push_x, shadow.push_z),
            (
                cart_position.x - player_position.x,
                cart_position.z - player_position.z
            )
        );

        // A server metadata correction is authoritative at the packet boundary.  The Java
        // client reasserts its private-fuel watcher only when its next local onUpdate runs.
        {
            let session = client.session.as_mut().expect("live test session");
            let state = session.state_mut();
            assert!(state.entities.apply_metadata(
                &mut state.world,
                entity_id,
                &vec![mc_protocol::MetadataEntry {
                    index: 16,
                    value: mc_protocol::MetadataValue::Byte(0),
                }],
            ));
            let metadata = session
                .state()
                .world
                .ecs
                .get::<&mc_world::Metadata>(generation)
                .expect("server watcher correction");
            assert_eq!(metadata.get(16), Some(&mc_world::MetadataValue::Byte(0)));
        }

        let seed = (0_i64..10_000)
            .find(|seed| {
                let mut random = mc_math::JavaRandom::new(*seed);
                random.next_i32_bound(4) == 0
            })
            .expect("a bounded JavaRandom seed must hit the smoke branch");
        client
            .session
            .as_mut()
            .expect("live test session")
            .state_mut()
            .entities
            .particle_random_mut(entity_id)
            .expect("furnace Entity.rand")
            .set_seed(seed);
        client.tick(&MoveInput::default());
        let shadow = client
            .furnace_minecart_predictions
            .get(&entity_id)
            .copied()
            .expect("furnace shadow survives one client tick");
        assert_eq!(shadow.fuel, 3599);
        assert_eq!(
            (shadow.push_x, shadow.push_z),
            (
                cart_position.x - player_position.x,
                cart_position.z - player_position.z
            )
        );
        {
            let metadata = client
                .session
                .as_ref()
                .expect("live test session")
                .state()
                .world
                .ecs
                .get::<&mc_world::Metadata>(generation)
                .expect("furnace watcher");
            assert_eq!(metadata.get(16), Some(&mc_world::MetadataValue::Byte(1)));
        }

        // Replace the network id with a new ECS generation.  The next client furnace tick drops
        // the old private fields before it mirrors the new cart's unpowered watcher.
        {
            let session = client.session.as_mut().expect("live test session");
            let state = session.state_mut();
            assert!(state.entities.despawn(&mut state.world, entity_id));
            state.entities.spawn(
                &mut state.world,
                entity_id,
                crate::sync::entities::TrackedKind::Type(mc_data::EntityType::MinecartFurnace),
                None,
                [16, 2064, 64],
                0.0,
                0.0,
                DVec3::ZERO,
                mc_world::Metadata::default(),
            );
        }
        client.tick_furnace_minecarts();
        let replacement = client
            .furnace_minecart_predictions
            .get(&entity_id)
            .copied()
            .expect("replacement furnace gets a fresh shadow");
        assert_ne!(replacement.generation, generation);
        assert_eq!(replacement.fuel, 0);
        assert_eq!((replacement.push_x, replacement.push_z), (0.0, 0.0));
    }

    /// FW2-SHEEP-DYE-DRIVER-APPLICATION: the reachable ItemDye path queues both targeted C02
    /// packets before applying the exact sheep-generation watcher mutation, consumes one survival
    /// dye only for a real recolour, and rejects both same-generation watcher corrections and
    /// network-id replacement callbacks without touching the replacement or inventory.
    #[test]
    fn live_sheep_dye_prediction_preserves_c02_order_and_generation_reconciliation() {
        let Some((mut client, _dir, mut to_net)) =
            client_aimed_at_stone(Some(stack_named_with_damage("dye", 2, 0)))
        else {
            return;
        };
        let entity_id = 44;
        let mut white = mc_world::Metadata::new();
        white.set(16, mc_world::MetadataValue::Byte(0));
        spawn_pick_target(
            &mut client,
            entity_id,
            mc_data::EntityType::Sheep,
            [16, 2064, 64],
            white,
        );
        let old_generation = client
            .session
            .as_ref()
            .expect("live session")
            .state()
            .entities
            .get(entity_id)
            .expect("sheep generation")
            .entity;
        client.hit = HitResult::Entity(interact::EntityHit {
            network_id: entity_id,
            hit_vec: DVec3::new(0.5, 65.0, 2.0),
        });

        let _ = drained(&mut to_net);
        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let order: Vec<&str> = sent
            .iter()
            .filter_map(|packet| match packet {
                mc_protocol::play::C2SPlay::UseEntity(use_entity) => {
                    Some(match use_entity.action {
                        mc_protocol::play::c2s::UseEntityAction::InteractAt { .. } => "interact_at",
                        mc_protocol::play::c2s::UseEntityAction::Interact => "interact",
                        mc_protocol::play::c2s::UseEntityAction::Attack => "attack",
                    })
                }
                mc_protocol::play::C2SPlay::PlayerBlockPlacement(placement)
                    if placement.position == BlockPos::new(-1, -1, -1) =>
                {
                    Some("sentinel")
                }
                _ => None,
            })
            .collect();
        assert_eq!(
            order,
            vec!["interact_at", "interact"],
            "ItemDye keeps the targeted C02 pair and suppresses fallback C08: {sent:?}"
        );
        assert_eq!(
            client.held_item().map(|stack| stack.count),
            Some(1),
            "one survival dye is consumed by a real recolour"
        );
        {
            let session = client.session.as_ref().expect("live session");
            let state = session.state();
            assert_eq!(
                state
                    .entities
                    .get(entity_id)
                    .expect("sheep")
                    .with_watched(&state.world, |watched| {
                        watched.fleece_colour().map(|colour| colour.metadata())
                    }),
                Some(Some(15)),
                "the local EntitySheep watcher becomes black"
            );
        }

        // A server update after classification is authoritative.  Feed the old click back into
        // the application seam to model a delayed callback; its expected white nibble no longer
        // matches the corrected red watcher, so neither side of the prediction is replayed.
        {
            let session = client.session.as_mut().expect("live session");
            let state = session.state_mut();
            assert!(state.entities.apply_metadata(
                &mut state.world,
                entity_id,
                &vec![mc_protocol::MetadataEntry {
                    index: 16,
                    value: mc_protocol::MetadataValue::Byte(14),
                }],
            ));
        }
        client.apply_entity_local_prediction(
            entity_id,
            old_generation,
            0,
            interact::EntityLocalInteraction::SheepDye {
                prediction: interact::SheepDyeInteraction {
                    consumed: true,
                    new_fleece_metadata: 15,
                    recolor: true,
                    decrement_stack: true,
                },
                expected_fleece_metadata: 0,
            },
            None,
        );
        assert_eq!(
            client.held_item().map(|stack| stack.count),
            Some(1),
            "a corrected same-generation sheep does not consume a stale dye"
        );
        {
            let session = client.session.as_ref().expect("live session");
            let state = session.state();
            assert_eq!(
                state
                    .entities
                    .get(entity_id)
                    .expect("corrected sheep")
                    .with_watched(&state.world, |watched| {
                        watched.fleece_colour().map(|colour| colour.metadata())
                    }),
                Some(Some(14)),
                "the server correction remains visible"
            );
        }

        // The id-reuse boundary is independent of the same-generation correction gate: the old
        // ECS handle cannot recolour a fresh white sheep under the same numeric id.
        despawn_pick_target(&mut client, entity_id);
        let mut replacement_white = mc_world::Metadata::new();
        replacement_white.set(16, mc_world::MetadataValue::Byte(0));
        spawn_pick_target(
            &mut client,
            entity_id,
            mc_data::EntityType::Sheep,
            [16, 2064, 64],
            replacement_white,
        );
        client.apply_entity_local_prediction(
            entity_id,
            old_generation,
            0,
            interact::EntityLocalInteraction::SheepDye {
                prediction: interact::SheepDyeInteraction {
                    consumed: true,
                    new_fleece_metadata: 15,
                    recolor: true,
                    decrement_stack: true,
                },
                expected_fleece_metadata: 0,
            },
            None,
        );
        let session = client.session.as_ref().expect("live session");
        let state = session.state();
        assert_eq!(
            state
                .entities
                .get(entity_id)
                .expect("replacement sheep")
                .with_watched(&state.world, |watched| {
                    watched.fleece_colour().map(|colour| colour.metadata())
                }),
            Some(Some(0)),
            "the replacement remains its authoritative white"
        );
        assert_eq!(
            client.held_item().map(|stack| stack.count),
            Some(1),
            "id reuse does not consume inventory for the stale generation"
        );
    }

    #[test]
    fn live_lead_attach_clear_invalid_and_block_fallback_preserve_java_order() {
        let Some((mut client, _dir, mut to_net)) =
            client_aimed_at_stone(Some(stack_named("lead", 2)))
        else {
            return;
        };
        let entity_id = 44;
        spawn_pick_target(
            &mut client,
            entity_id,
            mc_data::EntityType::Cow,
            [16, 2064, 64],
            mc_world::Metadata::default(),
        );
        client.hit = HitResult::Entity(interact::EntityHit {
            network_id: entity_id,
            hit_vec: DVec3::new(0.5, 65.0, 2.0),
        });

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, mc_protocol::play::C2SPlay::UseEntity(_)))
                .count(),
            2,
            "a successful EntityLiving lead click keeps INTERACT_AT then INTERACT: {sent:?}"
        );
        assert!(
            placements(&sent).is_empty(),
            "a consumed lead attach must not send the untargeted C08: {sent:?}"
        );
        let local_id = client
            .session
            .as_ref()
            .expect("live test session")
            .state()
            .local
            .entity_id;
        assert_eq!(
            client.held_item().expect("survival lead remains").count,
            1,
            "survival attach consumes one lead"
        );
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live test session")
                .state()
                .entities
                .get(entity_id)
                .expect("cow generation")
                .leashed_to(),
            Some(local_id)
        );

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, mc_protocol::play::C2SPlay::UseEntity(_)))
                .count(),
            2,
            "a local-held leash clear keeps the same C02 pair: {sent:?}"
        );
        assert!(placements(&sent).is_empty());
        assert_eq!(
            client.held_item().expect("clearing keeps lead").count,
            1,
            "clearing a leash does not decrement the held lead"
        );
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live test session")
                .state()
                .entities
                .get(entity_id)
                .expect("cow generation")
                .leashed_to(),
            None
        );

        // IMob is not allowed through EntityLiving.allowLeashing. Its invalid lead click falls
        // through to the untargeted item-use packet while preserving the selected stack.
        despawn_pick_target(&mut client, entity_id);
        spawn_pick_target(
            &mut client,
            entity_id,
            mc_data::EntityType::Enderman,
            [16, 2064, 64],
            mc_world::Metadata::default(),
        );
        client.right_click_mouse();
        let sent = drained(&mut to_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, mc_protocol::play::C2SPlay::UseEntity(_)))
                .count(),
            2,
            "invalid living lead still sends both targeted C02 packets: {sent:?}"
        );
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            1,
            "invalid lead reaches one fallback C08: {sent:?}"
        );
        assert_eq!(placed[0].position, BlockPos::new(-1, -1, -1));
        assert_eq!(client.held_item().expect("invalid lead remains").count, 1);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("live test session")
                .state()
                .entities
                .get(entity_id)
                .expect("enderman generation")
                .leashed_to(),
            None
        );

        // Capabilities, not the game-mode label, own ItemLead's creative copy rule.
        let Some((mut creative, _dir, mut creative_net)) =
            client_aimed_at_stone(Some(stack_named("lead", 2)))
        else {
            return;
        };
        creative
            .session
            .as_mut()
            .expect("creative session")
            .state_mut()
            .local
            .abilities
            .creative_mode = true;
        spawn_pick_target(
            &mut creative,
            entity_id,
            mc_data::EntityType::Cow,
            [16, 2064, 64],
            mc_world::Metadata::default(),
        );
        creative.hit = HitResult::Entity(interact::EntityHit {
            network_id: entity_id,
            hit_vec: DVec3::new(0.5, 65.0, 2.0),
        });
        creative.right_click_mouse();
        let sent = drained(&mut creative_net);
        assert!(placements(&sent).is_empty());
        assert_eq!(creative.held_item().expect("creative lead").count, 2);

        // ItemLead.onItemUse claims fences on the client but rejects ordinary blocks. The latter
        // therefore emits targeted C08 followed by the usual (-1,-1,-1) fallback.
        let Some((mut fence, _dir, mut fence_net)) =
            client_aimed_at_stone(Some(stack_named("lead", 2)))
        else {
            return;
        };
        let target = BlockPos::new(3, 65, 4);
        fence
            .session
            .as_mut()
            .expect("fence session")
            .state_mut()
            .world
            .set_block(target, mc_data::BlockState::new(mc_data::BlockId(85), 0));
        fence.right_click_mouse();
        let sent = drained(&mut fence_net);
        assert_eq!(
            placements(&sent).len(),
            1,
            "fence lead has no fallback C08: {sent:?}"
        );
        assert_eq!(placements(&sent)[0].position, target);

        let Some((mut ordinary, _dir, mut ordinary_net)) =
            client_aimed_at_stone(Some(stack_named("lead", 2)))
        else {
            return;
        };
        ordinary.right_click_mouse();
        let sent = drained(&mut ordinary_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            2,
            "non-fence lead has targeted plus fallback C08: {sent:?}"
        );
        assert_eq!(placed[0].position, target);
        assert_eq!(placed[1].position, BlockPos::new(-1, -1, -1));
    }

    fn resource_pack_statuses(
        sent: &[mc_protocol::play::C2SPlay],
    ) -> Vec<(&str, mc_protocol::play::c2s::ResourcePackStatusResult)> {
        sent.iter()
            .filter_map(|packet| match packet {
                mc_protocol::play::C2SPlay::ResourcePackStatus(status) => {
                    Some((status.hash.as_str(), status.result))
                }
                _ => None,
            })
            .collect()
    }

    fn resource_pack_client(
        mode: ResourceMode,
    ) -> Option<(
        Client,
        tempfile::TempDir,
        tokio::sync::mpsc::UnboundedReceiver<crate::net::ToNet>,
    )> {
        let (mut client, dir) = offline_client()?;
        let (session, _to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.ui = Ui::InGame;
        client.current_server_resource_mode = mode;
        let _ = drained(&mut to_net);
        Some((client, dir, to_net))
    }

    #[test]
    fn gui_screen_working_has_vanilla_text_percent_and_terminal_close() {
        let Some((mut client, _dir, _to_net)) = resource_pack_client(ResourceMode::Enabled) else {
            return;
        };

        client.begin_server_resource_pack_progress();
        assert!(matches!(client.ui, Ui::Loading));
        let progress = client
            .server_pack_progress
            .as_ref()
            .expect("GuiScreenWorking state");
        assert_eq!(progress.title, "Downloading Resource Pack");
        assert_eq!(progress.message, "Making Request...");
        assert_eq!(progress.progress, 0);

        client
            .server_pack_progress
            .as_mut()
            .expect("GuiScreenWorking state")
            .set_loading_progress(42);
        assert_eq!(client.server_pack_progress.as_ref().unwrap().progress, 42);

        client.finish_server_resource_pack_progress();
        assert!(client.server_pack_progress.is_none());
        assert!(matches!(client.ui, Ui::InGame));
    }

    /// java: the first S08 after GuiDownloadTerrain calls
    /// `displayGuiScreen(null)` whatever screen is open (`handlePlayerPosLook:719-726`). A
    /// server plugin's join-event S48 precedes the join teleport, so vanilla shows the
    /// GuiYesNo and closes it in the same drain: its callback never runs and no C19 is sent.
    /// Rust used to dismiss only its loading screen and kept the prompt (then sent its C19).
    #[test]
    fn the_first_position_after_terrain_closes_whatever_screen_a_server_opened() {
        let Some((mut client, _dir, mut to_net)) = resource_pack_client(ResourceMode::Prompt)
        else {
            return;
        };
        let joined = |client: &mut Client, joined: bool| {
            client
                .session
                .as_mut()
                .expect("live session")
                .state_mut()
                .local
                .entity_id_known = joined;
        };
        joined(&mut client, true);
        client.ui = Ui::Loading;
        let hash = "0123456789abcdef0123456789abcdef01234567";
        client.react(&ClientEvent::ResourcePack {
            url: "https://packs.example/join.zip".to_owned(),
            hash: hash.to_owned(),
        });
        assert!(matches!(client.ui, Ui::ConfirmServerResourcePack(..)));
        client.react(&ClientEvent::TerrainDownloaded);
        assert!(matches!(client.ui, Ui::InGame));
        assert!(
            resource_pack_statuses(&drained(&mut to_net)).is_empty(),
            "the orphaned GuiYesNo never answers"
        );
        assert_eq!(client.current_server_resource_mode, ResourceMode::Prompt);

        // GuiScreenWorking hides; the download it was showing keeps going.
        client.begin_server_resource_pack_progress();
        client.pending_server_resource_pack_hash = Some(hash.to_owned());
        client.react(&ClientEvent::TerrainDownloaded);
        assert!(client.server_pack_progress.is_none());
        assert!(matches!(client.ui, Ui::InGame));
        assert_eq!(
            client.pending_server_resource_pack_hash.as_deref(),
            Some(hash)
        );

        // A container closes locally (`GuiContainer.onGuiClosed`), with no C0D.
        client.ui = Ui::Container(Box::new(ContainerScreen::chest(1, 3, "Chest")));
        client.react(&ClientEvent::TerrainDownloaded);
        assert!(matches!(client.ui, Ui::InGame));
        assert!(
            !drained(&mut to_net)
                .iter()
                .any(|packet| matches!(packet, mc_protocol::play::C2SPlay::CloseWindow(_))),
            "displayGuiScreen(null) is not closeScreen()"
        );

        // Before JoinGame `thePlayer` is null: Java throws before reaching displayGuiScreen.
        joined(&mut client, false);
        client.ui = Ui::Loading;
        client.react(&ClientEvent::TerrainDownloaded);
        assert!(matches!(client.ui, Ui::Loading));
    }

