    /// java: `World.setBlockState` reaches `notifyNeighborsRespectDebug` only `if (!this.isRemote
    /// && (flags & 1) != 0)` (`World.java:381`), and `notifyBlockOfStateChange` is `!isRemote`
    /// gated too (`:531`). A placement predicted on the client therefore never runs
    /// `BlockFarmland.onNeighborBlockChange`: the farmland below stays farmland until the
    /// server's own neighbour update arrives as S23. (this test used to require the
    /// client-side farmland-to-dirt reaction, which vanilla never performs.)
    #[test]
    fn accepted_solid_placement_leaves_farmland_to_the_server_while_rejection_stays_packet_pure() {
        let farmland_pos = BlockPos::new(3, 65, 4);
        let placed_pos = farmland_pos.up();
        let farmland = mc_data::BlockState::new(mc_data::BlockId(60), 0);
        let dirt = mc_data::BlockState::new(mc_data::BlockId(3), 0);

        // Every ordinary ItemBlock uses the same live local-write callback.  The two log families
        // and stone are solid materials, so a client neighbour reaction would turn the farmland
        // to dirt; vanilla's client has none, which is what the dirt assertion below rules out.
        for name in ["log", "log2", "stone"] {
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named(name, 1)))
            else {
                return;
            };
            client
                .session
                .as_mut()
                .expect("session")
                .state_mut()
                .world
                .set_block(farmland_pos, farmland);

            client.right_click_mouse();

            let sent = drained(&mut to_net);
            assert_eq!(placements(&sent).len(), 1, "targeted C08 only: {sent:?}");
            assert_eq!(placements(&sent)[0].position, farmland_pos);
            assert_eq!(swings(&sent), 1);
            assert_eq!(
                sent.len(),
                2,
                "the local farmland callback must not enqueue another packet"
            );
            let world = &client.session.as_ref().expect("session").state().world;
            assert_eq!(
                world.block_at(farmland_pos),
                farmland,
                "no client-side BlockFarmland.onNeighborBlockChange for {name}"
            );
            assert_ne!(world.block_at(farmland_pos), dirt);
            assert_eq!(
                world.block_at(placed_pos).block(),
                mc_data::block_by_name(name).expect("placed block")
            );
        }

        // Creative runs ItemBlock.onItemUse on a copied stack and restores the inventory after the
        // callback: the local state write still happens, but the selected stack count does not
        // decrement.  This is the generic (non-piston) creative control.
        let creative_stone = stack_named("stone", 2);
        let Some((mut creative, _dir, mut creative_net)) =
            client_aimed_at_stone(Some(creative_stone.clone()))
        else {
            return;
        };
        {
            let state = creative.session.as_mut().expect("session").state_mut();
            state.local.game_mode = mc_protocol::play::s2c::GameMode::Creative;
            state.local.abilities.creative_mode = true;
        }
        creative.audio.clear_recent();
        creative.right_click_mouse();
        let sent = drained(&mut creative_net);
        assert_eq!(
            placements(&sent).len(),
            1,
            "creative generic placement has one C08"
        );
        assert_eq!(swings(&sent), 1, "creative generic placement swings once");
        assert_eq!(creative.held_item(), Some(&creative_stone));
        assert_eq!(
            creative
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(placed_pos)
                .block(),
            mc_data::BlockId(1),
            "creative generic ItemBlock still predicts the block locally"
        );
        // java: ItemBlock's place sound is `World.playSoundEffect` → the empty
        // `RenderGlobal.playSound`; the placer hears the server's S29 copy. This assertion used
        // to require a local copy, which is why every placement sounded twice in game.
        assert_eq!(
            creative.audio.recent().count(),
            0,
            "generic ItemBlock placement must not play a local place sound"
        );

        // ItemBanner extends ItemBlock but owns a client-validating callback that returns true
        // without invoking the generic local write/decrement/sound sequence. It still gets the
        // targeted packet and one swing, which is the deliberate no-prediction control.
        let banner = stack_named("banner", 1);
        let Some((mut banner_client, _dir, mut banner_net)) =
            client_aimed_at_stone(Some(banner.clone()))
        else {
            return;
        };
        banner_client.audio.clear_recent();
        banner_client.right_click_mouse();
        let sent = drained(&mut banner_net);
        assert_eq!(
            placements(&sent).len(),
            1,
            "banner keeps only the targeted C08"
        );
        assert_eq!(
            swings(&sent),
            1,
            "banner callback returns true and swings once"
        );
        assert_eq!(banner_client.held_item(), Some(&banner));
        assert_eq!(
            banner_client
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(placed_pos),
            mc_data::BlockState::AIR,
            "ItemBanner has no client-side block prediction"
        );
        assert!(
            banner_client
                .audio
                .recent()
                .all(|record| record.request.event.path != "step.stone"),
            "ItemBanner does not emit ItemBlock's local placement sound"
        );

        let Some((mut rejected, _dir, mut to_net)) =
            client_aimed_at_stone(Some(stack_named("stone", 1)))
        else {
            return;
        };
        {
            let world = &mut rejected
                .session
                .as_mut()
                .expect("session")
                .state_mut()
                .world;
            world.set_block(farmland_pos, farmland);
            world.set_block(placed_pos, mc_data::BlockState::new(mc_data::BlockId(1), 0));
        }

        rejected.right_click_mouse();

        let sent = drained(&mut to_net);
        assert_eq!(placements(&sent).len(), 1, "only the sentinel C08 remains");
        assert_eq!(placements(&sent)[0].position, BlockPos::new(-1, -1, -1));
        assert_eq!(swings(&sent), 0);
        assert_eq!(
            rejected
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(farmland_pos),
            farmland,
            "rejected placement never invokes the local neighbour reaction"
        );
    }

    /// java: `World.checkNoEntityCollision(bb, null)` reads the local player's
    /// `getEntityBoundingBox()`, the box `moveEntity` offsets and derives `posX/posZ` from. The
    /// blockers rebuilt it from the position (`posX -+ width / 2`), which is an ulp off once a
    /// move has rounded `minX`/`maxX` independently, and the strict overlap test then refused a
    /// block placed flush against the player that Java (and the server) accept.
    #[test]
    fn placement_blockers_use_the_authoritative_player_box() {
        // The fixture clicks the top of (3, 65, 4), so the wool goes to (3, 66, 4): x in [3, 4].
        let Some((mut client, _dir, mut to_net)) =
            client_aimed_at_stone(Some(stack_named("wool", 64)))
        else {
            return;
        };
        // A box clamped flush onto x = 4, the target cell's east face. Rebuilt from its centre
        // it would start at 3.999999999999999 (interact's flush-face gate test pins that).
        let exact = mc_math::Aabb::from_bounds(4.0, 66.0, 4.2, 4.600_000_023_841_856, 67.8, 4.8);
        client
            .session
            .as_mut()
            .and_then(crate::session::Session::predictor_mut)
            .expect("JoinGame built the predictor")
            .state
            .set_from_aabb(&exact);
        assert_eq!(
            client.placement_blockers().first(),
            Some(&exact),
            "the local player's box is handed over bit for bit"
        );

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        assert_eq!(placements(&sent).len(), 1, "{sent:?}");
        assert_eq!(
            placements(&sent)[0].position,
            BlockPos::new(3, 65, 4),
            "the targeted C08, not the refused-placement sentinel"
        );
        let world = &client.session.as_ref().expect("session").state().world;
        assert_eq!(
            world.block_at(BlockPos::new(3, 66, 4)).block(),
            mc_data::BlockId(35),
            "the wool is predicted beside the flush player"
        );
    }

    #[test]
    fn stair_item_placement_uses_live_yaw_after_targeted_c08_and_accepts_correction() {
        let base = BlockPos::new(3, 65, 4);
        let target = base.up();
        let stair = mc_data::block_by_name("stone_stairs").expect("stone stairs");

        for (yaw, expected_meta) in [(0.0, 2), (90.0, 1), (180.0, 3), (-90.0, 0)] {
            let held = stack_named("stone_stairs", 2);
            let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(held.clone()))
            else {
                return;
            };
            client
                .session
                .as_mut()
                .expect("session")
                .predictor_mut()
                .expect("join built predictor")
                .state
                .yaw = yaw;

            client.right_click_mouse();

            let sent = drained(&mut to_net);
            let placed = placements(&sent);
            assert_eq!(placed.len(), 1, "targeted C08 only at yaw {yaw}: {sent:?}");
            assert_eq!(placed[0].position, base);
            assert_eq!(placed[0].placed_block_direction, 1, "top face");
            assert_eq!(placed[0].stack.as_ref(), Some(&held));
            assert_eq!(swings(&sent), 1);
            assert_eq!(
                client
                    .session
                    .as_ref()
                    .expect("session")
                    .state()
                    .world
                    .block_at(target),
                mc_data::BlockState::new(stair, expected_meta),
                "yaw {yaw} must reach BlockStairs.onBlockPlaced before the local write"
            );
            assert_eq!(client.held_item().map(|stack| stack.count), Some(1));

            let session = client.session.as_mut().expect("session");
            let mut events = Vec::new();
            crate::sync::apply(
                session.state_mut(),
                mc_protocol::play::S2CPlay::BlockChange(mc_protocol::play::s2c::BlockChange {
                    position: target,
                    block_state_id: 0,
                }),
                &mut events,
            )
            .expect("authoritative correction applies");
            assert_eq!(
                session.state().world.block_at(target),
                mc_data::BlockState::AIR,
                "the server remains authoritative over the predicted stair"
            );
        }
    }

    /// W-RCLICK / F-P1-block-32-2, corrected. Repeater and comparator
    /// are `ItemReed`, not `ItemBlock`, so `PlayerControllerMP.onPlayerRightClick`'s
    /// `instanceof ItemBlock` + `canPlaceBlockOnSide` early return does not apply: the targeted
    /// C08 always goes out. `ItemReed.onItemUse` then needs the diode's solid top surface and a
    /// replaceable destination; a refusal returns false, so there is no swing and
    /// `rightClickMouse` falls through to the untargeted sentinel C08 as well.
    #[test]
    fn diode_item_reed_right_click_sends_the_targeted_c08_before_its_support_check() {
        let hit_pos = BlockPos::new(3, 65, 4);
        let target = hit_pos.up();
        let glass = mc_data::block_by_name("glass").expect("glass");
        let stone = mc_data::block_by_name("stone").expect("stone");

        for name in ["repeater", "comparator"] {
            let expected_item =
                i16::try_from(mc_data::item_by_name(name).expect("item").0).expect("item id fits");

            // Air is replaceable and the clicked stone has a solid top surface: both ItemReed
            // registrations must send the normal targeted packet and one local swing.
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named(name, 1)))
            else {
                return;
            };
            client.right_click_mouse();
            let sent = drained(&mut to_net);
            let placed = placements(&sent);
            assert_eq!(placed.len(), 1, "valid {name} click: {sent:?}");
            assert_eq!(placed[0].position, hit_pos);
            assert_eq!(placed[0].placed_block_direction, 1, "EnumFacing.UP");
            assert_eq!(
                (placed[0].cursor_x, placed[0].cursor_y, placed[0].cursor_z),
                (8, 16, 8),
                "targeted hit cursor must be preserved for {name}"
            );
            assert_eq!(
                placed[0].stack.as_ref().map(|stack| stack.item_id),
                Some(expected_item),
                "targeted packet keeps the {name} item"
            );
            assert_eq!(swings(&sent), 1, "valid {name} placement swings once");
            let expected_block = if name == "repeater" { 93 } else { 149 };
            assert_eq!(
                client
                    .session
                    .as_ref()
                    .expect("session")
                    .state()
                    .world
                    .block_at(target)
                    .block(),
                mc_data::BlockId(expected_block),
                "the ItemReed callback must write the {name} locally"
            );
            assert!(
                client.held_item().is_none(),
                "survival {name} decrements to zero"
            );

            // A non-solid support: the targeted packet still goes out, then `onItemUse` refuses
            // (no swing) and the sentinel follows.
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named(name, 1)))
            else {
                return;
            };
            client
                .session
                .as_mut()
                .expect("session")
                .state_mut()
                .world
                .set_block(hit_pos, mc_data::BlockState::new(glass, 0));
            client.right_click_mouse();
            let sent = drained(&mut to_net);
            let placed = placements(&sent);
            assert_eq!(
                placed.len(),
                2,
                "invalid support: targeted C08, then the sentinel: {sent:?}"
            );
            assert_eq!(placed[0].position, hit_pos);
            assert_eq!(placed[0].placed_block_direction, 1, "EnumFacing.UP");
            assert_eq!(placed[1].position, BlockPos::new(-1, -1, -1));
            assert_eq!(placed[1].placed_block_direction, 255);
            assert_eq!(swings(&sent), 0, "invalid {name} support does not swing");
            assert_eq!(
                client
                    .session
                    .as_ref()
                    .expect("session")
                    .state()
                    .world
                    .block_at(target),
                mc_data::BlockState::AIR,
                "no {name} is predicted on glass"
            );

            // An occupied destination: `World.canBlockBePlaced` refuses inside `onItemUse`, after
            // the targeted packet, so the sentinel follows it and nothing swings.
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named(name, 1)))
            else {
                return;
            };
            client
                .session
                .as_mut()
                .expect("session")
                .state_mut()
                .world
                .set_block(target, mc_data::BlockState::new(stone, 0));
            client.right_click_mouse();
            let sent = drained(&mut to_net);
            let placed = placements(&sent);
            assert_eq!(
                placed.len(),
                2,
                "occupied {name} target: targeted C08, then the sentinel: {sent:?}"
            );
            assert_eq!(placed[0].position, hit_pos);
            assert_eq!(placed[1].position, BlockPos::new(-1, -1, -1));
            assert_eq!(swings(&sent), 0, "occupied {name} target does not swing");
        }
    }

    /// java: `PlayerControllerMP.onPlayerRightClick` returns before
    /// the targeted C08 only for `heldStack.getItem() instanceof ItemBlock` whose
    /// `canPlaceBlockOnSide` fails. Every other placer (the eight `ItemReed` registrations,
    /// `ItemDoor`, `ItemBed`, `ItemSign`, `ItemRedstone`, `ItemSeeds`, `ItemSeedFood`,
    /// `ItemSkull`) gets the targeted C08 even into an occupied cell; its own `onItemUse` refuses
    /// afterwards. Controls: plain stone and the banner (an `ItemBlock` registered at 425 whose
    /// block is the standing banner) stay gated.
    #[test]
    fn only_item_block_placers_are_gated_before_the_targeted_c08() {
        let hit_pos = BlockPos::new(3, 65, 4);
        let stone = mc_data::block_by_name("stone").expect("stone");
        let targeted = |sent: &[mc_protocol::play::C2SPlay]| {
            placements(sent)
                .iter()
                .filter(|placement| placement.position == hit_pos)
                .count()
        };
        let occupied_click = |name: &str| {
            let (mut client, _dir, mut to_net) = client_aimed_at_stone(Some(stack_named(name, 1)))?;
            client
                .session
                .as_mut()
                .expect("session")
                .state_mut()
                .world
                .set_block(hit_pos.up(), mc_data::BlockState::new(stone, 0));
            client.right_click_mouse();
            Some(drained(&mut to_net))
        };

        for name in [
            "string",
            "reeds",
            "cake",
            "repeater",
            "brewing_stand",
            "cauldron",
            "flower_pot",
            "comparator",
            "wooden_door",
            "iron_door",
            "bed",
            "sign",
            "redstone",
            "wheat_seeds",
            "nether_wart",
            "carrot",
            "skull",
        ] {
            let Some(sent) = occupied_click(name) else {
                return;
            };
            assert_eq!(targeted(&sent), 1, "{name} is not an ItemBlock: {sent:?}");
        }
        for name in ["stone", "banner"] {
            let Some(sent) = occupied_click(name) else {
                return;
            };
            assert_eq!(targeted(&sent), 0, "{name} is an ItemBlock: {sent:?}");
        }
    }

