    /// W-RCLICK / `ItemSlab.onItemUse`: the targeted C08 is queued before the remote-world
    /// merge, then the survival copy decrements exactly once and the callback's true result
    /// produces one swing with no untargeted sentinel.
    #[test]
    fn slab_merge_is_applied_after_targeted_c08_and_decrements_live_stack() {
        let slab = stack_named("stone_slab", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(slab.clone())) else {
            return;
        };
        let pos = BlockPos::new(3, 65, 4);
        let single = mc_data::BlockId(44);
        let double = mc_data::BlockId(43);
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(slab.clone()));
        client.refresh_hotbar();
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .set_block(pos, mc_data::BlockState::new(single, 0));

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(placed.len(), 1, "merge has no sentinel C08: {sent:?}");
        assert_eq!(placed[0].position, pos);
        assert_eq!(
            placed[0].stack.as_ref(),
            Some(&slab),
            "C08 snapshots before decrement"
        );
        assert_eq!(swings(&sent), 1, "a consumed merge swings once");
        let session = client.session.as_ref().expect("session");
        assert_eq!(
            session.state().world.block_at(pos),
            mc_data::BlockState::new(double, 0),
            "the double slab appears after the targeted packet"
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(1),
            "survival ItemSlab decrements its live selected stack once"
        );
        assert_eq!(client.held_item().map(|stack| stack.count), Some(1));
    }

    /// `ItemSlab.tryPlace` returns true even when the double slab's collision box is blocked.
    /// The live controller must therefore consume the click and swing, while leaving both the
    /// local single slab and the held count unchanged.
    #[test]
    fn slab_collision_failure_is_consumed_without_local_write_or_decrement() {
        let slab = stack_named("stone_slab", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(slab.clone())) else {
            return;
        };
        let pos = BlockPos::new(3, 65, 4);
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(slab.clone()));
        client.refresh_hotbar();
        {
            let session = client.session.as_mut().expect("session");
            session
                .state_mut()
                .world
                .set_block(pos, mc_data::BlockState::new(mc_data::BlockId(44), 0));
            // `Entity.setPosition`: the bounding box is what `checkNoEntityCollision` reads,
            // so the player has to be moved with its box, not by assigning `pos` alone.
            session
                .predictor_mut()
                .expect("JoinGame predictor")
                .state
                .set_position(DVec3::new(3.5, 65.0, 4.5));
        }

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            1,
            "the consumed failure still has only targeted C08"
        );
        assert_eq!(placed[0].position, pos);
        assert_eq!(
            swings(&sent),
            1,
            "a true collision-blocked callback still swings"
        );
        let session = client.session.as_ref().expect("session");
        assert_eq!(
            session.state().world.block_at(pos),
            mc_data::BlockState::new(mc_data::BlockId(44), 0),
            "collision failure leaves the single slab in place"
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(2),
            "collision failure does not decrement"
        );
    }

