    #[test]
    fn door_item_places_both_halves_after_targeted_c08_and_accepts_independent_corrections() {
        let door = stack_named("wooden_door", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(door.clone())) else {
            return;
        };
        let base = BlockPos::new(3, 65, 4);
        let lower = base.up();
        let upper = lower.up();
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(door.clone()));
        client.refresh_hotbar();

        client.right_click_mouse();

        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            1,
            "successful ItemDoor has no sentinel: {sent:?}"
        );
        assert_eq!(placed[0].position, base);
        assert_eq!(placed[0].placed_block_direction, 1, "EnumFacing.UP");
        assert_eq!(
            placed[0].stack.as_ref(),
            Some(&door),
            "the targeted C08 snapshots the stack before ItemDoor decrements it"
        );
        assert_eq!(swings(&sent), 1, "a true ItemDoor callback swings once");

        let session = client.session.as_ref().expect("session");
        let wooden = mc_data::BlockId(64);
        assert_eq!(
            session.state().world.block_at(lower),
            mc_data::BlockState::new(wooden, 1),
            "yaw zero predicts the south-facing lower half"
        );
        assert_eq!(
            session.state().world.block_at(upper),
            mc_data::BlockState::new(wooden, 8),
            "an empty-neighbour tie predicts the left-hinge upper half"
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(1),
            "survival decrements exactly once"
        );

        // S23 remains packet-pure and authoritative for either predicted half.
        let session = client.session.as_mut().expect("session");
        let mut events = Vec::new();
        crate::sync::apply(
            session.state_mut(),
            mc_protocol::play::S2CPlay::BlockChange(mc_protocol::play::s2c::BlockChange {
                position: upper,
                block_state_id: 1 << 4,
            }),
            &mut events,
        )
        .expect("upper correction applies");
        assert_eq!(
            session.state().world.block_at(lower),
            mc_data::BlockState::new(wooden, 1),
            "an upper correction does not disturb the lower prediction"
        );
        assert_eq!(session.state().world.block_at(upper).block().0, 1);
        crate::sync::apply(
            session.state_mut(),
            mc_protocol::play::S2CPlay::BlockChange(mc_protocol::play::s2c::BlockChange {
                position: lower,
                block_state_id: 0,
            }),
            &mut events,
        )
        .expect("lower correction applies");
        assert_eq!(
            session.state().world.block_at(lower),
            mc_data::BlockState::AIR
        );
        assert_eq!(session.state().world.block_at(upper).block().0, 1);
    }

    #[test]
    fn double_plant_item_places_both_halves_after_targeted_c08_and_swings_once() {
        let plant = stack_named("double_plant", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(plant.clone()))
        else {
            return;
        };
        let base = BlockPos::new(3, 65, 4);
        let lower = base.up();
        let upper = lower.up();
        // BlockDoublePlant inherits BlockBush and therefore needs grass/dirt/farmland below its
        // lower cell; the fixture starts with stone only so replace the hit block for this case.
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .set_block(base, mc_data::BlockState::new(mc_data::BlockId(2), 0));
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(plant.clone()));
        client.refresh_hotbar();

        client.right_click_mouse();

        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            1,
            "double plant has one targeted C08 and no sentinel"
        );
        assert_eq!(placed[0].position, base);
        assert_eq!(placed[0].placed_block_direction, 1, "EnumFacing.UP");
        assert_eq!(
            placed[0].stack.as_ref(),
            Some(&plant),
            "the targeted C08 snapshots the stack before the pair writes/decrement"
        );
        let targeted = sent
            .iter()
            .position(|packet| {
                matches!(packet, mc_protocol::play::C2SPlay::PlayerBlockPlacement(_))
            })
            .expect("targeted placement packet");
        let swing = sent
            .iter()
            .position(|packet| matches!(packet, mc_protocol::play::C2SPlay::Animation(_)))
            .expect("successful placement swing");
        assert!(targeted < swing, "C08 precedes the C0A swing");
        assert_eq!(swings(&sent), 1, "the pair callback swings exactly once");

        let session = client.session.as_ref().expect("session");
        assert_eq!(
            session.state().world.block_at(lower),
            mc_data::BlockState::new(mc_data::BlockId(175), 0)
        );
        assert_eq!(
            session.state().world.block_at(upper),
            mc_data::BlockState::new(mc_data::BlockId(175), 10),
            "BlockDoublePlant's default NORTH upper state is metadata 10"
        );
        assert_eq!(
            client.held_item().map(|stack| stack.count),
            Some(1),
            "the pair decrements survival once after both writes"
        );
    }

    #[test]
    fn door_item_creative_retains_count_while_rejected_callbacks_fall_through() {
        let door = stack_named("wooden_door", 7);
        let Some((mut creative, _dir, mut creative_net)) =
            client_aimed_at_stone(Some(door.clone()))
        else {
            return;
        };
        creative
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .game_mode = mc_protocol::play::s2c::GameMode::Creative;
        creative
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .abilities
            .creative_mode = true;
        creative
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(door.clone()));
        creative.refresh_hotbar();
        creative.right_click_mouse();
        let sent = drained(&mut creative_net);
        assert_eq!(placements(&sent).len(), 1);
        assert_eq!(swings(&sent), 1);
        assert_eq!(creative.held_item().map(|stack| stack.count), Some(7));
        let lower = BlockPos::new(3, 66, 4);
        assert_eq!(
            creative
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(lower)
                .block(),
            mc_data::BlockId(64)
        );

        let denied =
            |mut client: Client,
             mut to_net: tokio::sync::mpsc::UnboundedReceiver<crate::net::ToNet>| {
                let held = stack_named("wooden_door", 2);
                client
                    .player_container
                    .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(held));
                client.refresh_hotbar();
                client.right_click_mouse();
                let sent = drained(&mut to_net);
                let placed = placements(&sent);
                assert_eq!(
                    placed.len(),
                    2,
                    "rejected ItemDoor needs targeted + sentinel"
                );
                assert_eq!(placed[0].position, BlockPos::new(3, 65, 4));
                assert_eq!(placed[1].position, BlockPos::new(-1, -1, -1));
                assert_eq!(placed[1].placed_block_direction, 255);
                assert_eq!(swings(&sent), 0);
                assert_eq!(client.held_item().map(|stack| stack.count), Some(2));
                assert_eq!(
                    client
                        .session
                        .as_ref()
                        .expect("session")
                        .state()
                        .world
                        .block_at(BlockPos::new(3, 66, 4)),
                    mc_data::BlockState::AIR
                );
            };

        let Some((mut wrong_face, _dir, wrong_face_net)) =
            client_aimed_at_stone(Some(stack_named("wooden_door", 2)))
        else {
            return;
        };
        wrong_face.hit = HitResult::Block(interact::BlockHit {
            pos: BlockPos::new(3, 65, 4),
            face: mc_math::Facing::North,
            hit_vec: DVec3::new(3.5, 65.5, 4.0),
        });
        denied(wrong_face, wrong_face_net);

        let Some((mut blocked_upper, _dir, blocked_upper_net)) =
            client_aimed_at_stone(Some(stack_named("wooden_door", 2)))
        else {
            return;
        };
        blocked_upper
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .set_block(
                BlockPos::new(3, 67, 4),
                mc_data::BlockState::new(mc_data::BlockId(1), 0),
            );
        denied(blocked_upper, blocked_upper_net);
    }

    /// `ItemSnow` stacks in place on a one-layer cell and the fallback `ItemBlock` receives the
    /// already-offset cell, so a blocked first offset is followed by the deliberate second one.
    #[test]
    fn snow_callback_stacks_and_preserves_live_double_offset_delegate() {
        let snow = stack_named("snow_layer", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(snow.clone())) else {
            return;
        };
        let pos = BlockPos::new(3, 65, 4);
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(snow.clone()));
        client.refresh_hotbar();
        {
            let session = client.session.as_mut().expect("session");
            session
                .state_mut()
                .world
                .set_block(pos.down(), mc_data::BlockState::new(mc_data::BlockId(1), 0));
            session
                .state_mut()
                .world
                .set_block(pos, mc_data::BlockState::new(mc_data::BlockId(78), 0));
        }

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(placed.len(), 1, "snow stacking has no sentinel: {sent:?}");
        assert_eq!(
            placed[0].position, pos,
            "targeted C08 remains the original hit"
        );
        assert_eq!(
            placed[0].stack.as_ref(),
            Some(&snow),
            "packet precedes snow decrement"
        );
        assert_eq!(swings(&sent), 1);
        let session = client.session.as_ref().expect("session");
        assert_eq!(
            session.state().world.block_at(pos),
            mc_data::BlockState::new(mc_data::BlockId(78), 1),
            "one-layer snow increments locally"
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(1)
        );

        let snow = stack_named("snow_layer", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(snow.clone())) else {
            return;
        };
        let first = pos.relative(mc_math::Facing::North);
        let second = first.relative(mc_math::Facing::North);
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(snow.clone()));
        client.refresh_hotbar();
        {
            let session = client.session.as_mut().expect("session");
            session
                .state_mut()
                .world
                .set_block(pos.down(), mc_data::BlockState::new(mc_data::BlockId(1), 0));
            session
                .state_mut()
                .world
                .set_block(pos, mc_data::BlockState::new(mc_data::BlockId(78), 1));
            session
                .state_mut()
                .world
                .set_block(first, mc_data::BlockState::new(mc_data::BlockId(1), 0));
            session.state_mut().world.set_block(
                second.down(),
                mc_data::BlockState::new(mc_data::BlockId(1), 0),
            );
        }
        client.hit = HitResult::Block(interact::BlockHit {
            pos,
            face: mc_math::Facing::North,
            hit_vec: DVec3::new(3.5, 65.25, 4.5),
        });

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            1,
            "double-offset delegate has no sentinel: {sent:?}"
        );
        assert_eq!(
            placed[0].position, pos,
            "the wire still carries the original hit"
        );
        assert_eq!(placed[0].placed_block_direction, 2, "EnumFacing.NORTH");
        assert_eq!(swings(&sent), 1, "the superclass placement is consumed");
        let session = client.session.as_ref().expect("session");
        assert_eq!(
            session.state().world.block_at(first).block(),
            mc_data::BlockId(1),
            "the first offset remains occupied"
        );
        assert_eq!(
            session.state().world.block_at(second),
            mc_data::BlockState::new(mc_data::BlockId(78), 0),
            "ItemBlock receives first offset and places at its second offset"
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(1),
            "delegate placement decrements once"
        );
    }

    /// The pre-C08 placement gate does not own `canPlayerEdit`: a denied special callback has
    /// already queued its targeted C08, then returns false so rightClickMouse falls through to
    /// exactly one untargeted sentinel and no swing.
    #[test]
    fn denied_slab_callback_falls_through_to_sentinel_without_consuming() {
        let slab = stack_named("stone_slab", 2);
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(slab.clone())) else {
            return;
        };
        let pos = BlockPos::new(3, 65, 4);
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(slab.clone()));
        client.refresh_hotbar();
        {
            let session = client.session.as_mut().expect("session");
            session.state_mut().local.abilities.allow_edit = false;
            session
                .state_mut()
                .world
                .set_block(pos, mc_data::BlockState::new(mc_data::BlockId(44), 0));
        }

        client.right_click_mouse();
        let sent = drained(&mut to_net);
        let placed = placements(&sent);
        assert_eq!(
            placed.len(),
            2,
            "denied callback reaches the sentinel: {sent:?}"
        );
        assert_eq!(placed[0].position, pos);
        assert_eq!(placed[1].position, BlockPos::new(-1, -1, -1));
        assert_eq!(placed[1].placed_block_direction, 255);
        assert_eq!(swings(&sent), 0, "a false callback does not swing");
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(pos),
            mc_data::BlockState::new(mc_data::BlockId(44), 0)
        );
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(2)
        );
    }

