    #[test]
    fn drinking_emits_six_predecrement_random_drink_beats() {
        const DRINK_RNG_SEED: i64 = 0x4452494E4B;

        let potion = stack_named("potion", 1);
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(Some(potion.clone())) else {
            return;
        };
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(potion.clone()));
        let identity = client
            .held_item_identity()
            .expect("selected potion identity");
        client
            .controller
            .set_item_in_use_at_slot(potion, 32, 0, identity);
        client.audio.clear_recent();

        // Pre-decrement counts are 32 through 4. Only 24,20,16,12,8,4 play.
        for _ in 0..29 {
            client.tick(&MoveInput::default());
        }

        let drinks: Vec<_> = client
            .audio
            .recent()
            .filter(|record| record.request.event.path == "random.drink")
            .collect();
        assert_eq!(
            drinks.len(),
            6,
            "expected one beat at each positive cadence"
        );
        let mut expected_rng = mc_math::JavaRandom::new(DRINK_RNG_SEED);
        for record in drinks {
            assert_eq!(record.request.volume, 0.5);
            assert_eq!(record.request.pitch, expected_rng.next_f32() * 0.1 + 0.9);
            assert!(
                record.request.position.is_some(),
                "drink sound follows the local player"
            );
        }
        assert_eq!(client.controller.item_in_use_count(), 3);
    }

    /// Java's cadence test is `itemInUseCount <= 25 &&
    /// itemInUseCount % 4 == 0`, and a client never finishes the use locally (`--count == 0 &&
    /// !isRemote`), so the counter keeps falling until the server's status 9. The beats at
    /// `0` and `-4` are vanilla too: on a real connection the status 9 always arrives after the
    /// client's own count reaches zero, so every eat/drink has one more beat than `24..=4`.
    #[test]
    fn the_eat_and_drink_cadence_continues_below_zero_until_the_status_9_finish() {
        let potion = stack_named("potion", 1);
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(Some(potion.clone())) else {
            return;
        };
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(potion.clone()));
        let identity = client
            .held_item_identity()
            .expect("selected potion identity");
        client
            .controller
            .set_item_in_use_at_slot(potion, 32, 0, identity);
        client.audio.clear_recent();

        // Pre-decrement counts 32 through -4: beats at 24, 20, 16, 12, 8, 4, 0 and -4.
        for _ in 0..37 {
            client.tick(&MoveInput::default());
        }
        let drinks = client
            .audio
            .recent()
            .filter(|record| record.request.event.path == "random.drink")
            .count();
        assert_eq!(
            drinks, 8,
            "the client keeps sampling at 0 and -4 while it waits"
        );
        assert_eq!(client.controller.item_in_use_count(), -5);
        assert!(
            client.controller.is_using_item(),
            "only status 9 ends a client use"
        );

        // Counts -5, -6 and -7 are silent (`-5 % 4 == -1`).
        for _ in 0..3 {
            client.tick(&MoveInput::default());
        }
        assert_eq!(
            client
                .audio
                .recent()
                .filter(|record| record.request.event.path == "random.drink")
                .count(),
            8
        );
    }

    #[test]
    fn eating_emits_five_predecrement_item_crumbs_and_one_random_eat_beat() {
        let apple = stack_named("apple", 1);
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(Some(apple.clone())) else {
            return;
        };
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(apple.clone()));
        client.refresh_hotbar();
        let identity = client
            .held_item_identity()
            .expect("selected apple identity");
        client
            .controller
            .set_item_in_use_at_slot(apple, 24, 0, identity);
        client.particles.clear();
        client.audio.clear_recent();

        client.tick(&MoveInput::default());

        assert_eq!(client.particles.len(), 5);
        assert!(client.particles.particles().iter().all(|particle| {
            particle.pos.x.is_finite()
                && particle.pos.y.is_finite()
                && particle.pos.z.is_finite()
                && particle.motion.x.is_finite()
                && particle.motion.y.is_finite()
                && particle.motion.z.is_finite()
        }));
        let eats: Vec<_> = client
            .audio
            .recent()
            .filter(|record| record.request.event.path == "random.eat")
            .collect();
        assert_eq!(eats.len(), 1);
        let mut expected_rng = mc_math::JavaRandom::new(ITEM_USE_RNG_SEED);
        for _ in 0..5 {
            expected_rng.next_f32();
            expected_rng.next_f32();
            expected_rng.next_f32();
        }
        assert_eq!(
            eats[0].request.volume,
            0.5 + 0.5 * expected_rng.next_i32_bound(2) as f32
        );
        assert_eq!(
            eats[0].request.pitch,
            (expected_rng.next_f32() - expected_rng.next_f32()) * 0.2 + 1.0
        );
        assert!(eats[0].request.position.is_some());
        assert_eq!(client.controller.item_in_use_count(), 23);
    }

    /// The final eat beat is `EntityPlayerSP.playSound` (local). The burp that follows is
    /// `World.playSoundAtEntity` (`ItemFood.java:62`), the empty client sink: the eater hears the
    /// server's S29 burp, so only the eat sound may reach the engine. The burp's pitch operand is
    /// still drawn, so the item-use stream position is unchanged. This test used to require a
    /// local burp, which played it twice.
    #[test]
    fn local_finish_status_emits_sixteen_food_crumbs_then_eat_and_burp_before_mutation() {
        let apple = stack_named("apple", 2);
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(Some(apple.clone())) else {
            return;
        };
        client
            .player_container
            .set_slot_contents(HOTBAR_SLOT_OFFSET, Some(apple.clone()));
        client.refresh_hotbar();
        let identity = client
            .held_item_identity()
            .expect("selected apple identity");
        client
            .controller
            .set_item_in_use_at_slot(apple, 32, 0, identity);
        client.particles.clear();
        client.audio.clear_recent();

        client.react(&ClientEvent::EntityStatus {
            network_id: 1,
            opcode: 9,
        });

        assert_eq!(client.particles.len(), 16);
        let item_use_audio: Vec<_> = client
            .audio
            .recent()
            .filter(|record| {
                matches!(
                    record.request.event.path.as_str(),
                    "random.eat" | "random.burp"
                )
            })
            .collect();
        assert_eq!(item_use_audio.len(), 1, "only the local eat beat plays");
        assert_eq!(item_use_audio[0].request.event.path, "random.eat");

        let mut expected_rng = mc_math::JavaRandom::new(ITEM_USE_RNG_SEED);
        for _ in 0..16 {
            expected_rng.next_f32();
            expected_rng.next_f32();
            expected_rng.next_f32();
        }
        assert_eq!(
            item_use_audio[0].request.volume,
            0.5 + 0.5 * expected_rng.next_i32_bound(2) as f32
        );
        assert_eq!(
            item_use_audio[0].request.pitch,
            (expected_rng.next_f32() - expected_rng.next_f32()) * 0.2 + 1.0
        );
        // The burp pitch operand is still consumed after the eat beat.
        expected_rng.next_f32();
        assert_eq!(client.item_use_rng.raw_seed(), expected_rng.raw_seed());
        assert!(!client.controller.is_using_item());
        assert_eq!(
            client
                .player_container
                .slot_stack(HOTBAR_SLOT_OFFSET)
                .map(|stack| stack.count),
            Some(1)
        );
    }

