    #[test]
    fn live_cake_right_click_predicts_every_bite_and_handles_ineligible_players() {
        use mc_protocol::play::{s2c::GameMode, C2SPlay};

        let pos = BlockPos::new(3, 65, 4);
        for bites in 0..=6 {
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named("bread", 3)))
            else {
                return;
            };
            put_click_target(
                &mut client,
                mc_data::BlockState::new(mc_data::BlockId(92), bites),
            );
            client.player_hud.food = 10;
            client.player_hud.saturation = 1.0;
            {
                let local = &mut client.session.as_mut().expect("session").state_mut().local;
                local.food_level = 10;
                local.saturation = 1.0;
            }

            client.right_click_mouse();

            let state = client
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(pos);
            if bites < 6 {
                assert_eq!(
                    state,
                    mc_data::BlockState::new(mc_data::BlockId(92), bites + 1)
                );
            } else {
                assert_eq!(
                    state,
                    mc_data::BlockState::AIR,
                    "the seventh slice removes cake"
                );
            }
            assert_eq!(
                (client.player_hud.food, client.player_hud.saturation),
                (12, 1.4)
            );
            let local = &client.session.as_ref().expect("session").state().local;
            assert_eq!((local.food_level, local.saturation), (12, 1.4));

            let sent = drained(&mut to_net);
            assert!(matches!(
                sent.as_slice(),
                [C2SPlay::PlayerBlockPlacement(_), C2SPlay::Animation(_)]
            ));
            let placed = placements(&sent);
            assert_eq!(placed.len(), 1, "cake suppresses the sentinel C08");
            assert_eq!(placed[0].position, pos);
            assert_eq!(placed[0].stack.as_ref().expect("bread").count, 3);
        }

        for creative in [false, true] {
            let Some((mut client, _dir, mut to_net)) =
                client_aimed_at_stone(Some(stack_named("bread", 3)))
            else {
                return;
            };
            put_click_target(
                &mut client,
                mc_data::BlockState::new(mc_data::BlockId(92), 4),
            );
            client.player_hud.food = if creative { 10 } else { 20 };
            client.player_hud.saturation = 2.0;
            {
                let local = &mut client.session.as_mut().expect("session").state_mut().local;
                local.food_level = client.player_hud.food;
                local.saturation = 2.0;
                if creative {
                    local.game_mode = GameMode::Creative;
                    local.abilities.invulnerable = true;
                }
            }

            client.right_click_mouse();

            let session = client.session.as_ref().expect("session");
            assert_eq!(
                session.state().world.block_at(pos),
                mc_data::BlockState::new(mc_data::BlockId(92), 4),
                "full-hunger and creative players do not eat cake"
            );
            assert_eq!(client.player_hud.saturation, 2.0);
            assert_eq!(session.state().local.saturation, 2.0);
            let sent = drained(&mut to_net);
            assert!(matches!(
                sent.as_slice(),
                [C2SPlay::PlayerBlockPlacement(_), C2SPlay::Animation(_)]
            ));
            assert_eq!(
                placements(&sent).len(),
                1,
                "an ineligible cake click is still handled and suppresses item fallback"
            );
        }
    }

    #[test]
    fn peaceful_food_regeneration_updates_local_state_and_hud_on_the_tenth_player_tick() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.player_hud.food = 9;
        client.player_hud.saturation = 2.0;
        let session = client.session.as_mut().expect("session");
        session.state_mut().env.difficulty =
            mc_protocol::play::s2c::ServerDifficultyLevel::Peaceful;
        session.state_mut().local.food_level = 9;
        session.state_mut().local.saturation = 2.0;

        for _ in 0..9 {
            client.tick(&MoveInput::default());
        }
        assert_eq!(client.player_hud.food, 9, "refill waits for tick ten");
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .food_level,
            9
        );

        client.tick(&MoveInput::default());
        assert_eq!(client.player_hud.food, 10);
        assert_eq!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .food_level,
            10
        );
        assert_eq!(
            client.player_hud.saturation, 2.0,
            "Peaceful refill changes food only"
        );

        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .env
            .difficulty = mc_protocol::play::s2c::ServerDifficultyLevel::Normal;
        for _ in 0..10 {
            client.tick(&MoveInput::default());
        }
        assert_eq!(
            client.player_hud.food, 10,
            "normal difficulty has no special refill"
        );
    }

    /// java: `EntityPlayerSP.onLivingUpdate` computes the sprint gate's
    /// `flag3 = foodLevel > 6.0F` *before* `super.onLivingUpdate()` reaches
    /// `EntityPlayer.onLivingUpdate`'s Peaceful refill, so the tick that refills 6 -> 7 still
    /// cannot start a sprint; the next one can. Negative control: running the refill ahead of
    /// the player tick (the pre-wave order) sprints one tick early.
    #[test]
    fn peaceful_refill_reaches_the_sprint_gate_one_tick_after_it_lands() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let session = client.session.as_mut().expect("session");
        session.state_mut().env.difficulty =
            mc_protocol::play::s2c::ServerDifficultyLevel::Peaceful;
        session.state_mut().local.food_level = 6;
        session
            .predictor_mut()
            .expect("join built predictor")
            .state
            .set_position(DVec3::new(3.5, 64.0, 10.5));
        let run = MoveInput {
            forward: true,
            sprint: true,
            ..MoveInput::default()
        };
        let sprinting = |client: &Client| {
            client
                .session
                .as_ref()
                .and_then(Session::predictor)
                .expect("join built predictor")
                .state
                .sprinting
        };

        for _ in 0..9 {
            client.tick(&run);
            assert!(!sprinting(&client), "food 6 cannot start a sprint");
        }
        client.tick(&run);
        assert_eq!(client.player_hud.food, 7, "tick ten refills");
        assert!(
            !sprinting(&client),
            "the refill lands after this tick's sprint gate"
        );
        client.tick(&run);
        assert!(sprinting(&client), "the next tick's gate sees food 7");
    }

