    /// `GuiContainer.updateScreen:761-764` closes a container for a
    /// dead player through `closeScreen()`, after `handleInput` drained its clicks: a queued C0E
    /// reaches the wire before that window's C0D, and GuiGameOver replaces the chest (first
    /// `updateScreen` on the next tick). `GuiInventory.updateScreen:34-42` does **not** call
    /// `super`, so the player's own inventory stays open with no C0D until the player closes
    /// it, which then sends C0D(0) and lands on GuiGameOver. The old client closed window 0 on
    /// the death tick. An alive player keeps the same screen.
    #[test]
    fn dead_player_closes_inventory_after_its_queued_click_while_alive_stays_open() {
        use mc_protocol::play::C2SPlay;

        // A chest: closed by the death tick, C0E before C0D(5).
        let Some((mut dead, _dir, mut dead_net)) = client_aimed_at_stone(None) else {
            return;
        };
        dead.ui = Ui::InGame;
        dead.react_to_window(&crate::sync::WindowEvent::Open(
            mc_protocol::play::s2c::OpenWindow {
                window_id: 5,
                inventory_type: "minecraft:chest".to_owned(),
                window_title: "Chest".to_owned(),
                slot_count: 27,
                entity_id: None,
            },
        ));
        let _ = drained(&mut dead_net);
        let Ui::Container(screen) = &mut dead.ui else {
            panic!("the chest must use GuiContainer");
        };
        let x = screen.gui_left() + 9;
        let y = screen.gui_top() + 19;
        let _ = screen.mouse_clicked_with_mods(x, y, 0, mc_ui::widget::keys::Modifiers::NONE);
        dead.session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .health = 0.0;
        dead.tick(&MoveInput::default());

        let sent = drained(&mut dead_net);
        let click = sent
            .iter()
            .position(|packet| matches!(packet, C2SPlay::ClickWindow(_)))
            .expect("queued chest click");
        let close = sent
            .iter()
            .position(
                |packet| matches!(packet, C2SPlay::CloseWindow(close) if close.window_id == 5),
            )
            .expect("dead chest close");
        assert!(click < close, "C0E must precede C0D: {sent:?}");
        let Ui::GameOver(screen) = &dead.ui else {
            panic!("closeScreen's displayGuiScreen(null) must substitute GuiGameOver");
        };
        assert_eq!(screen.timer(), 0, "first updateScreen is the next tick's");

        // The player's own inventory: GuiInventory skips GuiContainer.updateScreen.
        let Some((mut own, _dir, mut own_net)) = client_aimed_at_stone(None) else {
            return;
        };
        own.open_inventory();
        let _ = drained(&mut own_net);
        let Ui::Container(screen) = &mut own.ui else {
            panic!("survival inventory must use GuiContainer");
        };
        let x = screen.gui_left() + 9;
        let y = screen.gui_top() + 85;
        let _ = screen.mouse_clicked_with_mods(x, y, 0, mc_ui::widget::keys::Modifiers::NONE);
        own.session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .health = 0.0;
        own.tick(&MoveInput::default());
        own.tick(&MoveInput::default());
        let sent = drained(&mut own_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, C2SPlay::ClickWindow(_)))
                .count(),
            1,
            "the queued click is still drained: {sent:?}"
        );
        assert!(
            sent.iter()
                .all(|packet| !matches!(packet, C2SPlay::CloseWindow(_))),
            "a dead player's own inventory must not be closed by the tick: {sent:?}"
        );
        assert!(matches!(own.ui, Ui::Container(_)));
        // Closing it (GuiContainer.keyTyped -> closeScreen) sends C0D(0), then GuiGameOver.
        own.show_screen(None);
        let sent = drained(&mut own_net);
        assert!(
            sent.iter().any(
                |packet| matches!(packet, C2SPlay::CloseWindow(close) if close.window_id == 0)
            ),
            "{sent:?}"
        );
        assert!(matches!(own.ui, Ui::GameOver(_)));

        let Some((mut alive, _dir, mut alive_net)) = client_aimed_at_stone(None) else {
            return;
        };
        alive.open_inventory();
        let _ = drained(&mut alive_net);
        let Ui::Container(screen) = &mut alive.ui else {
            panic!("survival inventory must use GuiContainer");
        };
        let x = screen.gui_left() + 9;
        let y = screen.gui_top() + 85;
        let _ = screen.mouse_clicked_with_mods(x, y, 0, mc_ui::widget::keys::Modifiers::NONE);
        alive.tick(&MoveInput::default());

        let sent = drained(&mut alive_net);
        assert_eq!(
            sent.iter()
                .filter(|packet| matches!(packet, C2SPlay::ClickWindow(_)))
                .count(),
            1,
            "the alive control still drains exactly one click: {sent:?}"
        );
        assert!(
            sent.iter()
                .all(|packet| !matches!(packet, C2SPlay::CloseWindow(_))),
            "an alive player must not close the inventory: {sent:?}"
        );
        assert!(matches!(alive.ui, Ui::Container(_)));
    }

