    #[test]
    fn window_zero_hotbar_count_increases_drive_exact_five_tick_pickup_animation() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let slot = i16::try_from(HOTBAR_SLOT_OFFSET + 2).expect("hotbar slot fits");

        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot,
            item: Some(stack_named("stone", 1)),
        });
        assert_eq!(client.player_hud.animations_to_go[2], 5);

        Client::tick(&mut client, &MoveInput::default());
        assert_eq!(client.player_hud.animations_to_go[2], 4);

        client.player_hud.animations_to_go[2] = 2;
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot,
            item: Some(stack_named("stone", 1)),
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 0,
            "a fresh equal-count ItemStack must clear the replaced stack's timer"
        );

        client.player_hud.animations_to_go[2] = 2;
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot,
            item: Some(stack_named("dirt", 1)),
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 0,
            "a different equal-count stack also starts with animationsToGo zero"
        );

        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot,
            item: Some(stack_named("stone", 3)),
        });
        assert_eq!(client.player_hud.animations_to_go[2], 5);

        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: -1,
            slot: -1,
            item: Some(stack_named("stone", 64)),
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 5,
            "the carried-stack sentinel is not a hotbar pickup"
        );

        client.player_hud.animations_to_go[2] = 2;
        let mut snapshot = vec![None; HOTBAR_SLOT_OFFSET + 9];
        snapshot[HOTBAR_SLOT_OFFSET + 2] = Some(stack_named("stone", 3));
        client.react_to_window(&crate::sync::WindowEvent::Items {
            window_id: PLAYER_WINDOW_ID,
            items: snapshot,
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 0,
            "an equal S30 replacement owns a fresh zero-animation ItemStack"
        );

        client.player_hud.animations_to_go[2] = 2;
        client.react_to_window(&crate::sync::WindowEvent::Items {
            window_id: PLAYER_WINDOW_ID,
            items: vec![None; HOTBAR_SLOT_OFFSET + 9],
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 0,
            "an S30 removal clears the discarded stack's timer"
        );

        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot,
            item: None,
        });
        assert_eq!(
            client.player_hud.animations_to_go[2], 0,
            "removing the stack clears its pickup animation sidecar"
        );
    }

