    /// F-P1-entity.player-04-3: every foreign container's trailing 36 slots are views of the
    /// same InventoryPlayer that S30(window 0) and the unconditional hotbar S2F branch mutate.
    /// The Rust UI stores them by value, so both correction shapes must be mirrored before the
    /// next screen-to-window-zero convergence or the stale screen would undo the server packet.
    #[test]
    fn window_zero_corrections_reach_foreign_player_slots_without_touching_container_slots() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        client.react_to_window(&crate::sync::WindowEvent::Open(
            mc_protocol::play::s2c::OpenWindow {
                window_id: 8,
                inventory_type: "minecraft:chest".to_owned(),
                window_title: "Chest".to_owned(),
                slot_count: 27,
                entity_id: None,
            },
        ));

        let chest_marker = stack_named("gold_ingot", 1);
        let old_main = stack_named("stone", 2);
        let old_hotbar = stack_named("stick", 3);
        let mut foreign = vec![None; 27 + 36];
        foreign[0] = Some(chest_marker.clone());
        foreign[27] = Some(old_main);
        foreign[54] = Some(old_hotbar);
        client.react_to_window(&crate::sync::WindowEvent::Items {
            window_id: 8,
            items: foreign,
        });
        client.sync_window_zero_from_screen();

        let corrected_main = stack_named("dirt", 4);
        let untouched_main = stack_named("paper", 5);
        let corrected_hotbar = stack_named("apple", 6);
        let mut window_zero = vec![None; 45];
        window_zero[9] = Some(corrected_main.clone());
        window_zero[10] = Some(untouched_main.clone());
        window_zero[36] = Some(corrected_hotbar.clone());
        client.react_to_window(&crate::sync::WindowEvent::Items {
            window_id: 0,
            items: window_zero,
        });

        let Ui::Container(screen) = &client.ui else {
            panic!("the chest must remain open")
        };
        assert_eq!(screen.container.slot_stack(0), Some(&chest_marker));
        assert_eq!(screen.container.slot_stack(27), Some(&corrected_main));
        assert_eq!(screen.container.slot_stack(28), Some(&untouched_main));
        assert_eq!(screen.container.slot_stack(54), Some(&corrected_hotbar));

        let latest_hotbar = stack_named("diamond", 1);
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 36,
            item: Some(latest_hotbar.clone()),
        });
        let Ui::Container(screen) = &client.ui else {
            panic!("the chest must remain open")
        };
        assert_eq!(screen.container.slot_stack(0), Some(&chest_marker));
        assert_eq!(screen.container.slot_stack(28), Some(&untouched_main));
        assert_eq!(screen.container.slot_stack(54), Some(&latest_hotbar));

        client.sync_window_zero_from_screen();
        assert_eq!(client.player_container.slot_stack(9), Some(&corrected_main));
        assert_eq!(
            client.player_container.slot_stack(10),
            Some(&untouched_main)
        );
        assert_eq!(client.player_container.slot_stack(36), Some(&latest_hotbar));
    }

