    #[test]
    fn same_tick_inventory_open_sends_c16_before_one_abort_and_idle_reopen_is_inert() {
        use mc_protocol::play::{c2s, C2SPlay};
        use mc_render::input::keys as bind;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        client.send_click_block_to_controller(true);
        let _ = drained(&mut to_net);

        let mut keys = client.settings.keys.clone();
        let attack = keys.get(bind::ATTACK).expect("attack binding").binding();
        keys.set_state(attack, true);
        while keys.take_pressed(bind::ATTACK) {}
        let inventory = keys
            .get(bind::INVENTORY)
            .expect("inventory binding")
            .binding();
        keys.set_state(inventory, true);
        client.handle_game_input(&InputState::new(), &mut keys);

        let sent = drained(&mut to_net);
        let c16 = sent.iter().position(|packet| {
            matches!(
                packet,
                C2SPlay::ClientStatus(c2s::ClientStatus {
                    action: c2s::ClientStatusAction::OpenInventoryAchievement
                })
            )
        });
        let aborts = sent
            .iter()
            .enumerate()
            .filter_map(|(index, packet)| match packet {
                C2SPlay::PlayerDigging(c2s::PlayerDigging {
                    status: c2s::PlayerDiggingStatus::AbortDestroyBlock,
                    ..
                }) => Some(index),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            aborts.len(),
            1,
            "one active dig produces one ABORT: {sent:?}"
        );
        assert!(
            c16.is_some_and(|index| index < aborts[0]),
            "the screen-opening C16 must precede its same-tick ABORT: {sent:?}"
        );

        client.show_screen(None);
        let _ = drained(&mut to_net);
        keys.set_state(inventory, false);
        keys.set_state(inventory, true);
        client.handle_game_input(&InputState::new(), &mut keys);
        assert!(
            drained(&mut to_net).iter().all(|packet| !matches!(
                packet,
                C2SPlay::PlayerDigging(c2s::PlayerDigging {
                    status: c2s::PlayerDiggingStatus::AbortDestroyBlock,
                    ..
                })
            )),
            "held mouse with no active dig must not manufacture an ABORT"
        );
    }

    #[test]
    fn raw_escape_modal_aborts_once_clears_dig_and_cannot_later_stop() {
        use mc_protocol::play::{c2s, C2SPlay};
        use winit::keyboard::KeyCode;

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        client.send_click_block_to_controller(true);
        let _ = drained(&mut to_net);
        assert!(client.controller.hitting_block().is_some());

        client.handle_raw_key(KeyCode::Escape, true, false, None);
        client.handle_screen_input(&mut InputState::new(), 854, 480);
        assert!(matches!(client.ui, Ui::Pause(_)));
        assert!(client.controller.hitting_block().is_none());

        let sent = drained(&mut to_net);
        let aborts = sent
            .iter()
            .filter(|packet| {
                matches!(
                    packet,
                    C2SPlay::PlayerDigging(c2s::PlayerDigging {
                        status: c2s::PlayerDiggingStatus::AbortDestroyBlock,
                        ..
                    })
                )
            })
            .count();
        let stops = sent
            .iter()
            .filter(|packet| {
                matches!(
                    packet,
                    C2SPlay::PlayerDigging(c2s::PlayerDigging {
                        status: c2s::PlayerDiggingStatus::StopDestroyBlock,
                        ..
                    })
                )
            })
            .count();
        assert_eq!(
            aborts, 1,
            "raw Escape must queue exactly one ABORT: {sent:?}"
        );
        assert_eq!(
            stops, 0,
            "modal opening must not finish the stale dig: {sent:?}"
        );

        client.show_screen(None);
        let _ = drained(&mut to_net);
        client.send_click_block_to_controller(false);
        assert!(
            drained(&mut to_net).is_empty(),
            "the cleared dig cannot produce a later STOP or duplicate ABORT"
        );

        client.handle_raw_key(KeyCode::Escape, true, false, None);
        client.handle_screen_input(&mut InputState::new(), 854, 480);
        assert!(
            drained(&mut to_net).is_empty(),
            "idle Escape must not manufacture a digging packet"
        );
    }

    #[test]
    fn creative_held_damage_cannot_destroy_beyond_the_lerped_world_border() {
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let target = BlockPos::new(3, 65, 4);
        let session = client.session.as_mut().expect("session");
        session.state_mut().local.game_mode = mc_protocol::play::s2c::GameMode::Creative;
        session.state_mut().env.border = BorderState {
            old_diameter: 2.0,
            new_diameter: 2.0,
            ..BorderState::default()
        };
        let _ = drained(&mut to_net);

        client.send_click_block_to_controller(true);

        assert!(
            !client
                .session
                .as_ref()
                .expect("session")
                .state()
                .world
                .block_at(target)
                .props()
                .is_air(),
            "creative continuation outside the border must not predict destruction"
        );
        let sent = drained(&mut to_net);
        assert!(
            sent.iter().all(|packet| !matches!(
                packet,
                mc_protocol::play::C2SPlay::PlayerDigging(_)
                    | mc_protocol::play::C2SPlay::Animation(_)
            )),
            "outside-border held damage may sync C09 but must not dig or swing: {sent:?}"
        );
    }

    /// **W-CONFIRM.** java: `handleConfirmTransaction` (`:1174`) resolves window `0` to
    /// `thePlayer.inventoryContainer`, which exists for the whole session, so a **rejected**
    /// window-0 transaction is acked with no GUI open at all. The producer used to sit behind
    /// `apply_container_packet`'s `let Ui::Container(screen) = … else { return; }`.
    #[test]
    fn a_rejected_window_zero_transaction_is_acked_with_no_gui_open() {
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        assert!(
            !matches!(client.ui, Ui::Container(_)),
            "the whole point is that no container screen is open"
        );
        client.react_to_window(&crate::sync::WindowEvent::ConfirmTransaction {
            window_id: 0,
            action_number: 7,
            accepted: false,
        });
        let sent = drained(&mut to_net);
        let acks: Vec<_> = sent
            .iter()
            .filter_map(|p| match p {
                mc_protocol::play::C2SPlay::ConfirmTransaction(c) => Some(c),
                _ => None,
            })
            .collect();
        assert_eq!(
            acks.len(),
            1,
            "java: `addToSendQueue(new C0F…)` — got {sent:?}"
        );
        assert_eq!((acks[0].window_id, acks[0].action_id), (0, 7));
        assert!(acks[0].accepted, "java: the literal `true`");

        // Negative control 1: an *accepted* transaction is silent in vanilla too, which is why a
        // coverage test built on one cannot tell a correct handler from a missing one.
        client.react_to_window(&crate::sync::WindowEvent::ConfirmTransaction {
            window_id: 0,
            action_number: 8,
            accepted: true,
        });
        assert!(drained(&mut to_net).is_empty());
        // Negative control 2: a non-zero window with nothing open resolves to no container.
        client.react_to_window(&crate::sync::WindowEvent::ConfirmTransaction {
            window_id: 3,
            action_number: 9,
            accepted: false,
        });
        assert!(drained(&mut to_net).is_empty());
    }

    /// **W-CONFIRM / W-WINDOW, the "window 0 exists twice" half.** java:
    /// `EntityPlayer.inventoryContainer` is *one* object for the whole session, so
    /// `Container.getNextTransactionID`'s `++this.transactionID` is monotonic across every
    /// inventory open. `open_inventory` cloned `player_container` and threw the clone away, so
    /// the counter restarted at `1` every time -- `F-P0-network.play.client-03-5`,
    /// `F-P1-inventory-05-11`, `F-P2-client.gui.inventory-02-7`.
    ///
    /// For this to pass while the code is wrong, `open_inventory` would have to hand the screen
    /// a container whose counter is already `1`, which no clone of a fresh `player_container`
    /// can be. The pre-fix code gives `1, 1` here.
    #[test]
    fn window_zero_keeps_one_transaction_counter_across_inventory_opens() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.open_inventory();
        let Ui::Container(screen) = &mut client.ui else {
            panic!("open_inventory must open a container screen");
        };
        assert_eq!(screen.container.window_id, PLAYER_WINDOW_ID);
        // A real click through `Container::click`: allocates the id *and* predicts locally.
        assert_eq!(screen.container.click(-999, 0, 0, false).action_number, 1);

        client.show_screen(None);
        assert!(matches!(client.ui, Ui::InGame), "{:?}", client.ui.name());
        client.open_inventory();
        let Ui::Container(screen) = &mut client.ui else {
            panic!("open_inventory must open a container screen");
        };
        assert_eq!(
            screen.container.click(-999, 0, 0, false).action_number,
            2,
            "java: `++this.transactionID` on one session-long object"
        );
        assert_eq!(screen.container.click(-999, 0, 0, false).action_number, 3);

        // Negative control: a *non-zero* window's counter is its own -- `windowClick` calls
        // `openContainer.getNextTransactionID()`, and that container was new()'d at open. If the
        // fix had instead made every container share one counter this would read `4`.
        client.show_screen(None);
        client.react_to_window(&crate::sync::WindowEvent::Open(
            mc_protocol::play::s2c::OpenWindow {
                window_id: 3,
                inventory_type: "minecraft:chest".to_owned(),
                window_title: "Chest".to_owned(),
                slot_count: 27,
                entity_id: None,
            },
        ));
        let Ui::Container(screen) = &mut client.ui else {
            panic!("a 27-slot chest must open");
        };
        assert_eq!(screen.container.window_id, 3);
        assert_eq!(screen.container.click(-999, 0, 0, false).action_number, 1);
    }

    /// `EntityPlayerSP.closeScreenAndDropStack` clears the carried stack before
    /// `Minecraft.displayGuiScreen(null)` invokes `GuiContainer.onGuiClosed`. A direct screen
    /// replacement skips that preliminary clear. Pin both orders against the same live driver
    /// helper so a future close refactor cannot accidentally materialise a duplicate local drop.
    #[test]
    fn container_close_hook_distinguishes_close_from_direct_replacement() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let carried = stack_named("dirt", 3);
        let mut screen = ContainerScreen::player(0);
        screen.container.set_cursor(Some(carried.clone()));
        client.ui = Ui::Container(Box::new(screen));

        assert_eq!(client.finish_container_close(true), None);
        let Ui::Container(screen) = &client.ui else {
            unreachable!()
        };
        assert_eq!(screen.container.cursor(), None);

        let Ui::Container(screen) = &mut client.ui else {
            unreachable!()
        };
        screen.container.set_cursor(Some(carried.clone()));
        assert_eq!(client.finish_container_close(false), Some(carried));
        let Ui::Container(screen) = &client.ui else {
            unreachable!()
        };
        assert_eq!(screen.container.cursor(), None);
    }

    /// Creative mode must use `GuiContainerCreative`, whose player-inventory changes are C10
    /// packets rather than the survival screen's C0E transaction protocol. This exercises the
    /// live driver seam rather than the screen in isolation: game-mode selection, initial
    /// listener sync, close-time drain ordering, and C0D(0).
    #[test]
    fn creative_inventory_opens_the_creative_screen_and_drains_c10_before_close() {
        use mc_protocol::play::{c2s, s2c, C2SPlay, S2CPlay};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, to_game, mut to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(S2CPlay::JoinGame(
                s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 1,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                },
            )))
            .expect("channel");
        session.poll(16);
        client.session = Some(session);
        let dirt = stack_named("dirt", 7);
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 36,
            item: Some(dirt.clone()),
        });
        let _ = drained(&mut to_net);

        client.open_inventory();
        let opened = drained(&mut to_net);
        assert!(matches!(client.ui, Ui::Creative(_)));
        assert!(matches!(
            opened.first(),
            Some(C2SPlay::ClientStatus(c2s::ClientStatus {
                action: c2s::ClientStatusAction::OpenInventoryAchievement
            }))
        ));
        assert!(opened.iter().any(|packet| matches!(
            packet,
            C2SPlay::CreativeInventoryAction(c2s::CreativeInventoryAction {
                slot_id: 36,
                stack: Some(stack),
            }) if stack == &dirt
        )));

        let Ui::Creative(screen) = &mut client.ui else {
            unreachable!()
        };
        screen.click_slot(
            mc_ui::screens::container::creative_screen::CreativeSlot::Player(36),
            0,
            false,
        );
        client.show_screen(None);
        let closed = drained(&mut to_net);
        let c10 = closed.iter().position(|packet| {
            matches!(
                packet,
                C2SPlay::CreativeInventoryAction(c2s::CreativeInventoryAction {
                    slot_id: 36,
                    stack: None,
                })
            )
        });
        let c0d = closed.iter().position(|packet| {
            matches!(
                packet,
                C2SPlay::CloseWindow(c2s::CloseWindow { window_id: 0 })
            )
        });
        assert!(
            c10.zip(c0d).is_some_and(|(change, close)| change < close),
            "creative change must reach the server before C0D(0): {closed:?}"
        );
        assert_eq!(client.player_container.slot_stack(36), None);
    }

    /// `GuiInventory.updateScreen` and `GuiContainerCreative.updateScreen` replace one another
    /// when the server changes the local game mode while the inventory is open. The replacement
    /// is direct (`displayGuiScreen`), so pending creative mutations must be flushed as C10 while
    /// no C0D/C0E is produced by the mode edge in either direction.
    #[test]
    fn creative_inventory_switches_live_with_game_mode_without_close_packet() {
        use mc_protocol::play::{c2s, s2c, C2SPlay, S2CPlay};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, to_game, mut to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(S2CPlay::JoinGame(
                s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 1,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                },
            )))
            .expect("channel");
        session.poll(16);
        client.session = Some(session);
        let dirt = stack_named("dirt", 7);
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 36,
            item: Some(dirt.clone()),
        });
        let _ = drained(&mut to_net);

        client.open_inventory();
        assert!(matches!(client.ui, Ui::Creative(_)));
        let _ = drained(&mut to_net);

        // A pending creative mutation must cross the mode edge as C10 before the old screen is
        // discarded. `click_slot` models the same local pick that GuiContainerCreative performs.
        let Ui::Creative(screen) = &mut client.ui else {
            unreachable!()
        };
        // On the Inventory tab the pick goes through
        // `inventoryContainer.detectAndSendChanges`, so `ContainerPlayer`'s listener mirror
        // records the empty slot and the next creative screen re-uploads the restored stack.
        // (An item tab's direct upload leaves the mirror alone, and Java would then send nothing
        // for slot 36 on reopening.) The selected tab is process-wide, so pin it here.
        screen.set_tab(
            mc_ui::screens::container::creative::CreativeTab::Inventory
                .index()
                .expect("the Inventory tab is registered"),
        );
        screen.click_slot(
            mc_ui::screens::container::creative_screen::CreativeSlot::Player(36),
            0,
            false,
        );
        client
            .session
            .as_mut()
            .expect("joined session")
            .state_mut()
            .local
            .game_mode = s2c::GameMode::Survival;
        client
            .session
            .as_mut()
            .expect("joined session")
            .state_mut()
            .local
            .abilities
            .creative_mode = false;
        client.react(&ClientEvent::GameModeChanged(s2c::GameMode::Survival));
        client.tick(&MoveInput::default());

        let switched_to_survival = drained(&mut to_net);
        assert!(matches!(client.ui, Ui::Container(_)));
        assert!(matches!(
            client.ui,
            Ui::Container(ref screen)
                if screen.container.kind
                    == mc_ui::screens::container::ContainerKind::Player
                    && !screen.creative
        ));
        assert!(switched_to_survival.iter().any(|packet| matches!(
            packet,
            C2SPlay::CreativeInventoryAction(c2s::CreativeInventoryAction {
                slot_id: 36,
                stack: None,
            })
        )));
        assert!(
            switched_to_survival
                .iter()
                .all(|packet| !matches!(packet, C2SPlay::CloseWindow(_) | C2SPlay::ClickWindow(_))),
            "mode replacement is a direct displayGuiScreen path: {switched_to_survival:?}"
        );
        assert_eq!(client.player_container.slot_stack(36), None);

        // Put the slot back through the normal window-0 packet path, then switch to Creative.
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 36,
            item: Some(dirt.clone()),
        });
        let _ = drained(&mut to_net);
        client
            .session
            .as_mut()
            .expect("joined session")
            .state_mut()
            .local
            .game_mode = s2c::GameMode::Creative;
        client
            .session
            .as_mut()
            .expect("joined session")
            .state_mut()
            .local
            .abilities
            .creative_mode = true;
        client.react(&ClientEvent::GameModeChanged(s2c::GameMode::Creative));
        client.tick(&MoveInput::default());

        let switched_to_creative = drained(&mut to_net);
        assert!(matches!(client.ui, Ui::Creative(_)));
        assert!(switched_to_creative.iter().any(|packet| matches!(
            packet,
            C2SPlay::CreativeInventoryAction(c2s::CreativeInventoryAction {
                slot_id: 36,
                stack: Some(stack),
            }) if stack == &dirt
        )));
        assert!(
            switched_to_creative
                .iter()
                .all(|packet| !matches!(packet, C2SPlay::CloseWindow(_) | C2SPlay::ClickWindow(_))),
            "mode replacement is a direct displayGuiScreen path: {switched_to_creative:?}"
        );
    }

    /// java: the creative screen's `CreativeCrafting` listener
    /// compares against `ContainerPlayer.inventoryItemStacks`, which lives as long as the player:
    /// a reopen uploads only what changed. `handleRespawn` builds a new `EntityPlayerSP` (a new,
    /// empty mirror), so once the server has refilled the inventory the first opening uploads
    /// every occupied slot again.
    #[test]
    fn w21_ci_creative_reopen_uploads_changes_only_until_a_respawn() {
        use mc_protocol::play::{c2s, s2c, C2SPlay, S2CPlay};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, to_game, mut to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(S2CPlay::JoinGame(
                s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 1,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                },
            )))
            .expect("channel");
        session.poll(16);
        client.session = Some(session);
        let dirt = stack_named("dirt", 7);
        let server_sets_slot_36 = |client: &mut Client| {
            client.react_to_window(&crate::sync::WindowEvent::SetSlot {
                window_id: 0,
                slot: 36,
                item: Some(stack_named("dirt", 7)),
            });
        };
        server_sets_slot_36(&mut client);
        let _ = drained(&mut to_net);
        let uploads = |packets: Vec<C2SPlay>| -> Vec<(i16, Option<mc_protocol::ItemStack>)> {
            packets
                .into_iter()
                .filter_map(|packet| match packet {
                    C2SPlay::CreativeInventoryAction(c2s::CreativeInventoryAction {
                        slot_id,
                        stack,
                    }) => Some((slot_id, stack)),
                    _ => None,
                })
                .collect()
        };

        client.open_inventory();
        assert_eq!(
            uploads(drained(&mut to_net)),
            vec![(36, Some(dirt.clone()))]
        );
        client.show_screen(None);
        let _ = drained(&mut to_net);

        client.open_inventory();
        assert!(
            uploads(drained(&mut to_net)).is_empty(),
            "a reopen with nothing changed uploads nothing"
        );
        client.show_screen(None);
        let _ = drained(&mut to_net);

        client.react(&ClientEvent::Respawned {
            dimension: 0,
            changed_world: false,
        });
        // A vanilla server refills the new player's inventory right after the respawn.
        server_sets_slot_36(&mut client);
        let _ = drained(&mut to_net);
        client.open_inventory();
        assert_eq!(
            uploads(drained(&mut to_net)),
            vec![(36, Some(dirt))],
            "the new player's container has an empty mirror: everything is uploaded again"
        );
    }

    #[test]
    fn editable_book_opens_after_c08_and_done_sends_the_mutated_stack() {
        use mc_protocol::play::{C2SPlay, S2CPlay};

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (mut session, to_game, mut to_net) = offline_session(mc_world::World::new());
        to_game
            .try_send(crate::net::ToGame::Packet(S2CPlay::JoinGame(
                mc_protocol::play::s2c::JoinGame {
                    entity_id: 1,
                    hardcore_mode: false,
                    game_mode: 0,
                    dimension: 0,
                    difficulty: 2,
                    max_players: 20,
                    level_type: "default".into(),
                    reduced_debug_info: false,
                },
            )))
            .expect("channel");
        session.poll(16);
        client.session = Some(session);
        let book = mc_protocol::ItemStack {
            item_id: 386,
            count: 1,
            damage: 0,
            nbt: None,
        };
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 36,
            item: Some(book.clone()),
        });
        let _ = drained(&mut to_net);

        client.send_use_item(Some(book));
        assert!(matches!(client.ui, Ui::Book(_)));
        assert!(drained(&mut to_net)
            .iter()
            .any(|packet| matches!(packet, C2SPlay::PlayerBlockPlacement(_))));

        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let Ui::Book(screen) = &mut client.ui else {
            unreachable!()
        };
        screen.init(&ctx, &client.assets.language);
        screen.key_typed(
            Some('x'),
            0,
            mc_ui::widget::keys::Modifiers::default(),
            &client.clipboard,
            &client.font,
        );
        screen.mouse_clicked(
            ctx.width / 2 + 10,
            200,
            0,
            &client.font,
            &client.assets.language,
        );
        client.drain_book_actions();

        assert!(matches!(client.ui, Ui::InGame));
        let sent = drained(&mut to_net);
        let stack = sent.iter().find_map(|packet| match packet {
            C2SPlay::PluginMessage(message) if message.channel == "MC|BEdit" => {
                let mut payload = mc_protocol::PacketBuffer::from_slice(&message.data);
                mc_protocol::ItemStack::read(&mut payload).unwrap()
            }
            _ => None,
        });
        let stack = stack.expect("Done after an edit must send MC|BEdit");
        let pages = stack
            .nbt
            .as_ref()
            .and_then(|tag| tag.get("pages"))
            .and_then(|tag| match tag {
                mc_nbt::Nbt::List(pages) => Some(pages),
                _ => None,
            })
            .expect("pages tag");
        assert_eq!(pages.first().and_then(mc_nbt::Nbt::as_str), Some("x"));
    }

    #[test]
