    #[test]
    fn inbound_brand_is_stored_losslessly_rejects_malformed_and_resets_with_the_player() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        assert_eq!(client.server_brand(), None);

        let mut payload = mc_protocol::PacketBuffer::new();
        payload.write_string("Paper üñîçødé");
        payload.write_u8(0x7f); // Java ignores trailing plugin bytes after the string.
        client.react(&ClientEvent::PluginMessage {
            channel: "MC|Brand".to_owned(),
            data: payload.as_slice().to_vec(),
        });
        assert_eq!(client.server_brand(), Some("Paper üñîçødé"));

        let mut category = crash::CrashReportCategory::new("Affected level");
        client.describe_server_brand(&mut category);
        let mut rendered = String::new();
        category.append_to(&mut rendered);
        assert!(
            rendered.contains("\tServer brand: Paper üñîçødé"),
            "the stored brand must reach vanilla's affected-level crash metadata"
        );

        client.react(&ClientEvent::PluginMessage {
            channel: "MC|Brand".to_owned(),
            data: vec![5, b'x'],
        });
        assert_eq!(
            client.server_brand(),
            Some("Paper üñîçødé"),
            "a truncated string must not replace the previous EntityPlayerSP value"
        );
        assert!(client.fatal_error().is_none());

        client.react(&ClientEvent::Respawned {
            dimension: 0,
            changed_world: false,
        });
        assert_eq!(
            client.server_brand(),
            None,
            "S07 constructs a fresh EntityPlayerSP with no clientBrand"
        );
    }

    /// java: `handleUseBed` only runs `trySleep`; `GuiSleepMP` is
    /// chosen by `Minecraft.runTick:1771-1785` on the next tick, and only while
    /// `currentScreen == null`. An S0A that lands over a chest leaves the chest open (no C0D);
    /// GuiSleepMP opens on the first tick after the chest closes. Wake-up (S0B type 2) closes
    /// it on the next tick, not at packet time. Driven through the real packet path.
    #[test]
    fn local_bed_events_open_sleep_chat_and_leave_bed_sends_c0b() {
        use mc_protocol::play::{s2c, C2SPlay, S2CPlay};
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, to_game, mut to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        let deliver = |client: &mut Client, packet: S2CPlay| {
            to_game
                .try_send(crate::net::ToGame::Packet(packet))
                .expect("channel");
            client.poll();
        };
        deliver(
            &mut client,
            S2CPlay::JoinGame(s2c::JoinGame {
                entity_id: 42,
                hardcore_mode: false,
                game_mode: 0,
                dimension: 0,
                difficulty: 2,
                max_players: 20,
                level_type: "default".into(),
                reduced_debug_info: false,
            }),
        );
        client.ui = Ui::InGame;
        let _ = drained(&mut to_net);
        let bed = |player_id| {
            S2CPlay::UseBed(s2c::UseBed {
                player_id,
                bed_position: BlockPos::new(1, 2, 3),
            })
        };

        deliver(&mut client, bed(99));
        client.tick(&MoveInput::default());
        assert!(
            matches!(client.ui, Ui::InGame),
            "a foreign player's S0A must not open the local SleepScreen"
        );

        // An S0A over an open chest: vanilla's `currentScreen != null` skips GuiSleepMP.
        client.react_to_window(&crate::sync::WindowEvent::Open(s2c::OpenWindow {
            window_id: 5,
            inventory_type: "minecraft:chest".to_owned(),
            window_title: "Chest".to_owned(),
            slot_count: 27,
            entity_id: None,
        }));
        let _ = drained(&mut to_net);
        deliver(&mut client, bed(42));
        assert!(
            client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .sleeping
        );
        assert!(
            matches!(client.ui, Ui::Container(_)),
            "S0A itself never changes the screen (the old client opened GuiSleepMP here)"
        );
        client.tick(&MoveInput::default());
        assert!(
            matches!(client.ui, Ui::Container(_)),
            "runTick only opens GuiSleepMP when no screen is open"
        );
        assert!(
            drained(&mut to_net)
                .iter()
                .all(|packet| !matches!(packet, C2SPlay::CloseWindow(_))),
            "the chest must not be closed (C0D) by the S0A"
        );
        // The player closes the chest; the next tick opens GuiSleepMP.
        client.show_screen(None);
        assert!(matches!(client.ui, Ui::InGame));
        client.tick(&MoveInput::default());
        assert!(matches!(client.ui, Ui::Sleep(_)));

        client.handle_action(Action::StopSleeping);
        assert!(
            matches!(client.ui, Ui::Sleep(_)),
            "the server owns wake timing"
        );
        assert!(drained(&mut to_net).iter().any(|packet| matches!(
            packet,
            C2SPlay::EntityAction(mc_protocol::play::c2s::EntityAction {
                entity_id: 42,
                action: mc_protocol::play::c2s::EntityActionType::StopSleeping,
                aux_data: 0,
            })
        )));

        deliver(
            &mut client,
            S2CPlay::Animation(s2c::Animation {
                entity_id: 42,
                animation_type: 2,
            }),
        );
        assert!(
            !client
                .session
                .as_ref()
                .expect("session")
                .state()
                .local
                .sleeping
        );
        assert!(
            matches!(client.ui, Ui::Sleep(_)),
            "the wake packet itself leaves GuiSleepMP up until the next runTick"
        );
        client.tick(&MoveInput::default());
        assert!(matches!(client.ui, Ui::InGame));
    }

    /// java: `GuiScreen.handleInput` runs `while (Mouse.next())
    /// handleMouseInput()` with no age limit, so a click the window delivered more than 200 ms
    /// before the frame drained it (one long frame in between) still presses the button. The old
    /// screen path filtered mouse events to an age of 200 ms and dropped it.
    #[test]
    fn a_gui_click_older_than_200_ms_still_reaches_the_screen() {
        use winit::event::MouseButton;

        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let resolution = client.resolution(854, 480);
        let ctx = ScreenCtx::new(resolution, 0.0);
        let mut pause = PauseScreen::new();
        pause.init(&ctx, &client.assets.language);
        client.ui = Ui::Pause(Box::new(pause));
        let scale = resolution.scale_factor();
        // The centre of "Back to Game": `(width / 2 - 100, height / 4 + 24 - 16)`, 200x20.
        let mut input = mc_render::InputState::new();
        input.on_cursor_moved(
            f64::from(ctx.width / 2 * scale),
            f64::from((ctx.height / 4 + 18) * scale),
        );
        input.on_mouse_button_at_ms(MouseButton::Left, true, 0);
        std::thread::sleep(std::time::Duration::from_millis(260));
        client.handle_screen_input(&mut input, 854, 480);
        assert!(
            matches!(client.ui, Ui::InGame),
            "a 260 ms old press must still reach GuiIngameMenu, got {}",
            client.ui.name()
        );
    }

    /// java: GuiSleepMP inherits `GuiChat.mouseClicked`, which
    /// tries `handleComponentClick` before the input field and `super.mouseClicked`'s Leave Bed
    /// button. The bottom chat line overlaps the top of that button, so a click on a
    /// RUN_COMMAND span there sends the command (C01, no history) and does not leave the bed;
    /// SUGGEST_COMMAND overwrites the bed screen's own input (`setText(value, true)`). The old
    /// client never hit-tested chat on the bed screen: the same click sent C0B STOP_SLEEPING.
    #[test]
    fn a_chat_component_over_the_leave_bed_button_wins_the_click() {
        use mc_protocol::play::C2SPlay;
        use mc_ui::font::component::{ChatComponent, ChatStyle, ClickAction, ClickEvent};

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .sleeping = true;
        client.tick(&MoveInput::default());
        assert!(matches!(client.ui, Ui::Sleep(_)));
        let _ = drained(&mut to_net);

        let layout = ChatLayout::from_settings(&client.settings);
        let clickable = |action, value: &str| {
            ChatComponent::text("w".repeat(40)).with_style(ChatStyle {
                click_event: Some(ClickEvent {
                    action,
                    value: value.into(),
                }),
                ..ChatStyle::default()
            })
        };
        client.chat.add_message(
            clickable(ClickAction::RunCommand, "/hub"),
            0,
            client.tick as i32,
            &layout,
            &client.font,
            &client.assets.language,
            true,
        );
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        // Inside both the bottom chat line (y = height - 27) and the 200x20 Leave Bed button.
        let point = (ctx.width / 2 - 60, ctx.height - 27);
        {
            let Ui::Sleep(screen) = &mut client.ui else {
                unreachable!("asserted above");
            };
            screen.init(&ctx, &client.assets.language);
            assert!(screen.leave_bed_button().contains(point.0, point.1));
        }
        client.cursor = point;
        client.mouse_clicked(0, ctx);
        let sent = drained(&mut to_net);
        let ran = |packet: &C2SPlay| matches!(packet, C2SPlay::ChatMessage(chat) if chat.message == "/hub");
        assert!(
            sent.iter().any(ran),
            "the RUN_COMMAND span must win the click: {sent:?}"
        );
        assert!(
            sent.iter()
                .all(|packet| !matches!(packet, C2SPlay::EntityAction(_))),
            "Leave Bed must not fire under a handled component: {sent:?}"
        );
        assert!(matches!(client.ui, Ui::Sleep(_)));
        assert!(
            client.chat.sent_messages().is_empty(),
            "sendChatMessage(value, false)"
        );

        client.chat.add_message(
            clickable(ClickAction::SuggestCommand, "/msg Steve "),
            0,
            client.tick as i32,
            &layout,
            &client.font,
            &client.assets.language,
            true,
        );
        client.mouse_clicked(0, ctx);
        let Ui::Sleep(screen) = &client.ui else {
            panic!("SUGGEST_COMMAND must keep GuiSleepMP up");
        };
        assert_eq!(screen.chat.input.text(), "/msg Steve ");
        assert!(drained(&mut to_net).is_empty());
    }

    /// java: `runTick:1773` opens GuiGameOver *before*
    /// `currentScreen.updateScreen()` in the same tick, so a death screen opened from the game
    /// has `enableButtonsTimer == 1` after that tick and wakes its buttons 19 ticks later. The
    /// old client opened it after the screen tick (timer 0), one tick late.
    #[test]
    fn a_death_screen_opened_from_the_game_is_ticked_in_the_same_tick() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        client.ui = Ui::InGame;
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .local
            .health = 0.0;
        client.tick(&MoveInput::default());
        let Ui::GameOver(screen) = &client.ui else {
            panic!("a dead player with no screen must get GuiGameOver");
        };
        assert_eq!(screen.timer(), 1, "the opening tick also runs updateScreen");
        for _ in 0..18 {
            client.tick(&MoveInput::default());
        }
        // Lay the buttons out the way the frame's draw does before the wake-up tick.
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let Ui::GameOver(screen) = &mut client.ui else {
            panic!("still dead");
        };
        screen.init(&ctx, &client.assets.language);
        assert_eq!(screen.timer(), 19);
        assert!(!screen.buttons_enabled());
        client.tick(&MoveInput::default());
        let Ui::GameOver(screen) = &client.ui else {
            panic!("still dead");
        };
        assert_eq!(screen.timer(), 20);
        assert!(
            screen.buttons_enabled(),
            "the buttons wake on the 20th updateScreen, 19 ticks after the opening tick"
        );
    }

