    /// W-WORLD / W-NBT: row moves save synchronously while GuiMultiplayer stays alive, and the
    /// NBT writer replaces through vanilla's sibling `servers.dat_tmp` file rather than moving
    /// the in-memory list out of the screen or truncating the destination in place.
    #[test]
    fn save_servers_persists_without_emptying_the_live_multiplayer_screen() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut servers = ServerList::new();
        servers.add(ServerEntry::new("first", "one.invalid"));
        servers.add(ServerEntry::new("second", "two.invalid"));
        client.ui = Ui::Multiplayer(Box::new(MultiplayerScreen::new(servers)));

        client.handle_action(Action::SaveServers);

        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("saving a row move must keep GuiMultiplayer open")
        };
        assert_eq!(
            screen.servers.len(),
            2,
            "saving must not move the live list out"
        );
        let path = client.config.servers_path();
        let bytes = std::fs::read(&path).expect("synchronous servers.dat write");
        let saved = ServerList::read(&bytes).expect("valid raw compound");
        assert_eq!(saved.get(0).map(|entry| entry.name.as_str()), Some("first"));
        assert_eq!(
            saved.get(1).map(|entry| entry.name.as_str()),
            Some("second")
        );
        let mut temporary = path.as_os_str().to_owned();
        temporary.push("_tmp");
        assert!(
            !std::path::PathBuf::from(temporary).exists(),
            "successful rename must consume servers.dat_tmp"
        );
    }

    #[test]
    fn a_live_ping_favicon_save_keeps_the_multiplayer_rows_owned_by_the_screen() {
        use base64::Engine as _;
        use std::io::Cursor;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let image = image::RgbaImage::from_pixel(64, 64, image::Rgba([9, 8, 7, 255]));
        let mut png = Vec::new();
        image::DynamicImage::ImageRgba8(image)
            .write_to(&mut Cursor::new(&mut png), image::ImageFormat::Png)
            .expect("encode fixture favicon");
        let encoded = base64::engine::general_purpose::STANDARD.encode(png);

        let mut entry = ServerEntry::new("icon server", "icon.example");
        entry.icon_base64 = Some(encoded);
        let mut servers = ServerList::new();
        servers.add(entry);
        client.ui = Ui::Multiplayer(Box::new(MultiplayerScreen::new(servers)));

        // An absent favicon is the vanilla clear path. It changes the saved entry and therefore
        // exercises the exact callback that used to call `save_server_list` and empty the UI.
        let ping = crate::net::ping::parse_status("{}", Duration::from_millis(4))
            .expect("minimal status transport result");
        client
            .async_tx
            .send(AsyncMessage::Ping {
                generation: 0,
                index: 0,
                result: Box::new(Ok(ping)),
            })
            .expect("the client receiver remains live");
        client.drain_async();

        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("a favicon save must not replace the live multiplayer screen");
        };
        assert_eq!(screen.servers.len(), 1);
        assert!(screen.servers.get(0).unwrap().icon_base64.is_none());
        let bytes = std::fs::read(client.config.servers_path()).expect("favicon save");
        let saved = ServerList::read(&bytes).expect("valid servers.dat after favicon clear");
        assert_eq!(
            saved.len(),
            1,
            "the saved row must survive its favicon clear"
        );
        assert!(saved.get(0).unwrap().icon_base64.is_none());
    }

    #[test]
    fn the_typed_ping_favicon_reaches_the_screen_without_a_second_json_decode() {
        use base64::Engine as _;
        use std::io::Cursor;

        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let image = image::RgbaImage::from_pixel(64, 64, image::Rgba([1, 2, 3, 255]));
        let mut png = Vec::new();
        image::DynamicImage::ImageRgba8(image)
            .write_to(&mut Cursor::new(&mut png), image::ImageFormat::Png)
            .expect("encode fixture favicon");
        let payload = base64::engine::general_purpose::STANDARD.encode(png);
        let json =
            format!(r#"{{"description":"typed","favicon":"data:image/png;base64,{payload}"}}"#);
        let ping = crate::net::ping::parse_status(&json, Duration::from_millis(4))
            .expect("typed status parser");
        let expected = ping
            .favicon
            .as_ref()
            .expect("valid typed favicon")
            .rgba
            .clone();
        // The live driver must consume the typed result, not try to parse this diagnostic copy a
        // second time. A malformed raw snapshot therefore cannot erase a valid decoded icon.
        let mut ping = ping;
        ping.raw_json = "not a JSON status object".to_owned();

        let mut servers = ServerList::new();
        servers.add(ServerEntry::new("typed server", "typed.example"));
        client.ui = Ui::Multiplayer(Box::new(MultiplayerScreen::new(servers)));
        client
            .async_tx
            .send(AsyncMessage::Ping {
                generation: 0,
                index: 0,
                result: Box::new(Ok(ping)),
            })
            .expect("the client receiver remains live");
        client.drain_async();

        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("the typed ping must apply to the live multiplayer screen");
        };
        assert_eq!(screen.icons().len(), 1);
        assert_eq!(screen.icons()[0].rgba, expected);
        assert!(screen.servers.get(0).unwrap().icon_base64.is_some());
    }

    #[test]
    fn a_late_ping_from_before_refresh_cannot_overwrite_a_reused_row_index() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut servers = ServerList::new();
        servers.add(ServerEntry::new("server", "server.example"));
        let mut multiplayer = MultiplayerScreen::new(servers);
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        let language = client.assets.language.clone();
        multiplayer.init(&ctx, &language);
        let old_generation = multiplayer.ping_generation();
        assert_eq!(multiplayer.take_ping_queue().len(), 1);
        multiplayer.refresh_pings();
        assert_ne!(multiplayer.ping_generation(), old_generation);
        client.ui = Ui::Multiplayer(Box::new(multiplayer));

        let ping = crate::net::ping::parse_status(
            r#"{"description":"stale","version":{"name":"1.8.9","protocol":47}}"#,
            Duration::from_millis(1),
        )
        .expect("status fixture");
        client
            .async_tx
            .send(AsyncMessage::Ping {
                generation: old_generation,
                index: 0,
                result: Box::new(Ok(ping)),
            })
            .expect("the client receiver remains live");
        client.drain_async();

        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("the stale result must not replace the multiplayer screen");
        };
        assert_eq!(
            screen.servers.get(0).unwrap().state,
            mc_ui::screens::multiplayer::server_data::PingState::Pinging
        );
        assert!(screen.servers.get(0).unwrap().motd.is_empty());
        assert_eq!(screen.servers.get(0).unwrap().ping_ms, 0);
    }

    #[test]
    fn lan_beacons_dedupe_and_stale_generations_cannot_repopulate_the_screen() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let mut multiplayer = MultiplayerScreen::new(ServerList::new());
        multiplayer.set_ping_generation(41);
        client.ui = Ui::Multiplayer(Box::new(multiplayer));

        for motd in ["first", "replacement"] {
            client
                .async_tx
                .send(AsyncMessage::LanBeacon {
                    generation: 41,
                    motd: motd.to_owned(),
                    address: "192.0.2.7:25565".to_owned(),
                })
                .expect("the client receiver remains live");
        }
        client.drain_async();
        let Ui::Multiplayer(screen) = &mut client.ui else {
            panic!("LAN delivery must preserve the multiplayer screen")
        };
        assert_eq!(screen.lan_servers().len(), 1);
        assert_eq!(screen.lan_servers()[0].motd, "first");
        screen.clear_lan_servers();
        screen.set_ping_generation(42);

        client
            .async_tx
            .send(AsyncMessage::LanBeacon {
                generation: 41,
                motd: "stale".to_owned(),
                address: "192.0.2.8:25566".to_owned(),
            })
            .expect("the stale result can race cancellation onto the queue");
        client
            .async_tx
            .send(AsyncMessage::LanBeacon {
                generation: 42,
                motd: "fresh".to_owned(),
                address: "192.0.2.9:25567".to_owned(),
            })
            .expect("the replacement listener remains live");
        client.drain_async();

        let Ui::Multiplayer(screen) = &client.ui else {
            panic!("LAN delivery must preserve the multiplayer screen")
        };
        assert_eq!(screen.lan_servers().len(), 1);
        assert_eq!(screen.lan_servers()[0].motd, "fresh");
        assert_eq!(screen.lan_servers()[0].address, "192.0.2.9:25567");
    }

