    /// `TeleportToTeam` is constructed from the live scoreboard, then resolves its member names
    /// through `NetworkPlayerInfo` before delegating to the ordinary UUID-sorted player menu.
    /// This pins the full driver/UI/C18 path, including spectator filtering and the safe colour
    /// swatch adapter; supplying `Vec::new()` for teams makes the first caption assertion bite.
    #[test]
    fn spectator_team_packets_build_a_coloured_member_menu_and_exact_c18_action() {
        use mc_protocol::play::s2c::{
            AddPlayerEntry, GameMode, PlayerListItem, TeamInfo, Teams, TeamsAction,
        };

        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let member = uuid::Uuid::from_u128(0x1111_2222_3333_4444_5555_6666_7777_8888);
        let spectator = uuid::Uuid::from_u128(0x9999_aaaa_bbbb_cccc_dddd_eeee_ffff_0000);
        let add = |uuid, username: &str, game_mode| AddPlayerEntry {
            uuid,
            username: username.to_owned(),
            properties: Vec::new(),
            game_mode,
            ping: 0,
            display_name: None,
        };
        let session = client.session.as_mut().expect("connected test session");
        session
            .state_mut()
            .players
            .apply(&PlayerListItem::AddPlayer(vec![
                add(member, "member", GameMode::Survival),
                add(spectator, "ghost", GameMode::Spectator),
            ]))
            .expect("player-list rows decode");
        session
            .state_mut()
            .scoreboard
            .apply(&crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "red".to_owned(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "Red team".to_owned(),
                        prefix: "\u{a7}c[R] ".to_owned(),
                        suffix: String::new(),
                        friendly_flags: 0,
                        name_tag_visibility: "always".to_owned(),
                        color: 12,
                    },
                    players: vec![
                        "member".to_owned(),
                        "ghost".to_owned(),
                        "offline".to_owned(),
                    ],
                },
            })));

        client.refresh_spectator_entries();
        assert_eq!(spectator_team_color("\u{a7}c[R] "), Some(0xFF5555));
        assert_eq!(spectator_team_color("plain"), None);
        assert_eq!(spectator_team_color("\u{a7}"), None);
        assert_eq!(spectator_team_color("\u{a7}C"), None);

        assert_eq!(
            client.spectator_hud.select_slot(0, 1),
            SpectatorAction::None
        );
        assert_eq!(
            client.spectator_hud.select_slot(1, 2),
            SpectatorAction::None
        );
        assert_eq!(
            client.spectator_hud.select_slot(1, 3),
            SpectatorAction::None
        );
        assert_eq!(
            client.spectator_hud.caption(),
            "Select a team to teleport to"
        );

        // The valid lowercase prefix reaches the final swatch quad, not just the pure adapter.
        let mut draw = DrawList::new();
        let ctx = ScreenCtx::new(client.resolution(854, 480), 0.0);
        client.spectator_hud.draw(
            &mut draw,
            &mut client.font,
            &ctx,
            &std::array::from_fn(|index| (index + 1).to_string()),
            4,
        );
        assert!(draw.batches().iter().any(|batch| {
            batch.texture == UiTexture::Solid
                && draw.vertices()[batch.range.clone()]
                    .iter()
                    .any(|vertex| vertex.color == [1.0, 85.0 / 255.0, 85.0 / 255.0, 1.0])
        }));

        assert_eq!(
            client.spectator_hud.select_slot(0, 5),
            SpectatorAction::None
        );
        assert_eq!(
            client.spectator_hud.select_slot(0, 6),
            SpectatorAction::None
        );
        assert_eq!(
            client.spectator_hud.caption(),
            "Select a player to teleport to"
        );
        assert_eq!(
            client.spectator_hud.select_slot(0, 7),
            SpectatorAction::None
        );
        let action = client.spectator_hud.select_slot(0, 8);
        assert_eq!(action, SpectatorAction::Spectate(*member.as_bytes()));
        client.handle_spectator_action(action);
        assert!(drained(&mut to_net).iter().any(|packet| matches!(
            packet,
            mc_protocol::play::C2SPlay::Spectate(packet) if packet.target == member
        )));

        // Removed teams and teams with no online member cannot leave an activatable category.
        let session = client.session.as_mut().expect("connected test session");
        session
            .state_mut()
            .scoreboard
            .apply(&crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "red".to_owned(),
                action: TeamsAction::Remove,
            })));
        session
            .state_mut()
            .scoreboard
            .apply(&crate::sync::ScoreboardEvent::Teams(Box::new(Teams {
                team_name: "empty".to_owned(),
                action: TeamsAction::Create {
                    info: TeamInfo {
                        display_name: "Empty".to_owned(),
                        prefix: "\u{a7}a".to_owned(),
                        suffix: String::new(),
                        friendly_flags: 0,
                        name_tag_visibility: "always".to_owned(),
                        color: 10,
                    },
                    players: vec!["offline".to_owned()],
                },
            })));
        client.spectator_hud.dismiss();
        client.refresh_spectator_entries();
        client.spectator_hud.select_slot(0, 9);
        client.spectator_hud.select_slot(1, 10);
        client.spectator_hud.select_slot(1, 11);
        assert_eq!(
            client.spectator_hud.caption(),
            "Press a key to select a command, and again to use it."
        );
    }

    /// **W-WINDOW `F-P1-inventory-05-1` / `F-P0-network.play.server-12-2` /
    /// `F-P1-inventory-02-2`.** The inventory screen predicted into a clone, so closing it threw
    /// the prediction away and `held_item()` -- and therefore `C08PacketPlayerBlockPlacement`'s
    /// stack -- kept reading the stale mirror. The server does not repair this: an *accepted*
    /// `C0E` produces no slot traffic at all (`processClickWindow` sets
    /// `isChangingQuantityOnly = true` around `detectAndSendChanges`).
    ///
    /// Two real clicks, pick-up then put-down, so the assertion is on a prediction the click
    /// state machine actually made rather than on a hand-written slot write.
    #[test]
    fn an_inventory_prediction_survives_the_close_and_reaches_the_held_item() {
        let Some((mut client, _dir, _to_net)) = client_aimed_at_stone(None) else {
            return;
        };
        let dirt = stack_named("dirt", 64);
        // The server's own view of window 0: one stack in main-inventory slot 9, hotbar empty.
        client.react_to_window(&crate::sync::WindowEvent::SetSlot {
            window_id: 0,
            slot: 9,
            item: Some(dirt.clone()),
        });
        assert!(client.held_item().is_none(), "hotbar slot 0 starts empty");

        client.open_inventory();
        let Ui::Container(screen) = &mut client.ui else {
            panic!("open_inventory must open a container screen");
        };
        assert_eq!(
            screen.container.slot_stack(9),
            Some(&dirt),
            "java: `new GuiInventory(thePlayer)` shows `inventoryContainer`, contents and all"
        );
        // Left-click slot 9 (pick the stack up), then slot 36 (hotbar slot 0, put it down).
        screen.container.click(9, 0, 0, false);
        screen.container.click(36, 0, 0, false);
        assert_eq!(screen.container.slot_stack(36), Some(&dirt));
        // Negative control: nothing has converged yet, so the mirror is still the old one. This
        // is exactly the state the pre-fix client was left in *permanently*.
        assert_eq!(client.player_container.slot_stack(36), None);

        client.show_screen(None);
        assert_eq!(
            client.player_container.slot_stack(36),
            Some(&dirt),
            "the prediction has to land on `inventoryContainer`, not die with the screen"
        );
        assert_eq!(client.player_container.slot_stack(9), None);
        assert_eq!(
            client.held_item(),
            Some(&dirt),
            "`InventoryPlayer.getCurrentItem()` is what `C08` carries"
        );
    }

    /// The live driver path must wake a pending workbench map-extension result when S34 creates
    /// the exact `map_<damage>` record. The wrong-key and `scale == 4` controls below ensure this
    /// is not a broad "some map exists" feed or an accidental `<= 4` predicate.
    #[test]
    fn s34_map_scale_reaches_open_workbench_recipe_by_key_and_signed_byte() {
        let Some((mut client, _dir)) = offline_client() else {
            return;
        };
        let (session, _to_game, _to_net) = offline_session(mc_world::World::new());
        client.session = Some(session);
        client.react_to_window(&crate::sync::WindowEvent::Open(
            mc_protocol::play::s2c::OpenWindow {
                window_id: 3,
                inventory_type: "minecraft:crafting_table".to_owned(),
                window_title: "Crafting".to_owned(),
                slot_count: 0,
                entity_id: None,
            },
        ));

        let mut items = vec![None; 46];
        for (slot, item) in items.iter_mut().enumerate().skip(1).take(9) {
            *item = Some(if slot == 5 {
                mc_protocol::ItemStack {
                    item_id: 358,
                    count: 1,
                    damage: 17,
                    nbt: None,
                }
            } else {
                stack_named("paper", 1)
            });
        }
        client.react_to_window(&crate::sync::WindowEvent::Items {
            window_id: 3,
            items,
        });
        assert!(
            matches!(&client.ui, Ui::Container(screen) if screen.container.slot_stack(0).is_none()),
            "missing map data must retain vanilla's client-side non-match"
        );

        // A different map record is a keyed negative control: it must not unlock map 17.
        let wrong_key = mc_protocol::play::s2c::Maps {
            map_id: 18,
            scale: 3,
            icons: Vec::new(),
            update: None,
        };
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .apply_map_packet(&wrong_key)
            .expect("valid map snapshot");
        client.react(&ClientEvent::Maps(Box::new(wrong_key)));
        assert!(
            matches!(&client.ui, Ui::Container(screen) if screen.container.slot_stack(0).is_none()),
            "a map with another map_<id> key must not satisfy the centre stack"
        );

        // `RecipesMapExtending.matches` uses signed Java-byte `< 4`: -1 matches, 4 does not.
        let scale_four = mc_protocol::play::s2c::Maps {
            map_id: 17,
            scale: 4,
            icons: Vec::new(),
            update: None,
        };
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .apply_map_packet(&scale_four)
            .expect("valid map snapshot");
        client.react(&ClientEvent::Maps(Box::new(scale_four)));
        assert!(
            matches!(&client.ui, Ui::Container(screen) if screen.container.slot_stack(0).is_none()),
            "scale 4 is the exact upper non-match boundary"
        );

        let scale_negative = mc_protocol::play::s2c::Maps {
            map_id: 17,
            scale: -1,
            icons: Vec::new(),
            update: None,
        };
        client
            .session
            .as_mut()
            .expect("session")
            .state_mut()
            .world
            .apply_map_packet(&scale_negative)
            .expect("valid map snapshot");
        client.react(&ClientEvent::Maps(Box::new(scale_negative)));

        let mut root = mc_nbt::NbtCompound::new();
        root.insert("map_is_scaling", mc_nbt::Nbt::Byte(1));
        let expected = mc_protocol::ItemStack {
            item_id: 358,
            count: 1,
            damage: 17,
            nbt: Some(root),
        };
        let Ui::Container(screen) = &mut client.ui else {
            panic!("the crafting-table screen must remain open");
        };
        assert_eq!(screen.container.slot_stack(0), Some(&expected));
        let click = screen.container.click(0, 0, 0, false);
        assert_eq!(click.clicked_item, Some(expected));
        assert_eq!(
            screen.container.cursor().map(|stack| stack.item_id),
            Some(358)
        );
    }

    #[test]
    fn empty_map_count_one_replaces_selected_stack_and_creates_map_zero() {
        let empty = mc_protocol::ItemStack {
            item_id: 395,
            count: 1,
            damage: 0,
            nbt: None,
        };
        let Some((mut client, _dir, mut to_net)) = client_aimed_at_stone(Some(empty.clone()))
        else {
            return;
        };
        client
            .session
            .as_mut()
            .expect("live test session")
            .predictor_mut()
            .expect("JoinGame built predictor")
            .state
            .pos = DVec3::new(191.9, 65.0, -64.1);

        client.send_use_item(Some(empty));

        assert_eq!(
            client.held_item(),
            Some(&mc_protocol::ItemStack {
                item_id: 358,
                count: 1,
                damage: 0,
                nbt: None,
            })
        );
        let world = &client.session.as_ref().expect("session").state().world;
        assert_eq!(
            world.map_data(0).map(|map| (map.id, map.scale)),
            Some((0, 0))
        );
        assert_eq!(
            world.map_data_metadata(0),
            Some(&mc_world::world::MapDataMetadata {
                x_center: 128,
                z_center: -128,
                dimension: 0,
            })
        );
        let sent = drained(&mut to_net);
        assert!(matches!(
            sent.first(),
            Some(mc_protocol::play::C2SPlay::PlayerBlockPlacement(packet))
                if packet.stack.as_ref() == Some(&mc_protocol::ItemStack {
                    item_id: 395,
                    count: 1,
                    damage: 0,
                    nbt: None,
                })
        ));
        assert_eq!(
            sent.iter()
                .filter(|packet| {
                    matches!(packet, mc_protocol::play::C2SPlay::PlayerBlockPlacement(_))
                })
                .count(),
            1,
            "empty-map use keeps the ordinary single C08 packet"
        );
        assert!(
            sent.iter()
                .all(|packet| !matches!(packet, mc_protocol::play::C2SPlay::Animation(_))),
            "ItemEmptyMap does not add the fishing-rod swing side effect"
        );
    }

